window.DATA_A2_V=[{"id":"V1","q":"Estoy en paro, por eso ____ el subsidio por desempleo.","o":["estoy pagando","estoy cobrando","estoy dando","estoy regalando"],"a":1,"k":"실업·급여 어휘","t":"나는 실직 상태라서 실업 수당을 받고 있다.","e":"cobrar는 '(돈을) 받다, 수령하다'라는 뜻으로 월급·수당·연금 등을 받을 때 씁니다. 'estar en paro(실직 상태이다)'와 'subsidio por desempleo(실업 수당)'은 스페인에서 자주 쓰는 표현입니다. 참고로 중남미에서는 paro 대신 desempleo를 더 많이 씁니다. 예: Cobro el sueldo a fin de mes.(나는 월말에 월급을 받는다.)","x":["estoy pagando: '지불하고 있다'로, 수당은 내는 것이 아니라 받는 것이라 ✗","estoy cobrando: '(돈을) 받고 있다' → 수당을 받는 상황에 딱 맞아 정답 ✓","estoy dando: '주고 있다'로, 실직자가 수당을 주는 것은 의미가 맞지 않아 ✗","estoy regalando: '선물하고 있다'로, 문맥과 전혀 맞지 않아 ✗"]},{"id":"V2","q":"Decidió ser ____ porque siempre quiso ayudar a los enfermos.","o":["enfermera","limpiadora","repartidora","cajera"],"a":0,"k":"직업 어휘","t":"그녀는 늘 아픈 사람들을 돕고 싶어 했기 때문에 간호사가 되기로 결심했다.","e":"enfermera는 '간호사(여성)'입니다. 문장의 'ayudar a los enfermos(환자들을 돕다)'라는 단서가 병원 일을 하는 직업을 가리킵니다. enfermo(아픈 사람, 환자)와 enfermera(간호사)가 같은 어근이라는 것도 기억해 두세요. 남성형은 enfermero입니다.","x":["enfermera: '간호사' → 환자를 돕는 직업이라 정답 ✓","limpiadora: '청소부'로, 환자를 돕는다는 이유와 연결되지 않아 ✗","repartidora: '배달원'으로, 문맥과 맞지 않아 ✗","cajera: '계산원(캐셔)'로, 환자와 관련이 없어 ✗"]},{"id":"V3","q":"He comprado ____ nuevas para la cama.","o":["almohadas","lámparas","toallas","cortinas"],"a":0,"k":"침구·집 어휘","t":"침대용 새 베개를 샀다.","e":"almohada는 '베개'로, 'para la cama(침대용)'라는 단서와 가장 잘 어울립니다. 침구 관련 단어로 sábana(시트), manta(담요), edredón(이불)도 함께 알아 두면 좋습니다. 빈칸 뒤의 'nuevas'가 여성 복수형이므로 여성 복수 명사가 와야 한다는 점도 확인하세요.","x":["almohadas: '베개들' → 침대에 쓰는 물건이라 정답 ✓","lámparas: '전등, 램프'로, 침대에 놓는 물건이 아니라 ✗","toallas: '수건'으로, 욕실에서 쓰는 물건이라 ✗","cortinas: '커튼'으로, 창문에 다는 것이라 침대용이 아니어서 ✗"]},{"id":"V4","q":"¿Me dejas un ____? El mío no escribe bien.","o":["bolígrafo","sacapuntas","cuaderno","archivador"],"a":0,"k":"문구 어휘","t":"볼펜 하나 빌려줄래? 내 것은 잘 안 나와.","e":"bolígrafo는 '볼펜'입니다. 'El mío no escribe bien(내 것은 잘 써지지 않는다)'에서 escribir(쓰다)라는 동사가 단서이므로 필기구가 필요합니다. 'dejar'는 여기서 '빌려주다'라는 뜻으로, ¿Me dejas...?는 친구 사이에서 무언가를 빌릴 때 자주 쓰는 표현입니다. 중남미에서는 lapicera, pluma 등으로도 부릅니다.","x":["bolígrafo: '볼펜' → 글씨를 쓰는 도구라 정답 ✓","sacapuntas: '연필깎이'로, 글씨를 쓰는 도구가 아니라 ✗","cuaderno: '공책'으로, 공책이 '써지지 않는다'는 말은 어색해서 ✗","archivador: '서류철, 파일 보관함'으로, 문맥과 맞지 않아 ✗"]},{"id":"V5","q":"Lo que dices es ____, no tiene sentido.","o":["absurdo","cierto","racional","evidente"],"a":0,"k":"형용사 어휘","t":"네가 하는 말은 터무니없어, 말이 안 돼.","e":"absurdo는 '터무니없는, 말도 안 되는'이라는 뜻입니다. 뒤에 나오는 'no tiene sentido(의미가 없다, 말이 안 된다)'와 같은 의미를 반복해 강조하는 구조입니다. 'Lo que dices'는 '네가 말하는 것'이라는 뜻의 자주 쓰는 표현입니다.","x":["absurdo: '터무니없는' → '말이 안 된다'와 의미가 일치해 정답 ✓","cierto: '사실인, 맞는'으로, 뒤의 부정적 내용과 반대라 ✗","racional: '합리적인'으로, '말이 안 된다'와 모순되어 ✗","evidente: '명백한'으로, 뒤의 내용과 맞지 않아 ✗"]},{"id":"V6","q":"Puedes comprar ____ en el estanco o en la oficina de correos.","o":["sellos","juguetes","velas","especias"],"a":0,"k":"우편·상점 어휘","t":"우표는 담배 가게나 우체국에서 살 수 있다.","e":"sello는 '우표'입니다. 스페인에서는 estanco(국가 허가를 받은 담배 가게)에서 담배뿐 아니라 우표와 각종 인지도 팝니다. 이것은 스페인 특유의 문화로, 우체국(oficina de correos)과 함께 우표를 살 수 있는 대표적인 장소입니다. 중남미에서는 우표를 estampilla라고 부르는 나라가 많습니다.","x":["sellos: '우표' → 담배 가게와 우체국 모두에서 파는 물건이라 정답 ✓","juguetes: '장난감'으로, 우체국에서 팔지 않아 ✗","velas: '양초'로, 우체국과 관련이 없어 ✗","especias: '향신료'로, 담배 가게나 우체국에서 팔지 않아 ✗"]},{"id":"V7","q":"La semana ____ no trabajé porque tenía gripe.","o":["próxima","pasada","que viene","siguiente"],"a":1,"k":"시간 표현","t":"지난주에 나는 독감에 걸려서 일하지 않았다.","e":"'la semana pasada'는 '지난주'입니다. 동사 trabajé, tenía가 과거형이므로 과거를 나타내는 표현이 필요합니다. 'el año pasado(작년)', 'el mes pasado(지난달)'처럼 pasado/pasada를 붙이면 '지난 ~'이 됩니다.","x":["próxima: '다음'으로, 과거 시제 동사와 맞지 않아 ✗","pasada: '지난' → 과거 시제와 어울려 정답 ✓","que viene: 'la semana que viene'는 '다음 주'라서 과거 문장에 맞지 않아 ✗","siguiente: '그다음의'로, 과거 사건에 대해 '지난주'를 뜻하지 않아 ✗"]},{"id":"V8","q":"Prefiero tomar una cena ____, porque si como algo pesado no podré dormir bien.","o":["rica","grande","ligera","abundante"],"a":2,"k":"음식 형용사","t":"무거운 것을 먹으면 잠을 잘 못 자니까 저녁은 가볍게 먹는 게 좋다.","e":"ligero/ligera는 음식에 쓰면 '(소화가 잘 되는) 가벼운'이라는 뜻입니다. 뒤 문장의 'algo pesado(무거운 것, 기름지고 소화가 잘 안 되는 것)'와 반대 의미로 짝을 이룹니다. 'comida ligera(가벼운 식사)'는 자주 쓰는 표현입니다.","x":["rica: '맛있는'으로, 무거운 음식과 대조되는 의미가 아니라 ✗","grande: '양이 많은, 큰'으로, 잠을 방해하는 쪽이라 반대 의미여서 ✗","ligera: '가벼운' → pesado(무거운)의 반대말로 정답 ✓","abundante: '풍성한, 양이 많은'으로, 문맥과 반대라 ✗"]},{"id":"V9","q":"Aunque ahora está calvo, mi cuñado de joven tenía ____.","o":["canas","bigote","barba","melena"],"a":3,"k":"외모 어휘","t":"지금은 대머리지만, 우리 매형(처남)은 젊었을 때 머리가 길었다.","e":"melena는 '(어깨까지 오는) 긴 머리, 장발'입니다. 'Aunque ahora está calvo(지금은 대머리이지만)'라는 대조 표현이 있으므로, 예전에는 머리카락이 많았다는 내용이 와야 합니다. 'tener melena'는 '머리가 길다'라는 뜻입니다. cuñado는 배우자의 형제나 자매의 남편을 모두 가리킵니다.","x":["canas: '흰머리'로, 대머리와 대조되는 '머리숱'의 의미가 아니라 ✗","bigote: '콧수염'으로, 머리(대머리)와의 대조가 되지 않아 ✗","barba: '턱수염'으로, 대머리와의 대조가 되지 않아 ✗","melena: '긴 머리, 장발' → 대머리와 대조되어 정답 ✓"]},{"id":"V10","q":"Mi hijo pequeño es muy generoso, ____ todo lo que tiene.","o":["comparte","arregla","acumula","parte"],"a":0,"k":"동사 어휘","t":"우리 막내아들은 아주 너그러워서, 가진 것을 모두 나눈다.","e":"compartir는 '나누다, 함께 쓰다'라는 뜻입니다. generoso(너그러운, 인심 좋은)인 사람의 행동으로 가장 자연스럽습니다. 예: Comparto piso con dos amigos.(나는 친구 두 명과 아파트를 함께 쓴다.)","x":["comparte: '나눈다' → 너그러운 성격과 맞아 정답 ✓","arregla: '고친다, 정리한다'로, 너그러움과 관련이 없어 ✗","acumula: '모은다, 쌓아 둔다'로, 너그러움과 반대 의미라 ✗","parte: partir '자르다, 쪼개다/떠나다'로, '나누어 준다'는 뜻으로 쓰지 않아 ✗"]},{"id":"V11","q":"Si tienes infección, es lógico que el médico te recete ____.","o":["pomadas","jarabes","antialérgicos","antibióticos"],"a":3,"k":"의약품 어휘","t":"감염이 있으면 의사가 항생제를 처방하는 것은 당연하다.","e":"antibiótico는 '항생제'로, 세균 감염(infección)을 치료하는 약입니다. recetar는 '(약을) 처방하다'라는 뜻이고, 'Es lógico que + 접속법(바람·판단 등을 나타낼 때 쓰는 동사 형태)'이라서 recete가 쓰였습니다.","x":["pomadas: '연고'로, 감염 치료의 대표 약이 아니라 ✗","jarabes: '시럽(물약)'으로, 주로 기침 등에 쓰여 감염과 직접 연결되지 않아 ✗","antialérgicos: '알레르기 약'으로, 감염 치료약이 아니라 ✗","antibióticos: '항생제' → 감염 치료에 쓰는 약이라 정답 ✓"]},{"id":"V12","q":"En España hay casi ____ millones de personas.","o":["quarenta y siete","cuarenta y siete","cuarenta siete","quarenta siete"],"a":1,"k":"숫자 철자","t":"스페인에는 거의 4,700만 명의 사람이 있다.","e":"47은 'cuarenta y siete'로 씁니다. 스페인어에서 31부터 99까지는 십의 자리와 일의 자리 사이에 y(그리고)를 넣습니다. 또한 '40'은 c로 시작하는 cuarenta이며 포르투갈어·이탈리아어처럼 q로 쓰지 않습니다.","x":["quarenta y siete: q 철자가 틀렸습니다(cuarenta가 맞음) ✗","cuarenta y siete: 철자와 y 연결 모두 올바라 정답 ✓","cuarenta siete: 십의 자리와 일의 자리 사이에 y가 빠져서 ✗","quarenta siete: 철자도 틀리고 y도 빠져서 ✗"]},{"id":"V13","q":"El yoga te ayuda a tener una buena ____.","o":["altura","pintura","dentadura","postura"],"a":3,"k":"신체·건강 어휘","t":"요가는 좋은 자세를 갖도록 도와준다.","e":"postura는 '자세'입니다. 요가는 몸의 자세를 바르게 하는 운동이므로 가장 자연스럽습니다. 'tener buena postura(자세가 좋다)', 'mala postura(나쁜 자세)'처럼 씁니다.","x":["altura: '키, 높이'로, 요가로 키를 키우는 것은 아니라 ✗","pintura: '그림, 페인트'로, 문맥과 관련이 없어 ✗","dentadura: '치아(이 전체)'로, 요가와 관련이 없어 ✗","postura: '자세' → 요가의 효과로 정답 ✓"]},{"id":"V14","q":"Alba es hija ____, no tiene hermanos ni hermanas.","o":["menor","mayor","sola","única"],"a":3,"k":"가족 어휘","t":"알바는 외동딸이라서, 형제도 자매도 없다.","e":"'hija única'는 '외동딸', 'hijo único'는 '외아들'입니다. 'no tiene hermanos ni hermanas(형제도 자매도 없다)'가 단서입니다. único는 '유일한'이라는 뜻입니다.","x":["menor: '더 어린, 막내'로, 형제가 있어야 쓸 수 있어 ✗","mayor: '더 나이 많은, 맏이'로, 형제가 있어야 쓸 수 있어 ✗","sola: '혼자인, 외로운'으로, '외동'이라는 뜻의 고정 표현이 아니라 ✗","única: '유일한' → hija única(외동딸)로 정답 ✓"]},{"id":"V15","q":"¿Puede decirme la hora, si es tan ____?","o":["lindo","amable","bueno","majo"],"a":1,"k":"정중한 표현","t":"실례지만, 괜찮으시다면 몇 시인지 알려 주시겠어요?","e":"'si es tan amable'은 '친절하시다면, 괜찮으시다면'이라는 뜻의 정중한 부탁 표현입니다. 모르는 사람에게 부탁할 때 자주 붙입니다. amable은 '친절한'이라는 뜻입니다. 예: Si es tan amable, cierre la puerta.(괜찮으시면 문을 닫아 주세요.)","x":["lindo: '예쁜, 귀여운'(중남미에서 '친절한' 뜻도 있음)이지만 이 고정 표현에 쓰지 않아 ✗","amable: '친절한' → si es tan amable라는 정중 표현으로 정답 ✓","bueno: '좋은'으로, 이 정중한 부탁 표현에 쓰지 않아 ✗","majo: '(스페인 구어) 착한, 호감 가는'으로, 격식 있는 부탁 표현에 쓰지 않아 ✗"]},{"id":"V16","q":"¡Qué bien ____ esta colonia!","o":["suena","sabe","luce","huele"],"a":3,"k":"감각 동사","t":"이 향수 정말 좋은 냄새가 난다!","e":"oler는 '냄새가 나다'라는 뜻이며 불규칙 동사로 3인칭 단수가 huele입니다(o가 hue로 변함). colonia는 '향수(오드콜로뉴)'이므로 냄새와 관련된 동사가 필요합니다. 'oler bien(좋은 냄새가 나다)', 'oler mal(나쁜 냄새가 나다)'로 씁니다.","x":["suena: sonar '소리가 나다'로, 향수와 맞지 않아 ✗","sabe: saber '맛이 나다'로, 향수는 먹는 것이 아니라 ✗","luce: lucir '빛나다, 보기 좋다'로, 향수의 특성과 맞지 않아 ✗","huele: oler '냄새가 나다' → 향수에 맞아 정답 ✓"]},{"id":"V17","q":"Esta actriz no suele ser ____, en general tiene papeles secundarios.","o":["líder","protagonista","directora","artista"],"a":1,"k":"영화·연극 어휘","t":"이 여배우는 보통 주인공을 맡지 않고, 대체로 조연 역할을 한다.","e":"protagonista는 '주인공'으로 남녀 모두 같은 형태입니다. 'papeles secundarios(조연 역할)'와 대조되므로 '주연'이 와야 합니다. 'soler + 동사원형'은 '보통 ~하다'라는 뜻입니다.","x":["líder: '지도자, 리더'로, 배역과 관련된 말이 아니라 ✗","protagonista: '주인공' → 조연과 대조되어 정답 ✓","directora: '감독'으로, 여배우의 배역과 대조되는 말이 아니라 ✗","artista: '예술가'로, 배우도 예술가이므로 대조가 성립하지 않아 ✗"]},{"id":"V18","q":"Es un ____ de élite, por eso va a participar en los próximos Juegos Olímpicos.","o":["empresario","abogado","atleta","contable"],"a":2,"k":"스포츠 어휘","t":"그는 엘리트 운동선수라서 다음 올림픽에 참가할 것이다.","e":"atleta는 '운동선수(특히 육상 선수)'로, 남녀 모두 같은 형태입니다. 'Juegos Olímpicos(올림픽)'에 참가하는 사람이므로 운동선수가 맞습니다. 'de élite'는 '최상위 수준의'라는 뜻입니다.","x":["empresario: '기업가'로, 올림픽 참가와 관련이 없어 ✗","abogado: '변호사'로, 올림픽 참가와 관련이 없어 ✗","atleta: '운동선수' → 올림픽에 나가는 사람이라 정답 ✓","contable: '회계사'로, 올림픽 참가와 관련이 없어 ✗"]},{"id":"V19","q":"Este niño nunca me hace caso, es ____.","o":["impactante","desobediente","elegante","sorprendente"],"a":1,"k":"성격 형용사","t":"이 아이는 내 말을 절대 듣지 않아, 말을 안 듣는 아이야.","e":"desobediente는 '말을 안 듣는, 순종하지 않는'이라는 뜻입니다. 'hacer caso a alguien'은 '~의 말을 듣다, ~에게 신경 쓰다'라는 표현으로, 'nunca me hace caso(내 말을 전혀 안 듣는다)'가 단서입니다. 반대말은 obediente(말 잘 듣는)입니다.","x":["impactante: '충격적인, 인상적인'으로, 성격 묘사에 맞지 않아 ✗","desobediente: '말을 안 듣는' → 문맥과 일치해 정답 ✓","elegante: '우아한, 멋진'으로, 말을 듣지 않는 것과 관련이 없어 ✗","sorprendente: '놀라운'으로, 문맥과 맞지 않아 ✗"]},{"id":"V20","q":"Si le sigue doliendo el estómago, le ____ que vaya al médico.","o":["expongo","deseo","aconsejo","indico"],"a":2,"k":"충고 동사","t":"계속 배가 아프시면, 병원에 가 보시라고 권해 드립니다.","e":"aconsejar는 '충고하다, 권하다'입니다. 'aconsejar que + 접속법(바람·권유를 나타내는 동사 형태)'이라서 뒤에 vaya가 옵니다. 아픈 사람에게 병원에 가라고 하는 것은 충고이므로 가장 자연스럽습니다.","x":["expongo: exponer '전시하다, 설명하다'로, 충고의 의미가 아니라 ✗","deseo: desear '바라다'로, 상대가 병원에 가기를 '바란다'는 말은 어색해서 ✗","aconsejo: aconsejar '충고하다' → 병원에 가라고 권하는 문맥이라 정답 ✓","indico: indicar '가리키다, 지시하다'로, 의미가 가능은 하나 이 문맥에서는 충고가 가장 자연스러워 ✗"]},{"id":"V21","q":"¿De qué color era ____ de boda de papá?","o":["el vestido","la falda","el traje","camiseta"],"a":2,"k":"의류 어휘","t":"아빠의 결혼식 정장은 무슨 색이었어?","e":"traje는 '(남성용) 정장, 양복'입니다. 'traje de boda'는 '결혼식 예복'이고, 아빠(신랑)가 입는 옷이므로 traje가 맞습니다. 참고로 신부의 웨딩드레스는 'vestido de novia'라고 합니다.","x":["el vestido: '원피스, 드레스'로, 주로 여성이 입는 옷이라 아빠에게 맞지 않아 ✗","la falda: '치마'로, 아빠의 결혼식 옷으로 맞지 않아 ✗","el traje: '정장' → 남성 예복이라 정답 ✓","camiseta: '티셔츠'로, 관사도 없고 결혼식 옷으로 맞지 않아 ✗"]},{"id":"V22","q":"No bebo ____, prefiero el café.","o":["pollo","pan","té","arroz"],"a":2,"k":"음식·음료 어휘","t":"나는 차를 마시지 않고, 커피가 더 좋다.","e":"té는 '차(茶)'입니다. 동사 beber(마시다)가 있으므로 음료가 와야 하고, 뒤의 café(커피)와 비교되는 음료로 té가 자연스럽습니다. té는 악센트가 있어야 하며, 악센트 없는 te는 대명사 '너를/너에게'입니다.","x":["pollo: '닭고기'로, 마시는 것이 아니라 ✗","pan: '빵'으로, 마시는 것이 아니라 ✗","té: '차' → 마시는 음료라 정답 ✓","arroz: '쌀, 밥'으로, 마시는 것이 아니라 ✗"]},{"id":"V23","q":"Para escribir cuentos, debes tener mucha ____.","o":["generosidad","calma","imaginación","impaciencia"],"a":2,"k":"명사 어휘","t":"이야기를 쓰려면 상상력이 많아야 한다.","e":"imaginación은 '상상력'입니다. cuento(동화, 짧은 이야기)를 쓰는 데 가장 필요한 능력으로 자연스럽습니다. 'tener mucha imaginación(상상력이 풍부하다)'은 자주 쓰는 표현입니다.","x":["generosidad: '너그러움'으로, 글쓰기에 필요한 능력과 관련이 없어 ✗","calma: '침착함'으로, 이야기 창작의 핵심 능력이 아니라 ✗","imaginación: '상상력' → 이야기를 쓰는 데 필요해 정답 ✓","impaciencia: '조급함'으로, 오히려 부정적인 특성이라 ✗"]},{"id":"V24","q":"Lo que más me ____ del portugués es la pronunciación, tiene sonidos difíciles.","o":["fascina","agrada","cuesta","satisface"],"a":2,"k":"costar 구문","t":"포르투갈어에서 나에게 가장 어려운 것은 발음이다, 어려운 소리가 있다.","e":"costar는 gustar처럼 쓰는 동사로 '~에게 어렵다, 힘들다'라는 뜻입니다. 'Me cuesta + 명사/동사원형'은 '나에게 ~이 어렵다'로, 뒤의 'tiene sonidos difíciles(어려운 소리가 있다)'가 단서입니다. 예: Me cuesta levantarme temprano.(나는 일찍 일어나기가 힘들다.)","x":["fascina: '매료시키다'로, 뒤의 '어려운 소리'라는 이유와 맞지 않아 ✗","agrada: '마음에 들다'로, 어렵다는 내용과 맞지 않아 ✗","cuesta: costar '~에게 어렵다' → 발음이 어렵다는 문맥에 맞아 정답 ✓","satisface: '만족시키다'로, 문맥과 맞지 않아 ✗"]},{"id":"V25","q":"Hay agua en el suelo del baño. ¿Dónde está la ____?","o":["fregona","bañera","escoba","lavadora"],"a":0,"k":"청소 도구 어휘","t":"욕실 바닥에 물이 있어. 대걸레 어디 있어?","e":"fregona는 스페인에서 쓰는 '대걸레(밀대)'로, 바닥의 물을 닦을 때 씁니다. 동사 fregar(문질러 닦다)에서 온 말입니다. 중남미에서는 trapeador, mopa, lampazo 등 나라마다 다르게 부릅니다.","x":["fregona: '대걸레' → 바닥의 물을 닦는 도구라 정답 ✓","bañera: '욕조'로, 물을 닦는 도구가 아니라 ✗","escoba: '빗자루'로, 먼지를 쓰는 도구라 물에는 맞지 않아 ✗","lavadora: '세탁기'로, 바닥 청소 도구가 아니라 ✗"]},{"id":"V26","q":"¡Qué mal! ____ el anillo de oro que me regaló mi marido.","o":["He recuperado","He encontrado","He perdido","He visto"],"a":2,"k":"동사 어휘","t":"너무 속상해! 남편이 선물해 준 금반지를 잃어버렸어.","e":"perder는 '잃어버리다'입니다. 'He perdido'는 현재완료(최근 일어난 일을 나타내는 시제)입니다. '¡Qué mal!(정말 안 좋다, 속상하다!)'이라는 부정적 감탄이 단서입니다.","x":["He recuperado: '되찾았다'로, 좋은 소식이라 ¡Qué mal!과 맞지 않아 ✗","He encontrado: '찾았다'로, 좋은 소식이라 문맥과 맞지 않아 ✗","He perdido: '잃어버렸다' → 속상한 상황과 맞아 정답 ✓","He visto: '보았다'로, 속상할 이유가 되지 않아 ✗"]},{"id":"V27","q":"Mi madre dejó una ____ sobre la mesa para decirme que debo comprar pan.","o":["cuchara","nota","taza","copa"],"a":1,"k":"명사 어휘","t":"엄마가 빵을 사야 한다고 알려 주려고 식탁 위에 쪽지를 남겼다.","e":"nota는 '쪽지, 메모'입니다. 'para decirme(나에게 말하려고)'라는 목적이 있으므로 글로 전달하는 것이 필요합니다. 'dejar una nota(메모를 남기다)'는 자주 쓰는 표현입니다.","x":["cuchara: '숟가락'으로, 무언가를 알려 줄 수 없어 ✗","nota: '쪽지, 메모' → 메시지를 전하는 수단이라 정답 ✓","taza: '찻잔, 머그컵'으로, 메시지를 전할 수 없어 ✗","copa: '와인잔'으로, 메시지를 전할 수 없어 ✗"]},{"id":"V28","q":"El pescado a la plancha tiene menos ____ que el pescado frito.","o":["agua","sal","azúcar","grasa"],"a":3,"k":"음식 어휘","t":"구운 생선은 튀긴 생선보다 지방이 적다.","e":"grasa는 '지방, 기름기'입니다. 'a la plancha(철판에 구운)'는 기름을 거의 쓰지 않고, 'frito(튀긴)'는 기름을 많이 쓰므로 두 조리법의 차이는 지방의 양입니다.","x":["agua: '물'로, 굽기와 튀기기의 핵심 차이가 아니라 ✗","sal: '소금'으로, 조리법 차이와 직접 관련이 없어 ✗","azúcar: '설탕'으로, 생선 조리법과 관련이 없어 ✗","grasa: '지방' → 튀긴 요리가 기름이 더 많아 정답 ✓"]},{"id":"V29","q":"Las zapatillas de deporte son mucho más ____ que los zapatos de tacón.","o":["cómodas","grandes","duras","costosas"],"a":0,"k":"형용사 어휘","t":"운동화는 하이힐보다 훨씬 더 편하다.","e":"cómodo/cómoda는 '편안한'입니다. 운동화(zapatillas de deporte)와 하이힐(zapatos de tacón)을 비교할 때 가장 자연스러운 차이는 편안함입니다. 'más ... que'는 '~보다 더 ...한'이라는 비교 구문입니다. 반대말은 incómodo(불편한)입니다.","x":["cómodas: '편한' → 운동화의 대표적 장점이라 정답 ✓","grandes: '큰'으로, 신발 종류에 따른 일반적인 차이가 아니라 ✗","duras: '딱딱한'으로, 운동화는 오히려 부드러워서 ✗","costosas: '비싼'으로, 일반적인 비교 내용이 아니라 ✗"]},{"id":"V30","q":"Cuando una persona mayor entra en el autobús, siempre le ofrezco mi ____.","o":["sillón","asiento","mesilla","silla"],"a":1,"k":"교통 어휘","t":"버스에 어르신이 타시면, 나는 항상 내 자리를 양보한다.","e":"asiento는 '좌석, 자리'로, 버스·기차·극장 등의 좌석을 말합니다. 'ofrecer el asiento(자리를 양보하다)'는 자주 쓰는 표현입니다. 'persona mayor'는 '노인, 어르신'을 정중하게 부르는 말입니다.","x":["sillón: '안락의자'로, 버스 좌석이 아니라 ✗","asiento: '좌석' → 버스 자리에 맞아 정답 ✓","mesilla: '협탁(작은 탁자)'으로, 문맥과 맞지 않아 ✗","silla: '의자'지만 버스 좌석을 가리킬 때는 asiento를 써서 ✗"]},{"id":"V31","q":"Por la mañana suelo desayunar dos ____ de pan con mantequilla y mermelada y una taza de té.","o":["lonchas","tabletas","rebanadas","terrones"],"a":2,"k":"단위 명사","t":"아침에 나는 보통 버터와 잼을 바른 빵 두 조각과 차 한 잔을 먹는다.","e":"rebanada는 빵을 얇게 자른 '한 조각, 슬라이스'를 말합니다. 'una rebanada de pan(빵 한 조각)'처럼 씁니다. 스페인어는 음식마다 세는 단위가 다르므로 짝지어 외워 두면 좋습니다: loncha de jamón(햄 한 장), tableta de chocolate(초콜릿 한 판), terrón de azúcar(각설탕 한 개).","x":["lonchas: '(햄·치즈의) 얇은 조각'으로, 빵에는 보통 쓰지 않아 ✗","tabletas: '(초콜릿 등의) 판'으로, 빵에 쓰지 않아 ✗","rebanadas: '(빵의) 조각, 슬라이스' → pan과 어울려 정답 ✓","terrones: '덩어리(각설탕 등)'로, 빵에 쓰지 않아 ✗"]},{"id":"V32","q":"Este ____ hace una parada delante de mi casa.","o":["autobús","helicóptero","barco","avión"],"a":0,"k":"교통수단 어휘","t":"이 버스는 우리 집 앞에 정차한다.","e":"autobús는 '버스'입니다. 'hacer una parada(정차하다)'와 'delante de mi casa(우리 집 앞)'를 보면 도로를 다니며 정류장에 서는 교통수단이어야 합니다. 중남미에서는 나라에 따라 camión(멕시코), colectivo(아르헨티나), guagua(카리브) 등으로도 부릅니다.","x":["autobús: '버스' → 집 앞 정류장에 서는 교통수단이라 정답 ✓","helicóptero: '헬리콥터'로, 집 앞에 정차하지 않아 ✗","barco: '배'로, 집 앞 도로에 정차할 수 없어 ✗","avión: '비행기'로, 집 앞에 정차하지 않아 ✗"]},{"id":"V33","q":"Este hostal está muy bien ubicado, por eso tiene tantos ____.","o":["huéspedes","comensales","compradores","pasajeros"],"a":0,"k":"숙박 어휘","t":"이 호스텔은 위치가 아주 좋아서 투숙객이 많다.","e":"huésped는 '(호텔·숙소의) 투숙객, 손님'입니다. hostal은 '작은 호텔, 여관'이므로 그곳에 묵는 사람을 가리키는 단어가 필요합니다. 'bien ubicado(위치가 좋은)'도 숙소를 설명할 때 자주 쓰는 표현입니다.","x":["huéspedes: '투숙객' → 숙소에 묵는 손님이라 정답 ✓","comensales: '식사하는 손님'으로, 식당에 쓰는 말이라 ✗","compradores: '구매자'로, 상점에 쓰는 말이라 ✗","pasajeros: '승객'으로, 교통수단에 쓰는 말이라 ✗"]},{"id":"V34","q":"Necesito un cambio de ____, así que voy a pasar unos días en una casa rural.","o":["brisas","corrientes","vientos","aires"],"a":3,"k":"관용 표현","t":"나는 기분 전환(환경 변화)이 필요해서, 시골 별장에서 며칠 지낼 거야.","e":"'cambio de aires'는 '기분 전환, 환경을 바꾸는 것'이라는 관용 표현입니다. 직역하면 '공기를 바꾸기'로, 늘 있던 곳을 떠나 새로운 장소에서 쉬는 것을 뜻합니다. 항상 복수형 aires로 쓴다는 점에 유의하세요. casa rural은 '시골 민박, 전원주택'입니다.","x":["brisas: '산들바람'으로, 이 관용 표현에 쓰지 않아 ✗","corrientes: '흐름, 기류'로, 이 관용 표현에 쓰지 않아 ✗","vientos: '바람'으로, 이 관용 표현에 쓰지 않아 ✗","aires: cambio de aires(기분 전환)라는 고정 표현으로 정답 ✓"]},{"id":"V35","q":"Es difícil ____ el auto en esa parte de la ciudad, por eso prefiero ir allí en metro.","o":["arreglar","aparcar","arrancar","terminar"],"a":1,"k":"운전 어휘","t":"도시의 그 지역에서는 차를 주차하기가 어려워서, 나는 지하철로 가는 것을 더 좋아한다.","e":"aparcar는 '주차하다'입니다. 차 대신 지하철을 탄다는 이유로 '주차가 어렵다'가 가장 자연스럽습니다. aparcar는 주로 스페인에서 쓰고, 중남미에서는 estacionar나 parquear를 더 많이 씁니다. auto(차)도 중남미에서 흔히 쓰는 말입니다.","x":["arreglar: '고치다'로, 지하철을 타는 이유와 맞지 않아 ✗","aparcar: '주차하다' → 주차가 어려워 지하철을 타는 문맥이라 정답 ✓","arrancar: '시동을 걸다'로, 특정 지역에서 어려울 이유가 없어 ✗","terminar: '끝내다'로, 차와 함께 쓰면 의미가 맞지 않아 ✗"]},{"id":"V36","q":"El ____ les dejó el paquete a mis vecinos porque yo no estaba en casa en ese momento.","o":["repartidor","asesor","entrevistador","operador"],"a":0,"k":"직업 어휘","t":"내가 그때 집에 없어서 배달원이 이웃에게 소포를 맡겼다.","e":"repartidor는 '배달원'입니다. repartir(배달하다, 나누어 주다)에서 온 말입니다. paquete(소포)를 전달하는 사람이므로 가장 자연스럽습니다.","x":["repartidor: '배달원' → 소포를 전달하는 사람이라 정답 ✓","asesor: '상담사, 고문'으로, 소포를 배달하지 않아 ✗","entrevistador: '면접관, 인터뷰어'로, 소포와 관련이 없어 ✗","operador: '운영자, 교환원'으로, 소포 배달과 관련이 없어 ✗"]},{"id":"V37","q":"No pierda la ____, hay que pensar que todo va a salir bien.","o":["pereza","pena","humildad","esperanza"],"a":3,"k":"감정 명사","t":"희망을 잃지 마세요, 모든 게 잘될 거라고 생각해야 해요.","e":"esperanza는 '희망'입니다. 'perder la esperanza(희망을 잃다)'는 자주 쓰는 표현입니다. 뒤의 'todo va a salir bien(모든 게 잘될 것이다)'이라는 긍정적인 내용이 단서입니다. 'No pierda'는 usted에 대한 부정 명령형입니다.","x":["pereza: '게으름'으로, 잃지 말라고 할 대상이 아니라 ✗","pena: '슬픔, 유감'으로, 긍정적 생각을 하라는 문맥과 맞지 않아 ✗","humildad: '겸손'으로, 잘될 거라는 생각과 직접 연결되지 않아 ✗","esperanza: '희망' → 긍정적 내용과 맞아 정답 ✓"]},{"id":"V38","q":"María está en paro, no ____ desde hace tres meses.","o":["trabaja","descansa","llama","sale"],"a":0,"k":"동사 어휘","t":"마리아는 실직 상태라서, 석 달 전부터 일하지 않는다.","e":"trabajar는 '일하다'입니다. 'estar en paro(실직 상태이다)'라는 단서가 있으므로 '일하지 않는다'가 자연스럽습니다. 'desde hace + 기간'은 '~ 전부터 (지금까지)'라는 뜻으로 현재형과 함께 씁니다.","x":["trabaja: '일한다' → 실직 상태와 맞아 정답 ✓","descansa: '쉰다'로, '쉬지 않는다'는 실직과 반대 의미라 ✗","llama: '전화한다'로, 실직과 관련이 없어 ✗","sale: '나간다, 외출한다'로, 실직의 결과로 맞지 않아 ✗"]},{"id":"V39","q":"Han multado a ese ____ por exceso de velocidad.","o":["conductor","pasajero","viajero","peatón"],"a":0,"k":"교통 어휘","t":"그 운전자는 과속으로 벌금을 받았다.","e":"conductor는 '운전자'입니다. 'exceso de velocidad(과속)'는 차를 모는 사람만 할 수 있으므로 정답입니다. multar는 '벌금을 물리다'라는 뜻입니다. 중남미에서는 chofer(chófer)도 많이 씁니다.","x":["conductor: '운전자' → 과속은 운전자가 하는 것이라 정답 ✓","pasajero: '승객'으로, 과속의 책임이 없어 ✗","viajero: '여행자'로, 과속과 직접 관련이 없어 ✗","peatón: '보행자'로, 과속을 할 수 없어 ✗"]},{"id":"V40","q":"Los gemelos de mi clase tienen la misma edad que yo, ____ años.","o":["veinte y uno","veintiún","veintiuno","veinte y un"],"a":1,"k":"숫자 21+명사","t":"우리 반 쌍둥이들은 나와 나이가 같다, 21살이다.","e":"21은 한 단어로 veintiuno라고 쓰지만, 남성 명사 앞에서는 -o가 탈락해 veintiún이 됩니다(악센트 주의). años는 남성 명사이므로 'veintiún años'가 맞습니다. 여성 명사 앞에서는 veintiuna를 씁니다: veintiuna personas(21명).","x":["veinte y uno: 21~29는 한 단어로 붙여 써서 ✗","veintiún: 남성 명사 앞 줄어든 형태 → años 앞이라 정답 ✓","veintiuno: 남성 명사 바로 앞에서는 -o가 빠져야 해서 ✗","veinte y un: 띄어 쓰는 형태는 틀린 철자라 ✗"]},{"id":"V41","q":"Desde el ____ de Luisa se ve toda la ciudad.","o":["vehículo","ático","carro","auto"],"a":1,"k":"주거 어휘","t":"루이사의 꼭대기 층 집에서는 도시 전체가 보인다.","e":"ático는 '건물 꼭대기 층의 집(펜트하우스, 다락층)'입니다. 높은 곳에 있어서 'se ve toda la ciudad(도시 전체가 보인다)'와 잘 어울립니다. 나머지 보기는 모두 '자동차'를 뜻하는 말입니다.","x":["vehículo: '차량'으로, 도시 전체를 내려다보기 어려워 ✗","ático: '꼭대기 층 집' → 높아서 도시가 보여 정답 ✓","carro: '자동차'(중남미)로, 도시 전체를 내려다볼 수 없어 ✗","auto: '자동차'로, 도시 전체를 내려다볼 수 없어 ✗"]},{"id":"V42","q":"Para tener una salud de hierro, es ____ comer bien y hacer ejercicio físico.","o":["insignificante","ridículo","esencial","raro"],"a":2,"k":"형용사 어휘","t":"아주 튼튼한 건강을 가지려면, 잘 먹고 운동하는 것이 필수적이다.","e":"esencial은 '필수적인, 꼭 필요한'입니다. 'es esencial + 동사원형'은 '~하는 것이 필수다'라는 표현입니다. 'salud de hierro'는 직역하면 '철의 건강'으로, '아주 튼튼한 건강'을 뜻하는 관용 표현입니다.","x":["insignificante: '하찮은, 중요하지 않은'으로, 문맥과 반대라 ✗","ridículo: '우스꽝스러운'으로, 건강 조언과 맞지 않아 ✗","esencial: '필수적인' → 건강을 위한 조건이라 정답 ✓","raro: '이상한, 드문'으로, 문맥과 맞지 않아 ✗"]},{"id":"V43","q":"Prefiero entender lo que aprendo en vez de aprenderlo de ____.","o":["corazón","mente","cabeza","memoria"],"a":3,"k":"관용 표현","t":"나는 배우는 것을 외우기보다는 이해하는 것을 더 좋아한다.","e":"'aprender de memoria'는 '암기하다, 외우다'라는 고정 표현입니다. 'entender(이해하다)'와 대조됩니다. 'en vez de'는 '~하는 대신에'라는 뜻입니다. 영어의 'learn by heart'를 생각해 corazón을 고르지 않도록 주의하세요.","x":["corazón: '심장, 마음'으로, 스페인어에서는 이 표현에 쓰지 않아 ✗","mente: '정신'으로, 이 고정 표현에 쓰지 않아 ✗","cabeza: '머리'로, 이 고정 표현에 쓰지 않아 ✗","memoria: aprender de memoria(외우다) → 고정 표현으로 정답 ✓"]},{"id":"V44","q":"De nada sirvió que llegáramos dos horas antes al aeropuerto porque el vuelo salió con ____.","o":["lentitud","ventaja","retraso","puntualidad"],"a":2,"k":"여행 어휘","t":"비행기가 지연되어 출발했기 때문에, 우리가 공항에 두 시간 일찍 도착한 것은 아무 소용이 없었다.","e":"'salir con retraso'는 '늦게 출발하다, 지연되다'입니다. retraso는 '지연, 늦음'이라는 뜻입니다. 일찍 온 것이 소용없었다는 것은 비행기가 늦게 떠났기 때문입니다. 중남미에서는 retraso 대신 demora나 atraso도 많이 씁니다.","x":["lentitud: '느림'으로, 비행기 출발 지연을 나타내는 표현이 아니라 ✗","ventaja: '이점, 유리함'으로, 문맥과 맞지 않아 ✗","retraso: '지연' → 일찍 온 게 소용없던 이유라 정답 ✓","puntualidad: '정시성'으로, 제시간에 떠났다면 소용없다는 말이 성립하지 않아 ✗"]},{"id":"V45","q":"El trueno ____ tan fuerte que todos nos despertamos.","o":["silbó","chilló","gritó","sonó"],"a":3,"k":"소리 동사","t":"천둥이 너무 크게 울려서 우리 모두 잠에서 깼다.","e":"sonar는 '소리가 나다, 울리다'로, 사물이 내는 소리에 두루 씁니다. 천둥(trueno)은 사람이나 동물이 아니므로 소리를 '내다'라는 일반 동사 sonó가 가장 자연스럽습니다. 'tan ... que'는 '너무 ~해서 ...하다'라는 구문입니다.","x":["silbó: '휘파람을 불었다, 쌩쌩 소리 났다'로, 천둥소리에 맞지 않아 ✗","chilló: '비명을 질렀다, 끽끽거렸다'로, 천둥에 쓰지 않아 ✗","gritó: '소리쳤다'로, 사람이 하는 행동이라 ✗","sonó: '울렸다' → 천둥소리에 맞아 정답 ✓"]},{"id":"V46","q":"Las plantas ____ porque nadie las regó durante varias semanas.","o":["crecieron","se desarrollaron","se mojaron","se secaron"],"a":3,"k":"식물 동사","t":"몇 주 동안 아무도 물을 주지 않아서 식물들이 말라 버렸다.","e":"secarse는 '마르다, 시들다'입니다. regar는 '(식물에) 물을 주다'이므로 물을 주지 않으면 식물이 말라 버립니다. 재귀동사 secarse는 '스스로 마르다'라는 뜻으로 se가 함께 쓰입니다.","x":["crecieron: '자랐다'로, 물을 안 준 결과와 반대라 ✗","se desarrollaron: '성장했다'로, 문맥과 반대라 ✗","se mojaron: '젖었다'로, 물을 주지 않은 것과 모순이라 ✗","se secaron: '말랐다' → 물을 안 준 결과라 정답 ✓"]},{"id":"V47","q":"Algo que comí me ____ mal, me duele mucho el estómago.","o":["trajo","sentó","dio","creó"],"a":1,"k":"sentar mal","t":"내가 먹은 무언가가 탈이 났어, 배가 많이 아파.","e":"'sentar mal'은 음식이 '몸에 맞지 않다, 탈이 나다'라는 뜻의 표현입니다. gustar처럼 'me sienta mal(나에게 안 맞는다)' 구조로 씁니다. 반대로 'sentar bien'은 '몸에 잘 맞다, 어울리다'입니다. 예: El café me sienta mal.(커피는 나에게 안 맞는다.)","x":["trajo: '가져왔다'로, 'traer mal'이라는 표현은 없어 ✗","sentó: sentar mal '(음식이) 탈 나게 하다' → 고정 표현으로 정답 ✓","dio: '주었다'로, 'dar mal'은 이런 의미로 쓰지 않아 ✗","creó: '창조했다'로, 문맥과 맞지 않아 ✗"]},{"id":"V48","q":"¿Podrías ____ las plantas mientras estoy de viaje? Si no, van a secarse.","o":["barrer","fregar","regar","cortar"],"a":2,"k":"집안일 동사","t":"내가 여행하는 동안 식물에 물 좀 줄 수 있어? 안 그러면 말라 버릴 거야.","e":"regar는 '(식물에) 물을 주다'입니다. 불규칙 동사로 현재형은 riego, riegas, riega...처럼 e가 ie로 바뀝니다. 뒤의 'van a secarse(말라 버릴 것이다)'가 단서입니다.","x":["barrer: '(빗자루로) 쓸다'로, 식물에 하는 일이 아니라 ✗","fregar: '(설거지·걸레로) 닦다'로, 식물에 하는 일이 아니라 ✗","regar: '물을 주다' → 식물이 마르지 않게 하는 일이라 정답 ✓","cortar: '자르다'로, 식물이 마르는 것을 막지 못해 ✗"]},{"id":"V49","q":"Marzo es el ____ mes del año.","o":["sexto","octavo","quinto","tercer"],"a":3,"k":"서수","t":"3월은 한 해의 세 번째 달이다.","e":"서수 '세 번째'는 tercero인데, 남성 단수 명사 앞에서는 -o가 빠져 tercer가 됩니다(primero → primer도 마찬가지). mes(달)는 남성 명사이므로 'el tercer mes'가 맞습니다. 3월(marzo)은 세 번째 달이라는 의미적 단서도 확인하세요.","x":["sexto: '여섯 번째'로, 3월은 여섯 번째 달이 아니라 ✗","octavo: '여덟 번째'로, 3월에 맞지 않아 ✗","quinto: '다섯 번째'로, 3월에 맞지 않아 ✗","tercer: '세 번째'(남성 명사 앞 형태) → 정답 ✓"]},{"id":"V50","q":"Mi bisabuelo es el ____ de mi abuelo.","o":["suegro","hijo","padre","hermano"],"a":2,"k":"가족 어휘","t":"우리 증조할아버지는 우리 할아버지의 아버지이다.","e":"bisabuelo는 '증조할아버지'로, 할아버지(abuelo)의 아버지(padre)입니다. 접두사 bis-는 한 세대 위를 뜻합니다. 반대로 bisnieto는 '증손자'입니다.","x":["suegro: '시아버지, 장인'으로, 배우자의 아버지라 ✗","hijo: '아들'로, 세대 관계가 반대라 ✗","padre: '아버지' → 할아버지의 아버지가 증조할아버지라 정답 ✓","hermano: '형제'로, 같은 세대라 ✗"]},{"id":"V51","q":"Esta actriz está ____ al Óscar por su papel en la película que vimos anoche.","o":["elegida","escogida","candidata","nominada"],"a":3,"k":"영화 시상 어휘","t":"이 여배우는 어젯밤 우리가 본 영화의 역할로 오스카상 후보에 올랐다.","e":"'estar nominado/a a un premio'는 '~상 후보에 오르다'라는 표현입니다. nominar는 '후보로 지명하다'라는 뜻으로, 영화제·시상식에서 자주 씁니다. candidata도 '후보자'라는 뜻이지만 'candidata al Óscar'처럼 쓰며 'estar candidata'라고는 하지 않습니다.","x":["elegida: '선출된, 뽑힌'으로, 시상 후보를 나타내는 표현이 아니라 ✗","escogida: '선택된'으로, 상의 후보를 나타내는 표현이 아니라 ✗","candidata: '후보자'(명사)로, estar와 함께 이렇게 쓰지 않아 ✗","nominada: '후보에 오른' → estar nominada al Óscar로 정답 ✓"]},{"id":"V52","q":"Hace mucho frío, vamos a sentarnos cerca de la ____.","o":["silla","mesa","alfombra","chimenea"],"a":3,"k":"집 어휘","t":"너무 추워, 벽난로 가까이에 앉자.","e":"chimenea는 '벽난로'(또는 굴뚝)입니다. 'Hace mucho frío(아주 춥다)'라는 단서가 있으므로 따뜻한 곳 근처에 앉자는 말이 자연스럽습니다.","x":["silla: '의자'로, 추위를 피하는 장소가 아니라 ✗","mesa: '탁자'로, 추위와 관련이 없어 ✗","alfombra: '양탄자, 카펫'으로, 열을 내지 않아 ✗","chimenea: '벽난로' → 추울 때 가까이 앉는 곳이라 정답 ✓"]},{"id":"V53","q":"Antes de viajar en barco, necesito una ____ para el mareo.","o":["pomada","pastilla","loción","crema"],"a":1,"k":"의약품 어휘","t":"배를 타고 여행하기 전에 멀미약 한 알이 필요하다.","e":"pastilla는 '알약'입니다. 'pastilla para el mareo(멀미약)'처럼 'para + 증상'으로 약의 용도를 말합니다. mareo는 '멀미, 어지럼증'입니다.","x":["pomada: '연고'로, 바르는 약이라 멀미에 쓰지 않아 ✗","pastilla: '알약' → 멀미약은 먹는 약이라 정답 ✓","loción: '로션'으로, 멀미에 쓰지 않아 ✗","crema: '크림'으로, 바르는 것이라 멀미에 쓰지 않아 ✗"]},{"id":"V54","q":"No quiero seguir trabajando aquí, el jefe es ____.","o":["leal","afortunado","insoportable","competente"],"a":2,"k":"성격 형용사","t":"여기서 계속 일하고 싶지 않아, 상사가 견딜 수 없을 정도야.","e":"insoportable은 '견딜 수 없는, 참을 수 없는'입니다. soportar(견디다)에 부정 접두사 in-과 '가능'을 나타내는 -able이 붙은 말입니다. 그만두고 싶은 이유로 부정적인 성격이 와야 합니다.","x":["leal: '충실한, 의리 있는'으로, 긍정적이라 그만둘 이유가 아니라 ✗","afortunado: '운이 좋은'으로, 그만둘 이유가 아니라 ✗","insoportable: '견딜 수 없는' → 그만두고 싶은 이유라 정답 ✓","competente: '유능한'으로, 긍정적이라 문맥과 맞지 않아 ✗"]},{"id":"V55","q":"Te ____ muy bien el pintalabios rosa.","o":["queda","toma","toca","sirve"],"a":0,"k":"quedar 구문","t":"분홍색 립스틱이 너에게 아주 잘 어울려.","e":"'quedar bien/mal a alguien'은 '(옷·색 등이) ~에게 잘 어울리다/안 어울리다'라는 표현입니다. gustar처럼 간접목적격 대명사(te: 너에게)를 씁니다. pintalabios는 '립스틱'입니다. 예: Esa camisa te queda grande.(그 셔츠는 너에게 커.)","x":["queda: quedar bien '잘 어울리다' → 정답 ✓","toma: '마시다, 잡다'로, 어울림을 나타내지 않아 ✗","toca: '만지다, 차례이다'로, 어울림을 나타내지 않아 ✗","sirve: '쓸모 있다'로, 외모의 어울림을 나타내지 않아 ✗"]},{"id":"V56","q":"Mi abuelo usa un ____ para apoyarse cuando anda.","o":["casco","gorro","maletín","bastón"],"a":3,"k":"사물 어휘","t":"우리 할아버지는 걸을 때 지팡이를 짚으신다.","e":"bastón은 '지팡이'입니다. 'para apoyarse cuando anda(걸을 때 몸을 기대려고)'라는 단서가 있습니다. apoyarse는 '~에 기대다, 의지하다'라는 재귀동사입니다.","x":["casco: '헬멧'으로, 몸을 지탱하지 못해 ✗","gorro: '모자'로, 걸을 때 기대는 도구가 아니라 ✗","maletín: '서류 가방'으로, 몸을 지탱하지 못해 ✗","bastón: '지팡이' → 걸을 때 기대는 도구라 정답 ✓"]},{"id":"V57","q":"Si no te ____ prisa, llegaremos tarde.","o":["tomas","haces","pones","das"],"a":3,"k":"darse prisa","t":"서두르지 않으면 우리는 늦을 거야.","e":"'darse prisa'는 '서두르다'라는 고정 표현으로, 재귀대명사(te)와 동사 dar를 씁니다. 같은 뜻으로 apurarse가 있는데, 중남미에서 훨씬 많이 씁니다(¡Apúrate!). 예: ¡Date prisa!(서둘러!)","x":["tomas: tomar로는 이 표현을 만들지 않아 ✗","haces: hacer로는 이 표현을 만들지 않아 ✗","pones: ponerse prisa는 표준적인 표현이 아니라 ✗","das: darse prisa(서두르다) → 고정 표현으로 정답 ✓"]},{"id":"V58","q":"La paella está sosa, le ____ sal.","o":["falta","sobra","queda","resta"],"a":0,"k":"faltar 구문","t":"파에야가 싱거워, 소금이 부족해.","e":"faltar는 '부족하다, 모자라다'로, gustar처럼 'le falta + 명사' 구조로 씁니다. soso/sosa는 '싱거운'이라는 뜻이므로 소금이 부족하다는 말이 자연스럽습니다. 반대로 sobrar는 '남다, 넘치다'입니다.","x":["falta: faltar '부족하다' → 싱거운 이유라 정답 ✓","sobra: sobrar '남다, 너무 많다'로, 싱거운 것과 반대라 ✗","queda: quedar '남아 있다'로, 싱거운 이유를 설명하지 못해 ✗","resta: restar '빼다, 남다'로, 이 문맥에서 쓰지 않아 ✗"]},{"id":"V59","q":"Claro que conozco ese restaurante, es uno de los más ____ de la ciudad.","o":["simples","corrientes","conocidos","normales"],"a":2,"k":"형용사 어휘","t":"물론 그 식당 알지, 도시에서 가장 유명한 곳 중 하나야.","e":"conocido는 '잘 알려진, 유명한'입니다. 앞의 'Claro que conozco(물론 알지)'와 자연스럽게 연결됩니다. 'uno de los más + 형용사'는 '가장 ~한 것 중 하나'라는 최상급 표현입니다.","x":["simples: '단순한'으로, 알고 있다는 이유와 연결되지 않아 ✗","corrientes: '평범한, 흔한'으로, 최상급과 어색해서 ✗","conocidos: '유명한' → 알고 있다는 말과 연결되어 정답 ✓","normales: '보통의'로, 최상급과 어색하고 문맥과 맞지 않아 ✗"]},{"id":"V60","q":"Oceanía es un ____.","o":["continente","país","pueblo","estado"],"a":0,"k":"지리 어휘","t":"오세아니아는 대륙이다.","e":"continente는 '대륙'입니다. 오세아니아는 호주·뉴질랜드 등 여러 나라를 포함하는 대륙입니다. 스페인어권에서는 보통 다섯 대륙(América, Europa, Asia, África, Oceanía)으로 나누어 가르칩니다.","x":["continente: '대륙' → 오세아니아에 맞아 정답 ✓","país: '나라'로, 오세아니아는 여러 나라를 포함해 ✗","pueblo: '마을, 민족'으로, 오세아니아에 맞지 않아 ✗","estado: '주(州), 국가'로, 오세아니아에 맞지 않아 ✗"]},{"id":"V61","q":"Ese es el ____ que diseñó aquel edificio.","o":["albañil","fontanero","arquitecto","mecánico"],"a":2,"k":"직업 어휘","t":"저 사람이 저 건물을 설계한 건축가이다.","e":"arquitecto는 '건축가'입니다. 'diseñar un edificio(건물을 설계하다)'는 건축가의 일입니다. 건물을 실제로 짓는 사람은 albañil(벽돌공, 건설 인부)이라는 점과 구별하세요.","x":["albañil: '벽돌공, 건설 인부'로, 건물을 짓지만 설계하지는 않아 ✗","fontanero: '배관공'으로, 건물 설계와 관련이 없어 ✗","arquitecto: '건축가' → 건물을 설계하는 사람이라 정답 ✓","mecánico: '정비사'로, 건물 설계와 관련이 없어 ✗"]},{"id":"V62","q":"Ten cuidado cuando salgas. Hay hielo en las calles y te puedes ____.","o":["caer","levantar","marear","acostar"],"a":0,"k":"동사 어휘","t":"나갈 때 조심해. 거리에 얼음이 있어서 넘어질 수 있어.","e":"caer(se)는 '넘어지다, 떨어지다'입니다. 'te puedes caer'에서 te는 재귀대명사로, 'puedes caerte'라고 써도 같은 뜻입니다. 얼음(hielo) 때문에 미끄러져 넘어질 위험이 있다는 문맥입니다.","x":["caer: '넘어지다' → 얼음 때문에 생길 위험이라 정답 ✓","levantar: '일어나다, 들어 올리다'로, 위험을 나타내지 않아 ✗","marear: '어지럽다, 멀미하다'로, 얼음과 관련이 없어 ✗","acostar: '눕다, 잠자리에 들다'로, 문맥과 맞지 않아 ✗"]},{"id":"V63","q":"¿Te apetece que vayamos a la ____ de fotografía de ese museo?","o":["venta","revisión","exposición","compra"],"a":2,"k":"문화 어휘","t":"그 박물관의 사진 전시회에 같이 갈래?","e":"exposición는 '전시회'입니다. museo(박물관, 미술관)에서 열리는 'exposición de fotografía(사진전)'가 자연스럽습니다. '¿Te apetece + que + 접속법?'은 '~하고 싶니?'라는 스페인식 권유 표현입니다(중남미에서는 '¿Tienes ganas de...?'를 더 많이 씀).","x":["venta: '판매'로, 박물관에서 사진을 보러 가는 행사가 아니라 ✗","revisión: '검토, 점검'으로, 문맥과 맞지 않아 ✗","exposición: '전시회' → 박물관 사진전이라 정답 ✓","compra: '구매'로, 박물관 행사가 아니라 ✗"]},{"id":"V64","q":"No me gusta cómo me deja el pelo este ____.","o":["perfume","detergente","gel","champú"],"a":3,"k":"위생용품 어휘","t":"이 샴푸가 내 머리를 해 놓는 상태가 마음에 안 들어.","e":"champú는 '샴푸'입니다. 머리카락(pelo)에 직접 쓰는 제품이므로 가장 자연스럽습니다. 'dejar + 목적어 + 상태'는 '~을 어떤 상태로 만들다'라는 표현입니다. 예: Este champú me deja el pelo suave.(이 샴푸를 쓰면 머리가 부드러워진다.)","x":["perfume: '향수'로, 머리카락 상태를 바꾸는 제품이 아니라 ✗","detergente: '세제'로, 머리에 쓰지 않아 ✗","gel: '샤워젤(헤어젤)'로, 머리를 감는 대표 제품이 아니라 ✗","champú: '샴푸' → 머리카락에 쓰는 제품이라 정답 ✓"]},{"id":"V65","q":"Mi hermana es vegana, no come nada de origen ____.","o":["local","animal","desconocido","vegetal"],"a":1,"k":"음식 어휘","t":"우리 언니는 비건이라서 동물성 식품은 전혀 먹지 않는다.","e":"'de origen animal'은 '동물에서 나온, 동물성의'라는 뜻입니다. vegano/vegana(비건)는 고기뿐 아니라 우유·달걀 등 동물에서 나온 모든 것을 먹지 않는 사람입니다. 'nada de'는 '전혀 ~ 않다'는 강조 표현입니다.","x":["local: '지역의'로, 비건이 피하는 음식 기준이 아니라 ✗","animal: '동물성의' → 비건이 먹지 않는 것이라 정답 ✓","desconocido: '알 수 없는'으로, 비건의 정의와 관련이 없어 ✗","vegetal: '식물성의'로, 비건은 오히려 이것을 먹어서 ✗"]},{"id":"V66","q":"Suelo lavar ____ las prendas más delicadas porque en la lavadora se estropean.","o":["de cabeza","a mano","a pie","a ojo"],"a":1,"k":"관용 표현","t":"가장 섬세한 옷은 세탁기에서 상하기 때문에 나는 보통 손으로 빨래한다.","e":"'a mano'는 '손으로'라는 뜻입니다. 'lavar a mano(손빨래하다)', 'hecho a mano(수제의)'처럼 씁니다. 다른 보기들도 모두 a/de로 만드는 관용 표현이니 함께 외워 두세요.","x":["de cabeza: '거꾸로, 머리부터'로, 빨래 방법이 아니라 ✗","a mano: '손으로' → 손빨래라 정답 ✓","a pie: '걸어서'로, 빨래와 관련이 없어 ✗","a ojo: '눈대중으로'로, 빨래 방법이 아니라 ✗"]},{"id":"V67","q":"México es un país ____, no es pequeño en absoluto.","o":["chico","habitado","extenso","superpoblado"],"a":2,"k":"형용사 어휘","t":"멕시코는 넓은 나라이고, 전혀 작지 않다.","e":"extenso는 '넓은, 광대한'입니다. 뒤의 'no es pequeño en absoluto(전혀 작지 않다)'가 단서입니다. 'en absoluto'는 부정문에서 '전혀'라는 뜻입니다.","x":["chico: '작은'(중남미에서 자주 씀)으로, 뒤의 내용과 반대라 ✗","habitado: '사람이 사는'으로, 크기를 나타내지 않아 ✗","extenso: '넓은' → 작지 않다는 내용과 일치해 정답 ✓","superpoblado: '인구 과밀의'로, 면적을 나타내지 않아 ✗"]},{"id":"V68","q":"He comprado unas ____ preciosas en la floristería de la esquina.","o":["sandías","rosas","pulseras","carteras"],"a":1,"k":"꽃 어휘","t":"모퉁이 꽃집에서 아주 예쁜 장미를 몇 송이 샀다.","e":"rosa는 '장미'입니다. floristería(꽃집)에서 사는 물건이므로 꽃이 와야 합니다. -ería는 가게를 나타내는 접미사로 panadería(빵집), frutería(과일 가게)처럼 씁니다.","x":["sandías: '수박'으로, 꽃집에서 팔지 않아 ✗","rosas: '장미' → 꽃집에서 파는 꽃이라 정답 ✓","pulseras: '팔찌'로, 꽃집에서 팔지 않아 ✗","carteras: '지갑'으로, 꽃집에서 팔지 않아 ✗"]},{"id":"V69","q":"Hoy me ____ a mí limpiar el baño, ayer lo hiciste tú.","o":["pasa","da","toca","toma"],"a":2,"k":"tocar 구문","t":"오늘은 내가 욕실을 청소할 차례야, 어제는 네가 했잖아.","e":"tocar는 gustar처럼 쓰면 '~의 차례이다'라는 뜻입니다. 'Me toca a mí + 동사원형'은 '이번엔 내가 ~할 차례다'입니다. 'ayer lo hiciste tú(어제는 네가 했다)'가 단서입니다. 예: ¿A quién le toca?(누구 차례야?)","x":["pasa: '일어나다, 지나가다'로, 차례의 의미가 아니라 ✗","da: '주다'로, 차례의 의미가 아니라 ✗","toca: tocar '~의 차례이다' → 정답 ✓","toma: '잡다, 마시다'로, 차례의 의미가 아니라 ✗"]},{"id":"V70","q":"Prefiero dormir a oscuras, me molesta mucho ____.","o":["el calor","el ruido","la luz","la oscuridad"],"a":2,"k":"명사 어휘","t":"나는 어두운 곳에서 자는 것이 좋다, 빛이 아주 거슬린다.","e":"luz는 '빛, 불빛'입니다. 'dormir a oscuras(어둠 속에서 자다)'를 좋아하는 이유는 빛이 거슬리기 때문입니다. molestar는 gustar처럼 쓰는 동사로 '~에게 거슬리다, 성가시다'라는 뜻입니다.","x":["el calor: '더위'로, 어둠 속에서 자는 이유와 직접 연결되지 않아 ✗","el ruido: '소음'으로, 어둠과 관련이 없어 ✗","la luz: '빛' → 어두운 곳을 좋아하는 이유라 정답 ✓","la oscuridad: '어둠'으로, 어두운 곳을 좋아한다는 말과 모순이라 ✗"]},{"id":"V71","q":"No sé qué voy a estudiar cuando termine el bachillerato. Todavía no lo ____ claro.","o":["tomo","tengo","recuerdo","concluyo"],"a":1,"k":"tener claro","t":"고등학교를 마치면 무엇을 공부할지 모르겠어. 아직 확실하게 정하지 못했어.","e":"'tener claro algo'는 '~이 확실하다, 분명히 알고 있다'라는 표현입니다. 'no lo tengo claro'는 '확실하지 않다, 아직 잘 모르겠다'라는 뜻입니다. bachillerato는 스페인의 고등학교 과정(대학 진학 전 2년)을 말합니다.","x":["tomo: tomar로는 이 표현을 만들지 않아 ✗","tengo: tener claro '확실하다' → 고정 표현으로 정답 ✓","recuerdo: recordar '기억하다'로, 'claro'와 함께 쓰지 않아 ✗","concluyo: concluir '결론 내리다'로, 이 표현에 쓰지 않아 ✗"]},{"id":"V72","q":"¿Cuántos Roland Garros ____ Rafa Nadal?","o":["imaginó","guardó","creó","ganó"],"a":3,"k":"스포츠 동사","t":"라파 나달은 롤랑가로스(프랑스 오픈)에서 몇 번 우승했나요?","e":"ganar는 '이기다, 우승하다, (상을) 따다'입니다. 대회 이름과 함께 쓰면 '그 대회에서 우승하다'라는 뜻이 됩니다. Roland Garros는 테니스 대회이고 나달은 스페인의 유명한 테니스 선수입니다.","x":["imaginó: '상상했다'로, 대회와 함께 쓰지 않아 ✗","guardó: '보관했다'로, 대회 우승을 나타내지 않아 ✗","creó: '창조했다'로, 대회를 만든 것이 아니라 ✗","ganó: '우승했다' → 대회 우승 횟수를 묻는 문장이라 정답 ✓"]},{"id":"V73","q":"Este año hay poquísima nieve, así que no podemos ____.","o":["correr","esquiar","nadar","saltar"],"a":1,"k":"스포츠 동사","t":"올해는 눈이 아주 적어서 스키를 탈 수 없다.","e":"esquiar는 '스키를 타다'입니다. 'poquísima nieve(아주 적은 눈)'가 단서로, 눈이 없으면 할 수 없는 활동입니다. poquísimo는 poco에 -ísimo를 붙인 절대 최상급(아주 ~한)으로, c가 qu로 바뀝니다.","x":["correr: '달리다'로, 눈이 없어도 할 수 있어 ✗","esquiar: '스키를 타다' → 눈이 필요해 정답 ✓","nadar: '수영하다'로, 눈과 관련이 없어 ✗","saltar: '뛰다, 점프하다'로, 눈과 관련이 없어 ✗"]},{"id":"V74","q":"Es normal que haya más ____ en las zonas industriales.","o":["contaminación","naturaleza","concentración","aire fresco"],"a":0,"k":"환경 어휘","t":"공업 지역에 오염이 더 많은 것은 당연하다.","e":"contaminación는 '오염'입니다. 'zonas industriales(공업 지역)'에는 공장이 많아 대기·물 오염이 심한 것이 자연스럽습니다. 'Es normal que + 접속법(판단을 나타낼 때 쓰는 동사 형태)'이라서 haya가 쓰였습니다.","x":["contaminación: '오염' → 공업 지역의 특징이라 정답 ✓","naturaleza: '자연'으로, 공업 지역에 더 많지 않아 ✗","concentración: '집중, 농도'로, 무엇의 농도인지 없어 의미가 불분명해 ✗","aire fresco: '신선한 공기'로, 공업 지역과 반대라 ✗"]},{"id":"V75","q":"Feliciano es un hombre muy ____, todos se ríen con sus chistes.","o":["impaciente","serio","triste","divertido"],"a":3,"k":"성격 형용사","t":"펠리시아노는 아주 재미있는 사람이라서, 모두가 그의 농담에 웃는다.","e":"divertido는 '재미있는, 유쾌한'입니다. 'todos se ríen con sus chistes(모두가 그의 농담에 웃는다)'가 단서입니다. 반대말은 aburrido(지루한)입니다.","x":["impaciente: '참을성 없는'으로, 농담과 관련이 없어 ✗","serio: '진지한'으로, 사람들이 웃는 것과 반대라 ✗","triste: '슬픈'으로, 사람들을 웃기는 것과 맞지 않아 ✗","divertido: '재미있는' → 농담으로 웃기는 사람이라 정답 ✓"]},{"id":"V76","q":"¿Cuántas naranjas necesitaste ____ para el zumo de los chicos?","o":["exprimir","cortar","pelar","hervir"],"a":0,"k":"요리 동사","t":"아이들 주스를 만들려고 오렌지를 몇 개 짜야 했어?","e":"exprimir는 '(과즙을) 짜다'입니다. zumo(주스, 스페인어)를 만들려면 오렌지를 짜야 합니다. 'zumo de naranja exprimido(생오렌지 주스)'처럼 씁니다. 중남미에서는 주스를 jugo라고 합니다.","x":["exprimir: '짜다' → 오렌지 주스를 만드는 방법이라 정답 ✓","cortar: '자르다'로, 자르기만 해서는 주스가 되지 않아 ✗","pelar: '껍질을 벗기다'로, 주스를 만드는 핵심 동작이 아니라 ✗","hervir: '끓이다'로, 주스를 만드는 방법이 아니라 ✗"]},{"id":"V77","q":"La profesora me ____ por no haber hecho los deberes.","o":["sonrió","regañó","premió","felicitó"],"a":1,"k":"동사 어휘","t":"숙제를 하지 않아서 선생님이 나를 꾸짖으셨다.","e":"regañar는 '꾸짖다, 야단치다'입니다. 'por no haber hecho los deberes(숙제를 하지 않아서)'라는 이유가 부정적이므로 꾸중이 맞습니다. 'por + haber + 과거분사'는 '~했기 때문에'라는 표현입니다. 중남미에서는 retar, rezongar 등도 씁니다.","x":["sonrió: '미소 지었다'로, 숙제를 안 한 이유와 맞지 않아 ✗","regañó: '꾸짖었다' → 숙제를 안 한 결과라 정답 ✓","premió: '상을 주었다'로, 문맥과 반대라 ✗","felicitó: '축하했다, 칭찬했다'로, 문맥과 반대라 ✗"]},{"id":"V78","q":"No veo películas de terror porque soy muy ____.","o":["miedosa","curiosa","cotilla","valiente"],"a":0,"k":"성격 형용사","t":"나는 겁이 아주 많아서 공포 영화를 안 본다.","e":"miedoso/miedosa는 '겁이 많은'입니다. miedo(두려움)에 -oso를 붙여 만든 형용사입니다. 공포 영화(películas de terror)를 보지 않는 이유로 자연스럽습니다. 반대말은 valiente(용감한)입니다.","x":["miedosa: '겁 많은' → 공포 영화를 안 보는 이유라 정답 ✓","curiosa: '호기심 많은'으로, 오히려 영화를 볼 이유라 ✗","cotilla: '(스페인 구어) 남의 얘기 좋아하는'으로, 문맥과 관련이 없어 ✗","valiente: '용감한'으로, 공포 영화를 안 보는 이유와 반대라 ✗"]},{"id":"V79","q":"Llevo ____ porque no veo bien de lejos.","o":["pañuelos","collares","anteojos","pulseras"],"a":2,"k":"사물 어휘","t":"나는 멀리 있는 게 잘 안 보여서 안경을 쓴다.","e":"anteojos는 '안경'으로, 중남미에서 많이 쓰는 단어입니다. 스페인에서는 주로 gafas, 일부 나라에서는 lentes라고 합니다. 'no veo bien de lejos(멀리 잘 안 보인다)'가 단서입니다. 착용할 때는 llevar 동사를 씁니다.","x":["pañuelos: '손수건, 스카프'로, 시력과 관련이 없어 ✗","collares: '목걸이'로, 시력과 관련이 없어 ✗","anteojos: '안경' → 시력이 나쁠 때 쓰는 것이라 정답 ✓","pulseras: '팔찌'로, 시력과 관련이 없어 ✗"]},{"id":"V80","q":"Mi abuelo ____ la escuela cuando tenía trece años porque tenía que trabajar.","o":["dejó","hizo","construyó","vio"],"a":0,"k":"dejar 의미","t":"우리 할아버지는 일을 해야 했기 때문에 열세 살 때 학교를 그만두셨다.","e":"dejar는 '그만두다, 떠나다'라는 뜻이 있습니다. 'dejar la escuela/los estudios(학교/학업을 그만두다)'처럼 씁니다. 'porque tenía que trabajar(일해야 했기 때문에)'라는 이유가 단서입니다.","x":["dejó: '그만두었다' → 일 때문에 학교를 그만둔 문맥이라 정답 ✓","hizo: '했다, 만들었다'로, 학교와 함께 쓰면 의미가 맞지 않아 ✗","construyó: '지었다'로, 일해야 했다는 이유와 맞지 않아 ✗","vio: '보았다'로, 문맥과 맞지 않아 ✗"]},{"id":"V81","q":"No puedo creerlo. ¡Te has comido toda la ____ de chocolate!","o":["tableta","botella","onza","lata"],"a":0,"k":"단위 명사","t":"믿을 수가 없어. 초콜릿 한 판을 다 먹어 버렸구나!","e":"tableta는 '(초콜릿의) 판'입니다. 'toda la tableta(한 판 전체)'를 다 먹었다는 것이 놀라운 이유입니다. onza는 초콜릿 판의 '한 칸'을 뜻하므로 '전부'라는 의미와 어울리지 않습니다.","x":["tableta: '(초콜릿) 판' → 한 판을 다 먹은 것이라 정답 ✓","botella: '병'으로, 초콜릿에 쓰지 않아 ✗","onza: '(초콜릿 판의) 한 칸'으로, toda와 함께 놀라움을 주기엔 맞지 않아 ✗","lata: '캔'으로, 판 초콜릿에 쓰지 않아 ✗"]},{"id":"V82","q":"Cuando haya más nieve, iremos a esquiar a la ____.","o":["selva","granja","jungla","sierra"],"a":3,"k":"지형 어휘","t":"눈이 더 많이 오면 산에 스키 타러 가자.","e":"sierra는 '산맥, 산악 지대'입니다. 스페인에서는 'ir a la sierra'가 '산에 가다'라는 뜻으로 흔히 쓰입니다(예: Sierra Nevada). 'Cuando + 접속법(haya)'은 미래의 일을 말할 때 씁니다.","x":["selva: '정글, 밀림'으로, 눈이 오는 곳이 아니라 ✗","granja: '농장'으로, 스키를 타는 곳이 아니라 ✗","jungla: '정글'로, 눈과 관련이 없어 ✗","sierra: '산악 지대' → 스키를 타는 곳이라 정답 ✓"]},{"id":"V83","q":"Ten cuidado cuando cortes la rosa, puedes pincharte con ____.","o":["el tallo","las raíces","los pétalos","las espinas"],"a":3,"k":"식물 어휘","t":"장미를 자를 때 조심해, 가시에 찔릴 수 있어.","e":"espina는 '가시'입니다. pincharse는 '(뾰족한 것에) 찔리다'라는 재귀동사로, 장미 가시에 찔린다는 내용입니다. 꽃의 부분 이름도 함께 외워 두세요: tallo(줄기), raíz(뿌리), pétalo(꽃잎).","x":["el tallo: '줄기'로, 그 자체로 찌르지 않아 ✗","las raíces: '뿌리'로, 땅속에 있어 찔리지 않아 ✗","los pétalos: '꽃잎'으로, 부드러워 찔리지 않아 ✗","las espinas: '가시' → 찔리는 부분이라 정답 ✓"]},{"id":"V84","q":"Es ____ que, siendo una familia numerosa, os llevéis tan bien.","o":["patético","penoso","extraordinario","extendible"],"a":2,"k":"형용사 어휘","t":"대가족인데도 너희가 그렇게 사이좋게 지내는 건 대단한 일이야.","e":"extraordinario는 '대단한, 놀라운, 특별한'입니다. 'familia numerosa(대가족)'는 갈등이 생기기 쉬운데도 사이가 좋다는 것은 칭찬할 만한 일입니다. 'llevarse bien'은 '사이좋게 지내다'이고, 'Es + 형용사 + que + 접속법' 구조라서 llevéis가 쓰였습니다(vosotros 형태는 스페인에서만 사용).","x":["patético: '한심한, 비참한'으로, 사이좋은 것에 대한 평가로 맞지 않아 ✗","penoso: '유감스러운, 안타까운'으로, 긍정적 내용과 맞지 않아 ✗","extraordinario: '대단한' → 칭찬하는 문맥이라 정답 ✓","extendible: '늘릴 수 있는'으로, 의미가 맞지 않아 ✗"]},{"id":"V85","q":"En esta ____ hay unos dulces deliciosos.","o":["pastelería","charcutería","herboristería","carnicería"],"a":0,"k":"상점 어휘","t":"이 제과점에는 아주 맛있는 단것들이 있다.","e":"pastelería는 '제과점, 케이크 가게'입니다. dulces(단것, 과자, 디저트)를 파는 곳으로 가장 자연스럽습니다. 가게 이름의 -ería를 기억하세요: charcutería(햄·소시지 가게), carnicería(정육점), herboristería(약초 가게).","x":["pastelería: '제과점' → 단것을 파는 곳이라 정답 ✓","charcutería: '햄·소시지 가게'로, 단것을 주로 팔지 않아 ✗","herboristería: '약초 가게'로, 디저트를 팔지 않아 ✗","carnicería: '정육점'으로, 단것을 팔지 않아 ✗"]},{"id":"V86","q":"Quiere ganar más dinero, no se conforma con su ____.","o":["peso","sueldo","apariencia","cuerpo"],"a":1,"k":"직장 어휘","t":"그는 돈을 더 벌고 싶어 해서, 자기 월급에 만족하지 않는다.","e":"sueldo는 '월급, 급여'입니다. 'ganar más dinero(돈을 더 벌다)'가 단서입니다. 'conformarse con algo'는 '~에 만족하다, 그 정도로 받아들이다'라는 표현입니다. 비슷한 말로 salario가 있습니다.","x":["peso: '몸무게'로, 돈을 더 벌고 싶은 것과 관련이 없어 ✗","sueldo: '월급' → 돈을 더 벌고 싶다는 문맥에 맞아 정답 ✓","apariencia: '외모'로, 돈과 관련이 없어 ✗","cuerpo: '몸'으로, 돈과 관련이 없어 ✗"]},{"id":"V87","q":"Este no es el examen real, es simplemente un ____ para que estén mejor preparados.","o":["proyecto","ensayo","propósito","deseo"],"a":1,"k":"명사 어휘","t":"이것은 실제 시험이 아니라, 여러분이 더 잘 준비하도록 하는 연습(모의시험)일 뿐입니다.","e":"ensayo는 '연습, 리허설, 모의시험'이라는 뜻입니다. 'no es el examen real(실제 시험이 아니다)'라는 단서가 있습니다. ensayo는 '수필, 에세이'라는 뜻도 있으니 함께 알아 두세요. 'para que + 접속법'이라서 estén이 쓰였습니다.","x":["proyecto: '프로젝트, 계획'으로, 연습 시험을 뜻하지 않아 ✗","ensayo: '연습, 리허설' → 실제 시험 전 연습이라 정답 ✓","propósito: '목적'으로, 시험의 종류가 아니라 ✗","deseo: '바람, 소망'으로, 문맥과 맞지 않아 ✗"]},{"id":"V88","q":"La ____ de la segunda planta es muy cotilla.","o":["nuera","suegra","nieta","vecina"],"a":3,"k":"사람 어휘","t":"2층에 사는 이웃 여자는 남 얘기하기를 아주 좋아한다.","e":"vecina는 '이웃(여성)'입니다. 'de la segunda planta(2층의)'는 건물의 층을 나타내므로 같은 건물에 사는 이웃이 가장 자연스럽습니다. cotilla는 스페인 구어로 '남의 일에 참견하고 소문 내기 좋아하는 사람'입니다(중남미에서는 chismoso/a).","x":["nuera: '며느리'로, 층으로 소개하는 사람이 아니라 ✗","suegra: '시어머니, 장모'로, 층으로 소개하는 사람이 아니라 ✗","nieta: '손녀'로, 층으로 소개하는 사람이 아니라 ✗","vecina: '이웃' → 같은 건물 2층에 사는 사람이라 정답 ✓"]},{"id":"V89","q":"____ varias veces a la empresa de transportes, pero la línea está ocupada.","o":["He llamado","He contratado","He compensado","He seguido"],"a":0,"k":"전화 어휘","t":"운송 회사에 여러 번 전화했는데, 계속 통화 중이야.","e":"llamar는 '전화하다'입니다. 'la línea está ocupada(통화 중이다)'라는 단서가 전화와 관련됩니다. 'He llamado'는 현재완료(최근까지의 일을 나타내는 시제)로, 'varias veces(여러 번)'와 잘 어울립니다.","x":["He llamado: '전화했다' → 통화 중이라는 내용과 맞아 정답 ✓","He contratado: '계약했다, 고용했다'로, 통화 중과 연결되지 않아 ✗","He compensado: '보상했다'로, 문맥과 맞지 않아 ✗","He seguido: '따라갔다, 계속했다'로, 문맥과 맞지 않아 ✗"]},{"id":"V90","q":"En época de ____ hay unos descuentos increíbles.","o":["vacaciones","exámenes","rebajas","festividades"],"a":2,"k":"쇼핑 어휘","t":"세일 기간에는 엄청난 할인이 있다.","e":"rebajas는 '세일, 할인 판매(기간)'입니다. descuentos(할인)와 직접 연결됩니다. 스페인에서는 보통 1월과 7월에 'época de rebajas(세일 시즌)'가 있습니다. 중남미에서는 ofertas, liquidación 등을 많이 씁니다.","x":["vacaciones: '휴가'로, 할인과 직접 관련이 없어 ✗","exámenes: '시험'으로, 할인과 관련이 없어 ✗","rebajas: '세일' → 할인이 있는 시기라 정답 ✓","festividades: '축제, 명절'로, 할인과 직접 관련된 말이 아니라 ✗"]},{"id":"V91","q":"Me compré un ____ de pelo demasiado oscuro y he pasado de rubia a morena en un momento.","o":["cepillo","peine","tinte","secador"],"a":2,"k":"미용 어휘","t":"머리 염색약을 너무 어두운 걸 사서, 금발에서 순식간에 갈색 머리가 됐어.","e":"tinte는 '염색약'입니다. 'tinte de pelo(머리 염색약)'로 쓰며 teñir(염색하다)와 같은 어근입니다. 머리 색이 rubia(금발)에서 morena(갈색·검은 머리)로 바뀌었다는 것이 단서입니다. 'pasar de A a B'는 'A에서 B로 바뀌다'라는 표현입니다.","x":["cepillo: '빗(브러시)'으로, 머리 색을 바꾸지 못해 ✗","peine: '빗(참빗)'으로, 머리 색을 바꾸지 못해 ✗","tinte: '염색약' → 머리 색이 바뀐 이유라 정답 ✓","secador: '헤어드라이어'로, 머리 색을 바꾸지 못해 ✗"]},{"id":"V92","q":"Para mí, lo mejor es ir a mi trabajo a pie, no me gusta usar ningún ____ de transporte.","o":["elemento","medio","objeto","entorno"],"a":1,"k":"교통 어휘","t":"나에게는 걸어서 출근하는 게 최고야, 어떤 교통수단도 이용하고 싶지 않아.","e":"'medio de transporte'는 '교통수단'이라는 고정 표현입니다. medio는 '수단, 방법'이라는 뜻으로 'medios de comunicación(대중매체)'처럼도 씁니다. 'a pie'는 '걸어서'입니다.","x":["elemento: '요소'로, 교통수단을 나타내는 표현에 쓰지 않아 ✗","medio: medio de transporte(교통수단) → 고정 표현으로 정답 ✓","objeto: '물건'으로, 이 표현에 쓰지 않아 ✗","entorno: '환경, 주변'으로, 이 표현에 쓰지 않아 ✗"]},{"id":"V93","q":"Nadie quiere hablar con el vecino del quinto, es un tipo muy ____.","o":["antipático","agradable","paciente","amable"],"a":0,"k":"성격 형용사","t":"아무도 5층 이웃과 말하고 싶어 하지 않아, 아주 불친절한 사람이거든.","e":"antipático는 '불친절한, 정이 안 가는'입니다. 'Nadie quiere hablar con él(아무도 그와 말하고 싶지 않다)'이라는 부정적 결과의 이유가 됩니다. 반대말은 simpático(상냥한, 호감 가는)입니다. 'del quinto'는 'del quinto piso(5층의)'를 줄인 말입니다.","x":["antipático: '불친절한' → 아무도 말하고 싶어 하지 않는 이유라 정답 ✓","agradable: '상냥한, 기분 좋은'으로, 문맥과 반대라 ✗","paciente: '참을성 있는'으로, 부정적 결과의 이유가 아니라 ✗","amable: '친절한'으로, 문맥과 반대라 ✗"]},{"id":"V94","q":"Nuestro perro es un ____ todavía, es normal que lo muerda todo.","o":["lobezno","cachorro","osezno","potro"],"a":1,"k":"동물 새끼 어휘","t":"우리 개는 아직 강아지라서 뭐든 다 무는 게 당연해.","e":"cachorro는 '(개 등의) 새끼, 강아지'입니다. perro(개)의 새끼를 말하므로 정답입니다. 동물마다 새끼 이름이 다르니 함께 외워 두세요: lobezno(늑대 새끼), osezno(곰 새끼), potro(망아지).","x":["lobezno: '늑대 새끼'로, 개의 새끼가 아니라 ✗","cachorro: '강아지, 새끼' → 개의 새끼라 정답 ✓","osezno: '곰 새끼'로, 개에게 쓰지 않아 ✗","potro: '망아지'로, 말의 새끼라 ✗"]},{"id":"V95","q":"No me gusta el frío, prefiero vivir en un lugar con clima ____.","o":["templado","lluvioso","inestable","extremo"],"a":0,"k":"날씨 어휘","t":"나는 추위를 싫어해서, 온화한 기후의 곳에서 사는 게 더 좋다.","e":"templado는 '온화한, 따뜻한'이라는 뜻으로 기후를 말할 때 '너무 덥지도 춥지도 않은'을 의미합니다. 'clima templado(온화한 기후)'는 자주 쓰는 표현입니다. 물이나 음식에 쓰면 '미지근한'이라는 뜻도 됩니다.","x":["templado: '온화한' → 추위를 싫어하는 사람이 좋아할 기후라 정답 ✓","lluvioso: '비가 많은'으로, 추위를 피하는 이유와 연결되지 않아 ✗","inestable: '불안정한'으로, 좋아할 기후로 맞지 않아 ✗","extremo: '극단적인'으로, 오히려 아주 추울 수 있어 ✗"]},{"id":"V96","q":"Tengo muchos ____, mi familia es grandísima.","o":["parientes","seguidores","admiradores","padres"],"a":0,"k":"가족 어휘","t":"나는 친척이 아주 많아, 우리 가족은 엄청 대가족이야.","e":"pariente는 '친척'입니다. 'familia grandísima(아주 큰 가족)'라는 단서와 잘 맞습니다. 영어의 'parents(부모)'와 헷갈리지 않도록 주의하세요. 스페인어로 부모는 padres입니다.","x":["parientes: '친척' → 가족이 크다는 내용과 맞아 정답 ✓","seguidores: '팔로워, 추종자'로, 가족과 관련이 없어 ✗","admiradores: '팬, 숭배자'로, 가족과 관련이 없어 ✗","padres: '부모'로, 많을 수 없어 문맥과 맞지 않아 ✗"]},{"id":"V97","q":"Elvira vive en el ____ piso de ese bloque.","o":["cuatro","cuarenta","cuarto","catorce"],"a":2,"k":"서수","t":"엘비라는 저 아파트 건물 4층에 산다.","e":"층수는 서수(첫째·둘째처럼 순서를 나타내는 수)로 말하므로 '4층'은 'el cuarto piso'입니다. cuatro(4)는 기수(개수를 세는 수)라서 명사 앞에 'el ... piso' 형태로 쓰지 않습니다. bloque는 '아파트 동, 건물 한 채'를 뜻합니다.","x":["cuatro: '4'(기수)로, 층의 순서를 나타낼 때는 서수를 써서 ✗","cuarenta: '40'(기수)으로, 서수가 아니라 ✗","cuarto: '네 번째' → 층수를 나타내는 서수라 정답 ✓","catorce: '14'(기수)로, 서수가 아니라 ✗"]},{"id":"V98","q":"De todas las artes marciales, prefiero el ____.","o":["submarinismo","piragüismo","kárate","críquet"],"a":2,"k":"스포츠 어휘","t":"모든 무술 중에서 나는 가라테를 가장 좋아한다.","e":"kárate는 '가라테'로, artes marciales(무술)에 속하는 유일한 보기입니다. 스페인어에서는 악센트를 넣어 kárate로 씁니다(중남미 일부에서는 karate). 다른 보기는 모두 무술이 아닌 스포츠입니다.","x":["submarinismo: '스쿠버 다이빙'으로, 무술이 아니라 ✗","piragüismo: '카누 경기'로, 무술이 아니라 ✗","kárate: '가라테' → 무술이라 정답 ✓","críquet: '크리켓'으로, 무술이 아니라 ✗"]},{"id":"V99","q":"En un ____, el agua para el té está lista en muy poco tiempo.","o":["exprimidor","congelador","rallador","hervidor"],"a":3,"k":"주방 도구 어휘","t":"전기 주전자를 쓰면 찻물이 아주 짧은 시간에 준비된다.","e":"hervidor는 '주전자(전기 포트)'로, hervir(끓이다)에서 온 말입니다. 물을 끓여 차를 준비하는 도구이므로 정답입니다. -dor로 끝나는 주방 도구를 함께 외워 두세요: exprimidor(과즙기), rallador(강판), congelador(냉동고).","x":["exprimidor: '과즙기'로, 물을 끓이지 못해 ✗","congelador: '냉동고'로, 물을 얼리는 곳이라 ✗","rallador: '강판'으로, 물과 관련이 없어 ✗","hervidor: '주전자' → 물을 빨리 끓여 정답 ✓"]},{"id":"V100","q":"Qué bonito es ver el cielo nocturno lleno de ____.","o":["estrellas","planetas","lunas","meteoritos"],"a":0,"k":"자연 어휘","t":"별로 가득한 밤하늘을 보는 것은 정말 아름답다.","e":"estrella는 '별'입니다. 'cielo nocturno lleno de estrellas(별이 가득한 밤하늘)'는 아주 자연스러운 표현입니다. 하늘에 '가득' 보이는 것은 별이지, 행성이나 달이 아닙니다.","x":["estrellas: '별' → 밤하늘을 가득 채우는 것이라 정답 ✓","planetas: '행성'으로, 맨눈으로 하늘을 가득 채울 만큼 보이지 않아 ✗","lunas: '달들'로, 지구에서 보이는 달은 하나라 ✗","meteoritos: '운석'으로, 하늘을 가득 채운 모습으로 쓰지 않아 ✗"]},{"id":"V101","q":"En nuestra empresa de ____ trabajan dos conocidos arquitectos.","o":["alimentación","mudanzas","construcción","mensajería"],"a":2,"k":"업종 어휘","t":"우리 건설 회사에서는 유명한 건축가 두 명이 일한다.","e":"construcción는 '건설, 건축'입니다. arquitectos(건축가)가 일하는 곳으로 가장 자연스러운 업종입니다. 'empresa de + 업종'으로 회사 종류를 말합니다: empresa de mudanzas(이삿짐 회사), empresa de mensajería(택배 회사).","x":["alimentación: '식품'으로, 건축가가 일하는 업종이 아니라 ✗","mudanzas: '이사'로, 건축가와 관련이 없어 ✗","construcción: '건설' → 건축가가 일하는 업종이라 정답 ✓","mensajería: '택배, 배송'으로, 건축가와 관련이 없어 ✗"]},{"id":"V102","q":"El Nilo es el ____ más largo del mundo.","o":["río","mar","monte","volcán"],"a":0,"k":"지리 어휘","t":"나일강은 세계에서 가장 긴 강이다.","e":"río는 '강'입니다. 나일(el Nilo)은 아프리카의 강으로 세계에서 가장 긴 강으로 알려져 있습니다(아마존강과 논쟁이 있음). 강 이름은 남성이라서 'el Nilo', 'el Amazonas'처럼 el을 붙입니다.","x":["río: '강' → 나일강이라 정답 ✓","mar: '바다'로, 나일은 바다가 아니라 ✗","monte: '산'으로, 나일은 산이 아니라 ✗","volcán: '화산'으로, 나일은 화산이 아니라 ✗"]},{"id":"V103","q":"Tienes la piel ____, ¿por qué no te pones crema hidratante?","o":["mojada","seca","limpia","cuidada"],"a":1,"k":"피부 어휘","t":"너 피부가 건조하네, 보습 크림 바르는 게 어때?","e":"seco/seca는 '건조한, 마른'입니다. 'crema hidratante(보습 크림)'를 바르라는 조언의 이유로 자연스럽습니다. 'piel seca(건성 피부)'와 반대로 'piel grasa(지성 피부)'도 알아 두세요.","x":["mojada: '젖은'으로, 보습 크림이 필요한 이유가 아니라 ✗","seca: '건조한' → 보습 크림이 필요한 이유라 정답 ✓","limpia: '깨끗한'으로, 크림을 바르라는 조언과 연결되지 않아 ✗","cuidada: '잘 관리된'으로, 크림이 필요한 이유가 아니라 ✗"]},{"id":"V104","q":"Nunca le da las gracias a quienes le hacen favores, es muy ____.","o":["pesada","desagradecida","correcta","honrada"],"a":1,"k":"성격 형용사","t":"그녀는 자신에게 호의를 베푸는 사람들에게 한 번도 고맙다고 하지 않아, 정말 배은망덕해.","e":"desagradecido/a는 '고마움을 모르는, 배은망덕한'입니다. agradecer(감사하다)에서 온 agradecido(감사하는)에 부정 접두사 des-가 붙었습니다. 'Nunca le da las gracias(절대 고맙다고 하지 않는다)'가 단서입니다.","x":["pesada: '귀찮게 구는, 성가신'으로, 감사를 안 하는 것과 직접 관련이 없어 ✗","desagradecida: '고마움을 모르는' → 문맥과 일치해 정답 ✓","correcta: '예의 바른, 올바른'으로, 문맥과 반대라 ✗","honrada: '정직한'으로, 감사와 관련이 없어 ✗"]},{"id":"V105","q":"El ____ de esta ciudad siempre está lleno de cruceros.","o":["aeropuerto","puerto","ayuntamiento","estadio"],"a":1,"k":"장소 어휘","t":"이 도시의 항구는 항상 크루즈선으로 가득하다.","e":"puerto는 '항구'입니다. crucero(크루즈선)는 배이므로 배가 머무는 곳인 항구가 맞습니다. aeropuerto(공항)는 'aero-(하늘)'+'puerto(항구)'로 만들어진 단어라는 점도 재미있게 기억해 두세요.","x":["aeropuerto: '공항'으로, 배가 아니라 비행기가 있는 곳이라 ✗","puerto: '항구' → 크루즈선이 머무는 곳이라 정답 ✓","ayuntamiento: '시청'으로, 배와 관련이 없어 ✗","estadio: '경기장'으로, 배와 관련이 없어 ✗"]},{"id":"V106","q":"Conduce tan lentamente que todos los vehículos lo ____ en la carretera.","o":["empujan","adelantan","mueven","desplazan"],"a":1,"k":"운전 동사","t":"그는 너무 천천히 운전해서 도로에서 모든 차가 그를 추월한다.","e":"adelantar는 '추월하다, 앞지르다'입니다. 천천히 달리면 다른 차들이 앞질러 가는 것이 자연스럽습니다. lo는 직접목적격 대명사(그를)입니다. 중남미에서는 rebasar(멕시코), pasar도 씁니다.","x":["empujan: '민다'로, 차들이 미는 것은 아니라 ✗","adelantan: '추월한다' → 느린 차를 앞지르는 상황이라 정답 ✓","mueven: '움직인다'로, 의미가 맞지 않아 ✗","desplazan: '밀어내다, 이동시키다'로, 추월의 의미가 아니라 ✗"]},{"id":"V107","q":"Para mí, es ____ alquilar una vivienda que tenga lavadora. Considero que es muy necesaria.","o":["inútil","opcional","imprescindible","desagradable"],"a":2,"k":"형용사 어휘","t":"나에게는 세탁기가 있는 집을 빌리는 것이 필수다. 세탁기가 아주 필요하다고 생각한다.","e":"imprescindible은 '없어서는 안 되는, 필수적인'입니다. 뒤 문장의 'muy necesaria(아주 필요한)'와 같은 의미입니다. 'que tenga'는 원하는 조건을 나타내는 접속법(바람·조건을 나타내는 동사 형태)입니다.","x":["inútil: '쓸모없는'으로, 필요하다는 내용과 반대라 ✗","opcional: '선택 사항인'으로, 아주 필요하다는 말과 모순이라 ✗","imprescindible: '필수적인' → 아주 필요하다는 말과 일치해 정답 ✓","desagradable: '불쾌한'으로, 문맥과 맞지 않아 ✗"]},{"id":"V108","q":"Voy a ____ los platos. ¿Los secas tú?","o":["planchar","fregar","barrer","tender"],"a":1,"k":"집안일 동사","t":"내가 설거지할게. 네가 그릇 닦아(말려) 줄래?","e":"fregar는 '설거지하다, 문질러 씻다'입니다. 'fregar los platos(설거지하다)'는 스페인에서 흔한 표현이고, 중남미에서는 'lavar los platos'를 더 많이 씁니다. 다음에 secar(물기를 닦다)가 오므로 먼저 씻는 동작이 맞습니다.","x":["planchar: '다림질하다'로, 그릇에 하는 일이 아니라 ✗","fregar: '설거지하다' → 그릇을 씻은 뒤 말리는 흐름이라 정답 ✓","barrer: '쓸다'로, 그릇에 하는 일이 아니라 ✗","tender: '(빨래를) 널다'로, 그릇에 하는 일이 아니라 ✗"]},{"id":"V109","q":"Mi madre quiere vivir en la costa, pero mi padre prefiere las regiones del ____.","o":["interior","sur","este","norte"],"a":0,"k":"지리 어휘","t":"우리 엄마는 해안에서 살고 싶어 하지만, 아빠는 내륙 지역을 더 좋아한다.","e":"interior는 지리에서 '내륙(바다에서 먼 지역)'을 뜻합니다. costa(해안)와 반대되는 개념이므로 정답입니다. sur/este/norte는 방향이라 해안이 있을 수도 있어 대조가 되지 않습니다.","x":["interior: '내륙' → 해안과 대조되어 정답 ✓","sur: '남쪽'으로, 남쪽에도 해안이 있을 수 있어 대조가 안 돼 ✗","este: '동쪽'으로, 해안과 대조되는 말이 아니라 ✗","norte: '북쪽'으로, 해안과 대조되는 말이 아니라 ✗"]},{"id":"V110","q":"La gente optimista ____ de la vida lo máximo posible.","o":["desconfía","disfruta","se queja","se asusta"],"a":1,"k":"동사 어휘","t":"낙관적인 사람들은 인생을 최대한 즐긴다.","e":"disfrutar는 '즐기다'로, 'disfrutar de algo(~을 즐기다)'처럼 전치사 de와 함께 씁니다. optimista(낙관적인)인 사람의 특징으로 가장 자연스럽습니다. 'lo máximo posible'은 '가능한 한 최대로'라는 뜻입니다.","x":["desconfía: '불신한다'로, 낙관적인 태도와 맞지 않아 ✗","disfruta: '즐긴다' → 낙관적인 사람의 특징이라 정답 ✓","se queja: '불평한다'로, 낙관적인 태도와 반대라 ✗","se asusta: '겁먹는다'로, 문맥과 맞지 않아 ✗"]},{"id":"V111","q":"Prefieren viajar en primera ____ para ir más cómodos.","o":["clase","aula","sala","sección"],"a":0,"k":"여행 어휘","t":"그들은 더 편하게 가려고 일등석으로 여행하는 것을 선호한다.","e":"'primera clase'는 '일등석, 퍼스트 클래스'입니다. clase는 '수업'이라는 뜻 외에 '등급'이라는 뜻도 있습니다. 'clase turista(이코노미석)'도 함께 알아 두세요.","x":["clase: primera clase(일등석) → 고정 표현으로 정답 ✓","aula: '교실'로, 교통 좌석 등급에 쓰지 않아 ✗","sala: '홀, 방'으로, 좌석 등급에 쓰지 않아 ✗","sección: '구역, 부분'으로, 이 표현에 쓰지 않아 ✗"]},{"id":"V112","q":"No puedo continuar ____, estoy muy cansado.","o":["descansando","durmiendo","andando","soñando"],"a":2,"k":"동사 어휘","t":"계속 걸을 수 없어, 너무 피곤해.","e":"andar는 '걷다'입니다. 'continuar + 현재분사(-ando/-iendo)'는 '계속 ~하다'라는 표현입니다. 피곤한 사람이 계속할 수 없는 활동으로 '걷기'가 가장 자연스럽습니다.","x":["descansando: '쉬는 것'으로, 피곤하면 오히려 쉬고 싶어서 ✗","durmiendo: '자는 것'으로, 피곤해서 못 자는 것은 모순이라 ✗","andando: '걷는 것' → 피곤해서 계속 못 하는 활동이라 정답 ✓","soñando: '꿈꾸는 것'으로, 피곤함과 맞지 않아 ✗"]},{"id":"V113","q":"Para hacer merengue, debes ____ muy bien las claras de huevo y el azúcar.","o":["cortar","freír","cocer","batir"],"a":3,"k":"요리 동사","t":"머랭을 만들려면 달걀흰자와 설탕을 아주 잘 휘저어야(거품 내야) 한다.","e":"batir는 '(달걀 등을) 휘젓다, 거품 내다'입니다. 머랭(merengue)은 달걀흰자(claras de huevo)를 설탕과 함께 거품 내어 만듭니다. 달걀노른자는 yema라고 합니다.","x":["cortar: '자르다'로, 달걀흰자에 하는 동작이 아니라 ✗","freír: '튀기다'로, 머랭 만드는 방법이 아니라 ✗","cocer: '삶다, 익히다'로, 머랭 만드는 방법이 아니라 ✗","batir: '휘젓다' → 머랭을 만드는 동작이라 정답 ✓"]},{"id":"V114","q":"Me gustan las películas ____, sin intriga me aburro.","o":["históricas","biográficas","románticas","de suspense"],"a":3,"k":"영화 장르","t":"나는 서스펜스 영화를 좋아해, 긴장감이 없으면 지루해.","e":"'películas de suspense'는 '서스펜스(스릴러) 영화'입니다. intriga(긴장감, 흥미진진한 줄거리)가 없으면 지루하다는 말과 잘 맞습니다. 중남미에서는 suspenso라고 합니다.","x":["históricas: '역사의'로, 긴장감과 직접 관련이 없어 ✗","biográficas: '전기의'로, 긴장감과 직접 관련이 없어 ✗","románticas: '로맨스의'로, 긴장감을 주로 하는 장르가 아니라 ✗","de suspense: '서스펜스' → 긴장감이 핵심인 장르라 정답 ✓"]},{"id":"V115","q":"Pedro es muy ____, su estado de ánimo cambia con mucha facilidad.","o":["fiable","variable","arrogante","valiente"],"a":1,"k":"성격 형용사","t":"페드로는 아주 변덕스러워, 기분이 쉽게 바뀌어.","e":"variable은 '변하기 쉬운, 변덕스러운'입니다. 'su estado de ánimo cambia con mucha facilidad(기분이 아주 쉽게 바뀐다)'가 단서입니다. estado de ánimo는 '기분, 마음 상태'입니다.","x":["fiable: '믿을 만한'으로, 기분 변화와 관련이 없어 ✗","variable: '변덕스러운' → 기분이 쉽게 바뀐다는 내용과 일치해 정답 ✓","arrogante: '거만한'으로, 기분 변화와 관련이 없어 ✗","valiente: '용감한'으로, 문맥과 맞지 않아 ✗"]},{"id":"V116","q":"Si quieres ser abogado, debes estudiar ____.","o":["Historia","Física","Derecho","Medicina"],"a":2,"k":"학문 어휘","t":"변호사가 되고 싶다면 법학을 공부해야 한다.","e":"Derecho는 '법학'입니다. derecho는 '권리', '오른쪽', '곧은'이라는 뜻도 있지만, 학과 이름으로는 '법학'입니다. 학문 이름은 대문자로 시작하는 경우가 많습니다. abogado(변호사)가 되려면 법학을 공부해야 합니다.","x":["Historia: '역사학'으로, 변호사가 되는 전공이 아니라 ✗","Física: '물리학'으로, 변호사와 관련이 없어 ✗","Derecho: '법학' → 변호사가 되는 전공이라 정답 ✓","Medicina: '의학'으로, 의사가 되는 전공이라 ✗"]},{"id":"V117","q":"Soy ____, trabajo para una conocida aerolínea.","o":["auxiliar de vuelo","funcionaria","profesora de baile","dependienta"],"a":0,"k":"직업 어휘","t":"저는 승무원이에요, 유명한 항공사에서 일해요.","e":"'auxiliar de vuelo'는 '항공 승무원'입니다. aerolínea(항공사)에서 일한다는 단서와 가장 잘 맞습니다. 같은 뜻으로 azafata(스페인, 여성), aeromozo/a(중남미)도 씁니다.","x":["auxiliar de vuelo: '항공 승무원' → 항공사에서 일하는 직업이라 정답 ✓","funcionaria: '공무원'으로, 항공사 직원이 아니라 ✗","profesora de baile: '춤 선생님'으로, 항공사와 관련이 없어 ✗","dependienta: '점원'으로, 항공사와 관련이 없어 ✗"]},{"id":"V118","q":"Me llevo muy bien con mi ____, es decir, con la mujer de mi hijo.","o":["bisnieta","nieta","cuñada","nuera"],"a":3,"k":"가족 어휘","t":"나는 며느리, 즉 내 아들의 아내와 아주 사이가 좋다.","e":"nuera는 '며느리'입니다. 'es decir(즉)' 뒤에서 'la mujer de mi hijo(내 아들의 아내)'라고 직접 설명해 줍니다. 반대로 딸의 남편(사위)은 yerno라고 합니다.","x":["bisnieta: '증손녀'로, 아들의 아내가 아니라 ✗","nieta: '손녀'로, 아들의 아내가 아니라 ✗","cuñada: '형수, 처제, 시누이 등'으로, 아들의 아내가 아니라 ✗","nuera: '며느리' → 아들의 아내라 정답 ✓"]},{"id":"V119","q":"Si sigues las ____ de uso, entenderás cómo funciona este aparato.","o":["redacciones","correcciones","instrucciones","notas"],"a":2,"k":"명사 어휘","t":"사용 설명서를 따라 하면 이 기기가 어떻게 작동하는지 이해할 거야.","e":"'instrucciones de uso'는 '사용 설명서, 사용법'입니다. 기기(aparato)의 작동 방법을 알려 주는 것이므로 정답입니다. 'seguir las instrucciones(설명을 따르다)'는 자주 쓰는 표현입니다.","x":["redacciones: '작문, 글쓰기'로, 사용법을 뜻하지 않아 ✗","correcciones: '수정, 교정'으로, 사용법을 뜻하지 않아 ✗","instrucciones: '설명서, 지시사항' → 사용법을 알려 주어 정답 ✓","notas: '메모, 점수'로, 이 고정 표현에 쓰지 않아 ✗"]},{"id":"V120","q":"Me gusta hacer ____ porque hago ejercicio al tiempo que disfruto de la naturaleza.","o":["alfarería","dibujos","puzles","senderismo"],"a":3,"k":"취미 어휘","t":"나는 하이킹을 좋아한다, 자연을 즐기면서 운동도 하기 때문이다.","e":"senderismo는 '하이킹, 트레킹'으로, sendero(오솔길, 산길)에서 온 말입니다. 'hacer senderismo(하이킹하다)'로 씁니다. 운동과 자연 즐기기를 동시에 할 수 있는 활동이라 정답입니다. 'al tiempo que'는 '~하는 동시에'라는 뜻입니다.","x":["alfarería: '도예'로, 운동이 되지 않아 ✗","dibujos: '그림'으로, 운동이 되지 않아 ✗","puzles: '퍼즐'로, 운동도 자연도 아니라 ✗","senderismo: '하이킹' → 운동과 자연을 함께 즐겨 정답 ✓"]},{"id":"V121","q":"En el frigorífico solo hay una docena de huevos, varias manzanas y ____ de mermelada.","o":["una lata","una botella","un sobre","un tarro"],"a":3,"k":"용기 어휘","t":"냉장고에는 달걀 한 판(12개), 사과 몇 개, 잼 한 병밖에 없다.","e":"tarro는 '(유리) 병, 단지'로, 잼·꿀처럼 걸쭉한 음식을 담는 입구가 넓은 병입니다. 'un tarro de mermelada(잼 한 병)'가 자연스럽습니다. botella는 물·와인처럼 액체를 담는 목이 좁은 병이라는 점과 구별하세요. 중남미에서는 frasco도 많이 씁니다.","x":["una lata: '캔'으로, 잼은 보통 캔에 담지 않아 ✗","una botella: '(목이 좁은) 병'으로, 액체용이라 잼에는 맞지 않아 ✗","un sobre: '봉투, 작은 포장'으로, 냉장고 속 잼 용기로 맞지 않아 ✗","un tarro: '(입구 넓은) 병' → 잼을 담는 용기라 정답 ✓"]},{"id":"V122","q":"No sé cómo hacer este ejercicio, estoy ____.","o":["entretenido","satisfecho","confundido","concentrado"],"a":2,"k":"감정 형용사","t":"이 문제를 어떻게 푸는지 모르겠어, 헷갈려.","e":"confundido는 '혼란스러운, 헷갈리는'입니다. 'No sé cómo hacer este ejercicio(이 문제를 어떻게 하는지 모르겠다)'라는 단서와 잘 맞습니다. 일시적인 상태이므로 estar와 함께 씁니다.","x":["entretenido: '즐거운, 재미있게 빠져 있는'으로, 모른다는 내용과 맞지 않아 ✗","satisfecho: '만족한'으로, 문맥과 반대라 ✗","confundido: '헷갈리는' → 어떻게 할지 모르는 상태라 정답 ✓","concentrado: '집중한'으로, 모르겠다는 이유가 되지 않아 ✗"]},{"id":"V123","q":"A los niños les gusta mucho ____ dibujos animados en la tele.","o":["filmar","imaginar","ver","rodar"],"a":2,"k":"동사 어휘","t":"아이들은 TV로 만화 영화 보는 것을 아주 좋아한다.","e":"ver는 '보다'입니다. 'ver la tele/una película(TV/영화를 보다)'처럼 씁니다. 'dibujos animados'는 '만화 영화, 애니메이션'입니다. filmar, rodar는 '촬영하다'라는 뜻이라 시청하는 것과 다릅니다.","x":["filmar: '촬영하다'로, 아이들이 TV로 하는 일이 아니라 ✗","imaginar: '상상하다'로, TV와 함께 쓰지 않아 ✗","ver: '보다' → TV로 만화를 보는 것이라 정답 ✓","rodar: '(영화를) 찍다'로, 시청이 아니라 ✗"]},{"id":"V124","q":"Prefiero ____ mi opinión sobre ese asunto, os la diré en otro momento.","o":["exponeros","daros","contaros","reservarme"],"a":3,"k":"동사 어휘","t":"그 문제에 대한 내 의견은 아껴 둘게, 다음에 너희에게 말해 줄게.","e":"'reservarse algo'는 '~을 (말하지 않고) 남겨 두다, 보류하다'입니다. 'reservarme mi opinión'은 '내 의견을 밝히지 않고 아껴 두다'라는 뜻입니다. 뒤의 'os la diré en otro momento(다음에 말해 줄게)'가 지금은 말하지 않는다는 단서입니다.","x":["exponeros: '너희에게 설명하다'로, 다음에 말하겠다는 내용과 모순이라 ✗","daros: '너희에게 주다(말하다)'로, 지금 말하는 것이라 모순이라 ✗","contaros: '너희에게 이야기하다'로, 지금 말하는 것이라 모순이라 ✗","reservarme: '아껴 두다, 말하지 않다' → 다음에 말하겠다는 내용과 맞아 정답 ✓"]},{"id":"V125","q":"¡Qué ____! Quiere la ayuda de todos, pero él no ayuda a nadie.","o":["tolerante","egoísta","tierno","dulce"],"a":1,"k":"성격 형용사","t":"정말 이기적이야! 모두의 도움은 원하면서 자기는 아무도 안 도와줘.","e":"egoísta는 '이기적인'으로, 남녀 모두 같은 형태입니다. 자신은 도움을 받고 남은 돕지 않는 사람을 묘사하므로 정답입니다. '¡Qué + 형용사!'는 '정말 ~하다!'라는 감탄 표현입니다.","x":["tolerante: '관대한'으로, 문맥과 맞지 않아 ✗","egoísta: '이기적인' → 자기만 생각하는 사람이라 정답 ✓","tierno: '다정한, 부드러운'으로, 부정적 묘사가 아니라 ✗","dulce: '상냥한, 달콤한'으로, 문맥과 반대라 ✗"]},{"id":"V126","q":"La asignatura que más me gusta es ____. Me gusta aprender idiomas.","o":["la geografía","el francés","la historia","la biología"],"a":1,"k":"과목 어휘","t":"내가 가장 좋아하는 과목은 프랑스어야. 나는 언어 배우는 걸 좋아해.","e":"francés는 '프랑스어'로, 보기 중 유일한 언어(idioma) 과목입니다. 'Me gusta aprender idiomas(언어 배우는 것을 좋아한다)'가 단서입니다. 언어 이름은 남성 명사이므로 el francés, el inglés처럼 씁니다.","x":["la geografía: '지리'로, 언어 과목이 아니라 ✗","el francés: '프랑스어' → 언어 과목이라 정답 ✓","la historia: '역사'로, 언어 과목이 아니라 ✗","la biología: '생물'로, 언어 과목이 아니라 ✗"]},{"id":"V127","q":"Francia está en el ____ europeo.","o":["país","paisaje","continente","pueblo"],"a":2,"k":"지리 어휘","t":"프랑스는 유럽 대륙에 있다.","e":"continente는 '대륙'입니다. 'el continente europeo(유럽 대륙)'처럼 형용사 europeo와 함께 씁니다. 프랑스 자체가 나라(país)이므로 '유럽 나라 안에 있다'는 말은 성립하지 않습니다.","x":["país: '나라'로, 프랑스가 다른 나라 안에 있는 것은 아니라 ✗","paisaje: '풍경'으로, 위치를 나타내지 않아 ✗","continente: '대륙' → 유럽 대륙에 있다는 뜻이라 정답 ✓","pueblo: '마을, 민족'으로, 나라가 그 안에 있을 수 없어 ✗"]},{"id":"V128","q":"Va a ____ al mejor abogado para que defienda a su hijo.","o":["despedir","grabar","contratar","recordar"],"a":2,"k":"직장 동사","t":"그는 아들을 변호하도록 최고의 변호사를 고용할 것이다.","e":"contratar는 '고용하다, 계약하다'입니다. 변호사를 써서 아들을 변호하게 한다는 문맥이므로 정답입니다. 반대말은 despedir(해고하다)입니다. 'para que + 접속법(defienda)'은 '~하도록'이라는 목적을 나타냅니다.","x":["despedir: '해고하다'로, 변호를 맡기는 것과 반대라 ✗","grabar: '녹음하다, 녹화하다'로, 문맥과 맞지 않아 ✗","contratar: '고용하다' → 변호사를 쓰는 것이라 정답 ✓","recordar: '기억하다'로, 변호를 맡기는 행동이 아니라 ✗"]},{"id":"V129","q":"Víctor está ____ porque hace dos meses que no recibe su sueldo.","o":["enfadado","encantado","feliz","interesado"],"a":0,"k":"감정 형용사","t":"빅토르는 두 달째 월급을 받지 못해서 화가 나 있다.","e":"enfadado는 '화가 난'입니다. 월급(sueldo)을 받지 못한 것은 화가 날 만한 이유입니다. 'hace dos meses que no...'는 '두 달째 ~하지 않다'라는 표현입니다. 중남미에서는 enojado를 더 많이 씁니다.","x":["enfadado: '화난' → 월급을 못 받은 결과라 정답 ✓","encantado: '아주 기쁜'으로, 문맥과 반대라 ✗","feliz: '행복한'으로, 문맥과 반대라 ✗","interesado: '관심 있는'으로, 감정 반응으로 맞지 않아 ✗"]},{"id":"V130","q":"Actualmente, es fácil encontrar ____ de avión por un precio muy bajo.","o":["invitaciones","notas","billetes","entradas"],"a":2,"k":"여행 어휘","t":"요즘은 아주 싼 가격의 비행기 표를 쉽게 찾을 수 있다.","e":"billete는 '(교통수단의) 표, 승차권'입니다. 'billete de avión/tren(비행기/기차표)'로 씁니다. 공연·경기 입장권은 entrada라고 하니 구별하세요. 중남미에서는 교통 표를 boleto, pasaje라고 많이 합니다.","x":["invitaciones: '초대장'으로, 비행기 표가 아니라 ✗","notas: '메모, 점수'로, 비행기 표가 아니라 ✗","billetes: '(교통) 표' → 비행기 표라 정답 ✓","entradas: '입장권'으로, 공연·경기용이라 비행기에는 쓰지 않아 ✗"]},{"id":"V131","q":"Si no queda mantequilla, puedes ____ el pan con un poco de margarina.","o":["cortar","rebanar","hornear","untar"],"a":3,"k":"요리 동사","t":"버터가 없으면 빵에 마가린을 조금 발라도 돼.","e":"untar는 '(버터·잼 등을) 바르다'입니다. 'untar el pan con mantequilla(빵에 버터를 바르다)'처럼 'untar A con B' 구조로 씁니다. 버터 대신 마가린을 '바른다'는 문맥입니다.","x":["cortar: '자르다'로, 마가린과 함께 쓰는 동작이 아니라 ✗","rebanar: '얇게 썰다'로, 마가린과 함께 쓰는 동작이 아니라 ✗","hornear: '오븐에 굽다'로, 마가린을 바르는 것과 관련이 없어 ✗","untar: '바르다' → 빵에 마가린을 바르는 것이라 정답 ✓"]},{"id":"V132","q":"Para mí, la ____ de la historia más interesante es la de la Revolución Industrial.","o":["estación","semana","época","jornada"],"a":2,"k":"시간 어휘","t":"나에게 가장 흥미로운 역사의 시대는 산업혁명 시대이다.","e":"época는 '시대, 시기'입니다. 'época de la historia(역사의 시대)'처럼 긴 기간을 나타냅니다. 'la de la Revolución Industrial'에서 la는 앞의 la época를 반복하지 않으려고 쓴 말입니다.","x":["estación: '계절, 역'으로, 역사의 시대를 뜻하지 않아 ✗","semana: '주(週)'로, 역사의 시대로는 너무 짧아 ✗","época: '시대' → 산업혁명 시대를 가리켜 정답 ✓","jornada: '하루(근무일)'로, 역사의 시대를 뜻하지 않아 ✗"]},{"id":"V133","q":"Estos ____ no están amarillos todavía.","o":["cocos","kiwis","arándanos","plátanos"],"a":3,"k":"과일 어휘","t":"이 바나나들은 아직 노랗게 익지 않았다.","e":"plátano는 '바나나'로, 익으면 노란색이 됩니다. 'no están amarillos todavía(아직 노랗지 않다)'가 단서입니다. 중남미에서는 banana, banano라고도 하며, 일부 지역에서 plátano는 요리용 바나나를 뜻합니다.","x":["cocos: '코코넛'으로, 익어도 노래지지 않아 ✗","kiwis: '키위'로, 노랗게 익는 과일이 아니라 ✗","arándanos: '블루베리'로, 노래지지 않아 ✗","plátanos: '바나나' → 익으면 노래져 정답 ✓"]},{"id":"V134","q":"En época de rebajas, muchos productos son más ____.","o":["caros","baratos","bajos","costosos"],"a":1,"k":"쇼핑 형용사","t":"세일 기간에는 많은 상품이 더 싸다.","e":"barato는 '싼'입니다. 'época de rebajas(세일 기간)'에는 물건값이 내려가므로 정답입니다. 반대말은 caro(비싼)입니다. 'precios bajos(낮은 가격)'처럼 bajo는 가격(precio)에 쓰고 상품 자체에는 쓰지 않습니다.","x":["caros: '비싼'으로, 세일과 반대라 ✗","baratos: '싼' → 세일 기간의 특징이라 정답 ✓","bajos: '낮은'으로, 상품이 아니라 가격(precio)에 쓰는 말이라 ✗","costosos: '비싼'으로, 세일과 반대라 ✗"]},{"id":"V135","q":"Vivo en un barrio ____ donde hay tiendas y servicios de todo tipo.","o":["tranquilo","céntrico","mal comunicado","peligroso"],"a":1,"k":"주거 형용사","t":"나는 온갖 종류의 가게와 편의시설이 있는 시내 중심가 동네에 산다.","e":"céntrico는 '중심가의, 도심에 있는'입니다. 가게와 서비스가 다양하게 모여 있는 것은 도심 지역의 특징이므로 정답입니다. 'barrio céntrico(도심 동네)'는 집을 소개할 때 자주 쓰는 표현입니다.","x":["tranquilo: '조용한'으로, 가게가 많은 것과 직접 연결되지 않아 ✗","céntrico: '도심의' → 가게와 서비스가 많은 곳이라 정답 ✓","mal comunicado: '교통이 불편한'으로, 서비스가 많은 것과 맞지 않아 ✗","peligroso: '위험한'으로, 문맥과 관련이 없어 ✗"]},{"id":"V136","q":"El ____ es el segundo día de la semana.","o":["viernes","martes","sábado","miércoles"],"a":1,"k":"요일 어휘","t":"화요일은 한 주의 두 번째 날이다.","e":"스페인어권에서는 한 주가 월요일(lunes)부터 시작하므로 두 번째 날은 martes(화요일)입니다. 요일 순서: lunes, martes, miércoles, jueves, viernes, sábado, domingo. 요일은 남성 명사이며 소문자로 씁니다.","x":["viernes: '금요일'로, 다섯 번째 날이라 ✗","martes: '화요일' → 월요일 다음의 두 번째 날이라 정답 ✓","sábado: '토요일'로, 여섯 번째 날이라 ✗","miércoles: '수요일'로, 세 번째 날이라 ✗"]},{"id":"V137","q":"Si no tiene ____ para trabajar los fines de semana, este trabajo no es para usted.","o":["habilidad","disponibilidad","cualidad","aptitud"],"a":1,"k":"직장 어휘","t":"주말에 일할 수 있는 여건이 안 되신다면, 이 일은 당신에게 맞지 않습니다.","e":"disponibilidad는 '(시간적으로) 가능함, 시간을 낼 수 있음'입니다. 구인 광고에서 'disponibilidad para viajar(출장 가능)', 'disponibilidad horaria(근무 시간 유연성)'처럼 자주 쓰입니다. 주말에 일할 '시간이 되는지'를 묻는 문맥이라 정답입니다.","x":["habilidad: '능력, 솜씨'로, 주말 근무 가능 여부를 뜻하지 않아 ✗","disponibilidad: '시간 여건, 가능성' → 주말 근무 가능 여부라 정답 ✓","cualidad: '자질, 특성'으로, 시간 여건을 뜻하지 않아 ✗","aptitud: '적성, 소질'로, 시간 여건을 뜻하지 않아 ✗"]},{"id":"V138","q":"La ____ es el único instrumento musical que me gustaría aprender a tocar.","o":["trompeta","paleta","canasta","tapadera"],"a":0,"k":"악기 어휘","t":"트럼펫은 내가 배워서 연주해 보고 싶은 유일한 악기이다.","e":"trompeta는 '트럼펫'으로, 보기 중 유일한 악기(instrumento musical)입니다. 악기를 연주하는 것은 'tocar + 악기' 동사를 씁니다. 예: Toco la guitarra.(나는 기타를 친다.)","x":["trompeta: '트럼펫' → 악기라 정답 ✓","paleta: '팔레트, 주걱'으로, 악기가 아니라 ✗","canasta: '바구니'로, 악기가 아니라 ✗","tapadera: '뚜껑'으로, 악기가 아니라 ✗"]},{"id":"V139","q":"Sin ____, no veo bien de lejos.","o":["calcetines","guantes","gafas","pantalones"],"a":2,"k":"사물 어휘","t":"안경이 없으면 멀리 있는 게 잘 안 보인다.","e":"gafas는 '안경'으로, 스페인에서 주로 쓰는 단어이며 항상 복수형입니다. 시력과 관련된 물건은 보기 중 안경뿐입니다. 중남미에서는 lentes, anteojos를 더 많이 씁니다.","x":["calcetines: '양말'로, 시력과 관련이 없어 ✗","guantes: '장갑'으로, 시력과 관련이 없어 ✗","gafas: '안경' → 멀리 보는 데 필요해 정답 ✓","pantalones: '바지'로, 시력과 관련이 없어 ✗"]},{"id":"V140","q":"Las circunstancias actuales no me ____ irme de vacaciones, no tengo plata.","o":["impiden","admiten","prohíben","permiten"],"a":3,"k":"동사 어휘","t":"지금 상황이 휴가를 떠날 수 있게 해 주지 않아, 돈이 없거든.","e":"permitir는 '허락하다, ~할 수 있게 하다'입니다. 'no me permiten irme(내가 떠나는 것을 허락하지 않는다)'는 '여건상 갈 수 없다'라는 뜻입니다. plata는 중남미에서 '돈'을 뜻하는 구어입니다(스페인에서는 dinero, 원래 뜻은 '은').","x":["impiden: '막다'로, 'no'와 함께 쓰면 '막지 않는다'가 되어 돈이 없다는 내용과 모순이라 ✗","admiten: '받아들이다, 인정하다'로, 이 구조에서 자연스럽지 않아 ✗","prohíben: '금지하다'로, 'no'와 함께 쓰면 갈 수 있다는 뜻이 되어 모순이라 ✗","permiten: '할 수 있게 하다' → 돈이 없어 못 간다는 문맥이라 정답 ✓"]},{"id":"V141","q":"¿Quién ____ a vuestro bebé mientras estáis trabajando?","o":["responde","invita","recuerda","cuida"],"a":3,"k":"동사 어휘","t":"너희가 일하는 동안 누가 아기를 돌봐 주니?","e":"cuidar는 '돌보다'입니다. 'cuidar a + 사람'처럼 사람을 목적어로 할 때 전치사 a를 씁니다. 부모가 일하는 동안 아기를 '돌보는' 사람을 묻는 문장입니다. 'estáis trabajando'는 vosotros 형태로 스페인에서 씁니다(중남미에서는 ustedes están).","x":["responde: '대답하다'로, 아기를 돌보는 것이 아니라 ✗","invita: '초대하다'로, 문맥과 맞지 않아 ✗","recuerda: '기억하다'로, 문맥과 맞지 않아 ✗","cuida: '돌보다' → 아기를 돌보는 사람이라 정답 ✓"]},{"id":"V142","q":"Genaro es un caradura, siempre está ____ favores, pero nunca hace nada por nadie.","o":["pidiendo","dejando","prestando","mandando"],"a":0,"k":"동사 어휘","t":"헤나로는 뻔뻔한 사람이야, 늘 부탁만 하고 남을 위해선 아무것도 안 해.","e":"'pedir favores'는 '부탁하다, 호의를 청하다'입니다. caradura는 '뻔뻔한 사람'이라는 구어 표현입니다. 'estar + 현재분사(pidiendo)'는 진행형으로, siempre와 함께 쓰면 '늘 ~하고 있다'라는 불만의 뉘앙스가 됩니다. pedir는 현재분사에서 e가 i로 바뀌는 불규칙 동사입니다.","x":["pidiendo: '부탁하는' → 뻔뻔한 사람의 행동이라 정답 ✓","dejando: '남기는, 두는'으로, favores와 함께 쓰지 않아 ✗","prestando: '빌려주는'으로, 호의를 베푸는 것이라 문맥과 반대라 ✗","mandando: '보내는, 명령하는'으로, favores와 함께 자연스럽지 않아 ✗"]},{"id":"V143","q":"Nuestro ____ sale a las 10, así que debemos estar en el aeropuerto unas dos horas antes.","o":["autocar","vuelo","taxi","barco"],"a":1,"k":"여행 어휘","t":"우리 비행기는 10시에 출발하니까, 두 시간쯤 전에 공항에 가 있어야 해.","e":"vuelo는 '항공편, 비행'입니다. aeropuerto(공항)라는 단서가 있으므로 비행기와 관련된 단어가 와야 합니다. volar(날다)에서 온 말입니다.","x":["autocar: '관광버스'로, 공항에서 출발하지 않아 ✗","vuelo: '항공편' → 공항에 가야 하는 이유라 정답 ✓","taxi: '택시'로, 2시간 전에 공항에 갈 필요가 없어 ✗","barco: '배'로, 공항과 관련이 없어 ✗"]},{"id":"V144","q":"Los domingos solemos ir al ____ para disfrutar de la naturaleza.","o":["mercadillo","cine","campo","pub"],"a":2,"k":"장소 어휘","t":"일요일마다 우리는 보통 자연을 즐기러 시골(교외)에 간다.","e":"campo는 '시골, 들판, 교외'입니다. 'ir al campo(시골로 나가다)'는 자연을 즐기러 가는 것을 말합니다. campo는 '경기장, 분야'라는 뜻도 있습니다.","x":["mercadillo: '벼룩시장, 장터'로, 자연을 즐기는 곳이 아니라 ✗","cine: '영화관'으로, 자연과 관련이 없어 ✗","campo: '시골, 들판' → 자연을 즐기는 곳이라 정답 ✓","pub: '술집'으로, 자연과 관련이 없어 ✗"]},{"id":"V145","q":"____ en paz. ¡Estoy harto!","o":["Tenedme","Hacedme","Ponedme","Dejadme"],"a":3,"k":"관용 표현","t":"날 좀 내버려 둬. 지긋지긋해!","e":"'dejar en paz a alguien'은 '~을 가만히 내버려 두다'라는 관용 표현입니다. 'Dejadme'는 vosotros에 대한 긍정 명령형(dejad)에 me(나를)가 붙은 형태입니다(중남미에서는 ustedes 형태 'Déjenme'). 'estar harto'는 '진저리가 나다, 질리다'입니다.","x":["Tenedme: tener로는 이 표현을 만들지 않아 ✗","Hacedme: hacer로는 이 표현을 만들지 않아 ✗","Ponedme: poner로는 이 표현을 만들지 않아 ✗","Dejadme: dejar en paz(내버려 두다) → 고정 표현으로 정답 ✓"]},{"id":"V146","q":"A nadie le gusta ____ el ridículo.","o":["dejar","tener","hacer","dar"],"a":2,"k":"관용 표현","t":"웃음거리가 되는 것을 좋아하는 사람은 아무도 없다.","e":"'hacer el ridículo'는 '웃음거리가 되다, 망신당하다'라는 고정 표현입니다. ridículo(우스꽝스러운)를 명사로 써서 hacer와 함께 씁니다. 'A nadie le gusta'는 '아무도 ~을 좋아하지 않는다'로, gustar 구문입니다.","x":["dejar: dejar로는 이 표현을 만들지 않아 ✗","tener: tener로는 이 표현을 만들지 않아 ✗","hacer: hacer el ridículo(웃음거리가 되다) → 고정 표현으로 정답 ✓","dar: dar로는 이 표현을 만들지 않아 ✗"]},{"id":"V147","q":"Cuando viajo en ____, me gusta sentarme junto a la ventanilla.","o":["moto","ciclomotor","avión","bici"],"a":2,"k":"교통수단 어휘","t":"비행기로 여행할 때 나는 창가 자리에 앉는 것을 좋아한다.","e":"ventanilla는 '(차·비행기·기차의) 작은 창문'입니다. 'sentarse junto a la ventanilla(창가에 앉다)'는 좌석이 있는 교통수단에 쓰는 말이므로 avión(비행기)이 정답입니다. 교통수단과 함께 'en avión, en tren'처럼 전치사 en을 씁니다.","x":["moto: '오토바이'로, 창문이 없어 ✗","ciclomotor: '스쿠터, 원동기'로, 창문이 없어 ✗","avión: '비행기' → 창가 좌석이 있어 정답 ✓","bici: '자전거'로, 창문이 없어 ✗"]},{"id":"V148","q":"Mi abuela preparó una ____ de cumpleaños deliciosa.","o":["ensalada","macedonia","sopa","tarta"],"a":3,"k":"음식 어휘","t":"우리 할머니가 맛있는 생일 케이크를 만들어 주셨다.","e":"tarta는 '케이크, 타르트'입니다. 'tarta de cumpleaños(생일 케이크)'는 스페인에서 쓰는 표현이고, 중남미에서는 pastel, torta, queque 등 나라마다 다르게 부릅니다. macedonia는 '과일 샐러드'입니다.","x":["ensalada: '샐러드'로, 생일에 만드는 대표 음식이 아니라 ✗","macedonia: '과일 샐러드'로, 생일 케이크가 아니라 ✗","sopa: '수프'로, 생일 상징 음식이 아니라 ✗","tarta: '케이크' → tarta de cumpleaños로 정답 ✓"]},{"id":"V149","q":"Por fin ____ el carné de conducir.","o":["he suspendido","me he quitado","me he sacado","he tenido"],"a":2,"k":"관용 표현","t":"드디어 운전면허를 땄다.","e":"'sacarse el carné de conducir'는 '운전면허를 따다'라는 표현입니다(se 없이 'sacar el carné'라고도 함). 'Por fin(드디어)'이라는 단서가 긍정적인 결과를 가리킵니다. carné de conducir는 스페인 표현이고, 중남미에서는 licencia de conducir/manejar라고 합니다.","x":["he suspendido: '(시험에) 떨어졌다'로, 'Por fin'과 맞지 않아 ✗","me he quitado: '벗었다, 없앴다'로, 면허를 따는 의미가 아니라 ✗","me he sacado: '(면허를) 땄다' → 고정 표현으로 정답 ✓","he tenido: '가졌다'로, '드디어 땄다'는 의미를 나타내지 않아 ✗"]},{"id":"V150","q":"Me aburren las películas de este ____ de cine.","o":["cantante","fotógrafo","escultor","director"],"a":3,"k":"영화 직업 어휘","t":"이 영화감독의 영화들은 지루하다.","e":"'director de cine'는 '영화감독'입니다. 영화(películas)를 만드는 사람이므로 정답입니다. aburrir는 gustar처럼 쓰는 동사로 'Me aburren las películas(그 영화들이 나를 지루하게 한다)'라는 구조입니다.","x":["cantante: '가수'로, 영화를 만드는 사람이 아니라 ✗","fotógrafo: '사진작가'로, 'de cine'와 함께 영화를 만드는 사람을 뜻하지 않아 ✗","escultor: '조각가'로, 영화와 관련이 없어 ✗","director: '감독' → director de cine(영화감독)로 정답 ✓"]},{"id":"V151","q":"Mi madre es una persona organizada, siempre ____ lo que va a hacer con bastante antelación.","o":["olvida","abandona","programa","repite"],"a":2,"k":"계획 관련 동사","t":"우리 어머니는 계획적인 사람이라서, 할 일을 항상 꽤 미리 계획해 두신다.","e":"programar는 '(일정·활동을) 계획하다, 짜다'라는 뜻입니다. 앞 문장의 organizada(정리를 잘하는, 계획적인)와 뒤의 con bastante antelación(꽤 미리)이 '미리 계획한다'는 의미와 잘 어울립니다. 예: Programo mis vacaciones con meses de antelación.(나는 몇 달 전에 휴가를 계획해요.)","x":["olvida: olvidar(잊다)는 계획적인 사람의 행동과 반대라서 ✗","abandona: abandonar(포기하다, 버리다)는 문맥과 맞지 않습니다 ✗","programa: programar(계획하다, 일정을 짜다) → 정답 ✓","repite: repetir(반복하다)는 '미리 준비한다'는 의미가 없습니다 ✗"]},{"id":"V152","q":"Mi hermano siempre está ____, nunca ha tenido ningún problema de salud.","o":["sano","enfermo","cansado","contagiado"],"a":0,"k":"건강 상태 형용사","t":"우리 형(오빠)은 늘 건강하다. 한 번도 건강 문제가 있었던 적이 없다.","e":"sano는 '건강한, 병이 없는'이라는 뜻의 형용사로, 상태를 나타내므로 estar와 함께 씁니다. 뒷부분 nunca ha tenido ningún problema de salud(건강 문제가 전혀 없었다)가 결정적인 힌트입니다. 예: Come bien para estar sano.(건강하려면 잘 먹어라.)","x":["sano: 건강한 → 건강 문제가 없었다는 내용과 일치하므로 정답 ✓","enfermo: 아픈, 병든이라 뒷문장과 모순입니다 ✗","cansado: 피곤한이라는 뜻으로 건강 문제 유무와 관계없습니다 ✗","contagiado: 전염된, 감염된이라 문맥과 반대입니다 ✗"]},{"id":"V153","q":"Está prohibido ____ animales en esta zona.","o":["casar","cazar","cultivar","plantar"],"a":1,"k":"철자 비슷한 동사","t":"이 지역에서는 동물을 사냥하는 것이 금지되어 있다.","e":"cazar는 '사냥하다'라는 뜻으로, 동물(animales)과 함께 자연스럽게 쓰입니다. 발음이 비슷한 casar(결혼시키다)와 혼동하기 쉬우니 철자 z와 s를 잘 구별하세요. 참고로 중남미와 스페인 남부 일부에서는 z와 s를 똑같이 [s]로 발음해서 두 단어 소리가 같습니다.","x":["casar: 결혼시키다(casarse 결혼하다)로 동물과 어울리지 않습니다 ✗","cazar: 사냥하다 → 금지 구역에서 동물을 사냥하는 것이므로 정답 ✓","cultivar: (식물을) 재배하다로 동물에는 쓰지 않습니다 ✗","plantar: (나무·식물을) 심다로 동물에는 쓰지 않습니다 ✗"]},{"id":"V154","q":"El ____ de dientes que uso es especial para dientes sensibles.","o":["paño","peine","cepillo","trapo"],"a":2,"k":"생활용품 어휘","t":"내가 쓰는 칫솔은 시린 이(민감한 치아)용 특수 칫솔이다.","e":"cepillo de dientes는 '칫솔'입니다. cepillo는 원래 '솔, 브러시'라는 뜻으로 cepillo para el pelo(헤어브러시)처럼도 씁니다. 동사 cepillarse los dientes(이를 닦다)도 함께 알아 두세요.","x":["paño: 천, 행주라서 이를 닦는 도구가 아닙니다 ✗","peine: 빗으로 머리카락에 씁니다 ✗","cepillo: 솔, cepillo de dientes는 칫솔 → 정답 ✓","trapo: 걸레, 헝겊이라 맞지 않습니다 ✗"]},{"id":"V155","q":"No estoy contento con mis inquilinos, me ____ cuatro meses de alquiler.","o":["sacan","deben","prestan","dejan"],"a":1,"k":"deber 빚지다","t":"나는 세입자들이 마음에 들지 않는다. 그들이 나에게 4개월 치 월세를 밀려 있다.","e":"deber는 '~해야 한다' 외에 '(돈을) 빚지다'라는 뜻도 있습니다. me deben cuatro meses de alquiler는 '나에게 4개월 치 월세를 빚지고 있다(안 냈다)'는 의미입니다. inquilinos(세입자)와 alquiler(월세)가 힌트입니다. 예: Te debo diez euros.(너한테 10유로 빚졌어.)","x":["sacan: sacar(꺼내다, 빼내다)는 월세를 안 낸 상황을 표현하지 못합니다 ✗","deben: deber(빚지다) → 월세가 밀린 상황이므로 정답 ✓","prestan: prestar(빌려주다)는 세입자가 집주인에게 돈을 빌려주는 뜻이 되어 어색합니다 ✗","dejan: dejar(남기다, 두다)는 문맥상 의미가 맞지 않습니다 ✗"]},{"id":"V156","q":"Los Juegos Olímpicos empezarán el 26 de julio y ____ el 11 de agosto.","o":["arrancarán","finalizarán","comenzarán","se iniciarán"],"a":1,"k":"시작·끝 동사","t":"올림픽은 7월 26일에 시작해서 8월 11일에 끝날 것이다.","e":"empezar(시작하다)와 대비되는 말이 필요하므로 finalizar(끝나다, 종료되다)가 정답입니다. 'A일에 시작해서 B일에 끝난다'는 구조입니다. 비슷한 말로 terminar, acabar도 있습니다.","x":["arrancarán: arrancar(시작하다, 출발하다)로 empezar와 같은 의미라 ✗","finalizarán: finalizar(끝나다) → 시작과 대비되므로 정답 ✓","comenzarán: comenzar(시작하다)로 empezar와 같은 의미라 ✗","se iniciarán: iniciarse(시작되다)로 역시 시작의 의미라 ✗"]},{"id":"V157","q":"No ____ ese estilo musical, ¿puedes poner otra cosa?","o":["soporto","odio","niego","afronto"],"a":0,"k":"soportar 견디다","t":"나는 그 음악 스타일을 못 참겠어. 다른 것 좀 틀어 줄래?","e":"soportar는 '참다, 견디다'라는 뜻으로, 부정문 No soporto ~는 '~을 못 견디겠다, 너무 싫다'는 강한 거부감을 나타냅니다. 다른 음악을 틀어 달라는 뒷문장과 잘 맞습니다. 예: No soporto el ruido.(소음을 못 참겠어.)","x":["soporto: soportar(견디다)의 부정 → '못 참겠다'이므로 정답 ✓","odio: odiar(싫어하다)를 부정하면 '싫어하지 않는다'가 되어 뒷문장과 모순입니다 ✗","niego: negar(부정하다, 거절하다)는 음악 취향 표현에 맞지 않습니다 ✗","afronto: afrontar(맞서다, 대처하다)는 문맥과 맞지 않습니다 ✗"]},{"id":"V158","q":"Suelo beber limonada cuando hace calor porque es ____.","o":["picante","escalofriante","tranquilizante","refrescante"],"a":3,"k":"-ante 형용사","t":"더울 때 나는 보통 레모네이드를 마신다. 상쾌하기(시원하기) 때문이다.","e":"refrescante는 '상쾌하게 하는, 시원하게 하는'이라는 뜻입니다. 동사 refrescar(시원하게 하다)에서 나온 말로, 더운 날씨(hace calor)와 레모네이드에 딱 맞습니다. -ante로 끝나는 형용사는 '~하게 만드는'이라는 뜻을 가진 경우가 많습니다.","x":["picante: 매운이라 레모네이드에 어울리지 않습니다 ✗","escalofriante: 소름 끼치는, 오싹한이라 ✗","tranquilizante: 진정시키는(진정제)이라 문맥과 맞지 않습니다 ✗","refrescante: 상쾌한, 시원하게 하는 → 정답 ✓"]},{"id":"V159","q":"Es normal que no funcione la plancha, olvidaste ____.","o":["enchufarla","fregarla","apagarla","limpiarla"],"a":0,"k":"가전 관련 동사","t":"다리미가 작동하지 않는 게 당연해. 너 플러그 꽂는 걸 잊었잖아.","e":"enchufar는 '(플러그를) 꽂다, 전원에 연결하다'라는 뜻입니다. enchufe(콘센트, 플러그)에서 온 말입니다. 동사원형 뒤에 직접목적격 대명사 la(= la plancha 다리미를)가 붙어 enchufarla가 되었습니다.","x":["enchufarla: 플러그를 꽂다 → 작동하지 않는 이유로 맞으므로 정답 ✓","fregarla: fregar(설거지하다, 문질러 닦다)는 다리미 작동과 관계없습니다 ✗","apagarla: apagar(끄다)를 잊었다면 오히려 켜져 있다는 뜻이라 ✗","limpiarla: limpiar(청소하다)는 작동하지 않는 이유가 되지 않습니다 ✗"]},{"id":"V160","q":"Me bañé en la piscina porque hacía un día bastante ____.","o":["invernal","caluroso","tormentoso","lluvioso"],"a":1,"k":"날씨 형용사","t":"꽤 더운 날이어서 나는 수영장에서 수영을 했다.","e":"caluroso는 '더운'이라는 뜻으로 calor(더위)에서 나온 형용사입니다. 수영장에 들어간 이유로 가장 자연스럽습니다. hacer un día + 형용사는 '~한 날이다'라는 날씨 표현입니다. 예: Hace un día soleado.(화창한 날이다.)","x":["invernal: 겨울의, 겨울 같은이라 수영하기 어렵습니다 ✗","caluroso: 더운 → 수영한 이유로 맞으므로 정답 ✓","tormentoso: 폭풍우가 치는이라 ✗","lluvioso: 비가 오는이라 ✗"]},{"id":"V161","q":"No creas lo que dicen en ese blog, la mayoría son noticias ____.","o":["serias","falsas","auténticas","verdaderas"],"a":1,"k":"뉴스 관련 형용사","t":"그 블로그에서 하는 말 믿지 마. 대부분 가짜 뉴스야.","e":"noticias falsas는 '가짜 뉴스'입니다. 'No creas(믿지 마)'라는 말 뒤이므로 부정적인 의미의 형용사가 필요합니다. 영어에서 온 fake news도 스페인어권에서 많이 씁니다.","x":["serias: 진지한, 신뢰할 만한이라 믿지 말라는 말과 반대입니다 ✗","falsas: 거짓의, 가짜의 → 믿지 말라는 이유로 정답 ✓","auténticas: 진짜의라 문맥과 반대입니다 ✗","verdaderas: 사실인, 진실된이라 문맥과 반대입니다 ✗"]},{"id":"V162","q":"Mi ____ materna es el inglés, pero tengo un buen nivel de español y hablo un poco de francés.","o":["cultura","lengua","familia","patria"],"a":1,"k":"lengua materna","t":"내 모국어는 영어지만, 스페인어 실력도 좋고 프랑스어도 조금 한다.","e":"lengua materna는 '모국어'라는 고정 표현입니다. lengua는 '혀' 외에 '언어'라는 뜻도 있습니다. 뒤에 나오는 inglés, español, francés 같은 언어들이 힌트입니다.","x":["cultura: 문화로, 'cultura materna'라는 표현은 쓰지 않습니다 ✗","lengua: 언어, lengua materna는 모국어 → 정답 ✓","familia: 가족으로, familia materna는 '외가'라는 뜻이라 ✗","patria: 조국으로, 언어를 가리키지 않습니다 ✗"]},{"id":"V163","q":"Estoy ____ con mi hijo. ¡Ha suspendido todas las asignaturas!","o":["contenta","encantada","decepcionada","satisfecha"],"a":2,"k":"감정 형용사","t":"나는 아들에게 실망했어. 모든 과목에서 낙제했거든!","e":"decepcionada는 '실망한'이라는 뜻이며, estar decepcionado/a con + 사람은 '~에게 실망하다'입니다. 말하는 사람이 여성이라 -a 형태입니다. suspender는 스페인에서 '(시험·과목에서) 낙제하다'라는 뜻입니다(중남미에서는 reprobar를 많이 씁니다).","x":["contenta: 기쁜이라 모든 과목 낙제와 맞지 않습니다 ✗","encantada: 매우 기쁜, 반한이라 문맥과 반대입니다 ✗","decepcionada: 실망한 → 정답 ✓","satisfecha: 만족한이라 문맥과 반대입니다 ✗"]},{"id":"V164","q":"Estás ____. ¿Te sientes mal?","o":["sonriente","tranquilo","a gusto","pálido"],"a":3,"k":"외모·안색 형용사","t":"너 얼굴이 창백해. 몸이 안 좋니?","e":"pálido는 '창백한, 핏기 없는'이라는 뜻으로, 몸이 안 좋아 보일 때 자주 씁니다. 뒤의 ¿Te sientes mal?(몸이 안 좋니?)과 자연스럽게 이어집니다. 예: Se puso pálido al ver la sangre.(그는 피를 보고 창백해졌다.)","x":["sonriente: 웃고 있는이라 아파 보이는 모습과 맞지 않습니다 ✗","tranquilo: 차분한, 평온한이라 ✗","a gusto: 편안한, 기분 좋은이라 ✗","pálido: 창백한 → 몸이 안 좋냐는 질문과 맞으므로 정답 ✓"]},{"id":"V165","q":"En ese piso no vive nadie, hace tiempo que no está ____.","o":["habitado","lleno","abarrotado","vacío"],"a":0,"k":"habitado 거주된","t":"그 아파트에는 아무도 살지 않는다. 사람이 살지 않은 지 오래되었다.","e":"habitado는 '사람이 살고 있는, 거주 중인'이라는 뜻으로 동사 habitar(살다, 거주하다)에서 나왔습니다. no está habitado는 '사람이 살지 않는다'로 앞 문장 no vive nadie와 일치합니다. 스페인에서 piso는 '아파트(공동주택의 한 세대)'를 뜻합니다.","x":["habitado: 사람이 사는 → 부정문이 되어 '아무도 안 산다'와 일치하므로 정답 ✓","lleno: 가득 찬이라 no está lleno는 '꽉 차 있지 않다'로 의미가 다릅니다 ✗","abarrotado: (사람·물건으로) 꽉 들어찬이라 문맥과 맞지 않습니다 ✗","vacío: 비어 있는이라 no está vacío는 '비어 있지 않다'가 되어 모순입니다 ✗"]},{"id":"V166","q":"No hice bien el examen porque no estaba ____.","o":["concentrada","alegre","aburrida","enfadada"],"a":0,"k":"상태 형용사","t":"나는 집중하지 못해서 시험을 잘 보지 못했다.","e":"concentrado/a는 '집중한'이라는 뜻으로 estar와 함께 상태를 나타냅니다. 시험을 잘 못 본 이유로 '집중하지 못했다'가 가장 자연스럽습니다. 말하는 사람이 여성이라 concentrada입니다.","x":["concentrada: 집중한 → 집중하지 못해 시험을 망쳤으므로 정답 ✓","alegre: 즐거운이라 시험 결과의 이유로 어색합니다 ✗","aburrida: 지루한이라 no estaba aburrida는 이유가 되지 않습니다 ✗","enfadada: 화난이라 화나지 않아서 시험을 망쳤다는 것은 어색합니다 ✗"]},{"id":"V167","q":"La repentina muerte de su padre fue un duro ____ para él.","o":["corte","empujón","golpe","toque"],"a":2,"k":"golpe 타격","t":"아버지의 갑작스러운 죽음은 그에게 큰 충격(타격)이었다.","e":"golpe는 원래 '타격, 때림'이지만, un duro golpe는 '큰 충격, 뼈아픈 타격'이라는 비유적 표현으로 자주 씁니다. 슬픈 사건이 마음에 준 충격을 나타냅니다. 예: Perder el trabajo fue un golpe para ella.(실직은 그녀에게 타격이었다.)","x":["corte: 자름, 베인 상처, 정전 등의 뜻으로 이 표현에 쓰지 않습니다 ✗","empujón: 밀침이라 충격의 의미로 쓰지 않습니다 ✗","golpe: 타격, un duro golpe는 큰 충격 → 정답 ✓","toque: 가볍게 건드림, 손질이라 ✗"]},{"id":"V168","q":"No podemos ____ al edificio porque no tenemos las llaves del portal.","o":["asistir","salir","llamar","acceder"],"a":3,"k":"acceder 들어가다","t":"건물 현관 열쇠가 없어서 우리는 건물에 들어갈 수 없다.","e":"acceder a는 '~에 들어가다, 접근하다'라는 뜻으로 전치사 a와 함께 씁니다(al = a + el). 열쇠가 없어서 들어갈 수 없는 상황에 맞습니다. 인터넷에서 acceder a la cuenta(계정에 접속하다)처럼도 씁니다.","x":["asistir: asistir a는 '~에 참석하다'로 건물에는 맞지 않습니다 ✗","salir: 나가다라 열쇠 없이 들어가지 못하는 상황과 반대입니다 ✗","llamar: 부르다, 전화하다로 'llamar al edificio'는 어색합니다 ✗","acceder: acceder a(~에 들어가다) → 정답 ✓"]},{"id":"V169","q":"Estaba tan nerviosa que no podía ____ el número de teléfono correctamente.","o":["fabricar","realizar","hacer","marcar"],"a":3,"k":"marcar 번호 누르다","t":"나는 너무 긴장해서 전화번호를 제대로 누를 수가 없었다.","e":"marcar el número는 '(전화)번호를 누르다, 다이얼을 돌리다'라는 고정 표현입니다. marcar는 '표시하다'라는 기본 뜻 외에 '번호를 누르다', '골을 넣다(marcar un gol)', '(시계가) 시간을 가리키다'처럼 다양하게 씁니다.","x":["fabricar: 제조하다라 ✗","realizar: 실행하다, 실현하다로 번호와 쓰지 않습니다 ✗","hacer: 하다, 만들다로 번호를 누른다는 뜻으로 쓰지 않습니다 ✗","marcar: marcar el número(번호를 누르다) → 정답 ✓"]},{"id":"V170","q":"____ es una salsa que se hace con aceite y huevo.","o":["El guacamole","La mayonesa","El gazpacho","El kétchup"],"a":1,"k":"음식 어휘","t":"마요네즈는 기름과 달걀로 만드는 소스다.","e":"la mayonesa(마요네즈)는 기름(aceite)과 달걀(huevo)을 섞어 만드는 소스입니다. 다른 보기들도 음식 이름이지만 재료가 다릅니다. ser + 명사로 정의를 설명하는 문장입니다.","x":["El guacamole: 과카몰레, 아보카도로 만드는 멕시코 소스라 ✗","La mayonesa: 마요네즈, 기름과 달걀로 만듦 → 정답 ✓","El gazpacho: 가스파초, 토마토 등으로 만드는 스페인 냉수프라 ✗","El kétchup: 케첩, 토마토로 만드는 소스라 ✗"]},{"id":"V171","q":"Tenemos que limitar nuestro consumo eléctrico porque el precio de la luz ha sufrido una subida ____.","o":["leve","incansable","simbólica","considerable"],"a":3,"k":"정도 형용사","t":"전기 요금이 상당히 올랐기 때문에 우리는 전기 소비를 줄여야 한다.","e":"considerable는 '상당한, 꽤 큰'이라는 뜻입니다. 소비를 줄여야 할 정도라면 요금이 '크게' 올랐다는 의미가 맞습니다. 스페인에서 la luz는 '빛' 외에 일상적으로 '전기(요금)'를 뜻하기도 합니다.","x":["leve: 가벼운, 약간의라 소비를 줄일 이유로 약합니다 ✗","incansable: 지칠 줄 모르는으로 사람에게 쓰는 말이라 ✗","simbólica: 상징적인, 형식적인(아주 적은)이라 ✗","considerable: 상당한 → 소비를 줄일 만큼 큰 인상이므로 정답 ✓"]},{"id":"V172","q":"Todos podemos darte nuestra opinión, pero la decisión final ____ de ti.","o":["desconfía","depende","se ocupa","se cansa"],"a":1,"k":"depender de","t":"우리 모두 너에게 의견을 줄 수는 있지만, 최종 결정은 너에게 달려 있다.","e":"depender de는 '~에 달려 있다, ~에 의존하다'라는 뜻으로 전치사 de와 함께 씁니다. la decisión final depende de ti는 '최종 결정은 너에게 달렸다'라는 자주 쓰는 표현입니다. 예: Depende del tiempo.(날씨에 달렸어.)","x":["desconfía: desconfiar de(~를 믿지 않다)로 결정이 주어가 되면 어색합니다 ✗","depende: depender de(~에 달려 있다) → 정답 ✓","se ocupa: ocuparse de(~를 맡다, 처리하다)는 사람이 주어일 때 쓰며 문맥과 맞지 않습니다 ✗","se cansa: cansarse de(~에 싫증 나다)라 ✗"]},{"id":"V173","q":"Siempre es agradable hablar con Ismael, es un tipo de ____ fácil.","o":["aspecto","trato","uso","aire"],"a":1,"k":"de trato fácil","t":"이스마엘과 이야기하는 것은 늘 즐겁다. 그는 사귀기 편한(대하기 쉬운) 사람이다.","e":"trato는 '대우, 사람을 대하는 방식, 교제'라는 뜻이며, de trato fácil은 '사귀기 쉬운, 붙임성 좋은'이라는 표현입니다. 이야기하기 즐겁다는 앞 문장과 잘 맞습니다. 스페인 구어에서 tipo는 '녀석, 사람'이라는 뜻입니다.","x":["aspecto: 외모, 겉모습으로 de aspecto fácil이라는 표현은 쓰지 않습니다 ✗","trato: 대하는 방식, de trato fácil은 대하기 편한 → 정답 ✓","uso: 사용으로 사람 성격에 쓰지 않습니다 ✗","aire: 공기, 분위기로 이 표현과 맞지 않습니다 ✗"]},{"id":"V174","q":"¿En qué país ____ esta película?","o":["se compuso","se construyó","se ordenó","se filmó"],"a":3,"k":"filmar 촬영하다","t":"이 영화는 어느 나라에서 촬영되었니?","e":"filmar는 '(영화를) 촬영하다'라는 뜻이고, se filmó는 수동의 se를 써서 '촬영되었다'는 의미입니다. película(영화)와 짝을 이루는 동사입니다. 비슷한 말로 rodar(촬영하다)도 많이 씁니다: Se rodó en México.(멕시코에서 촬영되었다.)","x":["se compuso: componer(작곡하다, 구성하다)로 음악에 쓰입니다 ✗","se construyó: construir(건설하다)로 건물에 쓰입니다 ✗","se ordenó: ordenar(정리하다, 명령하다)라 ✗","se filmó: filmar(촬영하다)의 수동 표현 → 정답 ✓"]},{"id":"V175","q":"Genaro no está bien, tiene una ____ del corazón.","o":["vitalidad","especialidad","maldad","enfermedad"],"a":3,"k":"-dad 명사","t":"헤나로는 상태가 좋지 않다. 심장병을 앓고 있다.","e":"enfermedad는 '병, 질병'이며, una enfermedad del corazón은 '심장병'입니다. 형용사 enfermo(아픈)에서 나온 명사입니다. 보기 모두 -dad로 끝나는 명사이므로 뜻을 정확히 구별하는 것이 중요합니다.","x":["vitalidad: 활력이라 상태가 좋지 않다는 말과 맞지 않습니다 ✗","especialidad: 전문 분야, 특기라 ✗","maldad: 악의, 사악함이라 ✗","enfermedad: 병, 질병 → 정답 ✓"]},{"id":"V176","q":"Jaime está muy callado, hoy no tiene ____ de hablar.","o":["esperanzas","ilusiones","ganas","hambre"],"a":2,"k":"tener ganas de","t":"하이메는 무척 조용하다. 오늘은 말할 기분이 아닌가 보다.","e":"tener ganas de + 동사원형은 '~하고 싶다, ~할 마음이 있다'라는 매우 자주 쓰는 표현입니다. no tener ganas de hablar는 '말하고 싶지 않다'입니다. 예: Tengo ganas de verte.(너 보고 싶어.)","x":["esperanzas: 희망들로 tener esperanzas de는 '~할 희망이 있다'라 이 문맥에 어색합니다 ✗","ilusiones: 기대, 설렘으로 이 표현에 쓰지 않습니다 ✗","ganas: tener ganas de(~하고 싶다) → 정답 ✓","hambre: 배고픔으로 tener hambre는 '배고프다'라 ✗"]},{"id":"V177","q":"Lucía es muy ____, no quiere que su novio hable con ninguna otra mujer.","o":["imprudente","celosa","sensitiva","liberal"],"a":1,"k":"성격 형용사","t":"루시아는 질투심이 아주 많다. 남자친구가 다른 어떤 여자와도 말하지 않기를 원한다.","e":"celoso/a는 '질투하는, 질투심 많은'이라는 뜻입니다. 남자친구가 다른 여자와 말하는 것을 싫어하는 모습에 딱 맞습니다. 명사 celos(질투)와 함께 tener celos(질투하다)도 알아 두세요.","x":["imprudente: 경솔한, 조심성 없는이라 ✗","celosa: 질투심 많은 → 정답 ✓","sensitiva: 감각의, 감각적인이라 성격 설명에 맞지 않습니다(예민한은 sensible) ✗","liberal: 자유로운, 개방적인이라 문맥과 반대입니다 ✗"]},{"id":"V178","q":"Apenas hay tráfico, así que llegaremos ____ a nuestro destino.","o":["antes","más adelante","tarde","después"],"a":0,"k":"시간 부사","t":"교통량이 거의 없으니, 우리는 목적지에 일찍(예정보다 먼저) 도착할 것이다.","e":"antes는 '전에, 먼저, 더 일찍'이라는 뜻입니다. 교통이 거의 없으니(apenas hay tráfico) 예상보다 빨리 도착한다는 의미입니다. apenas는 '거의 ~않다'라는 부정의 뜻을 가진 부사입니다.","x":["antes: 더 일찍, 먼저 → 차가 없어서 빨리 도착하므로 정답 ✓","más adelante: 나중에, 더 앞쪽으로라 문맥과 맞지 않습니다 ✗","tarde: 늦게라 교통이 없다는 이유와 반대입니다 ✗","después: 나중에, 후에라 ✗"]},{"id":"V179","q":"Felisa es ____, aparte de buena persona, es guapa y trabajadora.","o":["una cruz","un banco","un tesoro","una medalla"],"a":2,"k":"비유 표현","t":"펠리사는 보물 같은 사람이다. 좋은 사람인 데다 예쁘고 부지런하다.","e":"ser un tesoro는 '보물 같은 사람이다, 정말 소중한 사람이다'라는 비유 표현입니다. 뒤에 나오는 좋은 사람, 예쁨, 부지런함 같은 칭찬과 잘 어울립니다. 반대로 ser una cruz는 '골칫거리, 짐'이라는 뜻입니다.","x":["una cruz: 십자가, 비유적으로 고통·짐이라 칭찬과 반대입니다 ✗","un banco: 은행, 벤치라 사람을 칭찬하는 표현이 아닙니다 ✗","un tesoro: 보물, 소중한 사람 → 정답 ✓","una medalla: 메달이라 사람을 비유하는 일반 표현이 아닙니다 ✗"]},{"id":"V180","q":"Uso un ____ especial para pieles sensibles.","o":["diamante","colorante","calmante","desodorante"],"a":3,"k":"생활용품 어휘","t":"나는 민감한 피부용 특수 데오도란트를 쓴다.","e":"desodorante는 '데오도란트(체취 제거제)'입니다. 피부(piel)에 직접 사용하는 제품이라 '민감한 피부용'이라는 설명과 맞습니다. -ante로 끝나는 명사는 '~하는 것(물질)'을 뜻하는 경우가 많습니다.","x":["diamante: 다이아몬드로 피부에 사용하는 제품이 아닙니다 ✗","colorante: 색소, 착색료라 ✗","calmante: 진통제, 진정제로 보통 복용하는 약이라 ✗","desodorante: 데오도란트 → 정답 ✓"]},{"id":"V181","q":"El gorrión es un ____ que suele volar en grupo.","o":["reptil","pájaro","anfibio","pez"],"a":1,"k":"동물 분류 어휘","t":"참새는 보통 무리를 지어 나는 새다.","e":"gorrión은 '참새'이고 pájaro는 '(작은) 새'입니다. 날아다닌다(volar)는 설명이 힌트입니다. 일반적으로 '새'는 ave라고도 하는데, pájaro는 주로 작은 새를 가리킵니다.","x":["reptil: 파충류라 ✗","pájaro: 새 → 참새는 새이므로 정답 ✓","anfibio: 양서류라 ✗","pez: (살아 있는) 물고기라 ✗"]},{"id":"V182","q":"Gracias al jarabe que me ____ mi doctora, ya no tengo tos.","o":["prestó","recetó","dejó","compró"],"a":1,"k":"recetar 처방하다","t":"의사 선생님이 처방해 주신 시럽 덕분에 이제 기침을 하지 않는다.","e":"recetar는 '(약을) 처방하다'라는 뜻으로, 의사(doctora)가 하는 행동에 맞습니다. 명사 receta는 '처방전' 또는 '요리법'입니다. jarabe는 '시럽(물약)', tos는 '기침'입니다.","x":["prestó: prestar(빌려주다)로 약에는 어색합니다 ✗","recetó: recetar(처방하다) → 의사가 약을 처방했으므로 정답 ✓","dejó: dejar(두다, 빌려주다)라 의사의 행동으로 어색합니다 ✗","compró: comprar(사다)로 의사가 약을 사 준다는 것은 부자연스럽습니다 ✗"]},{"id":"V183","q":"Hay cristales en el suelo, no andes ____.","o":["descalzo","vestido","descubierto","desnudo"],"a":0,"k":"descalzo 맨발","t":"바닥에 유리 조각이 있어. 맨발로 다니지 마.","e":"descalzo는 '맨발의, 신발을 신지 않은'이라는 뜻입니다. andar descalzo는 '맨발로 걷다'입니다. 유리 조각(cristales)이 있으니 발을 다치지 않도록 하라는 경고입니다.","x":["descalzo: 맨발의 → 유리에 발을 다칠 수 있으므로 정답 ✓","vestido: 옷을 입은이라 유리 조각과 관계없습니다 ✗","descubierto: 덮이지 않은, 드러난이라 발에 쓰기 어색합니다 ✗","desnudo: 벌거벗은이라 이 문맥에서 너무 넓은 의미입니다 ✗"]},{"id":"V184","q":"Después de un accidente tan grave, es un milagro que estén ____.","o":["agotados","vivos","nerviosos","exhaustos"],"a":1,"k":"상태 형용사","t":"그렇게 심각한 사고 후에 그들이 살아 있다는 건 기적이다.","e":"vivo는 '살아 있는'이라는 뜻으로 estar vivo는 '살아 있다'입니다. 심각한 사고(accidente tan grave) 후의 기적(milagro)이라는 문맥에 맞습니다. es un milagro que 뒤에는 접속법(바람·감정·판단을 나타내는 동사 형태)이 와서 estén이 쓰였습니다.","x":["agotados: 기진맥진한이라 기적이라고 할 일이 아닙니다 ✗","vivos: 살아 있는 → 사고 후 생존이 기적이므로 정답 ✓","nerviosos: 긴장한이라 ✗","exhaustos: 지칠 대로 지친이라 ✗"]},{"id":"V185","q":"Uso ____ de contacto porque no me gusta llevar gafas.","o":["bermudas","medias","lentes","guantes"],"a":2,"k":"콘택트렌즈 어휘","t":"나는 안경 쓰는 게 싫어서 콘택트렌즈를 낀다.","e":"lentes de contacto는 '콘택트렌즈'입니다. 스페인에서는 lentillas라고도 많이 말합니다. 중남미에서는 lentes만 쓰면 '안경'을 뜻하기도 하니 참고하세요.","x":["bermudas: 버뮤다 반바지라 ✗","medias: 스타킹이라 ✗","lentes: lentes de contacto(콘택트렌즈) → 정답 ✓","guantes: 장갑이라 ✗"]},{"id":"V186","q":"Antes cometía muchos errores, pero ahora que vive en Inglaterra tiene un ____ increíble del inglés.","o":["olvido","dominio","desconocimiento","desuso"],"a":1,"k":"dominio 숙달","t":"예전에는 실수를 많이 했지만, 영국에 사는 지금은 영어 실력이 놀라울 정도로 능숙하다.","e":"dominio는 '지배' 외에 '(언어·기술의) 숙달, 구사 능력'이라는 뜻이 있습니다. tener un dominio increíble del inglés는 '영어를 놀랍도록 잘 구사한다'입니다. 동사 dominar un idioma(언어를 마스터하다)도 함께 알아 두세요.","x":["olvido: 망각, 잊음이라 실력 향상과 반대입니다 ✗","dominio: 숙달, 구사 능력 → 정답 ✓","desconocimiento: 무지, 모름이라 문맥과 반대입니다 ✗","desuso: 사용하지 않음이라 ✗"]},{"id":"V187","q":"El ____ de mi equipo de baloncesto tiene muchos años de experiencia.","o":["entrenador","programador","funcionario","librero"],"a":0,"k":"직업 어휘","t":"우리 농구팀 감독(코치)은 경력이 아주 많다.","e":"entrenador는 '코치, 감독, 트레이너'라는 뜻으로 동사 entrenar(훈련시키다)에서 나왔습니다. 농구팀(equipo de baloncesto)과 연결되는 직업은 entrenador입니다. 중남미에서는 농구를 básquetbol이라고도 합니다.","x":["entrenador: 코치, 감독 → 농구팀과 어울리므로 정답 ✓","programador: 프로그래머라 ✗","funcionario: 공무원이라 ✗","librero: 서점 주인, 책 파는 사람이라 ✗"]},{"id":"V188","q":"Soy alérgica a la leche de ____ animal, por eso tomo leche de soja.","o":["creación","principio","origen","especie"],"a":2,"k":"origen 출처","t":"나는 동물성 우유에 알레르기가 있어서 두유를 마신다.","e":"de origen animal은 '동물에서 나온, 동물성의'라는 표현입니다. origen은 '기원, 출처'라는 뜻입니다. 반대로 de origen vegetal은 '식물성의'입니다.","x":["creación: 창조, 창작이라 ✗","principio: 시작, 원칙이라 ✗","origen: 기원, de origen animal은 동물성 → 정답 ✓","especie: 종(種)이라 'leche de especie animal'은 쓰지 않는 표현입니다 ✗"]},{"id":"V189","q":"Si tienes ____, ¿por qué no te quitas el abrigo?","o":["calor","tos","frío","dolor"],"a":0,"k":"tener + 명사","t":"더우면 코트를 벗지 그래?","e":"tener calor는 '덥다'라는 표현입니다. 스페인어는 몸으로 느끼는 더위·추위를 tener + 명사로 표현합니다(tener frío 춥다). 코트를 벗으라는 말에 맞는 이유는 더위입니다.","x":["calor: tener calor(덥다) → 코트를 벗을 이유이므로 정답 ✓","tos: tener tos(기침이 나다)는 코트를 벗을 이유가 아닙니다 ✗","frío: tener frío(춥다)라 오히려 코트를 입어야 합니다 ✗","dolor: tener dolor(통증이 있다)라 ✗"]},{"id":"V190","q":"Al llegar a la estación, podemos dejar el ____ en consigna y dar una vuelta antes de tomar el autobús.","o":["equipaje","billete","móvil","andén"],"a":0,"k":"여행 어휘","t":"역에 도착하면 짐을 물품 보관소에 맡기고 버스를 타기 전에 한 바퀴 둘러볼 수 있다.","e":"equipaje는 '짐, 수하물'입니다. consigna는 역이나 공항의 '수하물 보관소'를 말합니다. 짐을 맡기고 가볍게 구경하는 상황입니다. dar una vuelta는 '한 바퀴 돌다, 산책하다'라는 표현입니다.","x":["equipaje: 짐, 수하물 → 보관소에 맡기는 것이므로 정답 ✓","billete: 표, 승차권(중남미는 boleto)으로 보관소에 맡기지 않습니다 ✗","móvil: 휴대폰(중남미는 celular)이라 ✗","andén: 승강장(플랫폼)이라 맡길 수 있는 물건이 아닙니다 ✗"]},{"id":"V191","q":"Tengo un ____ que repite algunas palabras constantemente.","o":["cordero","loro","toro","borrego"],"a":1,"k":"동물 어휘","t":"나는 몇몇 단어를 계속 따라 하는 앵무새를 키운다.","e":"loro는 '앵무새'로 사람의 말을 따라 하는 새입니다. repetir palabras(단어를 반복하다)가 힌트입니다. 비유적으로 hablar como un loro는 '쉬지 않고 떠들다'라는 뜻입니다.","x":["cordero: 어린 양이라 ✗","loro: 앵무새 → 말을 따라 하므로 정답 ✓","toro: 황소라 ✗","borrego: 어린 양(1~2살)이라 ✗"]},{"id":"V192","q":"El Aconcagua es un ____ chileno que desemboca en el océano Pacífico.","o":["monte","río","volcán","lago"],"a":1,"k":"지리 어휘","t":"아콩카과는 태평양으로 흘러 들어가는 칠레의 강이다.","e":"desembocar en은 '(강이) ~로 흘러 들어가다'라는 뜻이므로 강(río)만 가능합니다. 아콩카과(Aconcagua)는 아르헨티나에 있는 아메리카 최고봉의 이름이기도 하지만, 같은 이름의 강이 칠레에 있어 태평양으로 흐릅니다. 동사가 결정적인 힌트입니다.","x":["monte: 산이라 바다로 흘러 들어갈 수 없습니다 ✗","río: 강 → desembocar(흘러 들어가다)와 어울리므로 정답 ✓","volcán: 화산이라 ✗","lago: 호수라 바다로 흘러 들어간다고 하지 않습니다 ✗"]},{"id":"V193","q":"He llegado tarde al trabajo porque hay mucho ____.","o":["transporte","conductor","tráfico","aparcamiento"],"a":2,"k":"교통 어휘","t":"차가 많이 막혀서(교통량이 많아서) 나는 회사에 늦게 도착했다.","e":"tráfico는 '교통, 교통량'이며 hay mucho tráfico는 '차가 많이 막힌다'입니다. 지각의 이유로 가장 자연스럽습니다. 중남미에서는 tránsito라고도 합니다.","x":["transporte: 교통수단, 운송이라 'hay mucho transporte'는 지각 이유로 어색합니다 ✗","conductor: 운전자로 단수형이라 mucho와 어울리지 않습니다 ✗","tráfico: 교통량, 교통 체증 → 정답 ✓","aparcamiento: 주차장, 주차라 지각 이유로 맞지 않습니다 ✗"]},{"id":"V194","q":"Vimos dos leones en el ____.","o":["mercado","estadio","banco","zoo"],"a":3,"k":"장소 어휘","t":"우리는 동물원에서 사자 두 마리를 봤다.","e":"zoo는 '동물원'으로 zoológico의 줄임말입니다. 사자(leones)를 볼 수 있는 곳은 동물원입니다.","x":["mercado: 시장이라 ✗","estadio: 경기장이라 ✗","banco: 은행, 벤치라 ✗","zoo: 동물원 → 사자를 볼 수 있으므로 정답 ✓"]},{"id":"V195","q":"En ____ del local, la música estaba al máximo volumen, pero por fuera no se oía nada.","o":["la azotea","el interior","la terraza","el exterior"],"a":1,"k":"안과 밖 어휘","t":"가게 안에서는 음악이 최대 볼륨이었지만, 밖에서는 아무 소리도 들리지 않았다.","e":"en el interior de는 '~의 안에서, 내부에서'라는 뜻입니다. 뒤의 por fuera(밖에서)와 대비되므로 '안쪽'을 뜻하는 interior가 맞습니다. local은 '가게, 점포, 업소'를 뜻합니다.","x":["la azotea: 옥상이라 ✗","el interior: 내부 → por fuera(밖)와 대비되므로 정답 ✓","la terraza: 테라스로 실외 공간이라 ✗","el exterior: 외부라 '밖에서는 안 들렸다'는 뒷말과 모순입니다 ✗"]},{"id":"V196","q":"Somos clientes ____ de este restaurante, venimos mucho.","o":["habituales","constantes","regulares","continuos"],"a":0,"k":"단골손님 표현","t":"우리는 이 식당의 단골손님이다. 자주 온다.","e":"cliente habitual은 '단골손님'이라는 고정 표현입니다. habitual은 '평소의, 습관적인'이라는 뜻입니다. venimos mucho(자주 온다)가 힌트입니다.","x":["habituales: 단골의, 늘 오는 → cliente habitual은 단골손님이므로 정답 ✓","constantes: 끊임없는이라 손님에게는 잘 쓰지 않습니다 ✗","regulares: 규칙적인, 보통의라 이 표현에서는 덜 자연스럽습니다 ✗","continuos: 연속적인이라 손님에게 쓰지 않습니다 ✗"]},{"id":"V197","q":"Hoy es un día ____ en toda España, por eso casi todas las tiendas están cerradas.","o":["ordinario","festivo","normal","laborable"],"a":1,"k":"día festivo","t":"오늘은 스페인 전국 공휴일이라서 거의 모든 상점이 문을 닫았다.","e":"día festivo는 '공휴일, 휴일'입니다. 상점들이 문을 닫은 이유로 맞습니다. 반대말은 día laborable(평일, 근무일)입니다. 중남미에서는 día feriado라고도 합니다.","x":["ordinario: 보통의, 평범한이라 가게가 닫힐 이유가 없습니다 ✗","festivo: 공휴일의 → 정답 ✓","normal: 평범한이라 ✗","laborable: 근무일의, 평일의라 문맥과 반대입니다 ✗"]},{"id":"V198","q":"Para tomar sopa debes usar ____.","o":["un tenedor","un cuchillo","un cucharón","una cuchara"],"a":3,"k":"식기 어휘","t":"수프를 먹으려면 숟가락을 써야 한다.","e":"cuchara는 '숟가락'입니다. 스페인어에서 수프는 tomar(먹다, 마시다)와 함께 자주 씁니다. cucharón(국자)은 cuchara보다 큰 것으로, 덜어 담을 때 씁니다.","x":["un tenedor: 포크라 수프를 먹을 수 없습니다 ✗","un cuchillo: 칼이라 ✗","un cucharón: 국자로 수프를 덜 때 쓰지 먹을 때 쓰지 않습니다 ✗","una cuchara: 숟가락 → 정답 ✓"]},{"id":"V199","q":"Esa profesora es demasiado ____ con sus alumnos, pienso que debería ser más estricta.","o":["seria","severa","suave","dura"],"a":2,"k":"성격 형용사","t":"그 선생님은 학생들에게 너무 무르다. 더 엄격해야 한다고 생각한다.","e":"suave는 '부드러운, 무른, 관대한'이라는 뜻입니다. 뒤에 '더 엄격해야 한다(debería ser más estricta)'고 했으므로 지금은 반대로 너무 부드럽다는 뜻입니다. 나머지 보기는 모두 '엄격하다'는 의미에 가깝습니다.","x":["seria: 진지한, 엄숙한이라 더 엄격해야 한다는 말과 어울리지 않습니다 ✗","severa: 엄격한이라 문맥과 반대입니다 ✗","suave: 부드러운, 무른 → 더 엄격해야 한다는 말과 맞으므로 정답 ✓","dura: 엄한, 단단한이라 문맥과 반대입니다 ✗"]},{"id":"V200","q":"Es muy útil tener aparcamiento ____, así no me preocupo por la seguridad de mi coche.","o":["barato","gratuito","grande","privado"],"a":3,"k":"전용 주차장","t":"전용(개인) 주차장이 있으면 정말 유용하다. 그러면 내 차의 안전을 걱정하지 않아도 된다.","e":"privado는 '사적인, 개인 전용의'라는 뜻입니다. 차의 안전(seguridad)을 걱정하지 않아도 되는 이유는 남들이 들어오지 못하는 전용 주차장이기 때문입니다. aparcamiento는 스페인어(스페인)로 '주차장'이며, 중남미에서는 estacionamiento를 많이 씁니다.","x":["barato: 싼이라 안전과 관계없습니다 ✗","gratuito: 무료의라 안전과 관계없습니다 ✗","grande: 큰이라 안전의 이유가 되지 않습니다 ✗","privado: 전용의, 개인의 → 차가 안전하므로 정답 ✓"]},{"id":"V201","q":"Esta película fue un ____ de taquilla cuando se estrenó. La vio mucha gente.","o":["fracaso","éxito","premio","intento"],"a":1,"k":"éxito 성공","t":"이 영화는 개봉했을 때 흥행에 성공했다. 많은 사람이 봤다.","e":"éxito de taquilla는 '흥행 성공(박스오피스 히트)'입니다. taquilla는 '매표소'라는 뜻입니다. 주의: éxito는 영어 exit(출구)가 아니라 '성공'이라는 뜻입니다(출구는 salida).","x":["fracaso: 실패라 많은 사람이 봤다는 말과 반대입니다 ✗","éxito: 성공, éxito de taquilla는 흥행 성공 → 정답 ✓","premio: 상이라 taquilla(매표소)와 어울리지 않습니다 ✗","intento: 시도라 ✗"]},{"id":"V202","q":"Al caerme, me ____ daño en la pierna derecha.","o":["tuve","puse","tomé","hice"],"a":3,"k":"hacerse daño","t":"넘어지면서 나는 오른쪽 다리를 다쳤다.","e":"hacerse daño는 '다치다'라는 고정 표현이며, me hice daño는 '내가 다쳤다'입니다. daño는 '손상, 해'라는 뜻입니다. 예: ¿Te has hecho daño?(너 다쳤니?)","x":["tuve: tener(가지다)로 'tener daño'라고 하지 않습니다 ✗","puse: poner(놓다)로 이 표현에 쓰지 않습니다 ✗","tomé: tomar(잡다, 먹다)로 이 표현에 쓰지 않습니다 ✗","hice: hacerse daño(다치다)의 1인칭 과거 → 정답 ✓"]},{"id":"V203","q":"____ a través de las redes sociales no siempre es bueno.","o":["Especializarse","Levantarse","Informarse","Acostarse"],"a":2,"k":"재귀동사 의미","t":"소셜 미디어를 통해 정보를 얻는 것이 항상 좋은 것은 아니다.","e":"informarse는 '정보를 얻다, 알아보다'라는 재귀동사입니다. a través de las redes sociales(소셜 미디어를 통해)와 자연스럽게 어울립니다. 동사원형이 문장의 주어 역할을 하고 있습니다.","x":["Especializarse: 전문화하다, 전공하다라 소셜 미디어와 어울리지 않습니다 ✗","Levantarse: 일어나다라 ✗","Informarse: 정보를 얻다 → 정답 ✓","Acostarse: 잠자리에 들다라 ✗"]},{"id":"V204","q":"A todo el mundo le gusta ____ tiempo con buenos amigos.","o":["practicar","poner","pasear","pasar"],"a":3,"k":"pasar tiempo","t":"좋은 친구들과 시간을 보내는 것은 누구나 좋아한다.","e":"pasar tiempo는 '시간을 보내다'라는 표현입니다. pasar는 '지나가다' 외에 '(시간을) 보내다'라는 뜻이 있습니다. 예: Pasé el fin de semana en la playa.(주말을 해변에서 보냈다.)","x":["practicar: 연습하다라 시간과 쓰지 않습니다 ✗","poner: 놓다라 ✗","pasear: 산책하다라 목적어 tiempo를 갖지 않습니다 ✗","pasar: pasar tiempo(시간을 보내다) → 정답 ✓"]},{"id":"V205","q":"Todas las ciudades deberían tener espacios ____ con árboles y otros elementos de la naturaleza.","o":["naranjas","blancos","azules","verdes"],"a":3,"k":"espacios verdes","t":"모든 도시에는 나무와 다른 자연 요소가 있는 녹지 공간이 있어야 한다.","e":"espacios verdes(녹지 공간)는 공원·정원처럼 나무와 풀이 있는 장소를 뜻하는 고정 표현입니다. 색 verde(초록)가 자연을 상징합니다. zonas verdes도 같은 뜻입니다.","x":["naranjas: 주황색이라 이런 표현이 없습니다 ✗","blancos: 흰색이라 ✗","azules: 파란색이라 ✗","verdes: 초록색, espacios verdes는 녹지 공간 → 정답 ✓"]},{"id":"V206","q":"Mi marido me trajo un ____ de flores el día de San Valentín.","o":["paquete","tarro","bote","ramo"],"a":3,"k":"단위 명사","t":"남편이 밸런타인데이에 나에게 꽃다발을 가져다주었다.","e":"ramo de flores는 '꽃다발'입니다. ramo는 '다발'이라는 뜻으로 꽃과 함께 씁니다. 스페인어에서는 물건마다 쓰는 단위 명사가 다르니 함께 외우는 것이 좋습니다.","x":["paquete: 소포, 꾸러미라 꽃과 쓰지 않습니다 ✗","tarro: (유리) 병, 단지라 ✗","bote: 통, 병(캔)이라 ✗","ramo: 다발, ramo de flores는 꽃다발 → 정답 ✓"]},{"id":"V207","q":"No te creo, eso que dices es ____.","o":["interesante","incontrolable","imposible","inseguro"],"a":2,"k":"판단 형용사","t":"난 네 말을 안 믿어. 네가 말하는 건 불가능한 일이야.","e":"imposible는 '불가능한'이라는 뜻입니다. 상대의 말을 믿지 않는다(No te creo)는 이유로 가장 자연스럽습니다. 보기들이 모두 in-/im-(부정 접두사)으로 시작하지만 interesante는 부정의 뜻이 아닙니다.","x":["interesante: 흥미로운이라 믿지 않는 이유가 아닙니다 ✗","incontrolable: 통제할 수 없는이라 ✗","imposible: 불가능한 → 믿지 않는 이유로 정답 ✓","inseguro: 불안한, 확신 없는이라 말의 내용을 평가하기 어색합니다 ✗"]},{"id":"V208","q":"Mi amiga Ana ____ diez kilos durante su embarazo.","o":["engordó","adelgazó","perdió","bajó"],"a":0,"k":"engordar 살찌다","t":"내 친구 아나는 임신 기간에 10킬로그램이 쪘다.","e":"engordar는 '살찌다, 체중이 늘다'라는 뜻이며, engordar diez kilos는 '10킬로그램이 찌다'입니다. 임신(embarazo) 중에는 보통 체중이 늘어납니다. 주의: embarazada는 '임신한'이라는 뜻이지 '당황한'이 아닙니다.","x":["engordó: engordar(살찌다) → 임신 중 체중 증가이므로 정답 ✓","adelgazó: adelgazar(살 빠지다)라 임신 중 상황과 맞지 않습니다 ✗","perdió: perder(잃다)로 '10킬로 빠졌다'가 되어 ✗","bajó: bajar(내리다, 줄다)로 '체중이 줄었다'가 되어 ✗"]},{"id":"V209","q":"Mi hija pasa ____ tiempo chateando en internet, por eso no va bien en los estudios.","o":["algo de","poquísimo","menos","demasiado"],"a":3,"k":"양 표현","t":"우리 딸은 인터넷 채팅을 너무 많이 해서 공부를 잘 못한다.","e":"demasiado는 '너무 많은, 지나친'이라는 뜻입니다. 공부를 잘 못하는 이유이므로 '지나치게 많은 시간'이 필요합니다. demasiado + 명사에서 demasiado는 명사의 성·수에 맞춰 변합니다(demasiada agua, demasiados libros).","x":["algo de: 약간의라 공부 못하는 이유로 약합니다 ✗","poquísimo: 아주 적은이라 문맥과 반대입니다 ✗","menos: 더 적은이라 비교 대상이 없어 어색합니다 ✗","demasiado: 너무 많은 → 정답 ✓"]},{"id":"V210","q":"Este ejercicio está ____, no has respondido a dos preguntas.","o":["incompleto","desordenado","hecho","bien"],"a":0,"k":"상태 형용사","t":"이 연습 문제는 미완성이야. 두 문제에 답을 안 했잖아.","e":"incompleto는 '불완전한, 완성되지 않은'이라는 뜻입니다. 두 문제를 답하지 않았으므로(no has respondido a dos preguntas) 미완성입니다. 접두사 in-은 반대의 뜻을 만듭니다(completo 완전한 → incompleto 불완전한).","x":["incompleto: 미완성의 → 두 문제를 안 풀었으므로 정답 ✓","desordenado: 어지러운, 정돈되지 않은이라 답을 안 쓴 이유와 다릅니다 ✗","hecho: 다 된, 완성된이라 문맥과 반대입니다 ✗","bien: 잘된이라 문맥과 반대입니다 ✗"]},{"id":"V211","q":"No tengo mucho dinero, por eso he comprado un ordenador ____.","o":["estropeado","usado","roto","moderno"],"a":1,"k":"상태 형용사","t":"돈이 많지 않아서 중고 컴퓨터를 샀다.","e":"usado는 '사용된, 중고의'라는 뜻입니다. 돈이 많지 않다(No tengo mucho dinero)는 이유와 연결되어 값싼 중고품을 샀다는 의미입니다. de segunda mano(중고의)라는 표현도 자주 씁니다. 스페인에서는 컴퓨터를 ordenador, 중남미에서는 computadora라고 합니다.","x":["estropeado: 고장 난이라 일부러 사는 물건이 아닙니다 ✗","usado: 중고의 → 돈이 없어서 싼 것을 샀으므로 정답 ✓","roto: 부서진, 망가진이라 ✗","moderno: 최신의라 오히려 비쌀 가능성이 높습니다 ✗"]},{"id":"V212","q":"Soy ____, pertenezco a la orquesta de mi ciudad.","o":["escultor","comentarista","músico","actor"],"a":2,"k":"직업 어휘","t":"나는 음악가다. 우리 도시의 오케스트라에 소속되어 있다.","e":"músico는 '음악가, 연주자'입니다. 오케스트라(orquesta)에 속한 사람은 음악가입니다. pertenecer a는 '~에 속하다'라는 뜻입니다.","x":["escultor: 조각가라 ✗","comentarista: 해설자, 논평가라 ✗","músico: 음악가 → 오케스트라 단원이므로 정답 ✓","actor: 배우라 ✗"]},{"id":"V213","q":"Si le interesa esta oferta de trabajo, mándenos su ____ y una carta de presentación.","o":["carné","dirección","tarjeta","currículum"],"a":3,"k":"취업 어휘","t":"이 채용 공고에 관심이 있으시면 이력서와 자기소개서를 보내 주십시오.","e":"currículum(이력서)은 취업 지원 시 carta de presentación(자기소개서, 커버레터)과 함께 보내는 서류입니다. currículum vítae, 줄여서 CV라고도 합니다. 중남미에서는 hoja de vida라고 부르는 나라도 있습니다.","x":["carné: 신분증, 회원증이라 ✗","dirección: 주소라 채용 지원 서류가 아닙니다 ✗","tarjeta: 카드라 ✗","currículum: 이력서 → 정답 ✓"]},{"id":"V214","q":"Me gusta llevar ropa ____, no me pongo nada que sea llamativo.","o":["vistosa","de marca","sencilla","nueva"],"a":2,"k":"옷 관련 형용사","t":"나는 수수한 옷을 입는 걸 좋아한다. 눈에 띄는 것은 아무것도 입지 않는다.","e":"sencillo/a는 '단순한, 수수한'이라는 뜻입니다. 뒤에 '눈에 띄는(llamativo) 것은 입지 않는다'고 했으므로 반대 의미인 sencilla가 맞습니다. ropa가 여성 명사라 sencilla입니다.","x":["vistosa: 화려한, 눈에 띄는이라 문맥과 반대입니다 ✗","de marca: 명품의, 브랜드의라 수수함과 관계없습니다 ✗","sencilla: 수수한, 단순한 → 정답 ✓","nueva: 새로운이라 문맥의 핵심과 맞지 않습니다 ✗"]},{"id":"V215","q":"Alberto ha cambiado tanto que apenas lo ____.","o":["reconozco","miro","veo","observo"],"a":0,"k":"reconocer 알아보다","t":"알베르토는 너무 많이 변해서 나는 그를 거의 못 알아보겠다.","e":"reconocer는 '알아보다, 인식하다'라는 뜻입니다. 많이 변했다(ha cambiado tanto)는 내용과 연결되어 '거의 못 알아본다'는 의미가 됩니다. 1인칭 현재는 reconozco로 불규칙(-zco)입니다. apenas는 '거의 ~않다'입니다.","x":["reconozco: reconocer(알아보다) → 변해서 못 알아보므로 정답 ✓","miro: mirar(쳐다보다)라 변화와 연결되지 않습니다 ✗","veo: ver(보다)라 '거의 안 본다'로 의미가 달라집니다 ✗","observo: observar(관찰하다)라 ✗"]},{"id":"V216","q":"Alberto, es el ____ de Juan, debes esperar a que él acabe para hacer tu pregunta.","o":["turno","objetivo","truco","plan"],"a":0,"k":"turno 차례","t":"알베르토, 지금은 후안 차례야. 네 질문을 하려면 그가 끝날 때까지 기다려야 해.","e":"turno는 '차례, 순번'입니다. es el turno de Juan은 '후안 차례다'입니다. 예: Es tu turno.(네 차례야.) 은행이나 병원에서 받는 번호표도 turno라고 합니다.","x":["turno: 차례 → 후안이 끝날 때까지 기다리라는 문맥에 맞으므로 정답 ✓","objetivo: 목표라 ✗","truco: 속임수, 요령이라 ✗","plan: 계획이라 ✗"]},{"id":"V217","q":"¿Cuánto tiempo ____ que estudias español?","o":["pasa","está","hace","es"],"a":2,"k":"hace + 기간","t":"너는 스페인어를 공부한 지 얼마나 됐니?","e":"¿Cuánto tiempo hace que + 현재형?은 '~한 지 얼마나 됐니?'라는 기간 표현입니다. hace는 시간 경과를 나타내는 무인칭 용법으로 항상 3인칭 단수입니다. 대답 예: Hace dos años que estudio español.(스페인어 공부한 지 2년 됐어.)","x":["pasa: pasar(지나가다)로 이 구문에 쓰지 않습니다 ✗","está: estar로 기간 표현을 만들지 않습니다 ✗","hace: hace + 기간 + que(~한 지 ~되다) → 정답 ✓","es: ser로 기간 표현을 만들지 않습니다 ✗"]},{"id":"V218","q":"El médico dice que tengo los ____ típicos de un resfriado común.","o":["aspectos","datos","síntomas","elementos"],"a":2,"k":"의료 어휘","t":"의사가 내게 일반 감기의 전형적인 증상이 있다고 말한다.","e":"síntomas는 '증상'입니다. 의사(médico)와 감기(resfriado)라는 단어가 힌트입니다. 예: Los síntomas son fiebre y tos.(증상은 열과 기침이다.)","x":["aspectos: 측면, 모습이라 의학적 표현이 아닙니다 ✗","datos: 자료, 데이터라 ✗","síntomas: 증상 → 정답 ✓","elementos: 요소라 ✗"]},{"id":"V219","q":"En aquel ____ vivían los reyes.","o":["palacio","chalé","bloque","refugio"],"a":0,"k":"건물 어휘","t":"저 궁전에서 왕들이 살았다.","e":"palacio는 '궁전'으로, 왕(reyes)이 사는 곳입니다. reyes는 rey(왕)의 복수형으로 '왕과 왕비, 국왕 부부'를 뜻하기도 합니다.","x":["palacio: 궁전 → 왕이 사는 곳이므로 정답 ✓","chalé: 단독주택, 별장이라 ✗","bloque: (아파트) 동, 블록이라 ✗","refugio: 대피소, 피난처라 ✗"]},{"id":"V220","q":"Me puse muy ____, por eso me salió mal el examen.","o":["roja","nerviosa","en forma","contenta"],"a":1,"k":"ponerse + 형용사","t":"나는 너무 긴장해서 시험을 망쳤다.","e":"ponerse + 형용사는 '(일시적으로) ~해지다'라는 뜻입니다. ponerse nervioso/a는 '긴장하다'로, 시험을 망친 이유로 자연스럽습니다. 말하는 사람이 여성이라 nerviosa입니다.","x":["roja: ponerse roja(얼굴이 빨개지다)는 시험을 망친 이유로 약합니다 ✗","nerviosa: ponerse nerviosa(긴장하다) → 정답 ✓","en forma: ponerse en forma(몸매를 가꾸다)라 ✗","contenta: 기뻐지다라 시험을 망친 이유가 아닙니다 ✗"]},{"id":"V221","q":"¿Me dejas una goma para ____ las palabras incorrectas?","o":["subrayar","borrar","limpiar","sacar"],"a":1,"k":"문구 관련 동사","t":"틀린 단어를 지우게 지우개 좀 빌려줄래?","e":"borrar는 '지우다'입니다. goma (de borrar)는 '지우개'라서 borrar와 짝을 이룹니다. 컴퓨터에서 파일을 '삭제하다'라고 할 때도 borrar를 씁니다. ¿Me dejas ~?는 '~ 빌려줄래?'라는 표현입니다.","x":["subrayar: 밑줄을 긋다라 지우개로 할 수 없습니다 ✗","borrar: 지우다 → 지우개로 틀린 단어를 지우므로 정답 ✓","limpiar: 청소하다, 닦다라 단어에는 쓰지 않습니다 ✗","sacar: 꺼내다라 ✗"]},{"id":"V222","q":"Una limusina es un ____ de gran tamaño.","o":["televisor","automóvil","teléfono","asiento"],"a":1,"k":"교통수단 어휘","t":"리무진은 대형 자동차다.","e":"automóvil은 '자동차'입니다. 리무진(limusina)은 길이가 긴 고급 승용차입니다. 일상에서는 coche(스페인), carro나 auto(중남미)를 더 많이 씁니다.","x":["televisor: 텔레비전 수상기라 ✗","automóvil: 자동차 → 리무진은 차이므로 정답 ✓","teléfono: 전화기라 ✗","asiento: 좌석이라 ✗"]},{"id":"V223","q":"Ya funciona mi reloj, afortunadamente me lo ____ mi padre.","o":["rompió","estropeó","compró","arregló"],"a":3,"k":"arreglar 고치다","t":"이제 내 시계가 작동한다. 다행히 아버지가 고쳐 주셨다.","e":"arreglar는 '고치다, 수리하다'라는 뜻입니다. 시계가 이제 작동한다(Ya funciona)와 다행히(afortunadamente)가 힌트입니다. me lo arregló에서 me는 '나에게(나를 위해)', lo는 '그것을(el reloj)'입니다.","x":["rompió: romper(부수다)라 다행이라는 말과 맞지 않습니다 ✗","estropeó: estropear(고장 내다)라 문맥과 반대입니다 ✗","compró: comprar(사다)라 '이제 작동한다'는 수리의 의미와 맞지 않습니다 ✗","arregló: arreglar(고치다) → 정답 ✓"]},{"id":"V224","q":"No tienes que ____ a la derecha, sino a la izquierda.","o":["girar","aparecer","llegar","regresar"],"a":0,"k":"girar 방향 전환","t":"오른쪽이 아니라 왼쪽으로 돌아야 해.","e":"girar는 '돌다, 방향을 틀다'라는 뜻으로 girar a la derecha/izquierda(오른쪽/왼쪽으로 돌다)처럼 씁니다. no ~ sino ~는 '~이 아니라 ~이다'라는 구문입니다. 같은 뜻으로 doblar도 씁니다(특히 중남미).","x":["girar: 돌다 → 방향을 말하는 문맥에 맞으므로 정답 ✓","aparecer: 나타나다라 ✗","llegar: 도착하다로 a la derecha와 쓰면 어색합니다 ✗","regresar: 돌아가다(귀환하다)라 방향 전환의 뜻이 아닙니다 ✗"]},{"id":"V225","q":"Barcelona es una ciudad ____ con residentes de muchas partes del mundo.","o":["decadente","cara","multicultural","diminuta"],"a":2,"k":"도시 형용사","t":"바르셀로나는 세계 여러 곳에서 온 주민들이 사는 다문화 도시다.","e":"multicultural은 '다문화의'라는 뜻입니다. 세계 여러 곳에서 온 주민(residentes de muchas partes del mundo)이라는 설명과 일치합니다. multi-는 '여럿의'라는 접두사입니다.","x":["decadente: 쇠퇴하는이라 ✗","cara: 비싼이라 주민 구성과 관계없습니다 ✗","multicultural: 다문화의 → 정답 ✓","diminuta: 아주 작은이라 바르셀로나와 맞지 않습니다 ✗"]},{"id":"V226","q":"¿Cuántos goles ____ Ronaldo en el anterior partido?","o":["controló","marcó","puso","cometió"],"a":1,"k":"marcar un gol","t":"호날두는 지난 경기에서 몇 골을 넣었니?","e":"marcar un gol은 '골을 넣다'라는 고정 표현입니다. meter un gol도 같은 뜻으로 구어에서 자주 씁니다. 반대로 '골을 먹다(실점하다)'는 recibir un gol입니다.","x":["controló: controlar(통제하다)로 골과 쓰지 않습니다 ✗","marcó: marcar un gol(골을 넣다) → 정답 ✓","puso: poner(놓다)로 이 표현에 쓰지 않습니다 ✗","cometió: cometer(범하다)는 cometer una falta(반칙하다)에 씁니다 ✗"]},{"id":"V227","q":"No soy capaz de ____ esa montaña, es demasiado alta.","o":["descender","mover","escalar","bajar"],"a":2,"k":"등산 동사","t":"나는 그 산을 오를 수 없다. 너무 높다.","e":"escalar는 '(산·벽을) 오르다, 등반하다'라는 뜻입니다. 산이 너무 높다(demasiado alta)는 이유와 연결됩니다. ser capaz de는 '~할 능력이 있다'입니다.","x":["descender: 내려가다라 높다는 이유와 연결되지 않습니다 ✗","mover: 움직이다라 산과 어울리지 않습니다 ✗","escalar: 오르다, 등반하다 → 정답 ✓","bajar: 내려가다라 ✗"]},{"id":"V228","q":"Con esta ____ de pan podemos hacer dos bocadillos.","o":["rodaja","barra","rebanada","loncha"],"a":1,"k":"빵 단위 명사","t":"이 바게트 한 개로 샌드위치 두 개를 만들 수 있다.","e":"barra de pan은 '(막대 모양의) 바게트 한 개'입니다. 스페인의 bocadillo는 바게트를 갈라 속을 넣은 샌드위치라 barra 하나로 두 개를 만들 수 있습니다. rebanada(빵 한 조각)로는 두 개를 만들기 어렵습니다.","x":["rodaja: (둥글게 썬) 한 조각으로 레몬·토마토 등에 씁니다 ✗","barra: 막대 모양 빵, barra de pan은 바게트 → 정답 ✓","rebanada: (빵) 한 장, 한 조각이라 샌드위치 두 개를 만들기에 부족합니다 ✗","loncha: (햄·치즈) 얇은 한 장이라 빵에는 쓰지 않습니다 ✗"]},{"id":"V229","q":"El Día de Muertos, los mexicanos ____ a sus seres queridos fallecidos.","o":["recuerdan","abandonan","invitan","reúnen"],"a":0,"k":"recordar 기억하다","t":"죽은 자의 날에 멕시코 사람들은 세상을 떠난 사랑하는 이들을 기린다(기억한다).","e":"recordar는 '기억하다, 추모하다'라는 뜻입니다. 죽은 자의 날(Día de Muertos)은 멕시코에서 세상을 떠난 가족을 기억하고 기리는 전통 명절입니다. seres queridos는 '사랑하는 사람들', fallecidos는 '고인이 된'입니다.","x":["recuerdan: recordar(기억하다, 기리다) → 정답 ✓","abandonan: abandonar(버리다)라 명절의 의미와 반대입니다 ✗","invitan: invitar(초대하다)는 고인에게 쓰기 어색합니다 ✗","reúnen: reunir(모으다)라 고인을 대상으로 쓰지 않습니다 ✗"]},{"id":"V230","q":"Terminé mi actividad en solo 5 minutos. Es bastante ____.","o":["difícil","fácil","larga","complicada"],"a":1,"k":"난이도 형용사","t":"나는 활동을 단 5분 만에 끝냈다. 꽤 쉽다.","e":"fácil은 '쉬운'입니다. 5분 만에 끝냈다(en solo 5 minutos)는 사실이 쉬웠다는 근거가 됩니다. 반대말은 difícil(어려운)입니다.","x":["difícil: 어려운이라 5분 만에 끝낸 것과 반대입니다 ✗","fácil: 쉬운 → 정답 ✓","larga: 긴이라 5분 만에 끝낸 것과 반대입니다 ✗","complicada: 복잡한이라 ✗"]},{"id":"V231","q":"Todavía no podemos ir al centro comercial, está ____.","o":["aquí","abierto","cerrado","cerca"],"a":2,"k":"영업 상태","t":"아직 쇼핑몰에 갈 수 없어. 문이 닫혀 있어.","e":"cerrado는 '닫힌, 영업하지 않는'이라는 뜻입니다. 아직 갈 수 없다(Todavía no podemos ir)는 이유로 문이 닫혀 있다는 것이 자연스럽습니다. 상태를 나타내므로 estar와 씁니다.","x":["aquí: 여기라 '갈 수 없다'는 이유가 되지 않습니다 ✗","abierto: 열린이라 갈 수 없는 이유와 반대입니다 ✗","cerrado: 닫힌 → 정답 ✓","cerca: 가까이라 갈 수 없는 이유가 아닙니다 ✗"]},{"id":"V232","q":"En la ____ solo tengo 20 euros, no me gusta llevar grandes cantidades de dinero.","o":["funda","carpeta","billetera","caja"],"a":2,"k":"소지품 어휘","t":"지갑에는 20유로밖에 없다. 나는 큰돈을 들고 다니는 걸 좋아하지 않는다.","e":"billetera는 '지갑'으로 billete(지폐)에서 나온 말입니다. 중남미에서 특히 많이 쓰고, 스페인에서는 cartera라고 많이 합니다. 돈(dinero)을 넣는 물건이므로 정답입니다.","x":["funda: 덮개, 케이스라 ✗","carpeta: 서류철, 폴더라 ✗","billetera: 지갑 → 돈을 넣는 곳이므로 정답 ✓","caja: 상자, 금고, 계산대라 들고 다니는 물건이 아닙니다 ✗"]},{"id":"V233","q":"Al aterrizar, todos los pasajeros del avión deben ____ el cinturón de seguridad.","o":["subirse","desabrocharse","abrocharse","quitarse"],"a":2,"k":"비행기 어휘","t":"착륙할 때 비행기의 모든 승객은 안전벨트를 매야 한다.","e":"abrocharse el cinturón은 '안전벨트를 매다'라는 표현입니다. 이착륙 때에는 안전벨트를 매야 하므로 abrocharse가 정답입니다. 반대말은 desabrocharse(벨트·단추를 풀다)입니다.","x":["subirse: (탈것에) 올라타다라 벨트와 쓰지 않습니다 ✗","desabrocharse: (벨트를) 풀다라 착륙 시 규칙과 반대입니다 ✗","abrocharse: (벨트를) 매다 → 정답 ✓","quitarse: 벗다, 풀다라 착륙 시 규칙과 반대입니다 ✗"]},{"id":"V234","q":"Mi tío Emilio siempre estuvo soltero, nunca ____.","o":["se distrajo","se casó","se ofendió","se mudó"],"a":1,"k":"재귀동사 의미","t":"우리 에밀리오 삼촌은 늘 독신이었다. 한 번도 결혼하지 않았다.","e":"casarse는 '결혼하다'입니다. soltero(독신의, 미혼의)라는 앞 문장과 '한 번도 결혼하지 않았다'는 의미가 이어집니다. casarse con + 사람은 '~와 결혼하다'입니다.","x":["se distrajo: distraerse(딴생각하다, 정신이 팔리다)라 ✗","se casó: casarse(결혼하다) → 독신이었다는 문맥에 맞으므로 정답 ✓","se ofendió: ofenderse(기분 상하다)라 ✗","se mudó: mudarse(이사하다)라 ✗"]},{"id":"V235","q":"La boda será en agosto y hará calor, así que lo mejor es que te pongas un vestido ____.","o":["primaveral","invernal","otoñal","veraniego"],"a":3,"k":"계절 형용사","t":"결혼식은 8월이고 더울 테니, 여름용 드레스를 입는 게 가장 좋겠다.","e":"veraniego는 '여름의, 여름용의'라는 뜻으로 verano(여름)에서 나왔습니다. 스페인의 8월은 여름이고 덥다(hará calor)고 했으므로 정답입니다. 남반구(아르헨티나·칠레 등)에서는 8월이 겨울이라는 점도 재미있는 차이입니다.","x":["primaveral: 봄의라 ✗","invernal: 겨울의라 더위와 맞지 않습니다 ✗","otoñal: 가을의라 ✗","veraniego: 여름의 → 8월의 더위에 맞으므로 정답 ✓"]},{"id":"V236","q":"¡Qué pregunta tan ____! Eres un cotilla.","o":["lógica","sensata","indiscreta","común"],"a":2,"k":"성격 형용사","t":"정말 무례한(눈치 없는) 질문이네! 너 참 남 얘기 좋아한다.","e":"indiscreto/a는 '무례한, 남의 사생활을 캐는, 눈치 없는'이라는 뜻입니다. cotilla는 '남의 일에 참견하고 소문 내기 좋아하는 사람'이라는 스페인 구어입니다(중남미에서는 chismoso). 질문이 사생활을 캐는 것이라는 의미입니다.","x":["lógica: 논리적인이라 cotilla와 연결되지 않습니다 ✗","sensata: 분별 있는, 현명한이라 ✗","indiscreta: 무례한, 사생활을 캐는 → 정답 ✓","común: 흔한, 평범한이라 ✗"]},{"id":"V237","q":"¿Te gusta viajar en grupo o prefieres hacerlo en ____?","o":["globo","avioneta","tranvía","solitario"],"a":3,"k":"en solitario","t":"너는 단체로 여행하는 걸 좋아하니, 아니면 혼자 여행하는 걸 좋아하니?","e":"en solitario는 '혼자서, 단독으로'라는 표현입니다. 앞의 en grupo(단체로)와 대비됩니다. solo(혼자)와 비슷한 뜻입니다.","x":["globo: en globo는 '열기구로'라 en grupo와 대비되지 않습니다 ✗","avioneta: en avioneta는 '경비행기로'라 ✗","tranvía: en tranvía는 '전차(트램)로'라 ✗","solitario: en solitario(혼자서) → en grupo와 대비되므로 정답 ✓"]},{"id":"V238","q":"Adoro mi trabajo, es muy ____ trabajar en algo que me gusta.","o":["gratificante","agobiante","decepcionante","preocupante"],"a":0,"k":"-ante 형용사","t":"나는 내 일을 정말 좋아한다. 좋아하는 일을 하는 것은 아주 보람 있다.","e":"gratificante는 '보람 있는, 만족감을 주는'이라는 뜻입니다. 일을 좋아한다(Adoro mi trabajo)는 긍정적인 문맥에 어울리는 유일한 형용사입니다. 나머지 보기는 모두 부정적인 뜻입니다.","x":["gratificante: 보람 있는 → 정답 ✓","agobiante: 숨 막히는, 부담스러운이라 ✗","decepcionante: 실망스러운이라 ✗","preocupante: 걱정스러운이라 ✗"]},{"id":"V239","q":"Siempre que vamos al cine compramos ____ de maíz. ¡Están buenísimas!","o":["chicles","palomitas","piruletas","bolitas"],"a":1,"k":"간식 어휘","t":"우리는 영화관에 갈 때마다 팝콘을 산다. 정말 맛있다!","e":"palomitas de maíz는 '팝콘'입니다. palomita는 원래 '작은 비둘기'라는 뜻입니다. 중남미에서는 나라마다 이름이 달라서 pochoclo(아르헨티나), canchita(페루), cotufas(베네수엘라), crispetas(콜롬비아) 등으로 부릅니다.","x":["chicles: 껌이라 maíz(옥수수)와 연결되지 않습니다 ✗","palomitas: palomitas de maíz(팝콘) → 정답 ✓","piruletas: 막대사탕이라 ✗","bolitas: 작은 구슬이라 ✗"]},{"id":"V240","q":"El ladrón fue ____ por la policía.","o":["detenido","felicitado","aceptado","animado"],"a":0,"k":"수동태 어휘","t":"도둑은 경찰에게 체포되었다.","e":"detener는 '체포하다, 멈추게 하다'라는 뜻이고, fue detenido는 'ser + 과거분사' 수동태로 '체포되었다'입니다. 도둑(ladrón)과 경찰(policía)이라는 단어가 힌트입니다. arrestar도 같은 뜻입니다.","x":["detenido: detener(체포하다)의 과거분사 → 정답 ✓","felicitado: felicitar(축하하다)라 도둑에게 맞지 않습니다 ✗","aceptado: aceptar(받아들이다)라 ✗","animado: animar(격려하다)라 ✗"]},{"id":"V241","q":"Ayer pasamos mucho calor porque no funcionaba el ____.","o":["ventilador","despertador","radiador","ordenador"],"a":0,"k":"가전 어휘","t":"어제는 선풍기가 작동하지 않아서 우리는 무척 더웠다.","e":"ventilador는 '선풍기'로, 더위(calor)를 식혀 주는 기계입니다. -dor로 끝나는 명사는 '~하는 기계, 도구'를 뜻하는 경우가 많습니다(ventilar 환기하다 → ventilador). pasar calor는 '더위를 겪다'입니다.","x":["ventilador: 선풍기 → 작동하지 않아 더웠으므로 정답 ✓","despertador: 자명종이라 더위와 관계없습니다 ✗","radiador: 라디에이터(난방기)라 오히려 열을 냅니다 ✗","ordenador: 컴퓨터(스페인)라 더위와 관계없습니다 ✗"]},{"id":"V242","q":"La ____ del piso en el que vivo pretende subir el precio del alquiler.","o":["compañera","vecina","propietaria","inquilina"],"a":2,"k":"주거 관련 어휘","t":"내가 사는 아파트의 집주인이 월세를 올리려고 한다.","e":"propietaria는 '소유주, 집주인(여성)'입니다. 월세(alquiler)를 올릴 수 있는 사람은 집주인입니다. pretender는 '~하려고 하다(의도하다)'라는 뜻이니 영어 pretend(~인 척하다)와 혼동하지 마세요.","x":["compañera: 동료, 룸메이트라 월세를 올릴 권한이 없습니다 ✗","vecina: 이웃이라 ✗","propietaria: 소유주, 집주인 → 정답 ✓","inquilina: 세입자라 월세를 내는 사람입니다 ✗"]},{"id":"V243","q":"Siempre pongo un ____ en la mesa a la hora de comer. Así no se ensucia.","o":["tazón","bol","jarrón","mantel"],"a":3,"k":"식탁 어휘","t":"나는 밥 먹을 때 항상 식탁에 식탁보를 깐다. 그러면 더러워지지 않는다.","e":"mantel은 '식탁보'입니다. 식탁이 더러워지지 않게(Así no se ensucia) 깔아 두는 천입니다. 비슷하게 생긴 manta는 '담요'이니 혼동하지 마세요.","x":["tazón: 큰 사발, 머그라 식탁을 덮지 않습니다 ✗","bol: 그릇, 볼이라 ✗","jarrón: 꽃병이라 ✗","mantel: 식탁보 → 식탁이 더러워지지 않게 하므로 정답 ✓"]},{"id":"V244","q":"Perdonad, ¿os importa hablar más ____? Es que el bebé está durmiendo.","o":["alto","despacito","bajito","claro"],"a":2,"k":"말하는 방식 부사","t":"얘들아 미안한데, 좀 더 작게 말해 줄래? 아기가 자고 있거든.","e":"bajito는 bajo(낮게)의 축소형으로 '작은 소리로, 나지막이'라는 뜻입니다. hablar bajito/bajo는 '작게 말하다'입니다. ¿os importa...?의 os는 vosotros(너희) 형태로 스페인에서 쓰며, 중남미에서는 ¿les importa...?라고 합니다.","x":["alto: 크게(큰 소리로)라 아기가 자는 상황과 반대입니다 ✗","despacito: 천천히라 소리 크기와 관계없습니다 ✗","bajito: 작은 소리로 → 아기가 자고 있으므로 정답 ✓","claro: 분명하게라 ✗"]},{"id":"V245","q":"Ruth no tiene un horario ____ de trabajo, su jornada laboral cambia semanalmente.","o":["intensivo","variable","incompatible","fijo"],"a":3,"k":"근무 형태 어휘","t":"루스는 고정된 근무 시간이 없다. 근무 시간이 매주 바뀐다.","e":"fijo는 '고정된, 정해진'이라는 뜻입니다. no tiene un horario fijo는 '정해진 시간표가 없다'로, 매주 바뀐다(cambia semanalmente)는 설명과 일치합니다. jornada laboral은 '근무 시간(하루 노동)'입니다.","x":["intensivo: 집중 근무(점심 휴식 없이 연속 근무)라 매주 바뀐다는 이유와 맞지 않습니다 ✗","variable: 변하는이라 부정문이 되면 '변하지 않는다'가 되어 모순입니다 ✗","incompatible: 양립할 수 없는이라 ✗","fijo: 고정된 → 정답 ✓"]},{"id":"V246","q":"A algunos insectos como las ____ les gusta la miel.","o":["águilas","gaviotas","moscas","palomas"],"a":2,"k":"곤충 어휘","t":"파리 같은 몇몇 곤충은 꿀을 좋아한다.","e":"mosca는 '파리'로 곤충(insecto)입니다. 나머지 보기는 모두 새(ave)입니다. a + 대상 + les gusta 구조로 '~는 ~를 좋아한다'를 나타냅니다.","x":["águilas: 독수리로 새라 ✗","gaviotas: 갈매기로 새라 ✗","moscas: 파리 → 곤충이므로 정답 ✓","palomas: 비둘기로 새라 ✗"]},{"id":"V247","q":"Ibiza es una ____ que está en el mar Mediterráneo.","o":["laguna","cordillera","isla","montaña"],"a":2,"k":"지리 어휘","t":"이비사는 지중해에 있는 섬이다.","e":"isla는 '섬'입니다. 이비사(Ibiza)는 스페인 발레아레스 제도에 속한 섬으로, 바다(mar Mediterráneo)에 있다는 설명이 힌트입니다.","x":["laguna: 석호, 작은 호수라 ✗","cordillera: 산맥이라 ✗","isla: 섬 → 정답 ✓","montaña: 산이라 ✗"]},{"id":"V248","q":"Me paró un ____ de policía para hacerme un test de alcoholemia.","o":["alcalde","ejecutivo","agente","mensajero"],"a":2,"k":"직업 어휘","t":"경찰관이 음주 측정을 하려고 나를 세웠다.","e":"agente de policía는 '경찰관'입니다. agente는 '요원, 대리인'이라는 뜻으로 agente de viajes(여행사 직원)처럼도 씁니다. test de alcoholemia는 '음주 측정'입니다.","x":["alcalde: 시장(市長)이라 ✗","ejecutivo: 임원, 경영자라 ✗","agente: agente de policía는 경찰관 → 정답 ✓","mensajero: 배달원, 전령이라 ✗"]},{"id":"V249","q":"Me gusta leer revistas de ____ para saber qué ropa se lleva en cada temporada.","o":["moda","historia","cocina","cine"],"a":0,"k":"잡지 종류","t":"나는 계절마다 어떤 옷이 유행하는지 알기 위해 패션 잡지 읽는 걸 좋아한다.","e":"moda는 '패션, 유행'입니다. qué ropa se lleva(어떤 옷을 입는지, 무엇이 유행하는지)가 힌트입니다. estar de moda는 '유행 중이다'라는 표현입니다.","x":["moda: 패션 → 옷 유행을 알려 주므로 정답 ✓","historia: 역사라 ✗","cocina: 요리라 ✗","cine: 영화라 ✗"]},{"id":"V250","q":"Ese reloj no funciona, no ____ la hora correcta.","o":["marca","realiza","construye","produce"],"a":0,"k":"marcar 가리키다","t":"그 시계는 고장 났어. 정확한 시간을 가리키지 않아.","e":"marcar la hora는 '(시계가) 시간을 가리키다, 표시하다'라는 뜻입니다. marcar는 '표시하다'라는 기본 뜻에서 '번호를 누르다', '골을 넣다' 등 다양하게 쓰입니다.","x":["marca: marcar la hora(시간을 가리키다) → 정답 ✓","realiza: realizar(실행하다)로 시계와 쓰지 않습니다 ✗","construye: construir(건설하다)라 ✗","produce: producir(생산하다)라 ✗"]},{"id":"V251","q":"El tomate se pone rojo cuando está ____.","o":["maduro","entero","cortado","pelado"],"a":0,"k":"과일 상태 형용사","t":"토마토는 익으면 빨갛게 된다.","e":"maduro는 '(과일이) 익은'이라는 뜻입니다. 사람에게 쓰면 '성숙한'입니다. ponerse rojo는 '빨갛게 되다'입니다.","x":["maduro: 익은 → 토마토가 익으면 빨개지므로 정답 ✓","entero: 통째의, 온전한이라 색과 관계없습니다 ✗","cortado: 잘린이라 ✗","pelado: 껍질을 벗긴이라 ✗"]},{"id":"V252","q":"Si hoy es ____, anteayer fue miércoles.","o":["viernes","domingo","lunes","jueves"],"a":0,"k":"요일 어휘","t":"오늘이 금요일이면 그저께는 수요일이었다.","e":"anteayer는 '그저께(이틀 전)'입니다. 수요일(miércoles)에서 이틀 뒤는 금요일(viernes)입니다. 참고로 ayer는 '어제', pasado mañana는 '모레'입니다.","x":["viernes: 금요일 → 그저께가 수요일이므로 정답 ✓","domingo: 일요일이면 그저께는 금요일입니다 ✗","lunes: 월요일이면 그저께는 토요일입니다 ✗","jueves: 목요일이면 그저께는 화요일입니다 ✗"]},{"id":"V253","q":"Me he apuntado a un ____, por eso necesito comprar ropa de deporte.","o":["seminario","club","colegio","gimnasio"],"a":3,"k":"장소 어휘","t":"나는 헬스장에 등록해서 운동복을 사야 한다.","e":"gimnasio는 '체육관, 헬스장'입니다. 운동복(ropa de deporte)이 필요하다는 이유와 연결됩니다. apuntarse a는 '~에 등록하다, 가입하다'라는 뜻입니다. 주의: 독일 등의 Gymnasium(중등학교)과 달리 스페인어 gimnasio는 운동하는 곳입니다.","x":["seminario: 세미나라 운동복이 필요 없습니다 ✗","club: 클럽, 동호회로 종류가 정해지지 않아 운동복이 꼭 필요한 이유가 되지 않습니다 ✗","colegio: 학교라 ✗","gimnasio: 헬스장 → 운동복이 필요하므로 정답 ✓"]},{"id":"V254","q":"Un año se divide en ____ meses.","o":["doscientos","doce","dos","diez"],"a":1,"k":"숫자 어휘","t":"1년은 12개월로 나뉜다.","e":"doce는 숫자 '12'입니다. 1년은 열두 달이므로 정답입니다. dividirse en은 '~로 나뉘다'입니다.","x":["doscientos: 200이라 ✗","doce: 12 → 정답 ✓","dos: 2라 ✗","diez: 10이라 ✗"]},{"id":"V255","q":"Me gustaría trabajar como ____ para esta marca de ropa.","o":["pintora","violinista","bailarina","modelo"],"a":3,"k":"직업 어휘","t":"나는 이 의류 브랜드의 모델로 일하고 싶다.","e":"modelo는 '모델'입니다. 의류 브랜드(marca de ropa)에서 일하는 직업으로 가장 자연스럽습니다. modelo는 남녀 모두 같은 형태이며 관사로 성을 구분합니다(el/la modelo).","x":["pintora: 화가라 의류 브랜드와 관계가 약합니다 ✗","violinista: 바이올리니스트라 ✗","bailarina: 무용수라 ✗","modelo: 모델 → 의류 브랜드와 연결되므로 정답 ✓"]},{"id":"V256","q":"Si quieres ____ tu nivel de español, te recomiendo pasar un tiempo en un país hispanohablante.","o":["limitar","mejorar","empeorar","comparar"],"a":1,"k":"mejorar 향상하다","t":"스페인어 실력을 늘리고 싶다면, 스페인어권 나라에서 한동안 지내 보길 권한다.","e":"mejorar는 '향상시키다, 나아지게 하다'라는 뜻입니다. mejorar el nivel(실력을 높이다)은 언어 학습에서 자주 쓰는 표현입니다. 반대말은 empeorar(악화시키다)입니다.","x":["limitar: 제한하다라 ✗","mejorar: 향상시키다 → 정답 ✓","empeorar: 악화시키다라 문맥과 반대입니다 ✗","comparar: 비교하다라 ✗"]},{"id":"V257","q":"Tiene una figura ____, ojalá me pareciera a ella.","o":["improbable","envidiable","pasable","aceptable"],"a":1,"k":"-able 형용사","t":"그녀는 부러운 몸매를 가졌다. 나도 그녀를 닮았으면 좋겠다.","e":"envidiable는 '부러운, 부러워할 만한'이라는 뜻으로 envidia(부러움, 질투)에서 나왔습니다. ojalá me pareciera a ella(그녀를 닮았으면 좋겠다)라는 소망이 힌트입니다. ojalá 뒤에는 접속법(바람을 나타내는 동사 형태)이 옵니다.","x":["improbable: 일어날 것 같지 않은이라 ✗","envidiable: 부러운 → 정답 ✓","pasable: 그럭저럭 봐줄 만한이라 닮고 싶을 정도가 아닙니다 ✗","aceptable: 괜찮은, 받아들일 만한이라 부러워할 정도가 아닙니다 ✗"]},{"id":"V258","q":"Una buena ____ al trabajar hará que te duela menos la espalda.","o":["apariencia","presencia","postura","actitud"],"a":2,"k":"postura 자세","t":"일할 때 좋은 자세를 취하면 허리가 덜 아플 것이다.","e":"postura는 '자세'입니다. 허리 통증(dolor de espalda)과 직접 연결되는 단어입니다. 비유적으로 '입장, 견해'라는 뜻도 있습니다.","x":["apariencia: 외모, 겉모습이라 허리 통증과 관계없습니다 ✗","presencia: 존재, 풍채라 ✗","postura: 자세 → 허리 통증과 관련되므로 정답 ✓","actitud: 태도, 마음가짐이라 몸의 자세가 아닙니다 ✗"]},{"id":"V259","q":"Esas ____ sólo las puedes comprar en la farmacia.","o":["tortillas","zapatillas","ventanillas","pastillas"],"a":3,"k":"약 관련 어휘","t":"그 알약들은 약국에서만 살 수 있다.","e":"pastillas는 '알약'입니다. 약국(farmacia)에서 파는 것이므로 정답입니다. 보기 모두 -illa로 끝나 비슷해 보이니 뜻을 잘 구별하세요.","x":["tortillas: 토르티야(스페인식 오믈렛·멕시코식 옥수수 전병)라 ✗","zapatillas: 운동화, 실내화라 ✗","ventanillas: 창구, (차) 창문이라 ✗","pastillas: 알약 → 약국에서 파므로 정답 ✓"]},{"id":"V260","q":"Me gusta vivir en este barrio porque es ____, apenas se escucha ruido.","o":["céntrico","ruidoso","tranquilo","antiguo"],"a":2,"k":"동네 형용사","t":"나는 이 동네에 사는 게 좋다. 조용해서 소음이 거의 들리지 않기 때문이다.","e":"tranquilo는 '조용한, 평온한'이라는 뜻입니다. 소음이 거의 들리지 않는다(apenas se escucha ruido)는 설명과 일치합니다. barrio는 '동네, 구역'입니다.","x":["céntrico: 중심가에 있는이라 소음이 없다는 설명과 맞지 않습니다 ✗","ruidoso: 시끄러운이라 문맥과 반대입니다 ✗","tranquilo: 조용한 → 정답 ✓","antiguo: 오래된이라 소음과 관계없습니다 ✗"]},{"id":"V261","q":"Con este tratamiento médico, seguro que va a ____ en poco tiempo.","o":["mejorar","reparar","empeorar","aprobar"],"a":0,"k":"mejorar 나아지다","t":"이 치료를 받으면 틀림없이 금방 나아질 것이다.","e":"mejorar는 목적어 없이 쓰면 '(건강이) 좋아지다, 나아지다'라는 뜻입니다. 치료(tratamiento médico)의 결과로 자연스럽습니다. 예: ¡Que te mejores!(빨리 낫길 바라!)","x":["mejorar: 나아지다 → 치료 효과이므로 정답 ✓","reparar: (물건을) 수리하다라 사람의 건강에 쓰지 않습니다 ✗","empeorar: 악화되다라 문맥과 반대입니다 ✗","aprobar: 합격하다, 승인하다라 ✗"]},{"id":"V262","q":"Estas ____ cortan mal, necesito unas nuevas.","o":["copas","varillas","cucharas","tijeras"],"a":3,"k":"도구 어휘","t":"이 가위는 잘 안 잘린다. 새 가위가 필요하다.","e":"tijeras는 '가위'이며 항상 복수형으로 씁니다(unas tijeras = 가위 하나). 동사 cortar(자르다)가 힌트입니다. 그래서 뒤에도 unas nuevas라고 했습니다.","x":["copas: (와인)잔, 트로피라 자르는 도구가 아닙니다 ✗","varillas: 가는 막대라 ✗","cucharas: 숟가락이라 ✗","tijeras: 가위 → 자르는 도구이므로 정답 ✓"]},{"id":"V263","q":"En esta ____ hago todas mis tareas del colegio.","o":["guía","libreta","revista","novela"],"a":1,"k":"학용품 어휘","t":"나는 이 공책에 학교 숙제를 전부 한다.","e":"libreta는 '공책, 수첩'입니다. 숙제(tareas del colegio)를 하는 곳으로 맞습니다. cuaderno도 같은 뜻으로 많이 씁니다. 주의: librería는 '서점', biblioteca는 '도서관'입니다.","x":["guía: 안내서, 가이드라 숙제를 하는 곳이 아닙니다 ✗","libreta: 공책 → 정답 ✓","revista: 잡지라 ✗","novela: 소설이라 ✗"]},{"id":"V264","q":"Las paredes están perfectas, el ____ ha hecho un buen trabajo.","o":["mesero","camarero","escultor","pintor"],"a":3,"k":"직업 어휘","t":"벽이 완벽하다. 페인트공이 일을 잘했다.","e":"pintor는 '화가' 외에 '페인트공(도장공)'이라는 뜻도 있습니다. 벽(paredes)을 칠하는 사람이므로 정답입니다. 동사 pintar(칠하다, 그리다)에서 나왔습니다.","x":["mesero: 웨이터(중남미 표현)라 벽과 관계없습니다 ✗","camarero: 웨이터(스페인 표현)라 ✗","escultor: 조각가라 ✗","pintor: 페인트공 → 벽을 칠하므로 정답 ✓"]},{"id":"V265","q":"El examen de química lo vamos a ____ mañana.","o":["olvidar","recordar","copiar","hacer"],"a":3,"k":"hacer un examen","t":"화학 시험은 내일 볼 것이다.","e":"hacer un examen은 '시험을 보다(치르다)'라는 표현입니다. 영어처럼 tomar를 쓰지 않는다는 점에 주의하세요. 이 문장은 목적어(El examen de química)를 앞으로 꺼내고 lo로 다시 받은 구조입니다.","x":["olvidar: 잊다라 '시험을 잊을 예정'은 어색합니다 ✗","recordar: 기억하다라 ✗","copiar: 베끼다(커닝하다)라 예정을 말하는 문장에 어울리지 않습니다 ✗","hacer: hacer un examen(시험을 보다) → 정답 ✓"]},{"id":"V266","q":"Fabio sabe ____ el piano y la guitarra.","o":["abrir","tomar","jugar","tocar"],"a":3,"k":"tocar vs jugar","t":"파비오는 피아노와 기타를 칠 줄 안다.","e":"tocar는 '(악기를) 연주하다'라는 뜻입니다. 영어 play처럼 하나의 동사가 아니라, 스페인어는 악기에는 tocar, 운동·게임에는 jugar를 씁니다. 예: Juego al fútbol y toco la guitarra.(나는 축구를 하고 기타를 친다.)","x":["abrir: 열다라 ✗","tomar: 잡다, 먹다라 악기와 쓰지 않습니다 ✗","jugar: 운동·게임을 하다라 악기에는 쓰지 않습니다 ✗","tocar: (악기를) 연주하다 → 정답 ✓"]},{"id":"V267","q":"Ana María es veterinaria, es decir, ____ a los animales.","o":["calma","anima","cura","enseña"],"a":2,"k":"curar 치료하다","t":"아나 마리아는 수의사다. 즉, 동물들을 치료한다.","e":"curar는 '치료하다, 고치다'라는 뜻입니다. 수의사(veterinaria)가 하는 일을 설명하고 있습니다. es decir는 '즉, 다시 말해'라는 연결 표현입니다.","x":["calma: calmar(진정시키다)라 수의사 업무의 핵심이 아닙니다 ✗","anima: animar(격려하다)라 ✗","cura: curar(치료하다) → 정답 ✓","enseña: enseñar(가르치다)라 ✗"]},{"id":"V268","q":"Trabajas demasiado. ¿Por qué no te ____ unos días libres?","o":["pones","tomas","haces","tienes"],"a":1,"k":"휴가 내기 표현","t":"너 일을 너무 많이 해. 며칠 쉬는 게 어때?","e":"tomarse unos días libres는 '며칠 휴가를 내다(쉬다)'라는 표현입니다. tomar(se) vacaciones(휴가를 가다)처럼 휴식에는 tomar를 씁니다. ¿Por qué no ~?는 '~하는 게 어때?'라는 제안 표현입니다.","x":["pones: poner(놓다)라 이 표현에 쓰지 않습니다 ✗","tomas: tomarse días libres(며칠 쉬다) → 정답 ✓","haces: hacer(하다)로 이 표현에 쓰지 않습니다 ✗","tienes: tener(가지다)는 재귀형으로 이렇게 쓰지 않습니다 ✗"]},{"id":"V269","q":"Voy al ____ automático, necesito sacar 100 euros.","o":["cajón","coche","carro","cajero"],"a":3,"k":"ATM 어휘","t":"현금 자동 인출기(ATM)에 가야겠어. 100유로를 뽑아야 해.","e":"cajero automático는 '현금 자동 인출기(ATM)'입니다. sacar dinero는 '돈을 인출하다'라는 표현입니다. 중남미에서는 carro가 '자동차'를 뜻하지만 이 문맥과는 관계없습니다.","x":["cajón: 서랍이라 ✗","coche: 자동차라 coche automático는 '오토매틱 차'가 되어 ✗","carro: 수레, 중남미에서는 자동차라 ✗","cajero: cajero automático(ATM) → 정답 ✓"]},{"id":"V270","q":"Dejé el pan demasiado tiempo en la ____, por eso se ha quemado.","o":["cafetera","batidora","nevera","tostadora"],"a":3,"k":"주방 기기 어휘","t":"빵을 토스터에 너무 오래 두어서 타 버렸다.","e":"tostadora는 '토스터'로 tostar(굽다)에서 나왔습니다. 빵(pan)이 탔다(se ha quemado)는 결과와 연결됩니다. -dora로 끝나는 명사는 '~하는 기계'인 경우가 많습니다(lavadora 세탁기).","x":["cafetera: 커피 메이커라 ✗","batidora: 믹서기, 거품기라 ✗","nevera: 냉장고라 빵이 타지 않습니다 ✗","tostadora: 토스터 → 빵이 타는 곳이므로 정답 ✓"]},{"id":"V271","q":"¡Qué zorro! Ese hombre es increíblemente ____.","o":["quejica","incrédulo","franco","astuto"],"a":3,"k":"동물 비유 표현","t":"정말 여우 같네! 저 남자는 엄청나게 교활하다.","e":"zorro는 '여우'로, 사람에게 ¡Qué zorro!라고 하면 '정말 꾀가 많다, 교활하다'라는 뜻입니다. astuto는 '영리한, 교활한, 꾀 많은'이라는 뜻입니다. 한국어의 '여우 같다'와 비슷한 비유입니다.","x":["quejica: 불평이 많은 사람(스페인 구어)이라 ✗","incrédulo: 잘 믿지 않는, 의심 많은이라 ✗","franco: 솔직한이라 여우의 이미지와 맞지 않습니다 ✗","astuto: 영리한, 교활한 → 정답 ✓"]},{"id":"V272","q":"Me gusta hacer ____, cada año viajo por placer a dos o tres lugares.","o":["deporte","ejercicio","gimnasia","turismo"],"a":3,"k":"hacer turismo","t":"나는 여행하는 것을 좋아한다. 매년 즐기려고 두세 곳을 여행한다.","e":"hacer turismo는 '관광하다, 여행하다'라는 표현입니다. 매년 즐거움을 위해(por placer) 여행한다는 설명과 일치합니다. turista(관광객)도 함께 알아 두세요.","x":["deporte: hacer deporte는 '운동하다'라 여행과 관계없습니다 ✗","ejercicio: hacer ejercicio는 '운동하다'라 ✗","gimnasia: hacer gimnasia는 '체조하다'라 ✗","turismo: hacer turismo(관광하다) → 정답 ✓"]},{"id":"V273","q":"Qué ____, puse el plato en la mesa hace un minuto y ahora no está ahí.","o":["bien","triste","extraño","lógico"],"a":2,"k":"감탄 표현","t":"이상하네, 1분 전에 접시를 식탁에 놓았는데 지금 거기 없어.","e":"¡Qué + 형용사!는 '정말 ~하다!'라는 감탄 표현입니다. extraño는 '이상한, 기묘한'으로, 접시가 갑자기 사라진 상황에 어울립니다. 같은 뜻으로 ¡Qué raro!도 자주 씁니다.","x":["bien: 좋다라 접시가 사라진 상황에 맞지 않습니다 ✗","triste: 슬픈이라 상황과 어울리지 않습니다 ✗","extraño: 이상한 → 접시가 사라진 상황이므로 정답 ✓","lógico: 논리적인, 당연한이라 문맥과 반대입니다 ✗"]},{"id":"V274","q":"A mi padre le ____ el fútbol. Cuando gana su equipo se vuelve loco de alegría.","o":["apasiona","ofende","desagrada","molesta"],"a":0,"k":"gustar류 동사","t":"우리 아버지는 축구에 열광하신다. 응원하는 팀이 이기면 기뻐서 어쩔 줄 몰라 하신다.","e":"apasionar는 '열광하게 하다, 무척 좋아하게 만들다'라는 뜻으로 gustar처럼 'a 사람 + le + 동사 + 주어' 구조로 씁니다. 팀이 이기면 기뻐 미친다(se vuelve loco de alegría)는 내용과 맞습니다. 나머지 보기도 같은 구조를 쓰지만 부정적인 뜻입니다.","x":["apasiona: apasionar(열광하게 하다) → 정답 ✓","ofende: ofender(기분 상하게 하다)라 ✗","desagrada: desagradar(불쾌하게 하다)라 문맥과 반대입니다 ✗","molesta: molestar(성가시게 하다)라 문맥과 반대입니다 ✗"]},{"id":"V275","q":"¿Te importa ____ el zumo? Está demasiado ácido.","o":["enfriar","azucarar","recalentar","salar"],"a":1,"k":"맛 관련 동사","t":"주스에 설탕 좀 넣어 줄래? 너무 셔.","e":"azucarar는 '설탕을 넣다, 달게 하다'로 azúcar(설탕)에서 나왔습니다. 주스가 너무 시다(demasiado ácido)는 문제를 해결하는 방법입니다. ¿Te importa + 동사원형?은 '~해 줄래?'라는 정중한 부탁입니다.","x":["enfriar: 차갑게 하다라 신맛을 줄이지 못합니다 ✗","azucarar: 설탕을 넣다 → 신맛을 줄이므로 정답 ✓","recalentar: 다시 데우다라 ✗","salar: 소금을 넣다라 주스에 어울리지 않습니다 ✗"]},{"id":"V276","q":"Salí ____ del trabajo, por eso no pude llegar al cine antes de que empezara la peli.","o":["pronto","tarde","rápido","antes"],"a":1,"k":"시간 부사","t":"회사에서 늦게 나와서 영화가 시작하기 전에 극장에 도착할 수 없었다.","e":"tarde는 '늦게'라는 뜻입니다. salir tarde del trabajo는 '퇴근이 늦다'입니다. 영화 시작 전에 도착하지 못한 이유로 맞습니다. peli는 película(영화)의 구어식 줄임말입니다.","x":["pronto: 일찍, 곧이라 문맥과 반대입니다 ✗","tarde: 늦게 → 늦게 나와서 도착하지 못했으므로 정답 ✓","rápido: 빨리라 문맥과 반대입니다 ✗","antes: 전에, 먼저라 늦은 이유가 되지 않습니다 ✗"]},{"id":"V277","q":"Ernesto es muy indeciso, no ____ decisiones fácilmente.","o":["toma","lleva","hace","realiza"],"a":0,"k":"결정 내리기","t":"에르네스토는 무척 우유부단해서 결정을 쉽게 내리지 못한다.","e":"tomar una decisión은 '결정을 내리다'라는 고정 표현입니다. indeciso(우유부단한)라는 성격 설명과 이어집니다. 스페인어에서는 '결정을 하다'에 hacer가 아니라 tomar를 쓴다는 점이 중요합니다.","x":["toma: tomar decisiones(결정을 내리다) → 정답 ✓","lleva: llevar(가져가다)라 이 표현에 쓰지 않습니다 ✗","hace: hacer(하다)는 decisión과 함께 쓰지 않는 것이 표준입니다 ✗","realiza: realizar(실행하다)라 이 표현에 쓰지 않습니다 ✗"]},{"id":"V278","q":"¿En qué ____ te compraste esas botas?","o":["pescadería","lavandería","carnicería","zapatería"],"a":3,"k":"가게 이름 -ería","t":"그 부츠 어느 신발 가게에서 샀니?","e":"zapatería는 '신발 가게'로 zapato(신발)에 -ería(가게)를 붙인 말입니다. botas(부츠)를 파는 곳이므로 정답입니다. 이처럼 -ería는 파는 물건 + 가게를 만듭니다(panadería 빵집, frutería 과일 가게).","x":["pescadería: 생선 가게라 ✗","lavandería: 세탁소라 ✗","carnicería: 정육점이라 ✗","zapatería: 신발 가게 → 부츠를 파므로 정답 ✓"]},{"id":"V279","q":"Ha vivido en Toledo toda su vida, por eso conoce la ciudad como la palma de su ____.","o":["cara","pie","mano","cabeza"],"a":2,"k":"관용 표현","t":"그는 평생 톨레도에 살아서 그 도시를 손바닥 보듯 훤히 안다.","e":"conocer algo como la palma de la mano는 '~을 손바닥 보듯 훤히 알다'라는 관용 표현입니다. palma는 '손바닥'이므로 mano(손)와 짝을 이룹니다. 이 문장에서는 la 대신 su를 써서 '그의 손바닥'이라고 했습니다.","x":["cara: 얼굴이라 palma(손바닥)와 맞지 않습니다 ✗","pie: 발이라 palma와 맞지 않습니다(발바닥은 planta) ✗","mano: 손, la palma de la mano는 손바닥 → 정답 ✓","cabeza: 머리라 ✗"]},{"id":"V280","q":"No me gusta llevar ropa ____, no quiero llamar la atención.","o":["llamativa","discreta","nueva","barata"],"a":0,"k":"옷 관련 형용사","t":"나는 눈에 띄는 옷을 입는 걸 좋아하지 않는다. 주목받고 싶지 않다.","e":"llamativo/a는 '눈에 띄는, 화려한'이라는 뜻으로 llamar la atención(주목을 끌다)과 관련된 말입니다. 주목받고 싶지 않다(no quiero llamar la atención)는 이유와 연결됩니다. ropa가 여성 명사라 llamativa입니다.","x":["llamativa: 눈에 띄는 → 주목받기 싫으니 입지 않으므로 정답 ✓","discreta: 수수한, 눈에 띄지 않는이라 문맥과 반대입니다 ✗","nueva: 새로운이라 주목과 관계없습니다 ✗","barata: 싼이라 주목과 관계없습니다 ✗"]},{"id":"V281","q":"Mi abuelito tiene una ____ enorme con peces de todos los colores.","o":["pecera","maceta","jarra","jardinera"],"a":0,"k":"생활용품 어휘","t":"우리 할아버지는 온갖 색깔의 물고기가 있는 커다란 어항을 가지고 계신다.","e":"pecera는 '어항'으로 pez(물고기)에서 나온 말입니다. 물고기(peces)가 사는 곳이므로 정답입니다. abuelito는 abuelo(할아버지)의 축소형으로 다정함을 나타냅니다(중남미에서 특히 많이 씁니다).","x":["pecera: 어항 → 물고기가 있으므로 정답 ✓","maceta: 화분이라 ✗","jarra: 주전자, 물병이라 ✗","jardinera: 화단 상자, 플랜터라 ✗"]},{"id":"V282","q":"No me gusta aprender idiomas solo, prefiero hacerlo en ____.","o":["grupo","asociación","banda","reunión"],"a":0,"k":"en grupo","t":"나는 혼자서 언어를 배우는 걸 좋아하지 않는다. 그룹으로 하는 걸 더 좋아한다.","e":"en grupo는 '그룹으로, 여럿이 함께'라는 표현으로 solo(혼자)와 대비됩니다. 언어 수업에서 clases en grupo(그룹 수업), clases individuales(개인 수업)처럼 자주 씁니다.","x":["grupo: en grupo(그룹으로) → solo와 대비되므로 정답 ✓","asociación: 협회라 en asociación은 '제휴하여'라는 뜻이 됩니다 ✗","banda: 밴드, 악단, 무리라 학습 방식에 쓰지 않습니다 ✗","reunión: 회의, 모임이라 en reunión은 '회의 중'이라 ✗"]},{"id":"V283","q":"Ahora ____ prisa. ¿Podemos hablar más tarde?","o":["hago","tengo","doy","dejo"],"a":1,"k":"tener prisa","t":"지금 나 바빠(급해). 나중에 얘기해도 될까?","e":"tener prisa는 '서두르다, 급하다'라는 표현입니다. 스페인어는 상태를 tener + 명사로 자주 나타냅니다(tener hambre 배고프다, tener sueño 졸리다). 중남미에서는 tener apuro라고도 합니다.","x":["hago: hacer(하다)는 prisa와 쓰지 않습니다 ✗","tengo: tener prisa(급하다) → 정답 ✓","doy: dar prisa는 '재촉하다'라는 뜻이라 문맥과 맞지 않습니다 ✗","dejo: dejar(두다)는 prisa와 쓰지 않습니다 ✗"]},{"id":"V284","q":"En una docena de huevos hay ____ unidades.","o":["once","doce","doscientas","dos"],"a":1,"k":"숫자 어휘","t":"달걀 한 다스에는 12개가 들어 있다.","e":"docena는 '다스(12개 묶음)'이므로 doce(12)가 정답입니다. docena는 doce에서 나온 말입니다. 시장에서 una docena de huevos(달걀 한 판·12개)처럼 자주 씁니다.","x":["once: 11이라 ✗","doce: 12 → 한 다스는 12개이므로 정답 ✓","doscientas: 200이라 ✗","dos: 2라 ✗"]},{"id":"V285","q":"Un trimestre es un periodo de ____ meses.","o":["cuatro","doce","tres","seis"],"a":2,"k":"기간 어휘","t":"한 분기(trimestre)는 3개월의 기간이다.","e":"trimestre는 '3개월, 분기'로 tri-(3)에서 온 말이므로 tres(3)가 정답입니다. 비슷하게 semestre는 6개월(학기), bimestre는 2개월입니다. 학교에서는 trimestre가 '학기(3학기제)'를 뜻하기도 합니다.","x":["cuatro: 4라 ✗","doce: 12라 1년입니다 ✗","tres: 3 → trimestre는 3개월이므로 정답 ✓","seis: 6이라 semestre입니다 ✗"]},{"id":"V286","q":"Los ladrones se llevaron todos los ____ de valor: cuadros, joyas, etc.","o":["alimentos","objetivos","objetos","aparatos"],"a":2,"k":"objeto/objetivo","t":"도둑들은 그림, 보석 등 값나가는 물건을 모두 가져갔다.","e":"objetos de valor는 '귀중품, 값나가는 물건'입니다. objeto는 '물건, 물체'입니다. 철자가 비슷한 objetivo(목표)와 혼동하지 마세요. 그림(cuadros), 보석(joyas)이 예시로 나와 있습니다.","x":["alimentos: 식품이라 그림·보석과 맞지 않습니다 ✗","objetivos: 목표라 objeto와 혼동하기 쉽지만 ✗","objetos: 물건, objetos de valor는 귀중품 → 정답 ✓","aparatos: 기기, 장치라 그림·보석을 포함하지 않습니다 ✗"]},{"id":"V287","q":"Mis hijos esperan la Navidad con ____. Les encanta esa época del año.","o":["pesimismo","ilusión","desgana","pereza"],"a":1,"k":"ilusión 설렘","t":"우리 아이들은 크리스마스를 설레며 기다린다. 그 시기를 정말 좋아한다.","e":"ilusión은 '환상' 외에 '설렘, 기대감'이라는 뜻으로 자주 씁니다. esperar con ilusión은 '설레며 기다리다'입니다. 예: Me hace mucha ilusión el viaje.(여행이 정말 기대돼.)","x":["pesimismo: 비관이라 문맥과 반대입니다 ✗","ilusión: 설렘, 기대 → 정답 ✓","desgana: 의욕 없음이라 문맥과 반대입니다 ✗","pereza: 귀찮음, 게으름이라 ✗"]},{"id":"V288","q":"Qué bien se duerme en esta cama, es muy ____.","o":["pequeña","vieja","estrecha","cómoda"],"a":3,"k":"가구 형용사","t":"이 침대에서는 정말 잘 잔다. 아주 편안하다.","e":"cómodo/a는 '편안한'이라는 뜻입니다. 잠이 잘 온다(Qué bien se duerme)는 이유로 가장 자연스럽습니다. cama가 여성 명사라 cómoda입니다. 참고로 명사 la cómoda는 '서랍장'이라는 뜻도 있습니다.","x":["pequeña: 작은이라 잘 자는 이유가 되기 어렵습니다 ✗","vieja: 낡은이라 ✗","estrecha: 좁은이라 ✗","cómoda: 편안한 → 잘 자는 이유이므로 정답 ✓"]},{"id":"V289","q":"Susana es una persona ____ que se comunica con facilidad con todo el mundo.","o":["abierta","cerrada","introvertida","misteriosa"],"a":0,"k":"성격 형용사","t":"수사나는 모든 사람과 쉽게 소통하는 개방적인 사람이다.","e":"abierto/a는 '열린'이라는 기본 뜻에서 사람에게 쓰면 '개방적인, 사교적인'이라는 뜻이 됩니다. 누구와도 쉽게 소통한다는 설명과 맞습니다. 반대말은 cerrado(폐쇄적인)입니다.","x":["abierta: 개방적인, 사교적인 → 정답 ✓","cerrada: 폐쇄적인이라 문맥과 반대입니다 ✗","introvertida: 내성적인이라 문맥과 반대입니다 ✗","misteriosa: 신비로운이라 소통과 관계없습니다 ✗"]},{"id":"V290","q":"Esta impresora es muy buena, ____ rápido y no se estropea fácilmente.","o":["graba","imprime","lee","escribe"],"a":1,"k":"imprimir 인쇄하다","t":"이 프린터는 정말 좋다. 빨리 인쇄되고 쉽게 고장 나지 않는다.","e":"imprimir는 '인쇄하다'로 impresora(프린터)와 같은 어원입니다. 프린터가 하는 일은 인쇄이므로 정답입니다. estropearse는 '고장 나다'입니다.","x":["graba: grabar(녹음·녹화하다)라 ✗","imprime: imprimir(인쇄하다) → 정답 ✓","lee: leer(읽다)라 프린터의 주된 기능이 아닙니다 ✗","escribe: escribir(쓰다)라 프린터에는 쓰지 않습니다 ✗"]},{"id":"V291","q":"Estuve con gripe dos semanas. Me sentía ____.","o":["de maravilla","genial","fatal","estupendamente"],"a":2,"k":"기분·몸 상태","t":"나는 2주 동안 독감을 앓았다. 몸 상태가 엉망이었다.","e":"sentirse fatal은 '몸(기분)이 아주 안 좋다'라는 표현입니다. fatal은 '최악의, 아주 나쁜'이라는 구어 표현으로 스페인에서 특히 많이 씁니다. 독감(gripe)에 걸린 상황에 어울리는 유일한 부정적 표현입니다.","x":["de maravilla: 아주 좋게라 독감과 맞지 않습니다 ✗","genial: 최고로 좋게라 ✗","fatal: 최악으로, 아주 안 좋게 → 정답 ✓","estupendamente: 아주 훌륭하게라 ✗"]},{"id":"V292","q":"Está ____ porque no consigue encontrar trabajo.","o":["desconectado","desesperado","despistado","despreocupado"],"a":1,"k":"des- 형용사","t":"그는 일자리를 구하지 못해서 절망하고 있다.","e":"desesperado는 '절망한, 필사적인'이라는 뜻으로 esperanza(희망)가 없는 상태입니다. 일자리를 찾지 못한다는 이유와 연결됩니다. 보기 모두 des-로 시작하니 뜻을 잘 구분하세요.","x":["desconectado: 연결이 끊긴이라 ✗","desesperado: 절망한 → 일자리를 못 구해서이므로 정답 ✓","despistado: 정신없는, 덜렁대는이라 ✗","despreocupado: 걱정 없는, 태평한이라 문맥과 반대입니다 ✗"]},{"id":"V293","q":"Puesto que me interesa especialmente lo que pasa en mi región, lo primero que leo es la prensa ____.","o":["local","amarilla","económica","internacional"],"a":0,"k":"신문 종류","t":"나는 우리 지역에서 일어나는 일에 특히 관심이 있기 때문에, 가장 먼저 지역 신문을 읽는다.","e":"prensa local은 '지역 신문(지역 언론)'입니다. 내 지역(mi región)에서 일어나는 일에 관심이 있다는 이유와 일치합니다. prensa는 '언론, 신문'이라는 뜻입니다. puesto que는 '~이므로'라는 접속사입니다.","x":["local: 지역의 → 지역 소식에 관심이 있으므로 정답 ✓","amarilla: prensa amarilla는 '황색 언론(선정적 신문)'이라 ✗","económica: 경제 신문이라 지역과 관계없습니다 ✗","internacional: 국제의라 문맥과 반대입니다 ✗"]},{"id":"V294","q":"La casa de mis abuelos es ____, por eso me encanta pasar tiempo allí.","o":["horrorosa","acogedora","horrible","diminuta"],"a":1,"k":"집 관련 형용사","t":"조부모님 댁은 아늑해서 나는 거기서 시간을 보내는 걸 정말 좋아한다.","e":"acogedor/a는 '아늑한, 포근한, 따뜻하게 맞아 주는'이라는 뜻으로 acoger(맞아들이다)에서 나왔습니다. 그곳에서 지내는 게 좋다는 이유로 맞습니다. casa가 여성 명사라 acogedora입니다.","x":["horrorosa: 끔찍한이라 좋아하는 이유와 반대입니다 ✗","acogedora: 아늑한 → 정답 ✓","horrible: 끔찍한이라 ✗","diminuta: 아주 작은이라 좋아하는 이유로 부족합니다 ✗"]},{"id":"V295","q":"Las cucharas, los tenedores y los cuchillos son los principales ____.","o":["envases","contenedores","alimentos","cubiertos"],"a":3,"k":"식기 어휘","t":"숟가락, 포크, 나이프는 주요 식사 도구(커틀러리)다.","e":"cubiertos는 '수저류, 커틀러리(숟가락·포크·나이프)'를 묶어 부르는 말입니다. cubierto는 '덮인'이라는 뜻의 형용사이기도 해서 문맥으로 구별합니다.","x":["envases: 용기, 포장 용기라 ✗","contenedores: 컨테이너, 큰 쓰레기통이라 ✗","alimentos: 식품이라 ✗","cubiertos: 수저류 → 정답 ✓"]},{"id":"V296","q":"Vivo en una ciudad ____ porque me encanta tener el mar cerca.","o":["histórica","costera","montañosa","industrial"],"a":1,"k":"도시 형용사","t":"바다가 가까이 있는 것을 정말 좋아해서 나는 해안 도시에 산다.","e":"costero/a는 '해안의'라는 뜻으로 costa(해안)에서 나왔습니다. 바다가 가까이 있다(tener el mar cerca)는 이유와 연결됩니다. ciudad가 여성 명사라 costera입니다.","x":["histórica: 역사적인이라 바다와 관계없습니다 ✗","costera: 해안의 → 바다와 가까우므로 정답 ✓","montañosa: 산이 많은이라 ✗","industrial: 공업의라 ✗"]},{"id":"V297","q":"Si tiene algún problema, ____ con nosotros en este número de teléfono.","o":["contacte","envíe","venga","insista"],"a":0,"k":"contactar con","t":"문제가 있으시면 이 전화번호로 저희에게 연락해 주십시오.","e":"contactar con은 '~와 연락하다'라는 뜻입니다. contacte는 usted(당신)에 대한 긍정 명령형으로, 고객 안내문에서 자주 씁니다. 전화번호(número de teléfono)와 con nosotros(저희와)가 힌트입니다.","x":["contacte: contactar con(~와 연락하다)의 usted 명령형 → 정답 ✓","envíe: enviar(보내다)라 목적어가 없어 con nosotros와 어울리지 않습니다 ✗","venga: venir(오다)라 전화번호와 맞지 않습니다 ✗","insista: insistir(고집하다, 계속 요구하다)라 ✗"]},{"id":"V298","q":"Lo normal es colocar la mesilla de noche al lado de la ____.","o":["cómoda","bañera","cama","cortina"],"a":2,"k":"가구 어휘","t":"보통 협탁(침대 옆 탁자)은 침대 옆에 놓는다.","e":"mesilla de noche는 '침대 옆 탁자(협탁)'이므로 침대(cama) 옆에 놓습니다. 중남미에서는 mesita de noche, buró(멕시코) 등으로도 부릅니다. al lado de는 '~의 옆에'입니다.","x":["cómoda: 서랍장이라 협탁을 두는 기준 위치가 아닙니다 ✗","bañera: 욕조라 ✗","cama: 침대 → 협탁은 침대 옆에 두므로 정답 ✓","cortina: 커튼이라 ✗"]},{"id":"V299","q":"Somos ____ habituales de este periódico.","o":["televidentes","espectadores","oyentes","lectores"],"a":3,"k":"매체 이용자 어휘","t":"우리는 이 신문의 정기 독자다.","e":"lector는 '독자'로 동사 leer(읽다)에서 나왔습니다. 신문(periódico)을 읽는 사람이므로 정답입니다. 매체별로 텔레비전은 televidente, 라디오는 oyente, 공연·영화는 espectador라고 합니다.","x":["televidentes: 시청자로 텔레비전에 씁니다 ✗","espectadores: 관객으로 공연·영화에 씁니다 ✗","oyentes: 청취자로 라디오에 씁니다 ✗","lectores: 독자 → 신문을 읽으므로 정답 ✓"]},{"id":"V300","q":"No estés ____, todo va a salir bien.","o":["triste","contento","feliz","relajado"],"a":0,"k":"감정 형용사","t":"슬퍼하지 마. 다 잘될 거야.","e":"No estés + 형용사는 '~해하지 마'라는 부정 명령입니다(estar의 접속법 형태를 씀). triste(슬픈)가 '다 잘될 거야(todo va a salir bien)'라는 위로의 말과 어울립니다. 나머지 보기는 긍정적인 감정이라 '하지 마'와 맞지 않습니다.","x":["triste: 슬픈 → 위로하는 상황이므로 정답 ✓","contento: 기쁜이라 '기뻐하지 마'는 어색합니다 ✗","feliz: 행복한이라 문맥과 맞지 않습니다 ✗","relajado: 편안한이라 '편히 있지 마'가 되어 ✗"]},{"id":"V301","q":"Soy ____, trabajo para un canal privado de televisión.","o":["costurera","niñera","cartera","reportera"],"a":3,"k":"직업 어휘","t":"저는 기자예요. 민영 텔레비전 방송국에서 일해요.","e":"reportera는 현장에서 취재해 보도하는 '기자, 리포터'(여성형, 남성형은 reportero)입니다. 텔레비전 방송국(canal de televisión)에서 일한다는 내용과 어울리는 직업은 reportera뿐입니다. 예: La reportera habló con los testigos.(기자가 목격자들과 이야기했다.)","x":["costurera: 재봉사, 바느질하는 사람이라 방송국 일과 관계없음 ✗","niñera: 아이 돌보는 사람(보모)이라 방송국과 맞지 않음 ✗","cartera: 우편집배원(또는 지갑)이라 방송국 일과 무관 ✗","reportera: 기자, 리포터 → 방송국에서 일하는 직업으로 정답 ✓"]},{"id":"V302","q":"____ decenas de relámpagos durante la tormenta.","o":["Tocamos","Dimos","Vimos","Escuchamos"],"a":2,"k":"감각 동사","t":"폭풍우가 치는 동안 우리는 수십 번의 번개를 봤다.","e":"relámpago는 '번개(번쩍이는 빛)'입니다. 빛은 눈으로 보는 것이므로 ver(보다)의 과거형 vimos가 맞습니다. 참고로 천둥소리는 trueno라고 하며, 이것은 escuchar/oír(듣다)와 어울립니다.","x":["Tocamos: tocar(만지다)의 과거형, 번개는 만질 수 없음 ✗","Dimos: dar(주다)의 과거형, 의미가 맞지 않음 ✗","Vimos: ver(보다)의 과거형, 번개(빛)를 봤다 → 정답 ✓","Escuchamos: escuchar(듣다)의 과거형, 소리인 천둥(trueno)에 어울림 ✗"]},{"id":"V303","q":"Afortunadamente, el negocio de mi hijo va ____.","o":["regular","inmediatamente","fatal","estupendamente"],"a":3,"k":"부사 어휘","t":"다행히도 내 아들의 사업은 아주 잘되고 있다.","e":"ir + 부사는 '(일이) ~하게 되어 가다'라는 뜻입니다. afortunadamente(다행히도)라는 긍정적인 말과 어울리려면 '아주 잘'이라는 뜻의 estupendamente가 필요합니다. 예: El examen me fue estupendamente.(시험을 아주 잘 봤다.)","x":["regular: 그저 그렇게, 보통으로 → '다행히'와 어울리지 않음 ✗","inmediatamente: 즉시, 곧바로 → 사업 상태를 나타내지 않음 ✗","fatal: 아주 나쁘게 → '다행히'와 반대 의미 ✗","estupendamente: 아주 훌륭하게, 아주 잘 → 정답 ✓"]},{"id":"V304","q":"Voy a usar la escoba para quitar el polvo del suelo porque la ____ no funciona.","o":["olla","secadora","vitrocerámica","aspiradora"],"a":3,"k":"가전제품 어휘","t":"청소기가 고장 나서 바닥의 먼지를 치우려고 빗자루를 쓸 거야.","e":"aspiradora는 '진공청소기'입니다. 빗자루(escoba)를 대신 쓴다는 것은 원래 먼지를 치우는 도구가 고장 났다는 뜻이므로 aspiradora가 맞습니다. pasar la aspiradora(청소기를 돌리다)라는 표현도 함께 기억하세요.","x":["olla: 냄비, 요리 도구라 먼지 청소와 무관 ✗","secadora: 빨래 건조기(또는 헤어드라이어)라 맞지 않음 ✗","vitrocerámica: 전기레인지(세라믹 쿡탑)라 청소 도구가 아님 ✗","aspiradora: 진공청소기 → 먼지를 치우는 기계로 정답 ✓"]},{"id":"V305","q":"Mi hermana es muy ____, siempre que me ve me abraza.","o":["cariñosa","extraña","fría","insensible"],"a":0,"k":"성격 형용사","t":"우리 언니는 정이 무척 많아서 나를 볼 때마다 안아 줘.","e":"cariñosa(남성형 cariñoso)는 '다정한, 애정 표현을 잘하는'이라는 뜻입니다. 볼 때마다 안아 준다는 설명과 딱 맞습니다. cariño(애정)에서 나온 말이며, 연인이나 가족을 부를 때 ¡Cariño!(자기야!)라고도 합니다.","x":["cariñosa: 다정한, 애정이 많은 → 포옹하는 행동과 일치하여 정답 ✓","extraña: 이상한, 낯선 → 포옹과 관련 없음 ✗","fría: 차가운, 냉정한 → 포옹하는 행동과 반대 ✗","insensible: 무감각한, 둔감한 → 문맥과 반대 ✗"]},{"id":"V306","q":"Mis padres no están ____, se divorciaron hace cinco años.","o":["juntos","viudos","solteros","separados"],"a":0,"k":"가족 관계 어휘","t":"우리 부모님은 함께 살지 않아요. 5년 전에 이혼하셨어요.","e":"estar juntos는 '함께 있다, (커플이) 같이 지내다'라는 뜻입니다. 이혼했기 때문에 '함께가 아니다(no están juntos)'가 자연스럽습니다. separados(헤어진)를 넣으면 'no están separados(헤어지지 않았다)'가 되어 이혼과 모순됩니다.","x":["juntos: 함께 → 'no están juntos(함께가 아니다)'로 이혼과 일치하여 정답 ✓","viudos: 배우자를 잃은(사별한) → 이혼과는 다른 상황 ✗","solteros: 미혼의 → 결혼한 적이 있는 부모님에게 맞지 않음 ✗","separados: 헤어진, 별거한 → 부정문이 되면 이혼과 모순 ✗"]},{"id":"V307","q":"Las ____ tienen ocho patas.","o":["serpientes","arañas","moscas","abejas"],"a":1,"k":"동물 어휘","t":"거미는 다리가 여덟 개다.","e":"araña는 '거미'로, 다리(pata)가 여덟 개인 동물입니다. 스페인어에서 동물의 다리는 pierna가 아니라 pata라고 합니다. 참고로 곤충(insecto)인 파리·벌은 다리가 여섯 개입니다.","x":["serpientes: 뱀, 다리가 없음 ✗","arañas: 거미, 다리가 8개 → 정답 ✓","moscas: 파리, 다리가 6개인 곤충 ✗","abejas: 벌, 다리가 6개인 곤충 ✗"]},{"id":"V308","q":"¡Qué ____ es! Siempre espera a que pague otra persona del grupo.","o":["aburrida","simpática","tacaña","extrovertida"],"a":2,"k":"성격 형용사","t":"정말 구두쇠야! 항상 무리의 다른 사람이 돈을 내길 기다려.","e":"tacaña(남성형 tacaño)는 '인색한, 구두쇠인'이라는 뜻입니다. 늘 남이 계산하기를 기다리는 사람을 묘사하므로 정답입니다. ¡Qué + 형용사 + es!는 '정말 ~하구나!'라는 감탄 표현입니다.","x":["aburrida: 지루한, 재미없는 → 돈 내는 행동과 무관 ✗","simpática: 상냥한, 호감 가는 → 부정적인 행동 묘사와 맞지 않음 ✗","tacaña: 인색한, 구두쇠 → 남이 계산하길 기다리는 사람으로 정답 ✓","extrovertida: 외향적인 → 돈 문제와 관계없음 ✗"]},{"id":"V309","q":"Aunque sea un adolescente, puedes hablar de todo con ella, es una chica muy ____.","o":["ingenua","mentirosa","madura","rebelde"],"a":2,"k":"성격 형용사","t":"비록 청소년이지만 그녀와는 무슨 이야기든 할 수 있어. 아주 성숙한 아이야.","e":"madura(남성형 maduro)는 '성숙한, 철든'이라는 뜻입니다. aunque(비록 ~이지만)로 '어린 나이인데도'라는 대조를 만들고, 무엇이든 이야기할 수 있다는 긍정적 내용이 뒤따르므로 madura가 맞습니다. 과일에 쓰면 '잘 익은'이라는 뜻도 됩니다.","x":["ingenua: 순진한, 세상 물정 모르는 → '무엇이든 이야기할 수 있다'와 어울리지 않음 ✗","mentirosa: 거짓말쟁이의 → 부정적 의미라 문맥과 반대 ✗","madura: 성숙한 → 어린데도 대화가 통한다는 대조와 일치하여 정답 ✓","rebelde: 반항적인 → 오히려 청소년의 전형적 특징이라 대조가 안 됨 ✗"]},{"id":"V310","q":"En una dictadura, no hay ____ de expresión.","o":["prohibición","libertad","intento","deseo"],"a":1,"k":"사회 어휘","t":"독재 체제에서는 표현의 자유가 없다.","e":"libertad de expresión은 '표현의 자유'라는 고정 표현입니다. 독재(dictadura) 체제에서 없는 것으로 가장 자연스럽습니다. 비슷하게 libertad de prensa(언론의 자유)도 자주 쓰입니다.","x":["prohibición: 금지 → '표현의 금지가 없다'는 독재와 반대 의미 ✗","libertad: 자유 → libertad de expresión(표현의 자유)으로 정답 ✓","intento: 시도 → 고정 표현이 아니며 의미가 어색함 ✗","deseo: 바람, 욕구 → 문맥에 맞지 않음 ✗"]},{"id":"V311","q":"La Tierra gira ____ del Sol.","o":["delante","detrás","al lado","alrededor"],"a":3,"k":"위치 전치사구","t":"지구는 태양 주위를 돈다.","e":"alrededor de는 '~의 주위에, ~을 둘러싸고'라는 뜻입니다. 지구가 태양을 중심으로 빙 돌고 있으므로 girar alrededor de(~의 주위를 돌다)가 맞습니다. 예: Nos sentamos alrededor de la mesa.(우리는 탁자에 둘러앉았다.)","x":["delante: delante de(~앞에), 회전 운동을 나타내지 않음 ✗","detrás: detrás de(~뒤에), 회전 운동과 맞지 않음 ✗","al lado: al lado de(~옆에), 도는 움직임이 아님 ✗","alrededor: alrededor de(~의 주위에) → 태양 주위를 돈다로 정답 ✓"]},{"id":"V312","q":"A veces, los camareros deben ser pacientes con los ____ difíciles.","o":["clientes","comerciantes","compradores","dependientes"],"a":0,"k":"직업·사람 어휘","t":"가끔 웨이터들은 까다로운 손님들에게 인내심을 가져야 한다.","e":"cliente는 가게·식당 등의 '손님, 고객'입니다. 웨이터(camarero)가 상대하는 사람은 식당 손님이므로 clientes가 정답입니다. 남녀 모두 cliente 형태를 쓸 수 있습니다(el/la cliente).","x":["clientes: 손님, 고객 → 웨이터가 상대하는 사람으로 정답 ✓","comerciantes: 상인 → 웨이터의 손님과 맞지 않음 ✗","compradores: 구매자 → 상점에서 물건을 사는 사람에 가까워 식당에 어색함 ✗","dependientes: 점원 → 손님이 아니라 일하는 사람 ✗"]},{"id":"V313","q":"Aunque perdió el concurso, su reacción fue ____.","o":["inadecuada","malísima","inaceptable","buena"],"a":3,"k":"평가 형용사","t":"대회에서 졌는데도 그의 반응은 좋았다.","e":"aunque(비록 ~이지만)는 앞뒤 내용이 대조될 때 씁니다. '졌다'는 부정적인 내용 뒤에는 긍정적인 결과가 와야 대조가 성립하므로 buena(좋은)가 정답입니다.","x":["inadecuada: 부적절한 → 졌으니 당연한 부정적 결과라 대조가 안 됨 ✗","malísima: 아주 나쁜 → aunque의 대조와 맞지 않음 ✗","inaceptable: 받아들일 수 없는 → 부정적이라 대조가 안 됨 ✗","buena: 좋은 → '졌지만 반응은 좋았다'는 대조로 정답 ✓"]},{"id":"V314","q":"Me relaja ____ el sol en la playa.","o":["poner","hacer","tomar","tener"],"a":2,"k":"동사 연어","t":"해변에서 햇볕을 쬐는 것은 나를 편안하게 해 준다.","e":"tomar el sol은 '햇볕을 쬐다, 일광욕하다'라는 고정 표현입니다. tomar는 '마시다, 잡다' 외에도 이렇게 다양한 표현에 쓰입니다. 예: tomar el aire(바람을 쐬다).","x":["poner: 놓다, 두다 → poner el sol은 쓰지 않음 ✗","hacer: 하다, 만들다 → hace sol은 '해가 쨍하다(날씨)'라는 뜻이라 다름 ✗","tomar: tomar el sol(햇볕을 쬐다) → 정답 ✓","tener: 가지다 → tener el sol은 의미가 없음 ✗"]},{"id":"V315","q":"Ten cuidado al mover esa caja, el contenido es ____.","o":["sólido","frágil","resistente","duro"],"a":1,"k":"성질 형용사","t":"그 상자를 옮길 때 조심해. 내용물이 깨지기 쉬워.","e":"frágil은 '깨지기 쉬운, 연약한'이라는 뜻입니다. 조심하라는 말과 어울리는 것은 frágil뿐입니다. 택배 상자에 쓰인 FRÁGIL은 '취급 주의(깨짐 주의)'라는 뜻입니다.","x":["sólido: 단단한, 견고한 → 조심할 이유가 안 됨 ✗","frágil: 깨지기 쉬운 → 조심하라는 이유로 정답 ✓","resistente: 튼튼한, 잘 견디는 → 문맥과 반대 ✗","duro: 딱딱한 → 조심할 이유가 안 됨 ✗"]},{"id":"V316","q":"¿Cuántos ____ hay en este ejército?","o":["espectadores","soldados","oyentes","televidentes"],"a":1,"k":"직업·사람 어휘","t":"이 군대에는 군인이 몇 명 있나요?","e":"soldado는 '군인, 병사'입니다. 군대(ejército)를 구성하는 사람이므로 정답입니다. 나머지 보기는 모두 공연·방송을 보거나 듣는 사람을 가리킵니다.","x":["espectadores: 관객 → 군대와 무관 ✗","soldados: 군인, 병사 → 군대를 이루는 사람으로 정답 ✓","oyentes: 청취자 → 라디오 등을 듣는 사람이라 맞지 않음 ✗","televidentes: 시청자 → 텔레비전을 보는 사람이라 맞지 않음 ✗"]},{"id":"V317","q":"Vimos varios ____ nadando en el lago.","o":["loros","ciervos","patos","conejos"],"a":2,"k":"동물 어휘","t":"우리는 호수에서 헤엄치는 오리 몇 마리를 봤다.","e":"pato는 '오리'로, 호수(lago)에서 헤엄치는 동물로 가장 자연스럽습니다. ver + 목적어 + 현재분사(nadando)는 '~가 ~하고 있는 것을 보다'라는 구조입니다.","x":["loros: 앵무새 → 물에서 헤엄치지 않음 ✗","ciervos: 사슴 → 호수에서 헤엄치는 동물로 어색함 ✗","patos: 오리 → 호수에서 헤엄치는 새로 정답 ✓","conejos: 토끼 → 헤엄치는 동물이 아님 ✗"]},{"id":"V318","q":"Si no eres ____, te van a echar del trabajo.","o":["mentiroso","perezoso","irresponsable","puntual"],"a":3,"k":"성격 형용사","t":"시간을 잘 지키지 않으면 너는 직장에서 쫓겨날 거야.","e":"puntual은 '시간을 잘 지키는'이라는 뜻입니다. 'Si no eres ~(~하지 않으면) 해고된다'이므로 빈칸에는 긍정적인 자질이 와야 합니다. echar del trabajo는 '해고하다'라는 뜻의 구어 표현입니다.","x":["mentiroso: 거짓말하는 → 'no eres mentiroso'면 오히려 좋은 것이라 해고 이유가 아님 ✗","perezoso: 게으른 → 게으르지 않으면 해고될 이유가 없음 ✗","irresponsable: 무책임한 → 무책임하지 않으면 해고될 이유가 없음 ✗","puntual: 시간을 잘 지키는 → 시간을 안 지키면 해고된다로 정답 ✓"]},{"id":"V319","q":"En este polideportivo hay muchas ____, puedes hacer de todo.","o":["residencias","viviendas","industrias","instalaciones"],"a":3,"k":"시설 어휘","t":"이 종합 체육관에는 시설이 많아서 뭐든지 할 수 있어.","e":"instalaciones는 '시설, 설비'라는 뜻으로, 체육관·학교 등의 운동장·수영장·코트 같은 공간을 말합니다. polideportivo(종합 스포츠 센터)와 가장 잘 어울립니다.","x":["residencias: 기숙사, 거주 시설 → 체육관에 맞지 않음 ✗","viviendas: 주택, 집 → 체육관과 무관 ✗","industrias: 산업, 공장 → 체육관과 무관 ✗","instalaciones: 시설, 설비 → 체육관의 각종 시설로 정답 ✓"]},{"id":"V320","q":"¿Qué ____ de televisión ves con más frecuencia?","o":["calle","vía","canal","puente"],"a":2,"k":"방송 어휘","t":"어떤 텔레비전 채널을 가장 자주 봐?","e":"canal은 '(텔레비전) 채널'입니다. canal de televisión(텔레비전 채널)은 자주 쓰는 표현입니다. canal에는 '운하'라는 뜻도 있습니다(el canal de Panamá 파나마 운하).","x":["calle: 거리, 길 → 텔레비전과 무관 ✗","vía: 길, 선로 → 텔레비전과 무관 ✗","canal: 채널 → canal de televisión으로 정답 ✓","puente: 다리(교량) → 텔레비전과 무관 ✗"]},{"id":"V321","q":"Me encuentro ____, no tengo fuerzas para hacer nada.","o":["lista","preparada","débil","fuerte"],"a":2,"k":"상태 형용사","t":"몸에 기운이 없어. 아무것도 할 힘이 없어.","e":"débil은 '약한, 기운 없는'이라는 뜻입니다. 뒤에 '아무것도 할 힘이 없다'는 설명이 오므로 débil이 딱 맞습니다. encontrarse + 형용사는 '(몸·기분이) ~하다'라는 뜻입니다.","x":["lista: (estar와 함께) 준비된 → 힘이 없다는 설명과 맞지 않음 ✗","preparada: 준비된 → 문맥과 맞지 않음 ✗","débil: 약한, 기운 없는 → 힘이 없다는 설명과 일치하여 정답 ✓","fuerte: 강한, 튼튼한 → 문맥과 반대 ✗"]},{"id":"V322","q":"Estudio inglés y español para ____ un trabajo mejor.","o":["conseguir","contactar","coleccionar","controlar"],"a":0,"k":"동사 어휘","t":"더 좋은 일자리를 얻으려고 영어와 스페인어를 공부해요.","e":"conseguir는 '얻다, 획득하다, 이루다'라는 뜻입니다. conseguir un trabajo(일자리를 얻다)는 아주 자주 쓰는 표현입니다. 예: Conseguí entradas para el concierto.(콘서트 표를 구했어.)","x":["conseguir: 얻다, 구하다 → 일자리를 얻다로 정답 ✓","contactar: 연락하다 → 일자리를 '연락하다'는 어색함 ✗","coleccionar: 수집하다 → 일자리를 수집하는 것은 맞지 않음 ✗","controlar: 통제하다, 관리하다 → 문맥에 맞지 않음 ✗"]},{"id":"V323","q":"Hay demasiada luz aquí. ¿Podrías bajar la ____?","o":["alfombra","cama","estantería","persiana"],"a":3,"k":"집 안 물건 어휘","t":"여기 빛이 너무 많이 들어와. 블라인드 좀 내려 줄래?","e":"persiana는 창문에 다는 '블라인드, 덧문'입니다. 빛을 막으려면 bajar la persiana(블라인드를 내리다)라고 합니다. 반대로 올리는 것은 subir la persiana입니다.","x":["alfombra: 카펫, 양탄자 → 빛을 막지 못함 ✗","cama: 침대 → 빛과 관계없음 ✗","estantería: 책장, 선반 → 빛을 막는 물건이 아님 ✗","persiana: 블라인드 → 내려서 빛을 막으므로 정답 ✓"]},{"id":"V324","q":"Alexander Fleming fue el ____ de la penicilina.","o":["conquistador","pensador","descubridor","investigador"],"a":2,"k":"사람 명사 어휘","t":"알렉산더 플레밍은 페니실린의 발견자였다.","e":"descubridor는 '발견자'로, descubrir(발견하다)에서 나온 말입니다. 플레밍은 페니실린을 발견한 사람이므로 정답입니다. investigador(연구자)도 그의 직업이긴 하지만 'el investigador de la penicilina'라고는 하지 않습니다.","x":["conquistador: 정복자 → 과학자와 관계없음 ✗","pensador: 사상가 → 약을 발견한 사람에게 맞지 않음 ✗","descubridor: 발견자 → 페니실린의 발견자로 정답 ✓","investigador: 연구자 → 'de la penicilina'와 함께 쓰면 어색함 ✗"]},{"id":"V325","q":"Es una mujer muy ____, por eso tiene su despacho perfectamente ordenado.","o":["organizada","despistada","despreocupada","imprudente"],"a":0,"k":"성격 형용사","t":"그녀는 매우 체계적인 사람이라서 사무실이 완벽하게 정리되어 있다.","e":"organizada(남성형 organizado)는 '정리를 잘하는, 체계적인'이라는 뜻입니다. por eso(그래서) 뒤에 사무실이 잘 정리되어 있다는 결과가 오므로 원인으로 organizada가 맞습니다.","x":["organizada: 체계적인, 정리를 잘하는 → 정리된 사무실의 원인으로 정답 ✓","despistada: 덜렁대는, 정신없는 → 결과와 반대 ✗","despreocupada: 걱정 없는, 무관심한 → 정리된 사무실과 맞지 않음 ✗","imprudente: 경솔한 → 정리 정돈과 관계없음 ✗"]},{"id":"V326","q":"No tenemos cerillas ni encendedor, así que no podemos ____ las velas.","o":["apagar","quemar","encender","derretir"],"a":2,"k":"동사 어휘","t":"성냥도 라이터도 없어서 초에 불을 붙일 수 없다.","e":"encender는 '불을 켜다, 불을 붙이다'라는 뜻입니다(활용: enciendo, enciendes...). 성냥(cerillas)과 라이터(encendedor)가 없으면 초를 켤 수 없으므로 정답입니다. 반대말은 apagar(끄다)입니다.","x":["apagar: 끄다 → 끄는 데는 성냥이 필요 없음 ✗","quemar: 태우다 → 초를 '태우다'는 어색함 ✗","encender: 불을 붙이다, 켜다 → 정답 ✓","derretir: 녹이다 → 성냥이 없다는 이유와 맞지 않음 ✗"]},{"id":"V327","q":"Las tortugas son muy ____.","o":["lentas","rápidas","altas","largas"],"a":0,"k":"묘사 형용사","t":"거북이는 매우 느리다.","e":"lento(느린)는 거북이(tortuga)의 대표적인 특징입니다. tortugas가 여성 복수이므로 형용사도 lentas로 맞춰 씁니다. 반대말은 rápido(빠른)입니다.","x":["lentas: 느린 → 거북이의 특징으로 정답 ✓","rápidas: 빠른 → 거북이의 특징과 반대 ✗","altas: 키가 큰, 높은 → 거북이에게 맞지 않음 ✗","largas: 긴 → 거북이의 대표적 특징이 아님 ✗"]},{"id":"V328","q":"¿Cuándo le darán los resultados del ____ de sangre?","o":["examen","ejercicio","análisis","test"],"a":2,"k":"의료 어휘","t":"혈액 검사 결과는 언제 나오나요?","e":"análisis de sangre는 '혈액 검사'라는 고정 표현입니다. análisis는 단수·복수 형태가 같습니다(el análisis, los análisis). 의료 검사에는 examen이나 test보다 análisis를 씁니다.","x":["examen: 시험 → 학교 시험에 주로 쓰며 '혈액 검사'로는 쓰지 않음 ✗","ejercicio: 연습 문제, 운동 → 의미가 맞지 않음 ✗","análisis: 분석, (의학) 검사 → análisis de sangre로 정답 ✓","test: 테스트 → 의료 혈액 검사에는 쓰지 않음 ✗"]},{"id":"V329","q":"Si no conoces el significado de una palabra, debes ____ en el diccionario.","o":["buscarla","anotarla","ponerla","escribirla"],"a":0,"k":"동사 어휘","t":"어떤 단어의 뜻을 모르면 사전에서 찾아봐야 해.","e":"buscar는 '찾다'라는 뜻이고, buscar en el diccionario는 '사전에서 찾아보다'입니다. buscarla의 la는 una palabra를 받는 직접목적격 대명사(~을/를)로, 동사원형 뒤에 붙여 씁니다.","x":["buscarla: 그것을 찾다 → 사전에서 단어를 찾다로 정답 ✓","anotarla: 그것을 메모하다 → 사전에서 하는 행동이 아님 ✗","ponerla: 그것을 놓다 → 의미가 맞지 않음 ✗","escribirla: 그것을 쓰다 → 사전에 쓰는 것은 어색함 ✗"]},{"id":"V330","q":"Alfredo es un ____, siempre está dando órdenes.","o":["perdedor","mandón","contestón","preguntón"],"a":1,"k":"성격 명사","t":"알프레도는 대장 노릇을 하는 사람이야. 항상 명령만 해.","e":"mandón은 mandar(명령하다)에서 나온 말로 '명령하길 좋아하는 사람, 우두머리 행세하는 사람'입니다. -ón 접미사는 어떤 행동을 지나치게 하는 사람을 나타냅니다(contestón 말대꾸하는 사람, preguntón 질문 많은 사람).","x":["perdedor: 패배자 → 명령하는 성격과 무관 ✗","mandón: 명령하길 좋아하는 사람 → 정답 ✓","contestón: 말대꾸를 잘하는 사람 → 명령과는 다른 성격 ✗","preguntón: 질문을 많이 하는 사람 → 명령과 무관 ✗"]},{"id":"V331","q":"Cuando no entiendo muchas palabras en inglés, me siento ____.","o":["genial","frustrado","orgulloso","estupendamente"],"a":1,"k":"감정 형용사","t":"영어 단어를 많이 이해하지 못하면 나는 좌절감을 느낀다.","e":"frustrado(여성형 frustrada)는 '좌절한, 답답한'이라는 뜻입니다. 단어를 이해하지 못하는 부정적인 상황에서 느끼는 감정이므로 정답입니다. sentirse + 형용사는 '~하게 느끼다'라는 구조입니다.","x":["genial: 아주 좋은 → 부정적인 상황과 맞지 않음 ✗","frustrado: 좌절한, 답답한 → 이해 못 할 때의 감정으로 정답 ✓","orgulloso: 자랑스러운 → 문맥과 반대 ✗","estupendamente: 아주 잘(부사) → 의미가 반대이고 형용사 자리에도 어색함 ✗"]},{"id":"V332","q":"No puedo pagar tanto. ¿Hay algo más ____?","o":["bonito","original","especial","económico"],"a":3,"k":"쇼핑 어휘","t":"그렇게 많이는 못 내요. 더 저렴한 것이 있나요?","e":"económico는 '경제적인, 값이 싼'이라는 뜻입니다. 너무 비싸서 돈을 많이 낼 수 없다는 상황이므로 '더 싼 것'을 찾는 것이 자연스럽습니다. barato(싼)와 비슷하지만 좀 더 정중한 느낌입니다.","x":["bonito: 예쁜 → 가격 문제와 무관 ✗","original: 독창적인 → 가격 문제와 무관 ✗","especial: 특별한 → 오히려 비쌀 수 있어 문맥과 맞지 않음 ✗","económico: 저렴한, 경제적인 → 가격 문제의 해결책으로 정답 ✓"]},{"id":"V333","q":"El corredor terminó ____ en tiempo récord.","o":["el movimiento","el salto","el paseo","la carrera"],"a":3,"k":"스포츠 어휘","t":"그 주자는 기록적인 시간에 경주를 마쳤다.","e":"carrera는 '달리기 경주, 레이스'입니다. 달리는 사람(corredor)이 마치는 것은 경주이므로 정답입니다. carrera는 '대학 전공, 경력'이라는 뜻도 있습니다(Estudio la carrera de Medicina 의학을 전공한다).","x":["el movimiento: 움직임 → 주자가 '움직임을 마치다'는 어색함 ✗","el salto: 점프 → 주자(달리기 선수)와 맞지 않음 ✗","el paseo: 산책 → 기록을 재는 활동이 아님 ✗","la carrera: 경주, 레이스 → 주자가 마치는 것으로 정답 ✓"]},{"id":"V334","q":"El ____ nos despertó esta mañana con su canto.","o":["cangrejo","gallo","escarabajo","escorpión"],"a":1,"k":"동물 어휘","t":"오늘 아침 수탉이 울어서 우리를 깨웠다.","e":"gallo는 '수탉'으로, 아침에 우는 동물로 유명합니다. 수탉의 울음은 canto(노래)라고 표현합니다. 암탉은 gallina, 병아리는 pollito입니다.","x":["cangrejo: 게 → 울지 않음 ✗","gallo: 수탉 → 아침에 울어 깨우는 동물로 정답 ✓","escarabajo: 딱정벌레 → 울어서 깨우지 않음 ✗","escorpión: 전갈 → 울지 않음 ✗"]},{"id":"V335","q":"Tienes los labios ____, deberías hidratarlos más a menudo.","o":["secos","perfectos","rojos","finos"],"a":0,"k":"신체 묘사 어휘","t":"입술이 건조하구나. 더 자주 보습을 해 주는 게 좋겠어.","e":"seco(여성형 seca)는 '마른, 건조한'이라는 뜻입니다. 보습하라(hidratarlos)는 조언과 어울리는 상태는 secos뿐입니다. labios가 남성 복수라 secos로 맞춥니다.","x":["secos: 건조한 → 보습이 필요한 상태로 정답 ✓","perfectos: 완벽한 → 보습하라는 조언과 맞지 않음 ✗","rojos: 빨간 → 보습과 직접 관계없음 ✗","finos: 얇은 → 보습으로 해결되는 문제가 아님 ✗"]},{"id":"V336","q":"Si no quieres mancharte la ropa al cocinar, ponte este ____.","o":["delantal","abrigo","pijama","camisón"],"a":0,"k":"의류 어휘","t":"요리할 때 옷을 더럽히고 싶지 않으면 이 앞치마를 둘러.","e":"delantal은 '앞치마'입니다. 요리할 때 옷에 얼룩이 묻지 않도록 두르는 것이므로 정답입니다. mancharse는 '(자기 몸·옷이) 더러워지다, 얼룩지다'라는 뜻입니다.","x":["delantal: 앞치마 → 요리할 때 옷을 보호하므로 정답 ✓","abrigo: 외투, 코트 → 요리할 때 입지 않음 ✗","pijama: 잠옷 → 옷을 보호하는 용도가 아님 ✗","camisón: (여성용) 잠옷 → 요리와 무관 ✗"]},{"id":"V337","q":"No me ____ el barrio en el que vivía, por eso me mudé a otro.","o":["molestaba","preocupaba","gustaba","desagradaba"],"a":2,"k":"감정 동사","t":"살던 동네가 마음에 들지 않아서 다른 곳으로 이사했다.","e":"gustar(마음에 들다)는 '좋아하는 대상'이 주어입니다. '동네가 마음에 들지 않았다 → 그래서 이사했다'라는 흐름이 자연스럽습니다. molestar나 preocupar를 넣으면 '거슬리지 않았다/걱정되지 않았다'가 되어 이사할 이유가 없어집니다.","x":["molestaba: 거슬리게 하다 → 'no me molestaba'면 이사할 이유가 없음 ✗","preocupaba: 걱정시키다 → 걱정되지 않았다면 이사할 이유가 없음 ✗","gustaba: 마음에 들다 → 마음에 들지 않아 이사했다로 정답 ✓","desagradaba: 불쾌하게 하다 → 'no me desagradaba'면 불만이 없다는 뜻이라 모순 ✗"]},{"id":"V338","q":"Vivo en un pueblo ____, está lejos de todo.","o":["extendido","aislado","desarrollado","deshabitado"],"a":1,"k":"장소 형용사","t":"나는 고립된 마을에 살아. 모든 곳에서 멀리 떨어져 있어.","e":"aislado는 '고립된, 외딴'이라는 뜻입니다. '모든 곳에서 멀다'는 설명과 정확히 맞습니다. aislar(고립시키다, 격리하다)에서 나온 말입니다.","x":["extendido: 넓게 퍼진 → 멀리 떨어져 있다는 의미가 아님 ✗","aislado: 고립된, 외딴 → 모든 곳에서 멀다는 설명과 일치하여 정답 ✓","desarrollado: 발전된 → 멀리 떨어진 것과 무관 ✗","deshabitado: 사람이 살지 않는 → 내가 살고 있으므로 모순 ✗"]},{"id":"V339","q":"El médico me preguntó si ____ fiebre.","o":["daba","hacía","ponía","tenía"],"a":3,"k":"동사 연어","t":"의사가 나에게 열이 있는지 물었다.","e":"tener fiebre는 '열이 있다'라는 고정 표현입니다. 스페인어에서는 신체 증상을 tener로 표현합니다(tener tos 기침이 나다, tener dolor de cabeza 머리가 아프다). 과거의 질문을 전하는 간접화법이라 불완료과거 tenía를 씁니다.","x":["daba: dar(주다) → fiebre와 함께 '열이 있다'로 쓰지 않음 ✗","hacía: hacer(하다) → hacer fiebre는 쓰지 않음 ✗","ponía: poner(놓다) → 열이 있다는 뜻이 되지 않음 ✗","tenía: tener fiebre(열이 있다) → 정답 ✓"]},{"id":"V340","q":"Ese niño no respeta a nadie, es un ____.","o":["cielo","maleducado","despistado","ángel"],"a":1,"k":"성격 명사","t":"저 아이는 아무도 존중하지 않아. 버릇없는 아이야.","e":"maleducado는 '버릇없는, 예의 없는 (사람)'입니다. mal(나쁘게) + educado(교육받은)로 이루어진 말로, 아무도 존중하지 않는다는 설명과 맞습니다. 반대말은 educado(예의 바른)입니다.","x":["cielo: 하늘, (애칭) 천사 같은 사람 → 칭찬하는 말이라 반대 ✗","maleducado: 버릇없는 사람 → 존중하지 않는 행동과 일치하여 정답 ✓","despistado: 덜렁이 → 존중과 관계없음 ✗","ángel: 천사(착한 아이) → 문맥과 반대 ✗"]},{"id":"V341","q":"Esperamos con muchas ganas la ____ de nuestro primer hijo, que nacerá en marzo.","o":["salida","llegada","partida","entrada"],"a":1,"k":"명사 어휘","t":"3월에 태어날 우리 첫아이가 오기를 손꼽아 기다리고 있어.","e":"llegada는 '도착, 옴'이라는 뜻으로, 아기가 태어나는 것을 la llegada de un bebé(아기의 탄생, 아기가 찾아옴)라고 자주 표현합니다. esperar con muchas ganas는 '몹시 기대하며 기다리다'입니다.","x":["salida: 출발, 출구 → 아기의 탄생에 쓰지 않음 ✗","llegada: 도착, 옴 → 아기가 찾아옴(탄생)으로 정답 ✓","partida: 출발, 떠남 → 탄생과 반대 의미 ✗","entrada: 입구, 입장 → 탄생에 쓰지 않음 ✗"]},{"id":"V342","q":"Lo ____, no te hice daño a propósito.","o":["noto","percibo","aprecio","siento"],"a":3,"k":"사과 표현","t":"미안해. 일부러 너를 아프게 한 게 아니야.","e":"Lo siento는 '미안합니다, 유감입니다'라는 대표적인 사과 표현입니다. sentir는 '느끼다'라는 뜻이지만 lo siento로 쓰면 사과가 됩니다. a propósito는 '일부러'라는 뜻입니다.","x":["noto: notar(알아차리다) → 사과 표현이 아님 ✗","percibo: percibir(지각하다) → 사과 표현이 아님 ✗","aprecio: apreciar(높이 평가하다, 고마워하다) → 사과가 아님 ✗","siento: Lo siento(미안해) → 사과 표현으로 정답 ✓"]},{"id":"V343","q":"Los girasoles tienen un bonito color ____.","o":["lila","morado","amarillo","fucsia"],"a":2,"k":"색깔 어휘","t":"해바라기는 예쁜 노란색을 띤다.","e":"amarillo는 '노란색'으로, 해바라기(girasol)의 대표 색입니다. 색깔 형용사가 color를 꾸밀 때는 남성 단수 그대로 씁니다(un color amarillo).","x":["lila: 연보라색, 라일락색 → 해바라기 색이 아님 ✗","morado: 보라색 → 해바라기 색이 아님 ✗","amarillo: 노란색 → 해바라기 색으로 정답 ✓","fucsia: 자홍색, 진분홍 → 해바라기 색이 아님 ✗"]},{"id":"V344","q":"La ____ que menos me gusta es el cordero.","o":["fruta","verdura","pasta","carne"],"a":3,"k":"음식 어휘","t":"내가 가장 싫어하는 고기는 양고기야.","e":"cordero는 '어린 양, 양고기'이므로 carne(고기)의 한 종류입니다. 그래서 '가장 덜 좋아하는 고기'가 됩니다. 다른 고기 종류로 cerdo(돼지고기), ternera(송아지고기), pollo(닭고기)가 있습니다.","x":["fruta: 과일 → 양고기는 과일이 아님 ✗","verdura: 채소 → 양고기는 채소가 아님 ✗","pasta: 파스타 → 양고기와 무관 ✗","carne: 고기 → 양고기는 고기의 한 종류로 정답 ✓"]},{"id":"V345","q":"La ____ me dijo que mi gato está muy sano.","o":["camarera","veterinaria","vendedora","mesera"],"a":1,"k":"직업 어휘","t":"수의사 선생님이 우리 고양이가 아주 건강하다고 말해 줬어.","e":"veterinaria(남성형 veterinario)는 '수의사'입니다. 동물(고양이)의 건강 상태를 판단하는 사람이므로 정답입니다. 동물 병원은 clínica veterinaria라고 합니다.","x":["camarera: 웨이트리스 → 동물 건강과 무관 ✗","veterinaria: 수의사 → 고양이의 건강을 진단하므로 정답 ✓","vendedora: 판매원 → 건강을 진단하지 않음 ✗","mesera: (중남미) 웨이트리스 → 동물 건강과 무관 ✗"]},{"id":"V346","q":"Esta casa es demasiado antigua, deberían ____.","o":["pintarla","reformarla","ordenarla","limpiarla"],"a":1,"k":"주거 동사","t":"이 집은 너무 오래돼서 리모델링을 해야 할 거야.","e":"reformar는 '(건물을) 개조하다, 리모델링하다'라는 뜻입니다. 집이 너무 낡았다면 전체적으로 고쳐야 하므로 reformarla가 가장 알맞습니다. la는 casa를 받는 직접목적격 대명사입니다.","x":["pintarla: 그것을 칠하다 → 오래된 집 문제를 해결하기엔 부족함 ✗","reformarla: 그것을 개조하다 → 낡은 집을 리모델링하다로 정답 ✓","ordenarla: 그것을 정리하다 → 오래된 것과 관계없음 ✗","limpiarla: 그것을 청소하다 → 오래된 것을 해결하지 못함 ✗"]},{"id":"V347","q":"Fue una ____ increíble, había muchos tipos de carne.","o":["jornada","excursión","barbacoa","gira"],"a":2,"k":"여가 어휘","t":"정말 대단한 바비큐 파티였어. 고기 종류가 아주 많았어.","e":"barbacoa는 '바비큐, 바비큐 파티'입니다. 다양한 고기가 있었다는 설명과 잘 어울립니다. 중남미에서는 asado(아르헨티나·칠레 등)라는 말도 많이 씁니다.","x":["jornada: 하루, 근무일 → 고기와 직접 관계없음 ✗","excursión: 소풍, 견학 → 고기 종류와 직접 연결되지 않음 ✗","barbacoa: 바비큐 → 여러 종류의 고기와 일치하여 정답 ✓","gira: 순회공연, 투어 → 고기와 관계없음 ✗"]},{"id":"V348","q":"Si no pagamos la ____ de la luz, no tendremos electricidad.","o":["hoja","factura","entrada","nota"],"a":1,"k":"생활 어휘","t":"전기 요금 고지서를 내지 않으면 전기가 끊길 거야.","e":"factura는 '청구서, 요금 고지서, 영수증'입니다. la factura de la luz는 '전기 요금 고지서'라는 고정 표현입니다(스페인에서는 전기를 luz라고 자주 부름). pagar la factura(요금을 내다)도 함께 기억하세요.","x":["hoja: 종이 한 장, 잎 → 요금과 무관 ✗","factura: 청구서, 고지서 → la factura de la luz로 정답 ✓","entrada: 입장권, 입구 → 전기 요금과 무관 ✗","nota: 메모, 점수 → 전기 요금 고지서가 아님 ✗"]},{"id":"V349","q":"No debe beber alcohol mientras siga este ____ médico.","o":["historial","tratamiento","chequeo","informe"],"a":1,"k":"의료 어휘","t":"이 치료를 받는 동안에는 술을 마시면 안 됩니다.","e":"tratamiento는 '치료, 치료 과정'입니다. seguir un tratamiento는 '치료를 받다(치료를 계속하다)'라는 표현으로, 약을 먹는 기간 동안 술을 피하라는 내용과 맞습니다.","x":["historial: 병력 기록 → '따르다(seguir)'의 대상이 아님 ✗","tratamiento: 치료 → seguir un tratamiento(치료를 받다)로 정답 ✓","chequeo: 건강 검진 → 일시적인 검사라 '계속하는 동안'과 맞지 않음 ✗","informe: 보고서, 소견서 → 따르는 치료가 아님 ✗"]},{"id":"V350","q":"Era una noticia tan ____ que al principio nadie creía que fuera cierta.","o":["ordinaria","habitual","impactante","conocida"],"a":2,"k":"평가 형용사","t":"너무 충격적인 소식이라 처음에는 아무도 사실이라고 믿지 않았다.","e":"impactante는 '충격적인, 강한 인상을 주는'이라는 뜻입니다. tan ~ que...는 '너무 ~해서 ...하다'라는 구조로, 아무도 믿지 못할 만한 소식이므로 impactante가 맞습니다.","x":["ordinaria: 평범한 → 믿지 못할 이유가 없음 ✗","habitual: 흔한, 일상적인 → 믿지 못할 이유가 없음 ✗","impactante: 충격적인 → 믿기지 않는 소식으로 정답 ✓","conocida: 잘 알려진 → 믿지 못할 소식과 반대 ✗"]},{"id":"V351","q":"¿De qué ____ quieres tu helado? ¿De vainilla o de fresa?","o":["forma","color","sabor","tamaño"],"a":2,"k":"음식 어휘","t":"아이스크림 무슨 맛으로 할래? 바닐라 아니면 딸기?","e":"sabor는 '맛'입니다. 바닐라·딸기는 아이스크림의 맛이므로 정답입니다. ¿De qué sabor...?(무슨 맛의...?)는 아이스크림 가게에서 자주 듣는 표현입니다.","x":["forma: 모양 → 바닐라·딸기는 모양이 아님 ✗","color: 색깔 → 바닐라·딸기는 맛을 묻는 답 ✗","sabor: 맛 → 바닐라·딸기 맛으로 정답 ✓","tamaño: 크기 → 질문의 답과 맞지 않음 ✗"]},{"id":"V352","q":"Antes de pasar el control de seguridad del aeropuerto, tenemos que ____ el equipaje.","o":["esconder","traspasar","facturar","devolver"],"a":2,"k":"여행 어휘","t":"공항 보안 검색대를 통과하기 전에 짐을 부쳐야 한다.","e":"facturar el equipaje는 공항에서 '짐을 부치다(수하물로 맡기다)'라는 뜻입니다. facturar는 원래 '청구서를 발행하다'라는 뜻이지만 공항에서는 이렇게 씁니다. 체크인 카운터는 mostrador de facturación이라고 합니다.","x":["esconder: 숨기다 → 보안 검색 전에 짐을 숨기는 것은 어색함 ✗","traspasar: 통과시키다, 넘기다 → 수하물 절차를 나타내지 않음 ✗","facturar: (짐을) 부치다 → 공항 절차로 정답 ✓","devolver: 돌려주다 → 문맥과 맞지 않음 ✗"]},{"id":"V353","q":"Las temperaturas ____ ayer notablemente. Pasaron de 15 a 28 grados centígrados.","o":["subieron","disminuyeron","permanecieron","bajaron"],"a":0,"k":"변화 동사","t":"어제 기온이 눈에 띄게 올랐다. 섭씨 15도에서 28도가 되었다.","e":"subir는 '오르다, 올라가다'라는 뜻입니다. 15도에서 28도로 높아졌으므로 subieron(올랐다)이 맞습니다. 반대로 내려가면 bajar 또는 disminuir를 씁니다.","x":["subieron: 올랐다 → 15도에서 28도로 상승하여 정답 ✓","disminuyeron: 줄었다 → 기온이 올랐으므로 반대 ✗","permanecieron: 그대로 유지되었다 → 기온이 변했으므로 틀림 ✗","bajaron: 내려갔다 → 기온이 올랐으므로 반대 ✗"]},{"id":"V354","q":"Sólo estaremos en Valencia hoy, así que vamos a sacar un billete de ida y ____.","o":["venida","vuelta","llegada","salida"],"a":1,"k":"여행 어휘","t":"오늘 하루만 발렌시아에 있을 거니까 왕복표를 사자.","e":"billete de ida y vuelta는 '왕복표'라는 고정 표현입니다. ida는 '가는 것', vuelta는 '돌아오는 것'입니다. 편도표는 billete de ida(또는 billete sencillo)라고 합니다. 중남미에서는 billete 대신 boleto를 많이 씁니다.","x":["venida: 오는 것 → ida y venida는 '왕래'라는 뜻이라 표에 쓰지 않음 ✗","vuelta: 돌아옴 → ida y vuelta(왕복)로 정답 ✓","llegada: 도착 → 표 이름에 쓰지 않음 ✗","salida: 출발 → 표 이름에 쓰지 않음 ✗"]},{"id":"V355","q":"Desde que ____ más, tienes mejor aspecto.","o":["te irritas","te estresas","te cuidas","te alteras"],"a":2,"k":"재귀 동사","t":"네가 몸 관리를 더 하게 된 뒤로 얼굴이 좋아 보여.","e":"cuidarse는 '자기 자신을 돌보다, 건강을 관리하다'라는 재귀동사(자기 자신에게 행동이 돌아가는 동사)입니다. 더 좋아 보이는 원인으로 자연스럽습니다. desde que는 '~한 이후로'라는 뜻입니다.","x":["te irritas: 짜증을 내다 → 좋아 보이는 원인이 아님 ✗","te estresas: 스트레스를 받다 → 좋아 보이는 원인이 아님 ✗","te cuidas: 몸 관리를 하다 → 좋아 보이는 원인으로 정답 ✓","te alteras: 흥분하다, 동요하다 → 좋아 보이는 원인이 아님 ✗"]},{"id":"V356","q":"No tienes que ____ nada para hacer ese curso. Es totalmente gratuito.","o":["apuntar","proponer","pagar","probar"],"a":2,"k":"동사 어휘","t":"그 강좌를 들으려고 아무것도 낼 필요 없어. 완전히 무료야.","e":"pagar는 '(돈을) 내다, 지불하다'라는 뜻입니다. 강좌가 무료(gratuito)라는 설명이 뒤따르므로 '아무것도 낼 필요가 없다'가 자연스럽습니다. no tener que + 동사원형은 '~할 필요가 없다'입니다.","x":["apuntar: 적다, (재귀형) 등록하다 → 무료라는 설명과 연결되지 않음 ✗","proponer: 제안하다 → 무료와 관계없음 ✗","pagar: 지불하다 → 무료라서 낼 필요가 없다로 정답 ✓","probar: 시도하다, 맛보다 → 무료와 관계없음 ✗"]},{"id":"V357","q":"Antes compraba el periódico en ____, pero ya no lo hago porque leo la versión digital.","o":["el quiosco","el centro de salud","la pastelería","la academia"],"a":0,"k":"장소 어휘","t":"예전에는 가판대에서 신문을 샀지만, 지금은 디지털판을 읽어서 더 이상 그러지 않아.","e":"quiosco는 거리에서 신문·잡지 등을 파는 '가판대, 키오스크'입니다. 신문을 사는 곳으로 가장 알맞습니다. kiosco로 쓰기도 합니다.","x":["el quiosco: 가판대 → 신문을 파는 곳으로 정답 ✓","el centro de salud: 보건소 → 신문을 사는 곳이 아님 ✗","la pastelería: 제과점 → 신문을 팔지 않음 ✗","la academia: 학원 → 신문을 파는 곳이 아님 ✗"]},{"id":"V358","q":"La ventana de mi cocina ____ a un bonito jardín.","o":["hace","da","sale","entra"],"a":1,"k":"동사 관용 표현","t":"우리 부엌 창문은 예쁜 정원 쪽으로 나 있다.","e":"dar a는 창문·문·방이 '~쪽으로 나 있다, ~을 향하다'라는 관용 표현입니다. 예: Mi habitación da a la calle.(내 방은 길 쪽으로 나 있다.) dar의 특별한 쓰임을 기억해 두세요.","x":["hace: hacer a는 이런 뜻이 없음 ✗","da: dar a(~쪽으로 나 있다) → 정답 ✓","sale: salir a(~로 나가다) → 창문 방향 표현이 아님 ✗","entra: entrar a(~에 들어가다) → 창문 방향 표현이 아님 ✗"]},{"id":"V359","q":"No tengo ningún plan para el fin de semana, quiero ____ en casa.","o":["sentarme","portarme","quedarme","tumbarme"],"a":2,"k":"재귀 동사","t":"주말에 아무 계획이 없어. 집에 있고 싶어.","e":"quedarse는 '(어떤 장소에) 머무르다, 남아 있다'라는 뜻입니다. quedarse en casa(집에 있다)는 아주 자주 쓰는 표현으로, 계획이 없다는 문맥과 맞습니다.","x":["sentarme: 앉다 → 'en casa'와 함께 계획을 말하기엔 어색함 ✗","portarme: 행동하다(처신하다) → portarse bien/mal 형태로 쓰며 맞지 않음 ✗","quedarme: 머무르다 → quedarse en casa(집에 있다)로 정답 ✓","tumbarme: 눕다 → 'en casa'와의 연결이 자연스럽지 않음 ✗"]},{"id":"V360","q":"Me encanta desayunar pan recién ____ con mantequilla y mermelada.","o":["puesto","hecho","dicho","visto"],"a":1,"k":"과거분사 표현","t":"나는 갓 구운 빵에 버터와 잼을 발라 아침으로 먹는 것을 정말 좋아해.","e":"recién hecho는 '갓 만든'이라는 뜻으로, 빵에 쓰면 '갓 구운'이 됩니다. hecho는 hacer(만들다)의 불규칙 과거분사입니다. 예: café recién hecho(갓 내린 커피).","x":["puesto: poner(놓다)의 과거분사 → '갓 놓은 빵'은 어색함 ✗","hecho: hacer(만들다)의 과거분사 → pan recién hecho(갓 구운 빵)로 정답 ✓","dicho: decir(말하다)의 과거분사 → 빵과 무관 ✗","visto: ver(보다)의 과거분사 → 빵과 무관 ✗"]},{"id":"V361","q":"Luisa es una periodista ____, lleva más de veinte años en el mundo del periodismo.","o":["recomendada","desanimada","experimentada","asombrada"],"a":2,"k":"경력 형용사","t":"루이사는 경험 많은 기자로, 언론계에 20년 넘게 몸담아 왔다.","e":"experimentada(남성형 experimentado)는 '경험이 많은, 노련한'이라는 뜻입니다. 20년 넘게 일했다는 설명과 정확히 맞습니다. llevar + 기간 + en은 '~에서 (얼마 동안) 지내 오다'라는 표현입니다.","x":["recomendada: 추천받은 → 20년 경력과 직접 연결되지 않음 ✗","desanimada: 의욕을 잃은 → 경력 설명과 맞지 않음 ✗","experimentada: 경험 많은, 노련한 → 20년 경력과 일치하여 정답 ✓","asombrada: 놀란 → 경력과 무관 ✗"]},{"id":"V362","q":"Le dejé dinero a mi sobrino y todavía no me lo ____.","o":["ha pedido","ha exigido","ha prestado","ha devuelto"],"a":3,"k":"동사 어휘","t":"조카에게 돈을 빌려줬는데 아직 돌려주지 않았어.","e":"devolver는 '돌려주다, 반납하다'라는 뜻입니다. 돈을 빌려줬는데(dejé dinero) '아직 돌려주지 않았다'가 자연스러운 흐름입니다. ha devuelto는 현재완료로 '지금까지 ~했다'를 나타내며, devuelto는 불규칙 과거분사입니다.","x":["ha pedido: 요청했다 → 돈을 빌린 쪽이 요청하지 않았다는 것은 어색함 ✗","ha exigido: 요구했다 → 문맥과 맞지 않음 ✗","ha prestado: 빌려줬다 → 빌려준 사람은 나이므로 틀림 ✗","ha devuelto: 돌려줬다 → 아직 돌려주지 않았다로 정답 ✓"]},{"id":"V363","q":"¿Me prestas 10 euros? Te los ____ mañana.","o":["devuelvo","cambio","vuelvo","pago"],"a":0,"k":"동사 어휘","t":"10유로 빌려줄래? 내일 돌려줄게.","e":"devolver는 '(빌린 것을) 돌려주다'입니다. Te los devuelvo의 te는 '너에게', los는 '그것들(10유로)을'입니다. 가까운 미래도 현재형으로 말할 수 있습니다. vuelvo는 volver(돌아오다)라서 물건을 돌려줄 때는 쓰지 않습니다.","x":["devuelvo: 돌려준다 → 빌린 돈을 돌려주다로 정답 ✓","cambio: 바꾼다, 환전한다 → 빌린 돈을 갚는 의미가 아님 ✗","vuelvo: 돌아온다 → 사람이 돌아오는 것이라 목적어를 받지 않음 ✗","pago: 지불한다 → 빌린 돈에는 devolver가 더 자연스러움 ✗"]},{"id":"V364","q":"No entiendo esta frase en ruso. ¿Puedes ____?","o":["traducirla","cambiarla","ordenarla","corregirla"],"a":0,"k":"동사 어휘","t":"이 러시아어 문장을 이해하지 못하겠어. 번역해 줄 수 있어?","e":"traducir는 '번역하다'라는 뜻입니다(현재형 traduzco, 과거형 traduje 불규칙). 외국어 문장을 이해하지 못할 때 부탁할 일로 가장 자연스럽습니다. la는 frase를 받는 직접목적격 대명사입니다.","x":["traducirla: 그것을 번역하다 → 정답 ✓","cambiarla: 그것을 바꾸다 → 이해를 돕지 못함 ✗","ordenarla: 그것을 정리하다(순서를 맞추다) → 문맥과 맞지 않음 ✗","corregirla: 그것을 고치다 → 이해하지 못하는 문제와 관계없음 ✗"]},{"id":"V365","q":"Para aprobar ese examen no ____ con leer un par de párrafos del libro, tienes que leerlo todo.","o":["basta","da","cuenta","coincide"],"a":0,"k":"동사 구문","t":"그 시험에 합격하려면 책의 단락 두어 개를 읽는 것으로는 충분하지 않아. 전부 읽어야 해.","e":"bastar con은 '~만으로 충분하다'라는 뜻입니다. no basta con + 동사원형은 '~하는 것만으로는 부족하다'가 됩니다. 예: Basta con una llamada.(전화 한 통이면 충분해.)","x":["basta: bastar con(~로 충분하다) → 정답 ✓","da: dar con은 '~을 찾아내다'라는 뜻이라 맞지 않음 ✗","cuenta: contar con은 '~을 믿다, 가지다'라는 뜻이라 맞지 않음 ✗","coincide: coincidir con은 '~와 일치하다'라는 뜻이라 맞지 않음 ✗"]},{"id":"V366","q":"No te la bebas, no es agua ____.","o":["fría","caliente","templada","pura"],"a":3,"k":"묘사 형용사","t":"그거 마시지 마. 깨끗한 물이 아니야.","e":"puro(여성형 pura)는 '순수한, 깨끗한, 섞인 것이 없는'이라는 뜻입니다. 마시지 말라는 경고의 이유로는 물이 깨끗하지 않다는 것이 자연스럽습니다. 마실 수 있는 물은 agua potable(식수)이라고도 합니다.","x":["fría: 차가운 → 차갑지 않다고 마시지 말라는 이유가 되지 않음 ✗","caliente: 뜨거운 → 뜨겁지 않다는 것은 마시지 말라는 이유가 아님 ✗","templada: 미지근한 → 마시지 말라는 이유가 아님 ✗","pura: 순수한, 깨끗한 → 깨끗하지 않아 마시면 안 된다로 정답 ✓"]},{"id":"V367","q":"Antonio Banderas primero ____ famoso en España y después en el resto del mundo.","o":["se puso","se convirtió","se quedó","se hizo"],"a":3,"k":"변화 동사","t":"안토니오 반데라스는 먼저 스페인에서 유명해지고 그다음 전 세계에서 유명해졌다.","e":"hacerse는 노력이나 과정을 거쳐 '~이 되다'라는 뜻으로, hacerse famoso(유명해지다)는 자주 쓰는 표현입니다. ponerse는 일시적인 감정·상태 변화(ponerse rojo 얼굴이 빨개지다), convertirse는 뒤에 en + 명사가 필요합니다.","x":["se puso: ponerse(일시적 상태 변화) → 유명해지는 과정에는 어색함 ✗","se convirtió: convertirse en + 명사(~로 변하다) → en이 없고 형용사와 쓰지 않음 ✗","se quedó: quedarse(결과로 ~하게 되다, quedarse ciego 눈이 멀다) → famoso와 쓰지 않음 ✗","se hizo: hacerse famoso(유명해지다) → 정답 ✓"]},{"id":"V368","q":"Le dolía tanto el ____ que le dijeron que necesitaba un collarín.","o":["pie","hombro","codo","cuello"],"a":3,"k":"신체 어휘","t":"그는 목이 너무 아파서 목 보호대가 필요하다는 말을 들었다.","e":"cuello는 '목'입니다. collarín은 목에 하는 '목 보호대, 깁스 칼라'이므로 목이 아플 때 필요합니다. 참고로 목구멍(목 안쪽)이 아플 때는 garganta를 씁니다(me duele la garganta).","x":["pie: 발 → 목 보호대와 무관 ✗","hombro: 어깨 → 목 보호대와 직접 관련 없음 ✗","codo: 팔꿈치 → 목 보호대와 무관 ✗","cuello: 목 → collarín(목 보호대)과 일치하여 정답 ✓"]},{"id":"V369","q":"Hoy no ____ nadie al trabajo, han venido todos.","o":["ha faltado","ha fallado","ha asistido","ha atendido"],"a":0,"k":"동사 어휘","t":"오늘은 아무도 결근하지 않았어. 모두 출근했어.","e":"faltar a는 '~에 빠지다, 결석/결근하다'라는 뜻입니다. no ha faltado nadie(아무도 빠지지 않았다)와 han venido todos(모두 왔다)가 같은 의미로 이어집니다.","x":["ha faltado: faltar al trabajo(결근하다) → 아무도 빠지지 않았다로 정답 ✓","ha fallado: 실패했다, 고장 났다 → 출근과 무관 ✗","ha asistido: 참석했다 → '아무도 참석 안 했다'가 되어 '모두 왔다'와 모순 ✗","ha atendido: 응대했다, 돌봤다 → 출근과 무관 ✗"]},{"id":"V370","q":"Si te acercas mucho al ____, te vas a quemar.","o":["mar","río","fuego","aire"],"a":2,"k":"자연 어휘","t":"불에 너무 가까이 가면 데일 거야.","e":"fuego는 '불'입니다. quemarse(데다, 화상을 입다)와 어울리는 것은 fuego뿐입니다. acercarse a는 '~에 다가가다'라는 재귀동사입니다.","x":["mar: 바다 → 가까이 간다고 데지 않음 ✗","río: 강 → 데는 원인이 아님 ✗","fuego: 불 → 가까이 가면 데므로 정답 ✓","aire: 공기 → 데는 원인이 아님 ✗"]},{"id":"V371","q":"Estos son los ____ que uso para ir al gimnasio.","o":["tacones","tenis","zuecos","botines"],"a":1,"k":"신발 어휘","t":"이게 내가 헬스장 갈 때 신는 운동화야.","e":"tenis는 '운동화'를 뜻합니다(스페인에서는 zapatillas de deporte도 많이 씀). 헬스장(gimnasio)에 신고 가는 신발로 가장 알맞습니다. tenis는 '테니스(운동)'라는 뜻도 있습니다.","x":["tacones: 하이힐 → 헬스장에 신지 않음 ✗","tenis: 운동화 → 헬스장에 신는 신발로 정답 ✓","zuecos: 나막신, 클로그 → 운동용이 아님 ✗","botines: 앵클부츠 → 운동용이 아님 ✗"]},{"id":"V372","q":"A mi hermana le gusta leer ____ de misterio.","o":["series","películas","novelas","programas"],"a":2,"k":"문학 어휘","t":"우리 언니는 추리 소설 읽는 것을 좋아해.","e":"leer(읽다)의 목적어가 될 수 있는 것은 novela(소설)입니다. novela de misterio는 '미스터리 소설, 추리 소설'입니다. series, películas, programas는 '보는(ver)' 것입니다.","x":["series: 드라마 시리즈 → 읽는 것이 아니라 보는 것 ✗","películas: 영화 → 보는 것 ✗","novelas: 소설 → 읽는 것으로 정답 ✓","programas: (방송) 프로그램 → 보는 것 ✗"]},{"id":"V373","q":"Estoy de tu parte, no soy tu ____.","o":["colega","amigo","aliado","enemigo"],"a":3,"k":"사람 관계 어휘","t":"나는 네 편이야. 너의 적이 아니야.","e":"enemigo는 '적'입니다. estar de tu parte(네 편이다)와 대조를 이루려면 '적이 아니다'가 와야 자연스럽습니다. 나머지 보기는 모두 '편'에 가까운 말이라 부정하면 앞 문장과 모순됩니다.","x":["colega: 동료 → 편이라면서 '동료가 아니다'는 모순 ✗","amigo: 친구 → 편이라면서 '친구가 아니다'는 모순 ✗","aliado: 동맹, 아군 → 편이라는 말과 모순 ✗","enemigo: 적 → 네 편이지 적이 아니다로 정답 ✓"]},{"id":"V374","q":"Vuestra casa es muy ____, está muy bien decorada.","o":["bonita","nueva","antigua","moderna"],"a":0,"k":"묘사 형용사","t":"너희 집은 정말 예쁘다. 장식이 아주 잘 되어 있어.","e":"bonita(남성형 bonito)는 '예쁜, 아름다운'입니다. 뒤에 '장식이 잘 되어 있다'는 설명이 따르므로, 장식과 직접 연결되는 평가인 bonita가 정답입니다. vuestra는 스페인에서 쓰는 vosotros(너희)의 소유형이고, 중남미에서는 su casa(ustedes)를 씁니다.","x":["bonita: 예쁜 → 장식이 잘 됐다는 설명과 일치하여 정답 ✓","nueva: 새로운 → 장식과 직접 관계없음 ✗","antigua: 오래된 → 장식과 직접 관계없음 ✗","moderna: 현대적인 → 장식 '잘 됨'의 근거로 보기 어려움 ✗"]},{"id":"V375","q":"No puedes viajar en avión sin ningún tipo de ____.","o":["declaración","descripción","documentación","compensación"],"a":2,"k":"여행 어휘","t":"어떤 종류의 신분 서류도 없이는 비행기를 탈 수 없다.","e":"documentación는 신분증·여권 같은 '서류, 신분 증명서'를 통틀어 이르는 말입니다. 비행기를 타려면 꼭 필요하므로 정답입니다. sin ningún tipo de는 '어떤 종류의 ~도 없이'라는 뜻입니다.","x":["declaración: 신고, 진술 → 탑승에 필수인 것이 아님 ✗","descripción: 묘사, 설명 → 의미가 맞지 않음 ✗","documentación: 신분 서류 → 비행기 탑승에 필요하여 정답 ✓","compensación: 보상 → 문맥과 무관 ✗"]},{"id":"V376","q":"Me gustaría estudiar en el ____, quiero vivir un tiempo fuera de mi país.","o":["extranjero","despacho","instituto","establecimiento"],"a":0,"k":"장소 어휘","t":"외국에서 공부하고 싶어. 한동안 내 나라 밖에서 살아 보고 싶거든.","e":"el extranjero는 '외국, 해외'라는 뜻입니다. estudiar en el extranjero(해외에서 공부하다, 유학하다)는 자주 쓰는 표현입니다. 사람을 가리키면 '외국인'이라는 뜻도 됩니다.","x":["extranjero: 외국, 해외 → 나라 밖에서 살고 싶다는 내용과 일치하여 정답 ✓","despacho: 사무실 → 나라 밖과 무관 ✗","instituto: (스페인) 중·고등학교 → 해외 생활과 직접 연결되지 않음 ✗","establecimiento: 시설, 업소 → 의미가 맞지 않음 ✗"]},{"id":"V377","q":"En los últimos años ____ el número de dispositivos electrónicos. Cada vez hay más.","o":["ha bajado","ha aumentado","ha compensado","se ha reducido"],"a":1,"k":"변화 동사","t":"최근 몇 년 동안 전자 기기의 수가 늘어났다. 점점 더 많아지고 있다.","e":"aumentar는 '늘다, 증가하다'라는 뜻입니다. cada vez hay más(점점 더 많아진다)라는 설명과 맞습니다. en los últimos años(최근 몇 년간)는 현재완료와 자주 함께 씁니다.","x":["ha bajado: 줄었다 → 점점 많아진다와 반대 ✗","ha aumentado: 늘었다 → 정답 ✓","ha compensado: 보상했다 → 의미가 맞지 않음 ✗","se ha reducido: 감소했다 → 문맥과 반대 ✗"]},{"id":"V378","q":"La famosa estrella del rock ____ una entrada triunfante en el programa.","o":["dio","actuó","puso","hizo"],"a":3,"k":"동사 연어","t":"그 유명한 록 스타가 프로그램에 화려하게 등장했다.","e":"hacer una entrada는 '(무대·장소에) 등장하다, 입장하다'라는 표현입니다. una entrada triunfal/triunfante(의기양양한 등장)와 함께 hacer를 씁니다. 같은 동사와 명사의 짝(연어)을 통째로 외워 두면 좋습니다.","x":["dio: dar → dar una entrada는 이 뜻으로 쓰지 않음 ✗","actuó: actuar(공연하다)는 자동사라 una entrada를 목적어로 받지 않음 ✗","puso: poner → poner una entrada는 '입장을 하다'라는 뜻이 아님 ✗","hizo: hacer una entrada(등장하다) → 정답 ✓"]},{"id":"V379","q":"En enero estamos en ____ en el hemisferio norte.","o":["otoño","verano","invierno","primavera"],"a":2,"k":"계절 어휘","t":"북반구에서 1월은 겨울이다.","e":"invierno는 '겨울'입니다. 북반구(hemisferio norte)에서 1월은 겨울이므로 정답입니다. 반대로 칠레·아르헨티나 같은 남반구에서는 1월이 여름(verano)입니다. estar en + 계절은 '~철이다'라는 표현입니다.","x":["otoño: 가을 → 1월이 아님 ✗","verano: 여름 → 남반구의 1월이라 틀림 ✗","invierno: 겨울 → 북반구의 1월로 정답 ✓","primavera: 봄 → 1월이 아님 ✗"]},{"id":"V380","q":"Elvira ha tenido un accidente de moto, por eso está en el ____.","o":["centro comercial","hospital","almacén","taller"],"a":1,"k":"장소 어휘","t":"엘비라는 오토바이 사고를 당해서 병원에 있다.","e":"hospital은 '병원'입니다. 사고(accidente)를 당한 결과로 있을 곳으로 가장 자연스럽습니다. por eso는 '그래서'라는 뜻으로 원인과 결과를 이어 줍니다.","x":["centro comercial: 쇼핑센터 → 사고 후 있을 곳이 아님 ✗","hospital: 병원 → 사고를 당한 사람이 있는 곳으로 정답 ✓","almacén: 창고 → 사고와 무관 ✗","taller: 정비소, 작업장 → 오토바이는 갈 수 있지만 사람(엘비라)이 있는 이유로는 어색함 ✗"]},{"id":"V381","q":"En el ____ de mi abuelo hay muchos árboles frutales.","o":["pozo","huerto","piso","carro"],"a":1,"k":"장소 어휘","t":"할아버지의 과수원에는 과일나무가 많다.","e":"huerto는 채소나 과일나무를 기르는 '텃밭, 과수원'입니다. 과일나무(árboles frutales)가 있는 곳으로 가장 알맞습니다. 비슷한 말로 huerta(넓은 농원)도 있습니다.","x":["pozo: 우물 → 나무가 있는 곳이 아님 ✗","huerto: 텃밭, 과수원 → 과일나무가 있는 곳으로 정답 ✓","piso: (스페인) 아파트, 층 → 과일나무가 많을 수 없음 ✗","carro: (중남미) 자동차, 수레 → 나무와 무관 ✗"]},{"id":"V382","q":"Me gustaría tener una casa con jardín para ____ mis propias verduras.","o":["echar","encontrar","cultivar","tirar"],"a":2,"k":"농사 동사","t":"내 채소를 직접 기를 수 있게 정원이 있는 집을 갖고 싶어.","e":"cultivar는 '재배하다, 기르다'라는 뜻입니다. cultivar verduras(채소를 재배하다)는 자연스러운 짝입니다. propio(자신의)는 mis propias verduras처럼 명사 앞에서 '직접 키운, 자기 소유의'라는 뜻을 더합니다.","x":["echar: 던지다, 붓다 → 채소를 기르는 뜻이 아님 ✗","encontrar: 찾다, 발견하다 → 정원이 필요한 이유가 되지 않음 ✗","cultivar: 재배하다 → 채소를 기르다로 정답 ✓","tirar: 버리다, 던지다 → 문맥과 반대 ✗"]},{"id":"V383","q":"Nadie entendió sus argumentos porque no eran ____.","o":["coherentes","incoherentes","ilógicos","irracionales"],"a":0,"k":"논리 형용사","t":"그의 주장은 앞뒤가 맞지 않아서 아무도 이해하지 못했다.","e":"coherente는 '일관성 있는, 앞뒤가 맞는'이라는 뜻입니다. no eran coherentes(일관성이 없었다)는 아무도 이해하지 못한 이유로 맞습니다. 나머지 보기는 이미 부정적인 뜻이라 no와 함께 쓰면 '논리적이었다'가 되어 버립니다.","x":["coherentes: 일관성 있는 → 일관성이 없어서 이해 못 했다로 정답 ✓","incoherentes: 일관성 없는 → no와 함께면 '일관성이 있었다'가 되어 모순 ✗","ilógicos: 비논리적인 → no와 함께면 '논리적이었다'가 되어 모순 ✗","irracionales: 비이성적인 → no와 함께면 이해 못 할 이유가 없어짐 ✗"]},{"id":"V384","q":"Aquel día todos lo pasamos muy bien, fue una experiencia ____.","o":["terrible","inolvidable","irrelevante","desagradable"],"a":1,"k":"평가 형용사","t":"그날 우리 모두 정말 즐거웠어. 잊지 못할 경험이었어.","e":"inolvidable은 '잊을 수 없는'이라는 뜻으로 olvidar(잊다)에 in-(부정) + -able(~할 수 있는)이 붙은 말입니다. 모두 즐거웠다(lo pasamos muy bien)는 긍정적 내용과 어울립니다.","x":["terrible: 끔찍한 → 즐거웠다는 내용과 반대 ✗","inolvidable: 잊지 못할 → 즐거운 경험으로 정답 ✓","irrelevante: 중요하지 않은 → 즐거웠던 경험과 맞지 않음 ✗","desagradable: 불쾌한 → 문맥과 반대 ✗"]},{"id":"V385","q":"Estos ____ son una delicia. Son los favoritos de mis hermanos.","o":["bolsos","bombones","botines","botones"],"a":1,"k":"음식 어휘","t":"이 초콜릿 봉봉들은 정말 맛있어. 우리 형제들이 제일 좋아하는 거야.","e":"bombón은 속에 크림 등이 든 '한 입 크기 초콜릿, 봉봉'입니다(복수 bombones). una delicia(진미, 아주 맛있는 것)와 어울리는 것은 먹는 것뿐입니다. 비슷하게 생긴 단어(bolso, botín, botón)와 헷갈리지 않도록 주의하세요.","x":["bolsos: 핸드백 → 먹는 것이 아님 ✗","bombones: 초콜릿 봉봉 → 맛있는 간식으로 정답 ✓","botines: 앵클부츠 → 먹는 것이 아님 ✗","botones: 단추 → 먹는 것이 아님 ✗"]},{"id":"V386","q":"Casi nunca llueve en el ____.","o":["desierto","bosque","valle","mar"],"a":0,"k":"자연 지형 어휘","t":"사막에는 비가 거의 내리지 않는다.","e":"desierto는 '사막'으로, 비가 거의 오지 않는 건조한 지역입니다. casi nunca는 '거의 ~않다'라는 빈도 표현입니다. desierto는 형용사로 '인적 없는'이라는 뜻도 있습니다(una calle desierta 텅 빈 거리).","x":["desierto: 사막 → 비가 거의 안 오는 곳으로 정답 ✓","bosque: 숲 → 비가 자주 오는 편임 ✗","valle: 계곡, 골짜기 → 비와 특별한 관계가 없음 ✗","mar: 바다 → 비가 안 오는 곳의 대표가 아님 ✗"]},{"id":"V387","q":"En mi ____ de noche hay una lámpara y una caja de pañuelos.","o":["sillón","cama","sofá","mesita"],"a":3,"k":"가구 어휘","t":"내 침대 옆 협탁에는 스탠드 하나와 티슈 한 상자가 있다.","e":"mesita de noche는 침대 옆에 두는 작은 탁자, 즉 '협탁, 침대 옆 탁자'입니다. mesita는 mesa(탁자)의 축소형(작은 것을 나타내는 형태)입니다. de noche와 결합해 하나의 단어처럼 씁니다.","x":["sillón: 안락의자 → de noche와 결합하지 않음 ✗","cama: 침대 → cama de noche라는 표현은 없음 ✗","sofá: 소파 → de noche와 결합하지 않음 ✗","mesita: 작은 탁자 → mesita de noche(협탁)로 정답 ✓"]},{"id":"V388","q":"Julio es el ____ mes del año.","o":["sexto","octavo","décimo","séptimo"],"a":3,"k":"서수 어휘","t":"7월은 일 년 중 일곱 번째 달이다.","e":"서수(순서를 나타내는 수)는 primero, segundo, tercero, cuarto, quinto, sexto, séptimo, octavo, noveno, décimo입니다. 7월(julio)은 일곱 번째 달이므로 séptimo가 정답입니다.","x":["sexto: 여섯 번째 → 6월(junio)에 해당 ✗","octavo: 여덟 번째 → 8월(agosto)에 해당 ✗","décimo: 열 번째 → 10월(octubre)에 해당 ✗","séptimo: 일곱 번째 → 7월로 정답 ✓"]},{"id":"V389","q":"Para seguir conduciendo, debes echarle ____ al coche.","o":["gasolina","energía","alimento","líquido"],"a":0,"k":"자동차 어휘","t":"계속 운전하려면 차에 휘발유를 넣어야 해.","e":"gasolina는 '휘발유, 가솔린'입니다. echar gasolina는 '기름을 넣다, 주유하다'라는 자주 쓰는 표현입니다. 주유소는 gasolinera입니다. 중남미 일부(아르헨티나 등)에서는 nafta라고도 합니다.","x":["gasolina: 휘발유 → echar gasolina(주유하다)로 정답 ✓","energía: 에너지 → 차에 '넣는' 구체적 대상이 아님 ✗","alimento: 음식, 영양 → 차에 넣지 않음 ✗","líquido: 액체 → 너무 막연해서 맞지 않음 ✗"]},{"id":"V390","q":"Nadie me ____ qué hay que hacer en este ejercicio, por eso no lo hice.","o":["preguntó","expresó","explicó","contestó"],"a":2,"k":"동사 어휘","t":"아무도 이 연습 문제에서 뭘 해야 하는지 나에게 설명해 주지 않아서 안 했어.","e":"explicar는 '설명하다'입니다. explicar qué hay que hacer(무엇을 해야 하는지 설명하다)는 자연스러운 구조입니다. 설명을 듣지 못해서 하지 않았다는 이유가 됩니다.","x":["preguntó: 물었다 → 남이 나에게 물어보지 않은 것은 안 한 이유가 되지 않음 ✗","expresó: 표현했다 → 할 일을 '표현하다'는 어색함 ✗","explicó: 설명했다 → 설명해 주지 않아 못 했다로 정답 ✓","contestó: 대답했다 → 질문이 없었으므로 맞지 않음 ✗"]},{"id":"V391","q":"Las Olimpiadas de 1992 tuvieron ____ en Barcelona.","o":["espacio","lugar","sitio","situación"],"a":1,"k":"관용 표현","t":"1992년 올림픽은 바르셀로나에서 열렸다.","e":"tener lugar은 '(행사가) 열리다, 개최되다'라는 관용 표현입니다. lugar(장소)를 쓰지만 sitio나 espacio로 바꿀 수 없습니다. 예: La boda tendrá lugar en mayo.(결혼식은 5월에 열린다.)","x":["espacio: 공간 → tener espacio는 '공간이 있다'라는 뜻 ✗","lugar: tener lugar(개최되다) → 정답 ✓","sitio: 장소, 자리 → tener sitio는 '자리가 있다'라는 뜻 ✗","situación: 상황, 위치 → 관용 표현이 아님 ✗"]},{"id":"V392","q":"Mi abuelo tiene ____ años.","o":["noventainueve","noventa y nueve","noventa e nueve","noventa nueve"],"a":1,"k":"숫자 쓰기","t":"우리 할아버지는 아흔아홉 살이시다.","e":"31부터 99까지는 십의 자리와 일의 자리를 y로 이어 띄어 씁니다: treinta y uno, noventa y nueve. 16~29는 한 단어(dieciséis, veintinueve)로 쓰는 것과 구별하세요.","x":["noventainueve: 붙여 쓰지 않음, 30 이상은 띄어 씀 ✗","noventa y nueve: 올바른 표기 → 정답 ✓","noventa e nueve: e는 i/hi로 시작하는 단어 앞에서만 y 대신 씀 ✗","noventa nueve: 가운데 y가 빠짐 ✗"]},{"id":"V393","q":"En otoño se caen ____ de muchos árboles.","o":["las raíces","los troncos","las maderas","las hojas"],"a":3,"k":"자연 어휘","t":"가을이 되면 많은 나무에서 잎이 떨어진다.","e":"hoja는 '나뭇잎'입니다(종이 한 장이라는 뜻도 있음). 가을(otoño)에 나무에서 떨어지는 것은 잎이므로 정답입니다. caerse는 '떨어지다, 넘어지다'라는 뜻입니다.","x":["las raíces: 뿌리 → 땅속에 있어 떨어지지 않음 ✗","los troncos: 나무 줄기 → 가을에 떨어지지 않음 ✗","las maderas: 목재 → 나무에서 떨어지는 것이 아님 ✗","las hojas: 나뭇잎 → 가을에 떨어지므로 정답 ✓"]},{"id":"V394","q":"Para mí, el ____ más útil es el frigorífico.","o":["envase","contenedor","fregadero","electrodoméstico"],"a":3,"k":"가전제품 어휘","t":"나에게 가장 유용한 가전제품은 냉장고야.","e":"electrodoméstico는 '가전제품'입니다. 냉장고(frigorífico, 중남미에서는 refrigerador/heladera 등)는 가전제품의 한 종류이므로 정답입니다. 세탁기(lavadora), 전자레인지(microondas)도 electrodomésticos입니다.","x":["envase: 용기, 포장 → 냉장고를 가리키지 않음 ✗","contenedor: 컨테이너, 대형 쓰레기통 → 냉장고와 맞지 않음 ✗","fregadero: 싱크대(개수대) → 냉장고와 다른 물건 ✗","electrodoméstico: 가전제품 → 냉장고가 속하는 범주로 정답 ✓"]},{"id":"V395","q":"Sueño con tener una casa con ____ al mar.","o":["vistazos","vistas","visiones","vistos"],"a":1,"k":"주거 어휘","t":"바다가 보이는 집을 갖는 게 꿈이야.","e":"vistas는 '전망, 경치'라는 뜻으로, con vistas al mar는 '바다 전망이 있는'이라는 고정 표현입니다. 호텔이나 집 광고에서 자주 볼 수 있습니다. soñar con은 '~을 꿈꾸다'입니다.","x":["vistazos: 힐끗 봄 → echar un vistazo(한번 훑어보다)에 쓰는 말 ✗","vistas: 전망 → con vistas al mar(바다 전망)로 정답 ✓","visiones: 환상, 시력 → 전망을 나타내지 않음 ✗","vistos: ver의 과거분사 복수 → 명사로 쓰지 않음 ✗"]},{"id":"V396","q":"Esas píldoras sólo puedes comprarlas en una ____.","o":["farmacia","boutique","papelería","librería"],"a":0,"k":"상점 어휘","t":"그 알약은 약국에서만 살 수 있어.","e":"farmacia는 '약국'입니다. 알약(píldoras)을 파는 곳이므로 정답입니다. 약사는 farmacéutico/a라고 합니다.","x":["farmacia: 약국 → 약을 파는 곳으로 정답 ✓","boutique: 옷 가게 → 약을 팔지 않음 ✗","papelería: 문구점 → 약을 팔지 않음 ✗","librería: 서점 → 약을 팔지 않음 ✗"]},{"id":"V397","q":"Yo pienso que las tiendas deberían decidir su propio horario. ¿Y tú qué ____?","o":["ves","opinas","miras","necesitas"],"a":1,"k":"의견 표현","t":"내 생각엔 가게들이 영업시간을 스스로 정해야 할 것 같아. 너는 어떻게 생각해?","e":"opinar는 '의견을 갖다, 생각하다'라는 뜻입니다. ¿Y tú qué opinas?는 '너는 어떻게 생각해?'라고 상대방 의견을 물을 때 쓰는 표현입니다. ¿Qué piensas?도 같은 뜻으로 씁니다.","x":["ves: 보다 → ¿qué ves?는 '무엇이 보이니?'라는 뜻 ✗","opinas: 의견을 갖다 → 의견을 묻는 표현으로 정답 ✓","miras: 바라보다 → 의견을 묻지 않음 ✗","necesitas: 필요하다 → 의견을 묻지 않음 ✗"]},{"id":"V398","q":"La cocina de Rafa está bien ____, tiene todos los muebles y aparatos necesarios.","o":["equipada","construida","repartida","compartida"],"a":0,"k":"주거 형용사","t":"라파의 부엌은 설비가 잘 갖춰져 있어. 필요한 가구와 기기가 다 있어.","e":"equipado(여성형 equipada)는 '설비를 갖춘'이라는 뜻입니다. bien equipada(잘 갖춰진)는 모든 가구와 기기가 있다는 설명과 일치합니다. 부동산 광고에서 cocina equipada(설비 완비 주방)를 자주 볼 수 있습니다.","x":["equipada: 설비를 갖춘 → 모든 가구·기기가 있다는 설명과 일치하여 정답 ✓","construida: 지어진 → 가구·기기를 갖춘 것과 직접 관련 없음 ✗","repartida: 나누어진, 배분된 → 의미가 맞지 않음 ✗","compartida: 공유된 → 가구·기기 설명과 맞지 않음 ✗"]},{"id":"V399","q":"Aunque me llevé el paraguas, me mojé porque la lluvia era muy ____ y el viento soplaba fuerte.","o":["extensa","ligera","intensa","tensa"],"a":2,"k":"날씨 형용사","t":"우산을 가져갔지만 비가 아주 세차게 내리고 바람도 강하게 불어서 젖었다.","e":"intenso(여성형 intensa)는 '강한, 격렬한'이라는 뜻입니다. 우산을 썼는데도 젖은 이유이므로 비가 세찼다는 뜻의 intensa가 맞습니다. 반대로 약한 비는 lluvia ligera(가랑비)라고 합니다.","x":["extensa: 넓은, 광대한 → 비의 세기를 나타내지 않음 ✗","ligera: 가벼운, 약한 → 젖은 이유가 되지 않음 ✗","intensa: 강한, 세찬 → 우산을 써도 젖은 이유로 정답 ✓","tensa: 긴장된, 팽팽한 → 비에 쓰지 않음 ✗"]},{"id":"V400","q":"Deberías ser más optimista y ver la ____ medio llena, no medio vacía.","o":["botella","taza","jarra","copa"],"a":0,"k":"관용 표현","t":"너는 좀 더 낙관적이 되어서 병이 반이나 비었다고 보지 말고 반이나 찼다고 봐야 해.","e":"ver la botella medio llena(병이 반쯤 찼다고 보다)는 '긍정적으로 보다'라는 관용 표현입니다. 반대로 medio vacía(반쯤 빈)로 보면 비관적인 시각입니다. 스페인어에서는 이 표현에 botella(병)를 씁니다(vaso를 쓰기도 함).","x":["botella: 병 → 관용 표현 la botella medio llena로 정답 ✓","taza: 찻잔, 컵 → 이 관용 표현에 쓰지 않음 ✗","jarra: 주전자, 피처 → 관용 표현에 쓰지 않음 ✗","copa: 와인잔, 트로피 → 관용 표현에 쓰지 않음 ✗"]},{"id":"V401","q":"En un musical se unen ____ y la música.","o":["el teatro","la danza","la arquitectura","la literatura"],"a":0,"k":"예술 어휘","t":"뮤지컬에서는 연극과 음악이 하나로 합쳐진다.","e":"musical(뮤지컬)은 연극(teatro)에 노래와 음악을 결합한 공연입니다. 그래서 el teatro가 정답입니다. 춤도 나오지만 뮤지컬의 기본 형식은 무대에서 이야기를 연기하는 연극입니다.","x":["el teatro: 연극 → 뮤지컬은 연극과 음악의 결합으로 정답 ✓","la danza: 춤 → 일부 요소일 뿐 뮤지컬의 기본 형식은 아님 ✗","la arquitectura: 건축 → 뮤지컬과 무관 ✗","la literatura: 문학 → 뮤지컬을 이루는 핵심 요소가 아님 ✗"]},{"id":"V402","q":"Marisa quiere que le operen la nariz porque se siente ____.","o":["acomplejada","furiosa","esperanzada","hermosa"],"a":0,"k":"감정 형용사","t":"마리사는 콤플렉스가 있어서 코 수술을 받고 싶어 한다.","e":"acomplejado(여성형 acomplejada)는 '콤플렉스(열등감)를 느끼는'이라는 뜻입니다. complejo(콤플렉스)에서 나온 말로, 외모 때문에 수술을 원하는 이유로 알맞습니다. querer que + 접속법(operen)은 '~가 ~하기를 원하다'라는 구조입니다.","x":["acomplejada: 콤플렉스를 느끼는 → 코 수술을 원하는 이유로 정답 ✓","furiosa: 몹시 화난 → 수술을 원하는 이유와 맞지 않음 ✗","esperanzada: 희망에 찬 → 수술하려는 원인이 아님 ✗","hermosa: 아름다운 → 아름답다고 느끼면 수술할 이유가 없음 ✗"]},{"id":"V403","q":"El día antes del examen, haré un ____ general.","o":["ejemplo","repaso","reconocimiento","curso"],"a":1,"k":"학습 어휘","t":"시험 전날에 전체 복습을 할 거야.","e":"repaso는 '복습'이고, repasar는 '복습하다'입니다. hacer un repaso general(전체 복습을 하다)은 시험 준비 때 자주 쓰는 표현입니다.","x":["ejemplo: 예, 예시 → 시험 전날 할 일로 맞지 않음 ✗","repaso: 복습 → 시험 전날 전체 복습으로 정답 ✓","reconocimiento: 인정, 인식, 검진 → 시험 공부와 무관 ✗","curso: 강좌, 학년 → 하루 만에 하는 일이 아님 ✗"]},{"id":"V404","q":"Ha mentido, todo lo que ha dicho es ____.","o":["incierto","impactante","inseguro","improbable"],"a":0,"k":"사실 형용사","t":"그는 거짓말을 했어. 그가 한 말은 전부 사실이 아니야.","e":"incierto는 '사실이 아닌, 거짓의(또는 불확실한)'라는 뜻입니다. cierto(사실인)에 in-(부정)이 붙은 말이라 mentir(거짓말하다)와 어울립니다. Es cierto(그건 사실이야)도 함께 기억하세요.","x":["incierto: 사실이 아닌 → 거짓말한 내용으로 정답 ✓","impactante: 충격적인 → 거짓이라는 뜻이 아님 ✗","inseguro: 불안한, 안전하지 않은 → 말의 진위와 무관 ✗","improbable: 일어날 것 같지 않은 → 거짓이라는 뜻이 아님 ✗"]},{"id":"V405","q":"No olvides el ____, en la casa rural a la que vamos hay una piscina enorme.","o":["biquini","traje","pañuelo","chaleco"],"a":0,"k":"의류 어휘","t":"비키니 잊지 마. 우리가 갈 시골 별장에는 엄청 큰 수영장이 있어.","e":"biquini(bikini로도 씀)는 '비키니 수영복'입니다. 수영장(piscina)이 있다는 이유와 어울립니다. 일반 수영복은 bañador(스페인) 또는 traje de baño라고 합니다.","x":["biquini: 비키니 → 수영장에 필요한 것으로 정답 ✓","traje: 정장 → 단독으로는 수영복이 아님(traje de baño여야 함) ✗","pañuelo: 손수건, 스카프 → 수영장과 무관 ✗","chaleco: 조끼 → 수영장과 무관 ✗"]},{"id":"V406","q":"Mis padres viven en un bonito ____ con jardín y piscina.","o":["chalé","balcón","dormitorio","cuarto"],"a":0,"k":"주거 어휘","t":"부모님은 정원과 수영장이 있는 예쁜 단독 주택에 사신다.","e":"chalé(chalet로도 씀)는 정원이 딸린 '단독 주택, 별장식 주택'입니다. 정원과 수영장이 있는 집으로 가장 알맞습니다. 스페인에서는 아파트를 piso라고 합니다.","x":["chalé: 단독 주택 → 정원·수영장이 있는 집으로 정답 ✓","balcón: 발코니 → 그 안에 정원과 수영장이 있을 수 없음 ✗","dormitorio: 침실 → 정원·수영장이 딸린 공간이 아님 ✗","cuarto: 방 → 정원·수영장이 딸린 공간이 아님 ✗"]},{"id":"V407","q":"Es lógico que ____, son hermanos.","o":["se levanten","se parezcan","se odien","se caigan"],"a":1,"k":"상호 재귀 동사","t":"서로 닮은 건 당연하지, 형제잖아.","e":"parecerse는 '(서로) 닮다'라는 뜻입니다. 형제라서 닮는 것은 당연하다는 흐름이 자연스럽습니다. Es lógico que 뒤에는 접속법(se parezcan)을 씁니다. 예: Me parezco a mi madre.(나는 엄마를 닮았다.)","x":["se levanten: 일어나다 → 형제인 것과 연관 없음 ✗","se parezcan: 서로 닮다 → 형제라서 닮는 것이 당연하므로 정답 ✓","se odien: 서로 미워하다 → 형제라서 당연한 일이 아님 ✗","se caigan: 넘어지다 → 형제와 무관 ✗"]},{"id":"V408","q":"Susana ha puesto los cubiertos, los platos y los vasos en la mesa, pero se le han olvidado las ____.","o":["toallas","sábanas","mantas","servilletas"],"a":3,"k":"식탁 어휘","t":"수사나는 식탁에 수저와 접시, 컵은 놓았는데 냅킨을 깜빡했다.","e":"servilleta는 식사할 때 쓰는 '냅킨'입니다. 식탁을 차릴 때(poner la mesa) 수저(cubiertos)·접시·컵과 함께 놓는 물건입니다. se le han olvidado는 '그녀가 (무심코) 잊어버렸다'라는 표현입니다.","x":["toallas: 수건 → 식탁에 놓는 물건이 아님 ✗","sábanas: 침대 시트 → 식탁과 무관 ✗","mantas: 담요 → 식탁과 무관 ✗","servilletas: 냅킨 → 식탁 차림에 필요한 물건으로 정답 ✓"]},{"id":"V409","q":"El niño está ____, tiene tos y fiebre.","o":["despierto","sano","hambriento","malo"],"a":3,"k":"건강 형용사","t":"아이가 아파. 기침도 하고 열도 있어.","e":"estar malo는 '아프다, 몸이 안 좋다'라는 뜻입니다(특히 스페인 구어). ser malo(나쁜 사람이다)와 estar malo(아프다)는 뜻이 다르니 주의하세요. 기침(tos)과 열(fiebre)이 있다는 설명과 맞습니다. estar enfermo도 같은 뜻입니다.","x":["despierto: 깨어 있는 → 기침·열과 관계없음 ✗","sano: 건강한 → 증상과 반대 ✗","hambriento: 배고픈 → 기침·열과 관계없음 ✗","malo: estar malo(아프다) → 기침과 열이 있어서 정답 ✓"]},{"id":"V410","q":"El agua está ____, ni fría ni caliente.","o":["congelada","templada","sucia","limpia"],"a":1,"k":"온도 형용사","t":"물이 미지근해. 차갑지도 뜨겁지도 않아.","e":"templado(여성형 templada)는 '미지근한, 적당히 따뜻한'이라는 뜻입니다. ni fría ni caliente(차갑지도 뜨겁지도 않은)라는 설명과 정확히 일치합니다. 기후에 쓰면 '온화한'이라는 뜻이 됩니다(clima templado).","x":["congelada: 얼어 있는 → '차갑지 않다'는 설명과 모순 ✗","templada: 미지근한 → 차갑지도 뜨겁지도 않아 정답 ✓","sucia: 더러운 → 온도와 관계없음 ✗","limpia: 깨끗한 → 온도와 관계없음 ✗"]},{"id":"V411","q":"Mis padres son muy ____, nos les importa que salga con un chico mucho menor que yo.","o":["severos","comprensivos","simples","delicados"],"a":1,"k":"성격 형용사","t":"우리 부모님은 이해심이 아주 많아서 내가 나보다 훨씬 어린 남자와 사귀어도 상관하지 않으셔.","e":"comprensivo(여성형 comprensiva)는 '이해심 많은, 너그러운'이라는 뜻입니다. 나이 차가 큰 연애도 개의치 않는 부모님의 태도와 어울립니다. 참고로 문장의 'nos les importa'는 'no les importa(그들에게 상관없다)'의 오타로 보입니다.","x":["severos: 엄격한 → 상관하지 않는 태도와 반대 ✗","comprensivos: 이해심 많은 → 정답 ✓","simples: 단순한 → 태도를 설명하지 못함 ✗","delicados: 섬세한, 예민한 → 문맥과 맞지 않음 ✗"]},{"id":"V412","q":"¡Qué café tan ____! Voy a ponerle una cucharadita de azúcar.","o":["caliente","fuerte","amargo","dulce"],"a":2,"k":"맛 형용사","t":"커피가 정말 쓰다! 설탕 한 티스푼 넣어야겠어.","e":"amargo는 '쓴'이라는 뜻입니다. 설탕을 넣겠다는 해결책이 나오므로 커피가 썼다는 것이 이유가 됩니다. ¡Qué + 명사 + tan + 형용사!는 '정말 ~한 ~구나!'라는 감탄 구조입니다.","x":["caliente: 뜨거운 → 설탕을 넣을 이유가 되지 않음 ✗","fuerte: 진한 → 설탕보다는 물이나 우유를 넣을 이유에 가까움 ✗","amargo: 쓴 → 설탕을 넣는 이유로 정답 ✓","dulce: 단 → 이미 달면 설탕을 넣을 이유가 없음 ✗"]},{"id":"V413","q":"Si usas una bolsa ____, contribuyes a la protección del medio ambiente.","o":["recargable","de plástico","reutilizable","de basura"],"a":2,"k":"환경 어휘","t":"재사용 가능한 가방을 쓰면 환경 보호에 기여하는 거야.","e":"reutilizable은 '재사용할 수 있는'이라는 뜻으로 re-(다시) + utilizar(사용하다) + -able(~할 수 있는)입니다. 환경 보호(protección del medio ambiente)와 연결되는 가방은 장바구니처럼 여러 번 쓰는 가방입니다.","x":["recargable: 충전 가능한 → 배터리 등에 쓰며 가방에 맞지 않음 ✗","de plástico: 비닐(플라스틱)의 → 오히려 환경에 해로움 ✗","reutilizable: 재사용 가능한 → 환경 보호와 연결되어 정답 ✓","de basura: 쓰레기용의 → 환경 보호의 근거가 아님 ✗"]},{"id":"V414","q":"La mejor ____ de baile fue la formada por Beatriz y Felipe.","o":["pandilla","multitud","agrupación","pareja"],"a":3,"k":"사람 집단 어휘","t":"최고의 댄스 커플은 베아트리스와 펠리페로 이루어진 팀이었다.","e":"pareja는 '두 사람 한 쌍, 커플, 파트너'입니다. 두 사람(베아트리스와 펠리페)이 이룬 춤 짝이므로 pareja de baile가 맞습니다. pareja는 '애인, 배우자'라는 뜻으로도 많이 씁니다.","x":["pandilla: 친구 무리, 패거리 → 두 사람의 짝이 아님 ✗","multitud: 군중 → 두 사람이 아님 ✗","agrupación: 단체, 모임 → 두 사람의 짝에 쓰지 않음 ✗","pareja: 한 쌍, 커플 → 두 사람의 춤 짝으로 정답 ✓"]},{"id":"V415","q":"____ de los diferentes tipos de alojamiento suben en temporada alta.","o":["Las temperaturas","Las categorías","Los precios","Los trayectos"],"a":2,"k":"여행 어휘","t":"성수기에는 여러 종류의 숙박 시설 가격이 오른다.","e":"precio는 '가격'입니다. temporada alta(성수기)에 숙소(alojamiento)의 가격이 오르는 것은 자연스러운 일입니다. 반대로 비수기는 temporada baja입니다.","x":["Las temperaturas: 기온 → 숙소의 기온이 오른다는 것은 어색함 ✗","Las categorías: 등급 → 성수기에 등급이 오르지 않음 ✗","Los precios: 가격 → 성수기에 숙소 가격이 올라 정답 ✓","Los trayectos: 경로, 구간 → 숙소와 무관 ✗"]},{"id":"V416","q":"Cuando nos sentamos en el tren, el ____ nos pidió los billetes.","o":["revisor","informador","maquinista","reportero"],"a":0,"k":"교통 직업 어휘","t":"우리가 기차에 앉자 검표원이 표를 보여 달라고 했다.","e":"revisor는 기차·버스의 '검표원, 차장'입니다. revisar(검사하다)에서 나온 말로, 승객에게 표를 확인하는 사람입니다. 기차를 운전하는 사람은 maquinista(기관사)입니다.","x":["revisor: 검표원 → 표를 확인하는 사람으로 정답 ✓","informador: 정보 제공자 → 표를 확인하는 직업이 아님 ✗","maquinista: 기관사 → 기차를 운전하므로 표를 검사하지 않음 ✗","reportero: 기자 → 기차 표와 무관 ✗"]},{"id":"V417","q":"A mi hermano no le gusta ____, por eso tiene barba.","o":["teñirse","levantarse","peinarse","afeitarse"],"a":3,"k":"재귀 동사","t":"우리 형은 면도하는 것을 싫어해서 수염을 기르고 있어.","e":"afeitarse는 '(자기) 면도하다'라는 재귀동사입니다. 면도를 싫어해서 수염(barba)이 있다는 인과관계가 자연스럽습니다. 일상 동작 재귀동사로 ducharse(샤워하다), peinarse(머리를 빗다)도 기억하세요.","x":["teñirse: 염색하다 → 수염이 있는 이유가 되지 않음 ✗","levantarse: 일어나다 → 수염과 무관 ✗","peinarse: 머리를 빗다 → 수염과 무관 ✗","afeitarse: 면도하다 → 면도를 안 해서 수염이 있다로 정답 ✓"]},{"id":"V418","q":"No puedo tomar ____ lácteos, soy alérgica.","o":["productos","utensilios","instrumentos","objetos"],"a":0,"k":"음식 어휘","t":"나는 유제품을 먹을 수 없어. 알레르기가 있거든.","e":"productos lácteos는 우유·치즈·요구르트 같은 '유제품'이라는 고정 표현입니다. lácteo는 '우유의'라는 뜻입니다. 음식에 대해 말하므로 producto(제품)가 맞습니다.","x":["productos: 제품 → productos lácteos(유제품)로 정답 ✓","utensilios: 도구, 기구 → 먹는 것이 아님 ✗","instrumentos: 악기, 도구 → 먹는 것이 아님 ✗","objetos: 물건 → 먹는 것이 아님 ✗"]},{"id":"V419","q":"En un partido de fútbol se enfrentan dos equipos de once ____ cada uno.","o":["jugadores","monitores","entrenadores","preparadores"],"a":0,"k":"스포츠 어휘","t":"축구 경기에서는 각각 열한 명의 선수로 이루어진 두 팀이 맞붙는다.","e":"jugador는 '선수'입니다. 축구 한 팀은 경기장에서 11명의 선수가 뜁니다. enfrentarse는 '서로 맞서다, 대결하다'라는 뜻입니다.","x":["jugadores: 선수 → 한 팀 11명의 선수로 정답 ✓","monitores: 지도자, 강사 → 경기에서 뛰는 사람이 아님 ✗","entrenadores: 감독, 코치 → 한 팀에 11명이 있지 않음 ✗","preparadores: 트레이너 → 경기에서 뛰는 사람이 아님 ✗"]},{"id":"V420","q":"No voy a ____, voy a decir lo que pienso.","o":["callarme","asombrarme","arrepentirme","expresarme"],"a":0,"k":"재귀 동사","t":"입 다물고 있지 않을 거야. 내 생각을 말할 거야.","e":"callarse는 '입을 다물다, 조용히 하다'라는 뜻입니다. no voy a callarme(입 다물지 않겠다)와 '생각을 말하겠다'가 같은 의미로 이어집니다. ¡Cállate!(조용히 해!)도 자주 듣는 표현입니다.","x":["callarme: 입을 다물다 → 말하겠다는 의지와 이어져 정답 ✓","asombrarme: 놀라다 → 생각을 말하는 것과 대조되지 않음 ✗","arrepentirme: 후회하다 → 문맥과 맞지 않음 ✗","expresarme: 의견을 표현하다 → 'no voy a expresarme'는 말하겠다는 뒤 문장과 모순 ✗"]},{"id":"V421","q":"Es normal que esté afónico, se pasó todo el concierto ____.","o":["fotografiando","gritando","vigilando","grabando"],"a":1,"k":"동사 어휘","t":"목이 쉰 게 당연하지. 콘서트 내내 소리를 질렀거든.","e":"gritar는 '소리 지르다'입니다. afónico는 '목이 쉰, 목소리가 안 나오는'이라는 뜻이라, 그 원인은 소리를 지른 것입니다. pasarse + 시간 + 현재분사(gritando)는 '~하면서 (시간을) 보내다'라는 구조입니다.","x":["fotografiando: 사진을 찍으며 → 목이 쉬는 원인이 아님 ✗","gritando: 소리를 지르며 → 목이 쉰 원인으로 정답 ✓","vigilando: 지켜보며, 감시하며 → 목이 쉬는 원인이 아님 ✗","grabando: 녹화하며 → 목이 쉬는 원인이 아님 ✗"]},{"id":"V422","q":"Necesito ____, los últimos días han sido muy estresantes.","o":["preocuparme","estresarme","relajarme","enojarme"],"a":2,"k":"재귀 동사","t":"좀 쉬어야겠어. 요 며칠 너무 스트레스가 심했어.","e":"relajarse는 '긴장을 풀다, 쉬다'라는 뜻입니다. 스트레스가 심했던(estresantes) 며칠 뒤에 필요한 것은 휴식이므로 relajarme가 정답입니다. 나머지는 모두 스트레스를 더하는 부정적인 동사입니다.","x":["preocuparme: 걱정하다 → 스트레스 해소가 아님 ✗","estresarme: 스트레스를 받다 → 오히려 원인을 더함 ✗","relajarme: 긴장을 풀다, 쉬다 → 스트레스 뒤에 필요한 것으로 정답 ✓","enojarme: (중남미) 화내다 → 스트레스 해소가 아님 ✗"]},{"id":"V423","q":"¿Quieres un ____ de postre?","o":["salmón","flan","bistec","filete"],"a":1,"k":"음식 어휘","t":"디저트로 플란 하나 먹을래?","e":"flan은 계란·우유·설탕으로 만든 '플란(커스터드 푸딩)'으로, 스페인과 중남미의 대표적인 디저트(postre)입니다. 나머지는 모두 생선이나 고기 요리입니다.","x":["salmón: 연어 → 디저트가 아님 ✗","flan: 플란(푸딩) → 대표적인 디저트로 정답 ✓","bistec: 비프스테이크 → 디저트가 아님 ✗","filete: 고기·생선의 필레(살코기 조각) → 디저트가 아님 ✗"]},{"id":"V424","q":"Julián es muy ____, juega al tenis y al baloncesto.","o":["ingenioso","deportista","risueño","afectuoso"],"a":1,"k":"성격 형용사","t":"훌리안은 운동을 아주 좋아해서 테니스도 치고 농구도 해.","e":"deportista는 '운동을 좋아하는, 운동을 잘하는 (사람)'입니다. 남녀 형태가 같습니다(un/una deportista). 테니스와 농구를 한다는 설명과 일치합니다.","x":["ingenioso: 재치 있는 → 운동과 무관 ✗","deportista: 운동을 좋아하는 → 테니스·농구를 해서 정답 ✓","risueño: 잘 웃는 → 운동과 무관 ✗","afectuoso: 다정한 → 운동과 무관 ✗"]},{"id":"V425","q":"Fue muy ____ que decidiéramos ir en taxi, ya que con otro medio de transporte habríamos llegado tarde.","o":["ridículo","desconcertante","oportuno","absurdo"],"a":2,"k":"평가 형용사","t":"택시를 타기로 한 건 정말 적절한 선택이었어. 다른 교통수단으로 갔다면 늦었을 거야.","e":"oportuno는 '시기적절한, 알맞은'이라는 뜻입니다. 택시 덕분에 늦지 않았으므로 좋은 결정이었다는 의미의 oportuno가 맞습니다. habríamos llegado는 '~했을 텐데'라는 과거 가정(가능법 완료)입니다.","x":["ridículo: 우스꽝스러운 → 좋은 결정이었다는 내용과 반대 ✗","desconcertante: 당혹스러운 → 문맥과 맞지 않음 ✗","oportuno: 적절한, 시기적절한 → 늦지 않게 해 준 결정으로 정답 ✓","absurdo: 터무니없는 → 문맥과 반대 ✗"]},{"id":"V426","q":"Voy a ____ la leche, está demasiado fría para mi gusto.","o":["colar","congelar","calentar","enfriar"],"a":2,"k":"요리 동사","t":"우유를 데울 거야. 내 입맛엔 너무 차가워.","e":"calentar는 '데우다, 따뜻하게 하다'라는 뜻입니다(활용: caliento, calientas...). 우유가 너무 차가우니 데우는 것이 해결책입니다. 반대말은 enfriar(식히다)입니다.","x":["colar: 거르다 → 차가운 문제를 해결하지 못함 ✗","congelar: 얼리다 → 더 차가워짐 ✗","calentar: 데우다 → 차가운 우유를 따뜻하게 하므로 정답 ✓","enfriar: 식히다 → 문맥과 반대 ✗"]},{"id":"V427","q":"Necesito saber la hora de salida y la hora de ____ de vuestro vuelo.","o":["entrada","aparición","llegada","presentación"],"a":2,"k":"여행 어휘","t":"너희 비행기의 출발 시간과 도착 시간을 알아야 해.","e":"llegada는 '도착'입니다. hora de salida(출발 시간)와 짝을 이루는 말은 hora de llegada(도착 시간)입니다. 공항 전광판에서 Salidas(출발), Llegadas(도착)를 볼 수 있습니다.","x":["entrada: 입장, 입구 → 비행기에는 쓰지 않음 ✗","aparición: 출현, 등장 → 비행기 시간에 쓰지 않음 ✗","llegada: 도착 → 출발과 짝을 이루어 정답 ✓","presentación: 발표, 소개 → 비행기 시간과 무관 ✗"]},{"id":"V428","q":"No planeaba ver a Pedro, nos encontramos por ____.","o":["curiosidad","necesidad","casualidad","interés"],"a":2,"k":"관용 표현","t":"페드로를 만날 계획은 없었는데 우연히 마주쳤어.","e":"por casualidad는 '우연히'라는 관용 표현입니다. 만날 계획이 없었다(no planeaba)는 앞부분과 자연스럽게 이어집니다. encontrarse con은 '~와 마주치다'라는 뜻입니다.","x":["curiosidad: 호기심 → por curiosidad는 '호기심으로'라서 맞지 않음 ✗","necesidad: 필요 → por necesidad는 '필요해서'라 계획 없음과 맞지 않음 ✗","casualidad: 우연 → por casualidad(우연히)로 정답 ✓","interés: 관심, 이익 → por interés는 '이익 때문에'라 맞지 않음 ✗"]},{"id":"V429","q":"Voy a la ____, quiero comprarle una buena botella de vino a mi padre.","o":["heladería","chocolatería","marisquería","bodega"],"a":3,"k":"상점 어휘","t":"와인 가게에 갈 거야. 아빠께 좋은 와인 한 병을 사 드리고 싶어.","e":"bodega는 '와인 가게, 와인 저장고(양조장)'입니다. 와인을 사는 곳으로 정답입니다. 참고로 일부 중남미 국가(쿠바, 페루, 베네수엘라 등)에서는 bodega가 '동네 식료품점'을 뜻하기도 합니다.","x":["heladería: 아이스크림 가게 → 와인을 팔지 않음 ✗","chocolatería: 초콜릿 가게 → 와인을 팔지 않음 ✗","marisquería: 해산물 식당 → 와인 사는 곳이 아님 ✗","bodega: 와인 가게 → 와인을 사는 곳으로 정답 ✓"]},{"id":"V430","q":"Lo pasamos ____ en el parque de atracciones, queremos volver a ir.","o":["regular","de pena","mal","fenomenal"],"a":3,"k":"감정 부사 표현","t":"놀이공원에서 정말 즐거운 시간을 보냈어. 또 가고 싶어.","e":"pasarlo fenomenal은 '아주 즐겁게 보내다'라는 뜻입니다. pasarlo bien/mal(즐겁게/나쁘게 보내다) 구조에서 fenomenal은 '최고로, 아주 좋게'를 나타냅니다. 다시 가고 싶다는 말과 어울립니다.","x":["regular: 그저 그렇게 → 다시 가고 싶다는 말과 어울리지 않음 ✗","de pena: 형편없이 → 문맥과 반대 ✗","mal: 나쁘게 → 문맥과 반대 ✗","fenomenal: 아주 좋게 → 다시 가고 싶을 만큼 즐거워 정답 ✓"]},{"id":"V431","q":"____, así que tenemos que poner cadenas a las ruedas del coche.","o":["Ha anochecido","Ha amanecido","Ha llovido","Ha nevado"],"a":3,"k":"날씨 동사","t":"눈이 왔으니 자동차 바퀴에 체인을 감아야 해.","e":"nevar는 '눈이 오다'입니다. 체인(cadenas)을 바퀴에 감는 이유는 눈 때문이므로 ha nevado가 정답입니다. 날씨 동사는 주어 없이 3인칭 단수로만 씁니다(llueve, nieva).","x":["Ha anochecido: 날이 저물었다 → 체인을 감는 이유가 아님 ✗","Ha amanecido: 날이 밝았다 → 체인과 무관 ✗","Ha llovido: 비가 왔다 → 보통 체인까지 필요하지는 않음 ✗","Ha nevado: 눈이 왔다 → 체인을 감는 이유로 정답 ✓"]},{"id":"V432","q":"Siempre ____ los escaparates de las tiendas, pero casi nunca compro nada.","o":["reviso","miro","recuerdo","visito"],"a":1,"k":"동사 어휘","t":"나는 늘 가게 진열창을 구경하지만 거의 아무것도 사지 않아.","e":"mirar는 '바라보다, 구경하다'입니다. mirar escaparates는 '아이쇼핑하다(진열창을 구경하다)'라는 표현입니다. 사지는 않고 구경만 한다는 내용과 맞습니다.","x":["reviso: 점검한다 → 아이쇼핑의 의미가 아님 ✗","miro: 구경한다 → mirar escaparates(아이쇼핑)로 정답 ✓","recuerdo: 기억한다 → 의미가 맞지 않음 ✗","visito: 방문한다 → 진열창을 '방문하다'는 어색함 ✗"]},{"id":"V433","q":"Tengo pánico a los aviones, por eso nunca ____.","o":["he volado","he rodado","he empujado","he saltado"],"a":0,"k":"동사 어휘","t":"나는 비행기가 너무 무서워서 한 번도 비행기를 타 본 적이 없어.","e":"volar는 '날다, 비행기를 타다'입니다(활용: vuelo, vuelas...). nunca + 현재완료(he volado)는 '한 번도 ~한 적이 없다'라는 경험 표현입니다. tener pánico a는 '~을 몹시 무서워하다'입니다.","x":["he volado: 비행기를 탔다 → 비행기 공포와 연결되어 정답 ✓","he rodado: 굴렀다, 촬영했다 → 비행기와 무관 ✗","he empujado: 밀었다 → 비행기와 무관 ✗","he saltado: 뛰었다 → 비행기 공포와 직접 관련 없음 ✗"]},{"id":"V434","q":"Tengo que ____ mi lápiz. ¿Me dejas tu sacapuntas?","o":["cortar","afilar","copiar","describir"],"a":1,"k":"학용품 어휘","t":"연필을 깎아야 해. 연필깎이 좀 빌려줄래?","e":"afilar는 '날카롭게 하다, (연필을) 깎다'라는 뜻입니다. sacapuntas(연필깎이)는 연필을 뾰족하게 만드는 도구이므로 afilar가 맞습니다. 칼을 갈 때도 afilar un cuchillo라고 합니다.","x":["cortar: 자르다 → 연필깎이로 하는 일이 아님 ✗","afilar: 뾰족하게 깎다 → 연필깎이로 연필을 깎으므로 정답 ✓","copiar: 베끼다 → 연필깎이와 무관 ✗","describir: 묘사하다 → 연필깎이와 무관 ✗"]},{"id":"V435","q":"Me ____ Sevilla, es una ciudad con mucho encanto.","o":["fascinó","aburrió","fastidió","hartó"],"a":0,"k":"감정 동사","t":"세비야에 완전히 반했어. 매력이 넘치는 도시야.","e":"fascinar는 '매혹시키다, 홀딱 반하게 하다'라는 뜻으로 gustar처럼 대상(Sevilla)이 주어입니다. Me fascinó는 '나를 매료시켰다 → 나는 반했다'입니다. 매력(encanto)이 많다는 긍정적 이유와 어울립니다.","x":["fascinó: 매료시켰다 → 매력 있는 도시라는 이유와 일치하여 정답 ✓","aburrió: 지루하게 했다 → 문맥과 반대 ✗","fastidió: 짜증 나게 했다 → 문맥과 반대 ✗","hartó: 질리게 했다 → 문맥과 반대 ✗"]},{"id":"V436","q":"El tango es un ____ de Argentina.","o":["plato","baile","dulce","postre"],"a":1,"k":"문화 어휘","t":"탱고는 아르헨티나의 춤이다.","e":"baile는 '춤'입니다(bailar 춤추다). 탱고(tango)는 부에노스아이레스에서 시작된 아르헨티나·우루과이의 대표적인 춤과 음악입니다. 다른 보기는 모두 음식 관련 단어입니다.","x":["plato: 요리, 접시 → 탱고는 음식이 아님 ✗","baile: 춤 → 탱고는 아르헨티나의 춤으로 정답 ✓","dulce: 단 과자 → 탱고와 무관 ✗","postre: 디저트 → 탱고와 무관 ✗"]},{"id":"V437","q":"Es una mujer generosa, siempre está ____ regalos.","o":["haciendo","acumulando","vendiendo","recogiendo"],"a":0,"k":"동사 연어","t":"그녀는 관대한 사람이라 늘 선물을 해.","e":"hacer regalos는 '선물을 하다(주다)'라는 표현입니다. generosa(관대한, 베풀기 좋아하는)한 사람이 하는 행동으로 맞습니다. estar + 현재분사(haciendo)는 '~하고 있다', siempre와 함께 쓰면 '늘 ~한다'라는 강조가 됩니다.","x":["haciendo: hacer regalos(선물하다) → 관대한 행동으로 정답 ✓","acumulando: 모으다, 쌓다 → 관대함과 반대 ✗","vendiendo: 팔다 → 관대함과 무관 ✗","recogiendo: 모으다, 줍다 → 남에게 베푸는 행동이 아님 ✗"]},{"id":"V438","q":"Entre la ropa interior más común están las ____ y los calzoncillos.","o":["sudaderas","cazadoras","bragas","rebecas"],"a":2,"k":"의류 어휘","t":"가장 흔한 속옷에는 여성용 팬티와 남성용 팬티가 있다.","e":"bragas는 스페인에서 쓰는 '여성용 팬티'이고, calzoncillos는 '남성용 팬티'입니다. 둘 다 ropa interior(속옷)입니다. 중남미에서는 여성용 팬티를 calzones, pantaletas 등으로 부르기도 합니다.","x":["sudaderas: 맨투맨, 트레이닝 상의 → 속옷이 아님 ✗","cazadoras: 점퍼, 재킷 → 속옷이 아님 ✗","bragas: 여성용 팬티 → 속옷으로 정답 ✓","rebecas: 카디건 → 속옷이 아님 ✗"]},{"id":"V439","q":"Tengo que ____ una llamada, voy a ir a otra habitación para no molestar.","o":["echar","hacer","practicar","dar"],"a":1,"k":"동사 연어","t":"전화를 한 통 해야 해서, 방해되지 않게 다른 방으로 갈게.","e":"hacer una llamada는 '전화를 걸다'라는 고정 표현입니다. llamar(전화하다)와 같은 뜻입니다. 전화를 받는 것은 contestar/atender una llamada라고 합니다.","x":["echar: 던지다 → echar una llamada는 쓰지 않음 ✗","hacer: hacer una llamada(전화를 걸다) → 정답 ✓","practicar: 연습하다 → 전화와 함께 쓰지 않음 ✗","dar: dar un toque(살짝 전화하다)는 있지만 dar una llamada는 일반적이지 않음 ✗"]},{"id":"V440","q":"La educación primaria es ____, no es opcional.","o":["urgente","incorrecta","innecesaria","obligatoria"],"a":3,"k":"교육 형용사","t":"초등 교육은 의무이며, 선택 사항이 아니다.","e":"obligatorio(여성형 obligatoria)는 '의무적인, 필수의'라는 뜻입니다. no es opcional(선택이 아니다)이라는 설명과 정확히 일치합니다. 반대말은 opcional, optativo(선택의)입니다.","x":["urgente: 긴급한 → 선택이 아니라는 설명과 맞지 않음 ✗","incorrecta: 틀린 → 문맥과 무관 ✗","innecesaria: 불필요한 → 문맥과 반대 ✗","obligatoria: 의무적인 → 선택이 아니라는 설명과 일치하여 정답 ✓"]},{"id":"V441","q":"No soy una persona paciente, por eso no puedo trabajar de ____ al público.","o":["cabeza","cara","pie","espalda"],"a":1,"k":"관용 표현","t":"나는 참을성 있는 사람이 아니라서 고객 응대 업무는 못 해.","e":"de cara al público는 '고객을 직접 상대하는, 대면 응대의'라는 관용 표현입니다. trabajar de cara al público(손님을 직접 응대하는 일을 하다)는 매장·창구 직원의 업무를 말합니다. cara는 '얼굴'입니다.","x":["cabeza: 머리 → 관용 표현이 아님 ✗","cara: 얼굴 → de cara al público(고객 응대)로 정답 ✓","pie: 발 → de pie는 '서서'라는 뜻이라 맞지 않음 ✗","espalda: 등 → de espaldas는 '등을 돌리고'라는 뜻으로 반대 ✗"]},{"id":"V442","q":"Esa doctora tiene muchos ____, por eso tienes que esperar más para que te den cita con ella.","o":["parientes","concursantes","pacientes","votantes"],"a":2,"k":"의료 어휘","t":"그 여의사는 환자가 많아서 예약을 잡으려면 더 기다려야 해.","e":"paciente는 '환자'입니다. 의사(doctora)에게 환자가 많아서 예약(cita)이 늦어진다는 내용입니다. paciente는 형용사로 '참을성 있는'이라는 뜻도 있습니다.","x":["parientes: 친척 → 예약이 늦어지는 이유가 아님 ✗","concursantes: 참가자, 출연자 → 의사와 무관 ✗","pacientes: 환자 → 의사에게 환자가 많아 정답 ✓","votantes: 유권자 → 의사와 무관 ✗"]},{"id":"V443","q":"Si caminas por una calle donde hay hielo, puede que ____.","o":["te levantes","reposes","te gires","te resbales"],"a":3,"k":"재귀 동사","t":"얼음이 있는 길을 걸으면 미끄러질 수도 있어.","e":"resbalarse는 '미끄러지다'라는 재귀동사입니다. 얼음(hielo) 위를 걸을 때 일어날 수 있는 일로 맞습니다. puede que 뒤에는 접속법(te resbales)을 씁니다.","x":["te levantes: 일어나다 → 얼음과 무관 ✗","reposes: 쉬다 → 얼음 길과 무관 ✗","te gires: 몸을 돌리다 → 얼음 때문에 일어나는 일이 아님 ✗","te resbales: 미끄러지다 → 얼음 길에서 일어날 수 있어 정답 ✓"]},{"id":"V444","q":"Tenéis un piso muy ____, el mío, en cambio, es muy oscuro.","o":["luminoso","simple","clásico","elegante"],"a":0,"k":"주거 형용사","t":"너희 아파트는 정말 밝구나. 반면에 내 집은 아주 어두워.","e":"luminoso는 '밝은, 빛이 잘 드는'이라는 뜻입니다. en cambio(반면에)로 '아주 어둡다(oscuro)'와 대조를 이루므로 반대말인 luminoso가 정답입니다. 스페인의 집 광고에서 자주 볼 수 있는 단어입니다.","x":["luminoso: 밝은 → 어두운 집과 대조를 이루어 정답 ✓","simple: 단순한 → 어둡다와 대조되지 않음 ✗","clásico: 고전적인 → 어둡다와 대조되지 않음 ✗","elegante: 우아한 → 밝기와 관계없음 ✗"]},{"id":"V445","q":"Cuando tengo que hacer un examen importante, siento ____ y no sé qué hacer para tranquilizarme.","o":["seguridad","ansiedad","satisfacción","estabilidad"],"a":1,"k":"감정 명사","t":"중요한 시험을 봐야 할 때면 불안해져서 마음을 진정시키려면 어떻게 해야 할지 모르겠어.","e":"ansiedad는 '불안, 초조함'입니다. 마음을 진정시키는(tranquilizarme) 방법을 모르겠다는 내용과 연결됩니다. 나머지 보기는 모두 긍정적인 상태라 진정할 필요가 없습니다.","x":["seguridad: 자신감, 안정감 → 진정할 필요가 없음 ✗","ansiedad: 불안 → 진정하고 싶은 감정으로 정답 ✓","satisfacción: 만족감 → 문맥과 반대 ✗","estabilidad: 안정 → 문맥과 반대 ✗"]},{"id":"V446","q":"Poneos ropa ____, está nevando.","o":["formal","de abrigo","de deporte","ligera"],"a":1,"k":"의류 어휘","t":"따뜻한 옷을 입어. 눈이 오고 있어.","e":"ropa de abrigo는 '방한복, 따뜻한 옷'이라는 표현입니다. abrigo는 '외투'라는 뜻 외에 '추위를 막는 것'이라는 의미도 있습니다. Poneos는 vosotros(너희)에게 하는 명령형이며, 중남미에서는 ustedes 명령형 Pónganse를 씁니다.","x":["formal: 정장의 → 눈과 관계없음 ✗","de abrigo: 방한용의 → 눈 오는 날에 맞아 정답 ✓","de deporte: 운동용의 → 추위와 직접 관련 없음 ✗","ligera: 가벼운 → 눈 오는 날과 반대 ✗"]},{"id":"V447","q":"Me gustaría pagar con ____ de crédito.","o":["papel","sobre","carta","tarjeta"],"a":3,"k":"결제 어휘","t":"신용카드로 결제하고 싶어요.","e":"tarjeta de crédito는 '신용카드'입니다. 체크카드는 tarjeta de débito입니다. pagar con tarjeta(카드로 결제하다)와 pagar en efectivo(현금으로 결제하다)도 함께 기억하세요.","x":["papel: 종이 → 신용카드의 뜻이 아님 ✗","sobre: 봉투 → 결제 수단이 아님 ✗","carta: 편지, 메뉴판 → 카드(card)와 헷갈리기 쉽지만 결제 카드가 아님 ✗","tarjeta: 카드 → tarjeta de crédito(신용카드)로 정답 ✓"]},{"id":"V448","q":"No pude llamarte porque mi móvil no tenía ____.","o":["batería","fuerza","energía","potencia"],"a":0,"k":"전자기기 어휘","t":"휴대폰 배터리가 없어서 너한테 전화할 수 없었어.","e":"batería는 '배터리'입니다. no tener batería는 '배터리가 없다(방전됐다)'라는 표현입니다. móvil은 스페인에서, celular는 중남미에서 쓰는 '휴대폰'입니다.","x":["batería: 배터리 → 휴대폰이 방전된 이유로 정답 ✓","fuerza: 힘 → 휴대폰에 쓰지 않음 ✗","energía: 에너지 → 휴대폰 상태 표현에 일반적이지 않음 ✗","potencia: 출력, 성능 → 전화를 못 한 이유가 되지 않음 ✗"]},{"id":"V449","q":"Asistir a esa conferencia es ____, nadie te obliga.","o":["optativo","agobiante","práctico","informativo"],"a":0,"k":"선택 형용사","t":"그 강연 참석은 선택 사항이야. 아무도 강요하지 않아.","e":"optativo는 '선택적인, 자유 선택의'라는 뜻입니다. nadie te obliga(아무도 강요하지 않는다)는 설명과 정확히 일치합니다. 학교의 선택 과목을 asignatura optativa라고 합니다.","x":["optativo: 선택적인 → 강요하지 않는다는 설명과 일치하여 정답 ✓","agobiante: 숨 막히는, 부담스러운 → 강요 여부와 무관 ✗","práctico: 실용적인 → 강요 여부와 무관 ✗","informativo: 유익한 정보를 주는 → 강요 여부와 무관 ✗"]},{"id":"V450","q":"El Popocatépetl, que tiene una altitud de 5400 metros sobre el nivel del mar, es un ____ activo.","o":["monte","bosque","volcán","pico"],"a":2,"k":"자연 지형 어휘","t":"해발 5,400미터인 포포카테페틀은 활화산이다.","e":"volcán은 '화산'이고 volcán activo는 '활화산'입니다. 멕시코의 포포카테페틀(Popocatépetl)은 지금도 활동 중인 유명한 화산입니다. activo(활동 중인)와 어울리는 것은 volcán뿐입니다.","x":["monte: 산 → activo(활동 중인)와 함께 쓰지 않음 ✗","bosque: 숲 → 산의 높이를 말하는 문장과 맞지 않음 ✗","volcán: 화산 → volcán activo(활화산)로 정답 ✓","pico: 산봉우리 → activo와 함께 쓰지 않음 ✗"]},{"id":"V451","q":"Mi hijo ____ al perro cada mañana y yo lo hago por la noche.","o":["pasea","marcha","camina","anda"],"a":0,"k":"pasear 동사","t":"내 아들은 매일 아침 개를 산책시키고, 나는 밤에 한다.","e":"pasear는 '산책하다'라는 뜻이지만, 뒤에 'a + 동물/사람'을 목적어로 두면 '~을 산책시키다'가 됩니다. 'pasear al perro(개를 산책시키다)'는 매우 자주 쓰는 표현입니다. 예: Paseo al perro dos veces al día.(나는 하루에 두 번 개를 산책시킨다.)","x":["pasea: '산책시키다'라는 뜻으로 목적어(al perro)를 바로 받을 수 있어 정답 ✓","marcha: marchar(떠나다, 행진하다)는 개를 산책시킨다는 뜻이 없습니다 ✗","camina: caminar(걷다)는 자동사(목적어를 받지 않는 동사)라 'camina al perro'라고 하지 않습니다 ✗","anda: andar(걷다, 다니다)도 목적어 없이 쓰는 동사라 맞지 않습니다 ✗"]},{"id":"V452","q":"La policía nunca pudo ____ aquel caso, por eso todavía es un misterio.","o":["producir","definir","inventar","aclarar"],"a":3,"k":"aclarar 동사","t":"경찰은 그 사건을 결코 해결하지 못했고, 그래서 아직도 미스터리다.","e":"aclarar는 '분명하게 하다, 밝히다, 해명하다'라는 뜻으로, 'aclarar un caso'는 '사건을 규명하다/해결하다'는 의미입니다. 뒤 문장의 '아직도 미스터리다'와 자연스럽게 이어집니다. 예: Necesito aclarar una duda.(궁금한 점 하나를 확실히 하고 싶어요.)","x":["producir: '생산하다'라는 뜻으로 사건과 어울리지 않습니다 ✗","definir: '정의하다, 규정하다'라는 뜻이라 사건 해결과 맞지 않습니다 ✗","inventar: '발명하다, 지어내다'라는 뜻이라 문맥에 맞지 않습니다 ✗","aclarar: '밝히다, 규명하다'로 미해결 사건 문맥에 딱 맞아 정답 ✓"]},{"id":"V453","q":"Este año no va bien nuestro negocio, no ____ como antes.","o":["compramos","vemos","asistimos","vendemos"],"a":3,"k":"상업 동사","t":"올해는 우리 사업이 잘 안 된다. 예전만큼 팔지 못한다.","e":"사업(negocio)이 잘 안 된다는 것은 물건을 예전처럼 많이 '팔지(vender)' 못한다는 뜻입니다. vendemos는 vender(팔다)의 1인칭 복수 현재형입니다. 예: Vendemos ropa de segunda mano.(우리는 중고 옷을 판다.)","x":["compramos: comprar(사다)는 사업 부진의 원인을 설명하기에 어색합니다 ✗","vemos: ver(보다)는 문맥과 관련이 없습니다 ✗","asistimos: asistir(참석하다)는 보통 'asistir a ~' 형태로 쓰여 맞지 않습니다 ✗","vendemos: vender(팔다)로 '예전만큼 팔지 못한다'는 의미가 되어 정답 ✓"]},{"id":"V454","q":"Voy a ____ el pelo, no me gusta tenerlo tan largo.","o":["alisarme","cepillarme","cortarme","rizarme"],"a":2,"k":"머리 손질 어휘","t":"머리를 자를 거야, 이렇게 긴 게 싫어.","e":"머리가 너무 길어서 싫다면 '자르다'가 자연스럽습니다. 'cortarse el pelo'는 '(미용실에서) 머리를 자르다'라는 뜻의 재귀 표현(자기 몸에 하는 행동을 나타내는 형태)입니다. 스페인어에서는 내가 직접 자르지 않아도 이렇게 말합니다.","x":["alisarme: alisarse el pelo(머리를 펴다, 스트레이트하다)는 길이를 줄이지 않습니다 ✗","cepillarme: cepillarse el pelo(머리를 빗다)는 길이와 관련 없습니다 ✗","cortarme: cortarse el pelo(머리를 자르다)로 긴 머리가 싫다는 문맥에 맞아 정답 ✓","rizarme: rizarse el pelo(머리를 곱슬하게 하다, 파마하다)는 문맥에 맞지 않습니다 ✗"]},{"id":"V455","q":"Esta chaqueta es preciosa, pero es demasiado ____.","o":["cara","cómoda","bonita","linda"],"a":0,"k":"형용사 caro","t":"이 재킷은 정말 예쁘지만 너무 비싸다.","e":"pero(하지만)는 앞 내용과 반대되는 내용을 이끕니다. '예쁘다'는 장점 뒤에는 단점이 와야 하므로 cara(비싼)가 정답입니다. demasiado(너무)는 지나치다는 부정적인 느낌을 줍니다. caro의 반대말은 barato(싼)입니다.","x":["cara: caro(비싼)의 여성형으로 '예쁘지만 너무 비싸다'는 대조가 성립해 정답 ✓","cómoda: '편안한'이라는 장점이라 pero 뒤 단점으로 어색합니다 ✗","bonita: '예쁜'은 preciosa와 같은 뜻이라 대조가 되지 않습니다 ✗","linda: '예쁜'(특히 중남미에서 자주 씀)으로 역시 대조가 되지 않습니다 ✗"]},{"id":"V456","q":"Todavía estoy en bata, tengo que cambiarme de ____ o me verán así los invitados.","o":["corbata","chaqueta","peinado","ropa"],"a":3,"k":"cambiarse de ropa","t":"아직 가운 차림이야. 옷을 갈아입어야 해, 안 그러면 손님들이 이런 모습을 보게 될 거야.","e":"'cambiarse de ropa'는 '옷을 갈아입다'라는 고정 표현입니다. bata(가운, 실내복)를 입고 있으니 옷 전체를 갈아입어야 하는 상황입니다. 'cambiarse de + 명사'는 '~을 바꾸다'라는 뜻으로 cambiarse de casa(이사하다)처럼도 씁니다.","x":["corbata: '넥타이'로, 가운 차림에서 넥타이만 바꾸는 것은 어색합니다 ✗","chaqueta: '재킷'으로, 가운을 벗고 옷 전체를 갈아입는 상황과 맞지 않습니다 ✗","peinado: '머리 모양'으로 옷과 관련이 없습니다 ✗","ropa: '옷'으로 cambiarse de ropa(옷을 갈아입다)가 되어 정답 ✓"]},{"id":"V457","q":"La policía me pidió que ____ al ladrón con la mayor precisión posible.","o":["describiera","reescribiera","inscribiera","escribiera"],"a":0,"k":"describir 동사","t":"경찰은 나에게 도둑을 최대한 정확하게 묘사해 달라고 했다.","e":"describir는 '묘사하다, 설명하다'라는 뜻으로, 사람의 생김새를 말로 설명할 때 씁니다. 'pedir que + 접속법(바람·요청을 나타내는 동사 형태)' 구조이고 pidió가 과거라서 접속법 과거 describiera가 쓰였습니다.","x":["describiera: describir(묘사하다)의 접속법 과거로 도둑의 인상착의를 설명한다는 뜻이 되어 정답 ✓","reescribiera: reescribir(다시 쓰다)는 사람을 대상으로 쓰지 않습니다 ✗","inscribiera: inscribir(등록하다, 새기다)는 문맥에 맞지 않습니다 ✗","escribiera: escribir(쓰다)는 '도둑을 쓰다'가 되어 의미가 통하지 않습니다 ✗"]},{"id":"V458","q":"Para hacer la ____ de una pizza, se necesita harina, agua, aceite, sal y levadura.","o":["figura","forma","superficie","masa"],"a":3,"k":"요리 어휘 masa","t":"피자 반죽을 만들려면 밀가루, 물, 기름, 소금, 이스트가 필요하다.","e":"masa는 '반죽'이라는 뜻으로 밀가루와 물 등을 섞어 만든 덩어리를 말합니다. 'masa de pizza(피자 반죽)', 'masa de pan(빵 반죽)'처럼 씁니다. harina(밀가루), levadura(이스트, 효모)도 함께 기억해 두세요.","x":["figura: '형상, 인물'로 재료로 만드는 것과 맞지 않습니다 ✗","forma: '모양, 형태'로 재료 목록과 어울리지 않습니다 ✗","superficie: '표면'으로 문맥에 맞지 않습니다 ✗","masa: '반죽'으로 재료들을 섞어 만드는 것이라 정답 ✓"]},{"id":"V459","q":"Los ____ son mamíferos.","o":["cerdos","mosquitos","gallos","escorpiones"],"a":0,"k":"동물 어휘","t":"돼지는 포유류이다.","e":"mamífero는 '포유류(새끼를 낳아 젖을 먹이는 동물)'입니다. 보기 중 포유류는 cerdo(돼지)뿐입니다. 다른 분류도 알아 두세요: ave(조류), insecto(곤충), arácnido(거미류).","x":["cerdos: '돼지'로 포유류라서 정답 ✓","mosquitos: '모기'로 곤충(insecto)입니다 ✗","gallos: '수탉'으로 조류(ave)입니다 ✗","escorpiones: '전갈'로 거미류(arácnido)입니다 ✗"]},{"id":"V460","q":"Julio y agosto son ____ de mayor ocupación hotelera en España.","o":["los meses","las semanas","las quincenas","los años"],"a":0,"k":"시간 어휘","t":"7월과 8월은 스페인에서 호텔 투숙률이 가장 높은 달이다.","e":"julio(7월)와 agosto(8월)는 '달(mes)'이므로 los meses가 정답입니다. 'mayor ocupación hotelera'는 '가장 높은 호텔 점유율(투숙률)'을 뜻합니다. 스페인은 여름 휴가철인 7~8월에 관광객이 가장 많습니다.","x":["los meses: '달들'로 7월, 8월을 가리키므로 정답 ✓","las semanas: '주들'로 7월과 8월은 주가 아닙니다 ✗","las quincenas: '보름(15일) 단위들'로 달 이름과 맞지 않습니다 ✗","los años: '해들'로 맞지 않습니다 ✗"]},{"id":"V461","q":"Las ____ del corazón hablan de la vida privada de los famosos.","o":["inspecciones","revistas","revisiones","exhibiciones"],"a":1,"k":"revista del corazón","t":"연예 잡지는 유명인들의 사생활에 대해 이야기한다.","e":"'revista del corazón'은 직역하면 '마음의 잡지'지만, 실제로는 연예인·유명인의 연애, 결혼 등 사생활 소식을 다루는 '연예/가십 잡지'를 뜻합니다. 'prensa del corazón(연예 언론)'이라는 표현도 자주 씁니다.","x":["inspecciones: '검사, 점검'으로 문맥에 맞지 않습니다 ✗","revistas: '잡지'로 revistas del corazón(연예 잡지)이 되어 정답 ✓","revisiones: '검토, 정기 검진'으로 맞지 않습니다 ✗","exhibiciones: '전시, 공연'으로 맞지 않습니다 ✗"]},{"id":"V462","q":"Si mezclamos el amarillo con el ____, vamos a obtener el color naranja.","o":["rojo","blanco","azul","negro"],"a":0,"k":"색깔 어휘","t":"노란색과 빨간색을 섞으면 주황색을 얻게 된다.","e":"amarillo(노랑)와 rojo(빨강)를 섞으면 naranja(주황)가 됩니다. 색 이름 앞에는 남성 정관사 el을 씁니다(el rojo, el azul). 참고로 노랑+파랑=초록(verde)입니다.","x":["rojo: '빨간색'으로 노랑과 섞으면 주황이 되어 정답 ✓","blanco: '흰색'으로 섞으면 연한 노랑이 됩니다 ✗","azul: '파란색'으로 섞으면 초록색(verde)이 됩니다 ✗","negro: '검은색'으로 섞으면 어두운 색이 됩니다 ✗"]},{"id":"V463","q":"En otoño se venden castañas ____ en muchas calles de la ciudad.","o":["asadas","rebozadas","congeladas","batidas"],"a":0,"k":"요리 방법 어휘","t":"가을이면 도시의 많은 거리에서 군밤을 판다.","e":"asar는 '굽다'라는 뜻이고, castañas asadas는 '군밤'입니다. 스페인에서는 가을·겨울에 거리 노점에서 군밤을 파는 풍경이 흔합니다. 예: pollo asado(통닭구이).","x":["asadas: '구운'으로 castañas asadas(군밤)가 되어 정답 ✓","rebozadas: '튀김옷을 입힌'으로 밤과 어울리지 않습니다 ✗","congeladas: '냉동된'으로 거리 노점과 어울리지 않습니다 ✗","batidas: '휘저은, 거품 낸'으로 계란 등에 쓰는 말입니다 ✗"]},{"id":"V464","q":"Recibir este boletín informativo no cuesta nada, es ____.","o":["difícil","gratis","especial","complicado"],"a":1,"k":"gratis 무료","t":"이 소식지를 받는 데는 돈이 들지 않는다, 무료다.","e":"'no cuesta nada(전혀 돈이 들지 않는다)'는 곧 gratis(무료)라는 뜻입니다. gratis는 형태가 변하지 않는 단어로 'es gratis', 'entrada gratis(무료 입장)'처럼 씁니다. 비슷한 말로 gratuito(무료의)가 있습니다.","x":["difícil: '어려운'으로 가격과 관련이 없습니다 ✗","gratis: '무료인'으로 '돈이 들지 않는다'와 같은 뜻이라 정답 ✓","especial: '특별한'으로 문맥에 맞지 않습니다 ✗","complicado: '복잡한'으로 맞지 않습니다 ✗"]},{"id":"V465","q":"¿Con cuánta frecuencia ____ esta revista?","o":["existe","sale","marcha","nace"],"a":1,"k":"salir 출판되다","t":"이 잡지는 얼마나 자주 나오나요?","e":"salir는 기본 뜻 '나가다' 외에 잡지·신문·책이 '나오다, 발행되다'라는 뜻도 있습니다. 예: La revista sale cada mes.(그 잡지는 매달 나온다.) 한국어 '나오다'와 쓰임이 비슷해 기억하기 쉽습니다.","x":["existe: existir(존재하다)는 발행 빈도와 맞지 않습니다 ✗","sale: salir(발행되다, 나오다)로 잡지 발행 빈도를 묻는 문장이 되어 정답 ✓","marcha: marchar(떠나다, 진행되다)는 잡지 발행에 쓰지 않습니다 ✗","nace: nacer(태어나다)는 창간을 뜻할 수는 있어도 빈도와 맞지 않습니다 ✗"]},{"id":"V466","q":"No ____ algunas fechas importantes, soy una persona olvidadiza.","o":["conozco","olvido","recuerdo","ignoro"],"a":2,"k":"recordar 동사","t":"나는 몇몇 중요한 날짜를 기억하지 못한다, 나는 잘 잊어버리는 사람이다.","e":"olvidadiza는 '건망증이 있는, 잘 잊는'이라는 뜻이므로 '날짜를 기억하지 못한다'가 자연스럽습니다. recordar는 '기억하다'로, 현재형은 recuerdo, recuerdas, recuerda처럼 o가 ue로 바뀝니다(어간 모음 변화).","x":["conozco: conocer(알다, 친분이 있다)는 날짜를 '기억한다'는 뜻이 아닙니다 ✗","olvido: olvidar(잊다)를 no와 쓰면 '잊지 않는다'가 되어 olvidadiza와 모순됩니다 ✗","recuerdo: recordar(기억하다)로 '기억하지 못한다'가 되어 정답 ✓","ignoro: ignorar(모르다, 무시하다)는 이 문맥에서 어색합니다 ✗"]},{"id":"V467","q":"Estamos muy ____ con el progreso escolar de nuestro hijo. Va muy bien en la escuela.","o":["intranquilos","descontentos","satisfechos","enojados"],"a":2,"k":"감정 형용사","t":"우리는 아들의 학업 성취에 매우 만족한다. 학교에서 아주 잘하고 있다.","e":"아이가 학교에서 잘하고 있으니 부모는 satisfechos(만족한)입니다. 'estar satisfecho con ~'은 '~에 만족하다'라는 표현입니다. 주어가 우리(부모 둘)라서 남성 복수형을 씁니다.","x":["intranquilos: '불안한'으로 좋은 결과와 반대입니다 ✗","descontentos: '불만족한'으로 문맥과 반대입니다 ✗","satisfechos: '만족한'으로 아이가 잘하는 상황에 맞아 정답 ✓","enojados: '화난'(특히 중남미에서 자주 씀)으로 문맥과 반대입니다 ✗"]},{"id":"V468","q":"Prefiero una clase de idiomas con pocos ____ para que podamos organizarnos fácilmente.","o":["clientes","seguidores","alumnos","usuarios"],"a":2,"k":"학교 어휘","t":"나는 우리가 쉽게 조직할 수 있도록 학생 수가 적은 어학 수업을 선호한다.","e":"수업(clase)에 참여하는 사람은 alumnos(학생들)입니다. alumno는 '학생, 수강생'을 뜻하며 estudiante와 비슷합니다. 'para que + 접속법(목적을 나타냄)'으로 'podamos'가 쓰인 점도 함께 보세요.","x":["clientes: '고객'으로 가게·회사에 어울리는 말입니다 ✗","seguidores: '팔로워, 추종자'로 수업과 맞지 않습니다 ✗","alumnos: '학생들'로 수업 문맥에 맞아 정답 ✓","usuarios: '사용자, 이용자'로 서비스·앱 등에 쓰는 말입니다 ✗"]},{"id":"V469","q":"____ no funcionaba, por eso no se escuchaba al cantante.","o":["La pantalla","El micrófono","La cámara","El vídeo"],"a":1,"k":"전자기기 어휘","t":"마이크가 작동하지 않아서 가수의 소리가 들리지 않았다.","e":"가수의 목소리가 들리지 않은 이유는 micrófono(마이크)가 고장 났기 때문입니다. funcionar는 '(기계가) 작동하다'라는 뜻입니다. 'no se escuchaba'는 '들리지 않았다'는 무인칭 표현입니다.","x":["La pantalla: '화면'은 소리와 관련이 없습니다 ✗","El micrófono: '마이크'로 소리가 들리지 않은 이유가 되어 정답 ✓","La cámara: '카메라'는 영상을 찍는 기기라 소리와 관련 없습니다 ✗","El vídeo: '비디오'는 가수 목소리가 안 들린 직접적 원인으로 어색합니다(중남미는 video) ✗"]},{"id":"V470","q":"Me aburría tanto la película que ____ dormida.","o":["me puse","me hice","me quedé","me tomé"],"a":2,"k":"quedarse dormido","t":"영화가 너무 지루해서 나는 잠들어 버렸다.","e":"'quedarse dormido/a'는 '(의도치 않게) 잠들어 버리다'라는 고정 표현입니다. quedarse + 형용사는 '어떤 상태가 되다'라는 뜻으로 quedarse sorprendido(놀라다)처럼도 씁니다. 화자가 여성이라 dormida입니다.","x":["me puse: ponerse + 형용사는 일시적 감정 변화(me puse nerviosa)에 쓰고, dormida와는 쓰지 않습니다 ✗","me hice: hacerse는 직업·신분 변화(hacerse rico)에 써서 맞지 않습니다 ✗","me quedé: quedarse dormida(잠들어 버리다)라는 고정 표현이 되어 정답 ✓","me tomé: tomarse(먹다, 마시다)는 의미가 통하지 않습니다 ✗"]},{"id":"V471","q":"Alberto es muy sensible, ____ cada vez que recuerda su infancia.","o":["se enfurece","se resiste","se contagia","se emociona"],"a":3,"k":"감정 동사","t":"알베르토는 아주 감수성이 예민해서 어린 시절을 떠올릴 때마다 감동한다(울컥한다).","e":"sensible은 '민감한, 감수성이 풍부한'이라는 뜻입니다(영어 sensible과 다름!). 그런 사람이 어린 시절을 떠올리면 emocionarse(감동하다, 울컥하다)가 자연스럽습니다. 예: Me emocioné al verte.(너를 보고 울컥했어.)","x":["se enfurece: enfurecerse(격분하다)는 감수성과 어울리지 않습니다 ✗","se resiste: resistirse(저항하다, 버티다)는 문맥에 맞지 않습니다 ✗","se contagia: contagiarse(감염되다, 옮다)는 문맥에 맞지 않습니다 ✗","se emociona: emocionarse(감동하다, 울컥하다)로 감수성 예민한 사람에 맞아 정답 ✓"]},{"id":"V472","q":"Gano poco dinero, por eso es difícil que ____.","o":["corte","compense","empiece","ahorre"],"a":3,"k":"ahorrar 동사","t":"나는 돈을 적게 벌어서 저축하기가 어렵다.","e":"ahorrar는 '저축하다, 아끼다'라는 뜻입니다. 돈을 적게 벌면 저축이 어렵다는 논리입니다. 'es difícil que + 접속법' 구조라서 ahorre(접속법 현재)가 쓰였습니다. 예: Ahorro un poco cada mes.(나는 매달 조금씩 저축한다.)","x":["corte: cortar(자르다)는 돈 문맥과 맞지 않습니다 ✗","compense: compensar(보상하다, 수지가 맞다)는 이 문장에서 의미가 어색합니다 ✗","empiece: empezar(시작하다)는 무엇을 시작하는지 알 수 없어 어색합니다 ✗","ahorre: ahorrar(저축하다)로 적은 수입과 논리적으로 이어져 정답 ✓"]},{"id":"V473","q":"Prefiero la soltería a tener un ____ infeliz.","o":["padrastro","ahijado","matrimonio","pariente"],"a":2,"k":"가족·결혼 어휘","t":"나는 불행한 결혼 생활을 하느니 독신이 더 좋다.","e":"soltería는 '독신(결혼하지 않은 상태)'이고, 그 반대가 matrimonio(결혼, 결혼 생활)입니다. 'preferir A a B'는 'B보다 A를 선호하다'라는 구조입니다. matrimonio는 '부부'라는 뜻으로도 씁니다.","x":["padrastro: '의붓아버지'로 독신과 비교 대상이 아닙니다 ✗","ahijado: '대자(代子), 양아들'로 문맥에 맞지 않습니다 ✗","matrimonio: '결혼 생활'로 독신과 대비되어 정답 ✓","pariente: '친척'으로 맞지 않습니다 ✗"]},{"id":"V474","q":"No ____ todos en tu auto, no hay suficiente espacio.","o":["manejamos","compartimos","estamos","cabemos"],"a":3,"k":"caber 동사","t":"우리 모두가 네 차에 들어가지 못해, 공간이 충분하지 않아.","e":"caber는 '(공간에) 들어가다, 수용되다'라는 뜻입니다. 1인칭 단수는 quepo로 불규칙이지만, cabemos(우리)는 규칙형입니다. 예: No quepo en estos pantalones.(이 바지가 안 맞아/안 들어가.) auto는 '자동차'(주로 중남미)입니다.","x":["manejamos: manejar(운전하다, 중남미)는 '모두 운전하다'가 되어 공간 부족과 맞지 않습니다 ✗","compartimos: compartir(공유하다)는 공간 부족 설명과 맞지 않습니다 ✗","estamos: estar(있다)는 공간에 들어갈 수 있는지를 표현하지 못합니다 ✗","cabemos: caber(들어가다)로 공간이 부족하다는 내용과 맞아 정답 ✓"]},{"id":"V475","q":"En ____ municipal hay unos dos mil libros.","o":["el gimnasio","la biblioteca","el polideportivo","el teatro"],"a":1,"k":"장소 어휘","t":"시립 도서관에는 약 2천 권의 책이 있다.","e":"책이 많이 있는 곳은 biblioteca(도서관)입니다. municipal은 '시(市)의, 시립의'라는 뜻입니다. 주의: librería는 '서점'이고 biblioteca가 '도서관'입니다.","x":["el gimnasio: '헬스장, 체육관'으로 책과 관련 없습니다 ✗","la biblioteca: '도서관'으로 책 2천 권과 어울려 정답 ✓","el polideportivo: '종합 체육 시설'로 맞지 않습니다 ✗","el teatro: '극장'으로 맞지 않습니다 ✗"]},{"id":"V476","q":"Como especialista en ecología, me preocupan mucho los problemas ____.","o":["capitales","digitales","medioambientales","mentales"],"a":2,"k":"환경 어휘","t":"생태학 전문가로서 나는 환경 문제가 매우 걱정된다.","e":"ecología(생태학) 전문가가 걱정하는 것은 problemas medioambientales(환경 문제)입니다. medio ambiente는 '환경'이고 형용사형은 medioambiental입니다. preocupar는 gustar처럼 'me preocupan'으로 씁니다.","x":["capitales: '주요한, 수도의'로 생태학과 연결되지 않습니다 ✗","digitales: '디지털의'로 맞지 않습니다 ✗","medioambientales: '환경의'로 생태학 전문가 문맥에 맞아 정답 ✓","mentales: '정신의'로 맞지 않습니다 ✗"]},{"id":"V477","q":"Afortunadamente, ____ llegó dos minutos después del accidente.","o":["la caravana","el tractor","la ambulancia","la furgoneta"],"a":2,"k":"차량 어휘","t":"다행히 사고 2분 뒤에 구급차가 도착했다.","e":"사고(accidente) 직후 도착해서 다행인 차는 ambulancia(구급차)입니다. afortunadamente는 '다행히'라는 뜻의 부사입니다. 관련 어휘: bomberos(소방관), policía(경찰).","x":["la caravana: '캠핑카, 행렬'로 사고 현장과 맞지 않습니다 ✗","el tractor: '트랙터'로 맞지 않습니다 ✗","la ambulancia: '구급차'로 사고 직후 도착해 다행인 상황이라 정답 ✓","la furgoneta: '승합차, 밴'으로 맞지 않습니다 ✗"]},{"id":"V478","q":"No le debo dinero a nadie, no me gusta tener ____.","o":["deudas","datos","daños","dudas"],"a":0,"k":"돈 어휘 deuda","t":"나는 아무에게도 돈을 빚지지 않았다, 빚이 있는 걸 좋아하지 않는다.","e":"deber dinero는 '돈을 빚지다'이고, 그 명사가 deuda(빚, 부채)입니다. 'tener deudas(빚이 있다)'처럼 씁니다. 철자가 비슷한 dudas(의심, 궁금한 점)와 헷갈리지 마세요.","x":["deudas: '빚'으로 돈을 빚지지 않는다는 앞 문장과 맞아 정답 ✓","datos: '데이터, 정보'로 맞지 않습니다 ✗","daños: '손해, 피해'로 맞지 않습니다 ✗","dudas: '의심, 의문'으로 철자는 비슷하지만 뜻이 다릅니다 ✗"]},{"id":"V479","q":"El pádel es un deporte de ____.","o":["raqueta","remo","balón","esquí"],"a":0,"k":"스포츠 어휘","t":"파델은 라켓 스포츠이다.","e":"pádel(파델)은 테니스와 비슷하게 벽이 있는 코트에서 라켓(raqueta)으로 하는 운동으로 스페인과 아르헨티나에서 매우 인기 있습니다. 'deporte de raqueta'는 '라켓 스포츠'라는 표현입니다.","x":["raqueta: '라켓'으로 파델은 라켓 스포츠라서 정답 ✓","remo: '노, 조정'으로 수상 스포츠입니다 ✗","balón: '공'으로 축구·농구 등 구기 종목에 씁니다 ✗","esquí: '스키'로 맞지 않습니다 ✗"]},{"id":"V480","q":"Cuando pase la azafata con el ____ de las bebidas, voy a pedirle un café.","o":["bolso","auto","carrito","puesto"],"a":2,"k":"기내 어휘","t":"승무원이 음료 카트를 끌고 지나가면 커피 한 잔을 달라고 할 거야.","e":"carrito는 carro(수레)의 축소형으로 '작은 카트, 수레'라는 뜻입니다. 비행기에서 승무원이 끌고 다니는 음료 카트는 'carrito de las bebidas'라고 합니다. 'cuando + 접속법(pase)'은 미래의 일을 나타냅니다.","x":["bolso: '핸드백'으로 음료를 운반하는 것이 아닙니다 ✗","auto: '자동차'로 기내에 맞지 않습니다 ✗","carrito: '카트, 작은 수레'로 기내 음료 카트를 뜻해 정답 ✓","puesto: '노점, 자리'로 지나가는 것이 아닙니다 ✗"]},{"id":"V481","q":"Estás muy estresado, deberías tomarte unos días de vacaciones para ____.","o":["desconectar","deshacer","destacar","desmontar"],"a":0,"k":"desconectar 동사","t":"너 스트레스가 너무 많아, 머리를 식히려면 며칠 휴가를 내야 해.","e":"desconectar는 원래 '(전원을) 끊다'라는 뜻이지만, 일상에서 '일에서 벗어나 머리를 식히다, 쉬다'라는 의미로 많이 씁니다. 예: Necesito desconectar del trabajo.(나는 일에서 벗어나 쉬어야 해.)","x":["desconectar: '머리를 식히다, 일상에서 벗어나다'로 휴가 문맥에 맞아 정답 ✓","deshacer: '원래대로 되돌리다, (짐을) 풀다'로 맞지 않습니다 ✗","destacar: '두드러지다, 강조하다'로 맞지 않습니다 ✗","desmontar: '분해하다, 해체하다'로 맞지 않습니다 ✗"]},{"id":"V482","q":"Todos los domingos me reúno con mi familia para almorzar y ____ la tarde juntos.","o":["usar","poner","hacer","pasar"],"a":3,"k":"pasar 시간 보내다","t":"매주 일요일 나는 가족과 모여 점심을 먹고 오후를 함께 보낸다.","e":"pasar + 시간 표현은 '(시간을) 보내다'라는 뜻입니다. 'pasar la tarde(오후를 보내다)', 'pasar las vacaciones(휴가를 보내다)'처럼 씁니다. 예: Pasé el fin de semana en casa.(나는 주말을 집에서 보냈다.)","x":["usar: '사용하다'로 시간과 함께 쓰면 어색합니다 ✗","poner: '놓다, 두다'로 시간과 맞지 않습니다 ✗","hacer: '하다, 만들다'로 'hacer la tarde'라고 하지 않습니다 ✗","pasar: '(시간을) 보내다'로 pasar la tarde가 되어 정답 ✓"]},{"id":"V483","q":"Voy a meter los platos sucios en el ____.","o":["lavavajillas","horno","frigorífico","microondas"],"a":0,"k":"주방 가전 어휘","t":"더러운 접시들을 식기세척기에 넣을게.","e":"더러운 접시(platos sucios)를 넣는 곳은 lavavajillas(식기세척기)입니다. lavar(씻다) + vajilla(식기)가 합쳐진 단어로, 단수와 복수가 같은 형태입니다. 중남미에서는 lavaplatos라고도 합니다.","x":["lavavajillas: '식기세척기'로 더러운 접시를 넣는 곳이라 정답 ✓","horno: '오븐'으로 요리하는 기계입니다 ✗","frigorífico: '냉장고'(스페인)로 음식을 보관하는 곳입니다 ✗","microondas: '전자레인지'로 음식을 데우는 기계입니다 ✗"]},{"id":"V484","q":"Voy a pedir un menú ____, tengo mucha hambre.","o":["vegano","infantil","vegetariano","completo"],"a":3,"k":"식당 어휘","t":"배가 너무 고파서 풀코스 메뉴를 주문할 거야.","e":"배가 매우 고프면 양이 많은 menú completo(전체 코스 메뉴)를 시키는 것이 자연스럽습니다. completo는 '완전한, 다 갖춘'이라는 뜻입니다. 'tener hambre(배고프다)'에서 hambre는 여성명사라 mucha hambre라고 씁니다.","x":["vegano: '비건(완전 채식)'은 배고픔과 직접 관련이 없습니다 ✗","infantil: '어린이용'으로 양이 적어 배고픈 상황과 맞지 않습니다 ✗","vegetariano: '채식'은 배고픔의 이유와 연결되지 않습니다 ✗","completo: '모든 코스를 갖춘'으로 배고픈 상황에 맞아 정답 ✓"]},{"id":"V485","q":"Mi hijo es muy ____, estudia cada día y me ayuda con las tareas de casa.","o":["responsable","lógico","cabezota","sonriente"],"a":0,"k":"성격 형용사","t":"내 아들은 매우 책임감이 강해서 매일 공부하고 집안일도 나를 도와준다.","e":"매일 공부하고 집안일을 돕는 아이는 responsable(책임감 있는)합니다. 'ser responsable'은 성격을 나타내므로 ser를 씁니다. 반대말은 irresponsable(무책임한)입니다.","x":["responsable: '책임감 있는'으로 성실한 행동과 맞아 정답 ✓","lógico: '논리적인'으로 행동 설명과 연결되지 않습니다 ✗","cabezota: '고집 센'으로 뒤 내용과 맞지 않습니다 ✗","sonriente: '잘 웃는'으로 공부·집안일과 관련 없습니다 ✗"]},{"id":"V486","q":"Toda la clase escuchaba a la profesora ____ porque les interesaba el tema.","o":["atentamente","lentamente","parcialmente","rápidamente"],"a":0,"k":"-mente 부사","t":"주제에 관심이 있었기 때문에 반 전체가 선생님 말씀을 주의 깊게 들었다.","e":"형용사 여성형 + -mente는 부사(동사를 꾸미는 말)를 만듭니다. atenta(주의 깊은) + mente → atentamente(주의 깊게). 관심이 있어서 들었으니 '주의 깊게'가 자연스럽습니다.","x":["atentamente: '주의 깊게'로 관심 있는 주제를 듣는 모습에 맞아 정답 ✓","lentamente: '천천히'로 듣는 방식과 어울리지 않습니다 ✗","parcialmente: '부분적으로'로 관심이 있었다는 이유와 맞지 않습니다 ✗","rápidamente: '빠르게'로 듣는 방식에 어색합니다 ✗"]},{"id":"V487","q":"El bar estaba tan lleno de gente que no ____ nadie más.","o":["volvía","salía","había","cabía"],"a":3,"k":"caber 동사","t":"바에 사람이 너무 꽉 차서 더 이상 아무도 들어갈 수 없었다.","e":"caber는 '(공간에) 들어가다'라는 뜻입니다. 'tan + 형용사 + que ~'는 '너무 ~해서 …하다'라는 구조입니다. cabía는 불완료과거(과거의 상태·배경을 나타내는 형태)입니다.","x":["volvía: volver(돌아오다)는 공간이 가득 찬 결과와 맞지 않습니다 ✗","salía: salir(나가다)는 문맥과 맞지 않습니다 ✗","había: haber(있다)를 쓰면 '아무도 더 없었다'가 되어 꽉 찬 상황과 모순됩니다 ✗","cabía: caber(들어갈 자리가 있다)로 꽉 찬 상황과 맞아 정답 ✓"]},{"id":"V488","q":"Necesito la máxima ____ para jugar bien al ajedrez.","o":["conexión","impresión","intención","concentración"],"a":3,"k":"concentración","t":"체스를 잘 두려면 최대한의 집중력이 필요하다.","e":"concentración은 '집중, 집중력'이라는 뜻으로 동사 concentrarse(집중하다)의 명사형입니다. 체스(ajedrez)처럼 머리를 쓰는 활동에 꼭 필요한 것입니다. 'jugar al ajedrez'처럼 jugar a + 경기를 씁니다.","x":["conexión: '연결'로 체스와 관련이 없습니다 ✗","impresión: '인상, 인쇄'로 맞지 않습니다 ✗","intención: '의도'로 문맥에 맞지 않습니다 ✗","concentración: '집중력'으로 체스를 잘 두는 데 필요해 정답 ✓"]},{"id":"V489","q":"Voy a llevar mi coche al ____ de mecánica para que le cambien los neumáticos.","o":["taller","piso","cuarto","salón"],"a":0,"k":"taller 정비소","t":"타이어를 갈려고 내 차를 정비소에 맡길 거야.","e":"taller는 '작업장, 공방'이라는 뜻이며, 'taller mecánico / taller de mecánica'는 '자동차 정비소'입니다. 'taller de cerámica(도예 공방)'처럼 수업·워크숍의 뜻으로도 씁니다. neumático는 '타이어'입니다.","x":["taller: '작업장, 정비소'로 차를 고치는 곳이라 정답 ✓","piso: '아파트, 층'으로 맞지 않습니다 ✗","cuarto: '방'으로 맞지 않습니다 ✗","salón: '거실, 홀'로 맞지 않습니다 ✗"]},{"id":"V490","q":"Copien lo que está escrito en el encerado antes de que lo ____.","o":["borre","reproduzca","imprima","fotocopie"],"a":0,"k":"borrar 동사","t":"칠판에 쓰인 것을 지우기 전에 베껴 쓰세요.","e":"borrar는 '지우다'라는 뜻입니다. 칠판(encerado, 스페인 일부 지역 표현; 보통 pizarra)의 글을 지우기 전에 베끼라는 내용입니다. 'antes de que + 접속법' 구조라서 borre(접속법 현재)가 쓰였습니다.","x":["borre: borrar(지우다)로 칠판 글씨를 지우기 전에 베끼라는 뜻이 되어 정답 ✓","reproduzca: reproducir(재생하다, 복제하다)는 칠판 문맥에 어색합니다 ✗","imprima: imprimir(인쇄하다)는 칠판과 맞지 않습니다 ✗","fotocopie: fotocopiar(복사하다)는 칠판에 쓰지 않습니다 ✗"]},{"id":"V491","q":"Mi trabajo es ____, por eso cuando llego a casa me relajo escuchando música clásica.","o":["estresante","útil","fascinante","manual"],"a":0,"k":"estresante","t":"내 일은 스트레스가 많아서 집에 오면 클래식 음악을 들으며 긴장을 푼다.","e":"집에 와서 relajarse(긴장을 풀다)해야 할 정도라면 일이 estresante(스트레스를 주는)한 것입니다. -ante 형태의 형용사는 '~하게 만드는'이라는 뜻이 많습니다(interesante, emocionante).","x":["estresante: '스트레스를 주는'으로 퇴근 후 긴장을 푸는 이유가 되어 정답 ✓","útil: '유용한'으로 긴장을 풀어야 하는 이유가 되지 않습니다 ✗","fascinante: '매혹적인'으로 문맥에 맞지 않습니다 ✗","manual: '손으로 하는'으로 휴식 이유로 어색합니다 ✗"]},{"id":"V492","q":"Hoy las ____ son altísimas, así que no voy a nadar.","o":["olas","ondas","rocas","piedras"],"a":0,"k":"바다 어휘","t":"오늘은 파도가 엄청 높아서 수영하지 않을 거야.","e":"ola는 '(바다의) 파도'입니다. 파도가 높으면 수영이 위험하겠죠. onda는 '전파, 음파, 웨이브(머리)' 등 물리적 파동을 가리켜 바다 파도에는 쓰지 않습니다. altísimas는 altas의 최상급(매우 높은)입니다.","x":["olas: '파도'로 수영하지 않는 이유가 되어 정답 ✓","ondas: '파동, 전파'로 바다 파도에는 쓰지 않습니다 ✗","rocas: '바위'로 '높다'는 이유와 수영 문맥이 어색합니다 ✗","piedras: '돌'로 맞지 않습니다 ✗"]},{"id":"V493","q":"No puedo ir al viaje porque mis padres no me ____ permiso.","o":["hacen","toman","dan","ponen"],"a":2,"k":"dar permiso","t":"부모님이 허락해 주지 않아서 나는 여행에 갈 수 없다.","e":"'dar permiso'는 '허락하다, 허가를 주다'라는 고정 표현입니다. 반대로 '허락을 구하다'는 'pedir permiso'입니다. 예: ¿Me das permiso para salir?(나가도 돼요?)","x":["hacen: hacer permiso라고 하지 않습니다 ✗","toman: tomar permiso는 쓰지 않는 표현입니다 ✗","dan: dar permiso(허락하다)라는 고정 표현이 되어 정답 ✓","ponen: poner permiso라고 하지 않습니다 ✗"]},{"id":"V494","q":"Ahora casi nadie ____ cartas, todos mandan correos electrónicos.","o":["reparte","hace","envía","comparte"],"a":2,"k":"enviar 동사","t":"요즘은 거의 아무도 편지를 보내지 않는다, 모두 이메일을 보낸다.","e":"enviar는 '보내다'라는 뜻으로 mandar와 같은 의미입니다. 'enviar cartas(편지를 보내다)'는 뒤의 'mandan correos electrónicos(이메일을 보낸다)'와 대비됩니다. 현재형 envía에는 악센트가 붙습니다.","x":["reparte: repartir(나눠 주다, 배달하다)는 집배원의 일이라 맞지 않습니다 ✗","hace: hacer cartas는 어색한 표현입니다 ✗","envía: enviar(보내다)로 이메일을 보내는 것과 대비되어 정답 ✓","comparte: compartir(공유하다)는 편지와 어울리지 않습니다 ✗"]},{"id":"V495","q":"Los ____ son pasos subterráneos.","o":["puentes","portones","bloques","túneles"],"a":3,"k":"túnel 어휘","t":"터널은 지하 통로이다.","e":"subterráneo는 '지하의'라는 뜻입니다. 땅속이나 산을 뚫어 만든 통로는 túnel(터널)입니다. 단수는 túnel, 복수는 túneles(악센트 위치 주의)입니다.","x":["puentes: '다리'로 땅 위나 물 위로 지나갑니다 ✗","portones: '대문, 큰 문'으로 맞지 않습니다 ✗","bloques: '블록, 건물 동'으로 맞지 않습니다 ✗","túneles: '터널'로 지하 통로라서 정답 ✓"]},{"id":"V496","q":"¡Qué día tan ____! No necesito el abrigo.","o":["lluvioso","nublado","frío","caluroso"],"a":3,"k":"날씨 형용사","t":"정말 더운 날이야! 외투가 필요 없어.","e":"외투(abrigo)가 필요 없다면 날씨가 caluroso(더운)합니다. '¡Qué + 명사 + tan + 형용사!'는 '정말 ~한 …이구나!'라는 감탄 구조입니다. 예: ¡Qué casa tan bonita!(정말 예쁜 집이다!)","x":["lluvioso: '비가 오는'으로 외투가 필요 없다는 내용과 맞지 않습니다 ✗","nublado: '흐린'으로 외투가 필요 없는 이유가 되지 않습니다 ✗","frío: '추운'으로 외투가 필요하므로 반대입니다 ✗","caluroso: '더운'으로 외투가 필요 없어 정답 ✓"]},{"id":"V497","q":"Quería reservar una habitación en ese hotel, pero me dijo la recepcionista que estaba ____.","o":["desocupado","completo","vacío","disponible"],"a":1,"k":"호텔 어휘","t":"그 호텔에 방을 예약하고 싶었는데 접수원이 만실이라고 말했다.","e":"호텔이 completo라는 것은 '만실(빈방이 없음)'이라는 뜻입니다. pero(하지만)가 있으므로 예약할 수 없는 상황이 와야 합니다. 식당·극장 등에서도 'Está completo'라고 합니다.","x":["desocupado: '비어 있는'으로 예약 가능한 상황이라 pero와 맞지 않습니다 ✗","completo: '만실인'으로 예약하지 못한 상황과 맞아 정답 ✓","vacío: '텅 빈'으로 예약을 막는 이유가 되지 않습니다 ✗","disponible: '이용 가능한'으로 pero와 반대 의미입니다 ✗"]},{"id":"V498","q":"Mi abuela siempre está ____ anécdotas de su juventud.","o":["diciendo","hablando","expresando","contando"],"a":3,"k":"contar 이야기하다","t":"우리 할머니는 늘 젊은 시절의 일화를 이야기해 주신다.","e":"contar는 '세다'라는 뜻 외에 '(이야기·일화를) 들려주다'라는 뜻이 있습니다. 'contar anécdotas / contar un cuento(이야기를 들려주다)'처럼 씁니다. 'estar + 현재분사(-ndo)'는 진행을 나타내며 siempre와 함께 쓰면 '늘 ~하고 있다'는 뜻입니다.","x":["diciendo: decir(말하다)는 anécdotas와 함께 쓰면 어색합니다 ✗","hablando: hablar(말하다)는 목적어 없이 쓰거나 'hablar de ~'로 씁니다 ✗","expresando: expresar(표현하다)는 일화와 어울리지 않습니다 ✗","contando: contar(이야기해 주다)로 contar anécdotas가 되어 정답 ✓"]},{"id":"V499","q":"Mi padre me compró el ____ de béisbol que más me gustó.","o":["bate","palo","listón","bastón"],"a":0,"k":"스포츠 용품","t":"아버지가 내가 가장 마음에 들어 한 야구 방망이를 사 주셨다.","e":"야구(béisbol)에서 공을 치는 도구는 bate(방망이, 배트)입니다. 'bate de béisbol(야구 배트)'로 씁니다. 야구는 중남미(쿠바, 도미니카공화국, 베네수엘라 등)에서 매우 인기 있는 스포츠입니다.","x":["bate: '야구 배트'로 béisbol과 어울려 정답 ✓","palo: '막대기, (골프) 클럽'으로 야구 방망이에는 쓰지 않습니다 ✗","listón: '각목, (높이뛰기) 바'로 맞지 않습니다 ✗","bastón: '지팡이'로 맞지 않습니다 ✗"]},{"id":"V500","q":"____ nublado, puede que llueva.","o":["Es","Tiene","Está","Hace"],"a":2,"k":"estar nublado","t":"날이 흐리네, 비가 올지도 몰라.","e":"하늘의 상태를 말할 때 '흐리다'는 'está nublado'라고 estar를 씁니다(지금의 상태). 반면 기온은 'hace frío/calor(춥다/덥다)'로 hacer를 씁니다. 'puede que + 접속법'은 '~일지도 모른다'는 뜻입니다.","x":["Es: ser는 nublado와 함께 날씨 상태를 말할 때 쓰지 않습니다 ✗","Tiene: tener는 날씨 표현에 쓰지 않습니다 ✗","Está: estar nublado(흐리다)라는 날씨 표현이 되어 정답 ✓","Hace: hacer는 hace frío/calor/sol처럼 명사와 쓰며 nublado와 쓰지 않습니다 ✗"]},{"id":"V501","q":"Para saber si tienes ____, debes usar un termómetro.","o":["tos","fiebre","sed","hambre"],"a":1,"k":"건강 어휘","t":"열이 있는지 알려면 체온계를 사용해야 한다.","e":"termómetro(체온계)로 확인하는 것은 fiebre(열)입니다. 'tener fiebre'는 '열이 나다'라는 표현입니다. 비슷하게 tener tos(기침이 나다), tener sed(목마르다), tener hambre(배고프다)도 tener를 씁니다.","x":["tos: '기침'은 체온계로 재지 않습니다 ✗","fiebre: '열'로 체온계로 확인하는 것이라 정답 ✓","sed: '갈증'은 체온계로 알 수 없습니다 ✗","hambre: '배고픔'은 체온계로 알 수 없습니다 ✗"]},{"id":"V502","q":"Todavía hay que luchar por la ____ entre hombres y mujeres.","o":["maldad","igualdad","rivalidad","enemistad"],"a":1,"k":"사회 어휘","t":"아직도 남녀 간의 평등을 위해 싸워야 한다.","e":"igualdad는 '평등'으로 형용사 igual(같은)의 명사형입니다. 'igualdad entre hombres y mujeres'는 '남녀평등'입니다. 'luchar por ~'는 '~을 위해 싸우다'라는 뜻입니다. 반대말은 desigualdad(불평등)입니다.","x":["maldad: '악, 사악함'으로 위해 싸울 대상이 아닙니다 ✗","igualdad: '평등'으로 남녀평등을 위한 투쟁이 되어 정답 ✓","rivalidad: '경쟁 관계'로 맞지 않습니다 ✗","enemistad: '적대감'으로 맞지 않습니다 ✗"]},{"id":"V503","q":"El xilófono es un ____ de percusión.","o":["utensilio","dispositivo","aparato","instrumento"],"a":3,"k":"악기 어휘","t":"실로폰은 타악기이다.","e":"악기는 instrumento (musical)라고 합니다. 'instrumento de percusión'은 '타악기', 'instrumento de viento'는 '관악기', 'instrumento de cuerda'는 '현악기'입니다.","x":["utensilio: '(주방) 도구'로 악기에는 쓰지 않습니다 ✗","dispositivo: '장치, 기기'로 전자기기에 씁니다 ✗","aparato: '기구, 기계'로 악기에는 쓰지 않습니다 ✗","instrumento: '악기'로 instrumento de percusión(타악기)이 되어 정답 ✓"]},{"id":"V504","q":"La clase de ____ siempre se da en la sala de ordenadores.","o":["manualidades","informática","peluquería","gimnasia"],"a":1,"k":"과목 어휘","t":"컴퓨터 수업은 항상 컴퓨터실에서 한다.","e":"sala de ordenadores(컴퓨터실)에서 하는 수업은 informática(컴퓨터, 정보학)입니다. ordenador는 스페인에서 쓰는 '컴퓨터'이고, 중남미에서는 computadora라고 합니다.","x":["manualidades: '공작, 만들기'로 컴퓨터실과 관련 없습니다 ✗","informática: '컴퓨터/정보학'으로 컴퓨터실에서 하는 수업이라 정답 ✓","peluquería: '미용'으로 맞지 않습니다 ✗","gimnasia: '체조, 체육'으로 체육관에서 합니다 ✗"]},{"id":"V505","q":"No leo la prensa del corazón porque no me interesa la vida de los ____.","o":["deportistas","famosos","escritores","científicos"],"a":1,"k":"famoso 유명인","t":"나는 유명인들의 삶에 관심이 없어서 연예 잡지를 읽지 않는다.","e":"'prensa del corazón(연예 언론)'은 famosos(유명인, 연예인)의 사생활을 다룹니다. famoso는 형용사 '유명한'이지만 명사로 쓰여 '유명인'이라는 뜻도 됩니다.","x":["deportistas: '운동선수들'로 연예 언론의 주된 대상이라고 보기 어렵습니다 ✗","famosos: '유명인들'로 연예 언론이 다루는 대상이라 정답 ✓","escritores: '작가들'로 맞지 않습니다 ✗","científicos: '과학자들'로 맞지 않습니다 ✗"]},{"id":"V506","q":"Es normal que estés preocupada, pero todo va a ____ bien.","o":["llevar","entrar","pasar","salir"],"a":3,"k":"salir bien","t":"걱정하는 건 당연하지만, 모든 게 잘될 거야.","e":"'salir bien'은 '(일이) 잘되다, 잘 풀리다'라는 표현이고, 반대는 'salir mal(잘못되다)'입니다. 예: El examen me salió bien.(시험을 잘 봤어.) 'Es normal que + 접속법(estés)' 구조도 함께 보세요.","x":["llevar: llevar bien은 '잘 지내다, 잘 감당하다'로 주어 todo와 맞지 않습니다 ✗","entrar: entrar bien은 '잘 들어가다'로 맞지 않습니다 ✗","pasar: pasar bien은 이 문맥에서 쓰지 않습니다(pasarlo bien은 '즐겁게 보내다') ✗","salir: salir bien(잘되다)으로 위로하는 말이 되어 정답 ✓"]},{"id":"V507","q":"Me temo que no podré viajar esa semana concreta, así que tengo que ____ la reserva que hice.","o":["expulsar","neutralizar","anular","rechazar"],"a":2,"k":"anular 동사","t":"하필 그 주에는 여행을 갈 수 없을 것 같아서, 내가 한 예약을 취소해야 한다.","e":"anular는 '취소하다, 무효로 하다'라는 뜻으로 예약·주문 등을 취소할 때 씁니다. 'anular una reserva'는 'cancelar una reserva'와 같은 뜻입니다. 'Me temo que ~'는 '유감스럽지만 ~인 것 같다'는 표현입니다.","x":["expulsar: '쫓아내다, 추방하다'로 예약과 맞지 않습니다 ✗","neutralizar: '무력화하다, 중화하다'로 맞지 않습니다 ✗","anular: '취소하다'로 예약 취소 문맥에 맞아 정답 ✓","rechazar: '거절하다'로 자신이 한 예약에는 어색합니다 ✗"]},{"id":"V508","q":"El anciano no podía ____ sin bastón.","o":["comer","oír","hablar","caminar"],"a":3,"k":"caminar 동사","t":"그 노인은 지팡이 없이는 걸을 수 없었다.","e":"bastón은 '지팡이'로 걷는 것을 도와주는 도구입니다. 그래서 caminar(걷다)가 정답입니다. 'sin + 명사'는 '~ 없이'라는 뜻입니다. anciano는 '노인'입니다.","x":["comer: '먹다'는 지팡이와 관련이 없습니다 ✗","oír: '듣다'는 지팡이와 관련이 없습니다 ✗","hablar: '말하다'는 지팡이와 관련이 없습니다 ✗","caminar: '걷다'로 지팡이가 필요한 행동이라 정답 ✓"]},{"id":"V509","q":"Vivo en un piso ____ porque no puedo pagar el alquiler yo solo.","o":["construido","compartido","repartido","destruido"],"a":1,"k":"piso compartido","t":"월세를 혼자서 낼 수 없어서 나는 셰어하우스에 산다.","e":"piso compartido는 '여럿이 함께 사는 아파트(셰어하우스)'입니다. compartir(공유하다)의 과거분사가 형용사로 쓰였습니다. 혼자 alquiler(월세)를 낼 수 없으니 함께 사는 것이죠. 스페인 대학생들 사이에서 매우 흔합니다.","x":["construido: '지어진'으로 월세 문제와 연결되지 않습니다 ✗","compartido: '공유된'으로 함께 살며 월세를 나눈다는 뜻이 되어 정답 ✓","repartido: '분배된'으로 piso와 함께 쓰지 않습니다 ✗","destruido: '파괴된'으로 맞지 않습니다 ✗"]},{"id":"V510","q":"José Luis siempre ha sido muy ____, no se conforma con poco.","o":["desvergonzado","manipulador","ambicioso","incompetente"],"a":2,"k":"성격 형용사","t":"호세 루이스는 늘 매우 야망이 컸다, 적은 것에 만족하지 않는다.","e":"'no se conforma con poco(적은 것에 만족하지 않는다)'는 ambicioso(야망 있는, 욕심 많은) 사람의 특징입니다. conformarse con ~은 '~에 만족하다, 감수하다'입니다.","x":["desvergonzado: '뻔뻔한'으로 뒤 설명과 연결되지 않습니다 ✗","manipulador: '남을 조종하는'으로 맞지 않습니다 ✗","ambicioso: '야망 있는'으로 적은 것에 만족하지 않는 성격과 맞아 정답 ✓","incompetente: '무능한'으로 맞지 않습니다 ✗"]},{"id":"V511","q":"Cuando la cantante salió al ____, el público aplaudió con entusiasmo.","o":["salón","escenario","patio","aula"],"a":1,"k":"공연 어휘","t":"가수가 무대에 나오자 관객들이 열광적으로 박수를 쳤다.","e":"escenario는 '무대'로 가수나 배우가 공연하는 곳입니다. 'salir al escenario'는 '무대에 오르다/나오다'입니다. público(관객), aplaudir(박수 치다)도 함께 기억해 두세요.","x":["salón: '거실, 홀'로 공연 무대가 아닙니다 ✗","escenario: '무대'로 가수가 나와 관객이 박수 치는 곳이라 정답 ✓","patio: '안뜰, 마당'으로 맞지 않습니다 ✗","aula: '교실'로 맞지 않습니다 ✗"]},{"id":"V512","q":"El ____ que cubre mi cama es perfecto para el invierno.","o":["sillón","perchero","edredón","zapatero"],"a":2,"k":"침구 어휘","t":"내 침대를 덮고 있는 솜이불은 겨울에 딱이다.","e":"edredón은 '두꺼운 솜이불, 깃털 이불'로 침대를 덮는 것입니다. 겨울에 따뜻하게 덮기 좋습니다. 관련 어휘: sábana(시트), almohada(베개), manta(담요).","x":["sillón: '안락의자'로 침대를 덮지 않습니다 ✗","perchero: '옷걸이 스탠드'로 맞지 않습니다 ✗","edredón: '솜이불'로 침대를 덮고 겨울에 좋아 정답 ✓","zapatero: '신발장'으로 맞지 않습니다 ✗"]},{"id":"V513","q":"Una ____ cuenta con detalle la vida de una persona.","o":["biografía","historia","carta de presentación","infografía"],"a":0,"k":"글의 종류","t":"전기는 한 사람의 생애를 자세히 이야기한다.","e":"biografía는 '전기(어떤 사람의 일생을 기록한 글)'입니다. bio(생명)+grafía(기록)로 이루어진 말입니다. 자신이 쓴 전기는 autobiografía(자서전)라고 합니다.","x":["biografía: '전기'로 한 사람의 생애를 다루므로 정답 ✓","historia: '역사, 이야기'로 한 사람의 생애에 한정되지 않습니다 ✗","carta de presentación: '자기소개서(커버레터)'로 생애 전체를 자세히 다루지 않습니다 ✗","infografía: '인포그래픽'으로 정보를 그림으로 보여 주는 것입니다 ✗"]},{"id":"V514","q":"A pesar de que estuvimos hablando durante horas, no ____ a ninguna conclusión.","o":["llegamos","fuimos","marchamos","vinimos"],"a":0,"k":"llegar a 표현","t":"몇 시간 동안 이야기했는데도 우리는 아무런 결론에 이르지 못했다.","e":"'llegar a una conclusión'은 '결론에 이르다/도달하다'라는 고정 표현입니다. 'llegar a un acuerdo(합의에 이르다)'도 같은 형태입니다. 'A pesar de que ~'는 '~에도 불구하고'입니다.","x":["llegamos: llegar a una conclusión(결론에 이르다)이 되어 정답 ✓","fuimos: ir a una conclusión이라고 하지 않습니다 ✗","marchamos: marchar(떠나다)는 결론과 쓰지 않습니다 ✗","vinimos: venir a una conclusión은 쓰지 않는 표현입니다 ✗"]},{"id":"V515","q":"Como no me apetece ____ por la noche, suelo prepararme un sándwich.","o":["cocinar","tender","fregar","barrer"],"a":0,"k":"집안일 동사","t":"밤에는 요리하고 싶지 않아서 보통 샌드위치를 만들어 먹는다.","e":"cocinar는 '요리하다'입니다. 요리하기 싫어서 간단한 샌드위치를 만든다는 흐름입니다. 'apetecer'는 gustar처럼 'me apetece + 동사원형(~하고 싶다)'으로 씁니다. 'soler + 동사원형'은 '보통 ~하다'입니다.","x":["cocinar: '요리하다'로 샌드위치로 대신한다는 흐름에 맞아 정답 ✓","tender: '(빨래를) 널다'로 저녁 식사와 관련 없습니다 ✗","fregar: '(설거지·바닥을) 닦다'로 샌드위치와 연결되지 않습니다 ✗","barrer: '(빗자루로) 쓸다'로 맞지 않습니다 ✗"]},{"id":"V516","q":"¿Por qué están todas las luces de la casa ____? Solo necesitamos una.","o":["apagadas","encendidas","cambiadas","abiertas"],"a":1,"k":"encender 동사","t":"왜 집의 불이 다 켜져 있어? 하나만 있으면 되잖아.","e":"encendido/a는 encender(켜다)의 과거분사로 '켜져 있는'이라는 뜻입니다. '하나만 필요하다'고 했으니 불이 모두 켜져 있는 상황입니다. 반대말은 apagado/a(꺼진)입니다. 'estar + 과거분사'는 상태를 나타냅니다.","x":["apagadas: '꺼진'으로 '하나만 필요하다'와 맞지 않습니다 ✗","encendidas: '켜진'으로 불이 다 켜져 있다는 불평이 되어 정답 ✓","cambiadas: '교체된'으로 뒤 문장과 맞지 않습니다 ✗","abiertas: '열린'으로 불(luces)에는 쓰지 않습니다 ✗"]},{"id":"V517","q":"Los periodistas insistieron con sus preguntas, pero el famoso atleta no quiso hacer ____.","o":["declaraciones","explicaciones","invitaciones","excepciones"],"a":0,"k":"hacer declaraciones","t":"기자들은 계속 질문을 했지만, 그 유명한 육상 선수는 아무 발언도 하려 하지 않았다.","e":"'hacer declaraciones'는 '(언론에) 발언하다, 성명을 내다'라는 표현입니다. 기자(periodistas)와 함께 자주 쓰입니다. 'no quiso'는 querer의 단순과거로 '~하려 하지 않았다(거부했다)'는 뜻입니다.","x":["declaraciones: '발언, 성명'으로 기자들의 질문에 답하는 상황에 맞아 정답 ✓","explicaciones: '설명'으로 hacer와 쓰기 어색하고 보통 dar explicaciones라고 합니다 ✗","invitaciones: '초대'로 맞지 않습니다 ✗","excepciones: '예외'로 맞지 않습니다 ✗"]},{"id":"V518","q":"En mi jardín hay muchas ____, entre otros tipos de flores.","o":["nueces","margaritas","fresas","manzanas"],"a":1,"k":"꽃 어휘","t":"우리 집 정원에는 여러 종류의 꽃들 중에서도 데이지가 많다.","e":"margarita는 '데이지(마거리트) 꽃'입니다. 'entre otros tipos de flores(다른 종류의 꽃들 중에서)'라고 했으니 꽃 이름이 와야 합니다. 다른 꽃: rosa(장미), girasol(해바라기), tulipán(튤립).","x":["nueces: '호두'로 견과류입니다 ✗","margaritas: '데이지'로 꽃이라서 정답 ✓","fresas: '딸기'로 과일입니다 ✗","manzanas: '사과'로 과일입니다 ✗"]},{"id":"V519","q":"Os ____ por vuestro proyecto, es magnífico.","o":["desprecio","felicito","reprendo","acepto"],"a":1,"k":"felicitar 동사","t":"너희 프로젝트 정말 훌륭하다, 축하해.","e":"felicitar는 '축하하다, 칭찬하다'라는 뜻입니다. 'felicitar a alguien por ~'는 '~에 대해 누구를 축하하다'입니다. os는 vosotros(너희, 스페인)의 목적격 대명사입니다. 중남미에서는 'Los felicito'라고 합니다.","x":["desprecio: despreciar(경멸하다)는 '훌륭하다'와 모순됩니다 ✗","felicito: felicitar(축하하다)로 훌륭한 프로젝트를 칭찬하는 문맥에 맞아 정답 ✓","reprendo: reprender(꾸짖다)는 문맥과 반대입니다 ✗","acepto: aceptar(받아들이다)는 'por vuestro proyecto'와 어울리지 않습니다 ✗"]},{"id":"V520","q":"Tengo un grupo de amigos ____, cada uno es de un país diferente.","o":["multicultural","individual","temporal","provisional"],"a":0,"k":"multicultural","t":"나에게는 다문화 친구 그룹이 있는데, 각자 다른 나라 출신이다.","e":"multicultural은 '다문화의'라는 뜻으로 multi(여럿)+cultural(문화의)입니다. 친구들이 서로 다른 나라 출신이라는 설명과 딱 맞습니다. -al로 끝나는 형용사는 남녀 형태가 같습니다.","x":["multicultural: '다문화의'로 각기 다른 나라 출신 친구들에 맞아 정답 ✓","individual: '개인의'로 그룹과 모순됩니다 ✗","temporal: '일시적인'으로 국적 설명과 맞지 않습니다 ✗","provisional: '임시의'로 맞지 않습니다 ✗"]},{"id":"V521","q":"John ____ bastante bien el español, por eso no se siente inseguro al hablarlo.","o":["desconoce","encuentra","cuida","domina"],"a":3,"k":"dominar 동사","t":"존은 스페인어를 꽤 잘 구사해서 말할 때 자신감이 없지 않다.","e":"dominar는 '지배하다'라는 뜻도 있지만, 언어와 함께 쓰면 '능숙하게 구사하다, 마스터하다'라는 뜻입니다. 예: Domina tres idiomas.(그는 3개 언어를 능숙하게 한다.)","x":["desconoce: desconocer(모르다)는 자신감 있다는 뒤 내용과 모순됩니다 ✗","encuentra: encontrar(찾다)는 언어 실력과 관련 없습니다 ✗","cuida: cuidar(돌보다)는 언어와 어울리지 않습니다 ✗","domina: dominar(능숙하게 구사하다)로 자신감 있게 말한다는 내용과 맞아 정답 ✓"]},{"id":"V522","q":"Voy a la ____ a comprar merluza y atún.","o":["pescadería","farmacia","carnicería","frutería"],"a":0,"k":"가게 어휘","t":"메를루사와 참치를 사러 생선 가게에 간다.","e":"merluza(대구류 생선)와 atún(참치)은 생선이므로 pescadería(생선 가게)에서 삽니다. 가게 이름은 보통 '-ería'로 끝납니다: carnicería(정육점), frutería(과일 가게), panadería(빵집).","x":["pescadería: '생선 가게'로 생선을 사는 곳이라 정답 ✓","farmacia: '약국'으로 맞지 않습니다 ✗","carnicería: '정육점'으로 고기를 파는 곳입니다 ✗","frutería: '과일 가게'로 맞지 않습니다 ✗"]},{"id":"V523","q":"En invierno me gusta dormir tapado con una ____ para no tener frío.","o":["bota","bufanda","manta","falda"],"a":2,"k":"침구 어휘 manta","t":"겨울에는 춥지 않게 담요를 덮고 자는 것을 좋아한다.","e":"manta는 '담요'로 잘 때 덮거나 소파에서 덮는 것입니다. 'tapado con ~'은 '~을 덮고'라는 뜻입니다. 중남미 일부에서는 cobija, frazada라고도 합니다.","x":["bota: '부츠'로 잘 때 덮지 않습니다 ✗","bufanda: '목도리'로 잘 때 덮는 것이 아닙니다 ✗","manta: '담요'로 잘 때 덮어 따뜻하게 하는 것이라 정답 ✓","falda: '치마'로 맞지 않습니다 ✗"]},{"id":"V524","q":"Mi coche no puede pasar por esa calle tan ____.","o":["larga","corta","ancha","estrecha"],"a":3,"k":"형용사 estrecho","t":"내 차는 그렇게 좁은 길은 지나갈 수 없다.","e":"차가 지나갈 수 없는 길은 estrecha(좁은) 길입니다. 반대말은 ancho/a(넓은)입니다. 'tan + 형용사'는 '그렇게 ~한'이라는 뜻입니다.","x":["larga: '긴'으로 지나갈 수 없는 이유가 되지 않습니다 ✗","corta: '짧은'으로 지나갈 수 없는 이유가 되지 않습니다 ✗","ancha: '넓은'으로 문맥과 반대입니다 ✗","estrecha: '좁은'으로 차가 못 지나가는 이유가 되어 정답 ✓"]},{"id":"V525","q":"Prefiero pagar una ____ plana, independientemente del número de llamadas que haga.","o":["cantidad","paga","tarifa","tasa"],"a":2,"k":"tarifa plana","t":"통화 횟수와 상관없이 정액 요금제를 내는 게 더 좋다.","e":"'tarifa plana'는 '정액 요금제(사용량과 상관없이 일정 금액을 내는 요금)'입니다. tarifa는 '요금, 요금표'를 뜻합니다. 휴대폰·인터넷 요금제에서 자주 쓰는 표현입니다.","x":["cantidad: '양, 금액'으로 plana와 함께 쓰지 않습니다 ✗","paga: '급여, 용돈'으로 맞지 않습니다 ✗","tarifa: '요금'으로 tarifa plana(정액제)가 되어 정답 ✓","tasa: '세금, 비율'로 tasa plana라고 하지 않습니다 ✗"]},{"id":"V526","q":"Busco alojamiento con ____ incluido, voy a viajar en mi auto.","o":["baño","aparcamiento","desayuno","almuerzo"],"a":1,"k":"숙박 어휘","t":"내 차로 여행할 거라서 주차장이 포함된 숙소를 찾고 있다.","e":"차로 여행하면 aparcamiento(주차장)가 필요합니다. aparcar는 스페인에서 '주차하다'이고, 중남미에서는 estacionamiento / estacionar를 많이 씁니다. 'con ~ incluido'는 '~이 포함된'입니다.","x":["baño: '욕실'은 차와 관련이 없습니다 ✗","aparcamiento: '주차장'으로 차로 여행하는 이유와 연결되어 정답 ✓","desayuno: '아침 식사'는 차와 관련이 없습니다 ✗","almuerzo: '점심 식사'는 차와 관련이 없습니다 ✗"]},{"id":"V527","q":"¿En qué ____ debo llevar el anillo de casada?","o":["brazo","mano","pierna","dedo"],"a":3,"k":"신체 어휘","t":"결혼반지는 어느 손가락에 껴야 하나요?","e":"반지(anillo)는 dedo(손가락)에 낍니다. 손가락 이름: pulgar(엄지), índice(검지), corazón(중지), anular(약지), meñique(새끼). 결혼반지는 보통 dedo anular(약지)에 낍니다.","x":["brazo: '팔'로 반지를 끼는 곳이 아닙니다 ✗","mano: '손'이지만 반지는 손가락에 끼므로 dedo가 더 정확합니다 ✗","pierna: '다리'로 맞지 않습니다 ✗","dedo: '손가락'으로 반지를 끼는 곳이라 정답 ✓"]},{"id":"V528","q":"Hoy estás muy ____, no has dicho ni una palabra en todo el día.","o":["hablador","animado","callado","charlatán"],"a":2,"k":"성격·상태 형용사","t":"오늘 너 정말 말이 없네, 하루 종일 한마디도 안 했어.","e":"하루 종일 한마디도 하지 않았으니 callado(말이 없는, 조용한)입니다. callarse(입을 다물다)에서 나온 말입니다. 'estar callado'는 오늘의 상태, 'ser callado'는 원래 성격이 과묵함을 나타냅니다.","x":["hablador: '수다스러운'으로 문맥과 반대입니다 ✗","animado: '활기찬'으로 뒤 내용과 맞지 않습니다 ✗","callado: '말이 없는'으로 한마디도 안 했다는 내용과 맞아 정답 ✓","charlatán: '말 많은, 수다쟁이'로 문맥과 반대입니다 ✗"]},{"id":"V529","q":"Trabajamos en una ____ de productos cárnicos.","o":["empresa","residencia","habitación","vivienda"],"a":0,"k":"empresa 회사","t":"우리는 육가공 제품 회사에서 일한다.","e":"empresa는 '회사, 기업'입니다. 'trabajar en una empresa'는 '회사에서 일하다'라는 기본 표현입니다. cárnico는 '고기의'라는 뜻으로 'productos cárnicos'는 '육류 제품'입니다.","x":["empresa: '회사'로 제품을 만드는 일터라 정답 ✓","residencia: '거주지, 기숙사, 요양원'으로 제품 생산과 맞지 않습니다 ✗","habitación: '방'으로 맞지 않습니다 ✗","vivienda: '주택'으로 맞지 않습니다 ✗"]},{"id":"V530","q":"Augusto y yo ya no estamos juntos, ____ hace un mes.","o":["nos unimos","nos casamos","salimos","rompimos"],"a":3,"k":"romper 헤어지다","t":"아우구스토와 나는 더 이상 사귀지 않아, 한 달 전에 헤어졌어.","e":"romper는 '깨다'라는 뜻이지만, 연인 관계에서는 '헤어지다'라는 의미로 씁니다. 'romper con alguien(누구와 헤어지다)'처럼 씁니다. 'hace + 기간'은 '~ 전에'입니다.","x":["nos unimos: unirse(결합하다)는 헤어졌다는 내용과 반대입니다 ✗","nos casamos: casarse(결혼하다)는 문맥과 반대입니다 ✗","salimos: salir는 '사귀다'라는 뜻이라 문맥과 반대입니다 ✗","rompimos: romper(헤어지다)로 더 이상 함께하지 않는다는 내용과 맞아 정답 ✓"]},{"id":"V531","q":"No es normal que ____ todo tu dinero en tonterías.","o":["pongas","uses","gastes","tengas"],"a":2,"k":"gastar 동사","t":"네가 쓸데없는 것에 돈을 다 써 버리는 건 정상이 아니야.","e":"gastar는 '(돈을) 쓰다, 소비하다'입니다. 'gastar dinero en ~'은 '~에 돈을 쓰다'라는 표현입니다. 'No es normal que + 접속법' 구조라서 gastes(접속법 현재)가 쓰였습니다. tontería는 '바보 같은 것, 쓸데없는 것'입니다.","x":["pongas: poner(놓다)는 'dinero en tonterías'와 어울리지 않습니다 ✗","uses: usar(사용하다)는 돈 소비에 쓰기 어색합니다 ✗","gastes: gastar(돈을 쓰다)로 gastar dinero en ~ 표현이 되어 정답 ✓","tengas: tener(가지다)는 의미가 통하지 않습니다 ✗"]},{"id":"V532","q":"Soy tu madre, así que ____ y no me contestes.","o":["déjame","ignórame","olvídame","obedéceme"],"a":3,"k":"obedecer 동사","t":"나는 네 엄마야, 그러니 말 잘 듣고 말대꾸하지 마.","e":"obedecer는 '복종하다, 말을 듣다'라는 뜻입니다. 명령형 obedece에 목적격 대명사 me가 붙어 obedéceme(내 말을 들어라)가 되었고, 강세 위치를 유지하려고 악센트가 붙습니다. contestar는 여기서 '말대꾸하다'의 의미입니다.","x":["déjame: '나를 내버려 둬'로 엄마의 권위와 맞지 않습니다 ✗","ignórame: '나를 무시해'로 문맥과 반대입니다 ✗","olvídame: '나를 잊어'로 맞지 않습니다 ✗","obedéceme: '내 말을 들어'로 엄마로서의 명령에 맞아 정답 ✓"]},{"id":"V533","q":"¿Puedes pasarme el ____, por favor? La carne está sosa.","o":["salero","azucarero","colador","mantel"],"a":0,"k":"식탁 어휘","t":"소금통 좀 건네줄래? 고기가 싱거워.","e":"soso/a는 '싱거운, 맛이 밍밍한'이라는 뜻입니다. 싱거우면 소금이 필요하니 salero(소금통)를 달라고 합니다. -ero는 담는 그릇을 나타냅니다: azucarero(설탕통), servilletero(냅킨꽂이).","x":["salero: '소금통'으로 싱거운 고기에 필요해 정답 ✓","azucarero: '설탕통'으로 고기 간을 맞추는 데 쓰지 않습니다 ✗","colador: '체, 거름망'으로 맞지 않습니다 ✗","mantel: '식탁보'로 맞지 않습니다 ✗"]},{"id":"V534","q":"El plástico es un ____ más ligero que el hierro.","o":["valor","material","objeto","factor"],"a":1,"k":"material 어휘","t":"플라스틱은 철보다 가벼운 재료이다.","e":"material은 '재료, 소재'입니다. 플라스틱(plástico)과 철(hierro)은 모두 물건을 만드는 재료입니다. 'más + 형용사 + que'는 비교급(~보다 더 …한)입니다.","x":["valor: '가치'로 플라스틱을 설명하기에 맞지 않습니다 ✗","material: '재료, 소재'로 플라스틱과 철을 비교하는 문맥에 맞아 정답 ✓","objeto: '물건'으로 플라스틱 자체는 물건이 아니라 재료입니다 ✗","factor: '요인'으로 맞지 않습니다 ✗"]},{"id":"V535","q":"Andrea trabaja como ____ de vuelo en una compañía aérea española.","o":["participante","colaboradora","cooperante","auxiliar"],"a":3,"k":"auxiliar de vuelo","t":"안드레아는 스페인 항공사에서 승무원으로 일한다.","e":"'auxiliar de vuelo'는 '객실 승무원'입니다. auxiliar는 '보조원'이라는 뜻으로 auxiliar administrativo(사무 보조원)처럼도 씁니다. azafata, sobrecargo도 승무원을 뜻합니다.","x":["participante: '참가자'로 직업이 아닙니다 ✗","colaboradora: '협력자'로 de vuelo와 함께 쓰지 않습니다 ✗","cooperante: '(해외) 봉사 활동가'로 맞지 않습니다 ✗","auxiliar: auxiliar de vuelo(객실 승무원)가 되어 정답 ✓"]},{"id":"V536","q":"Este café está ____, le puse sal en vez de azúcar.","o":["delicioso","malísimo","muy rico","buenísimo"],"a":1,"k":"맛 형용사","t":"이 커피는 정말 맛없어, 설탕 대신 소금을 넣었거든.","e":"설탕 대신 소금을 넣었으니 커피 맛이 malísimo(아주 나쁜, 정말 맛없는)입니다. -ísimo는 '매우 ~한'을 나타내는 절대최상급입니다: malo → malísimo, bueno → buenísimo.","x":["delicioso: '맛있는'으로 소금을 넣은 커피와 반대입니다 ✗","malísimo: '정말 맛없는'으로 소금을 넣은 결과에 맞아 정답 ✓","muy rico: '아주 맛있는'으로 반대입니다 ✗","buenísimo: '정말 맛있는'으로 반대입니다 ✗"]},{"id":"V537","q":"Para secar los platos uso este ____ de cocina.","o":["trapo","detergente","limpiador","estropajo"],"a":0,"k":"주방 용품 어휘","t":"접시를 말리려고 나는 이 행주를 쓴다.","e":"trapo는 '헝겊, 걸레'이고 'trapo de cocina'는 '행주'입니다. secar는 '말리다, 닦아 물기를 없애다'입니다. 설거지할 때 쓰는 수세미는 estropajo입니다.","x":["trapo: '행주, 헝겊'으로 접시 물기를 닦는 데 써서 정답 ✓","detergente: '세제'로 말리는 데 쓰지 않습니다 ✗","limpiador: '세정제'로 말리는 데 쓰지 않습니다 ✗","estropajo: '수세미'로 씻을 때 쓰지 말릴 때 쓰지 않습니다 ✗"]},{"id":"V538","q":"Están ____ porque han estado trabajando todo el día sin pausa.","o":["animados","emocionados","entusiasmados","exhaustos"],"a":3,"k":"상태 형용사","t":"그들은 쉬지 않고 하루 종일 일했기 때문에 기진맥진하다.","e":"exhausto/a는 '녹초가 된, 기진맥진한'으로 cansado(피곤한)보다 강한 말입니다. 쉬지 않고(sin pausa) 일했으니 매우 지친 상태입니다. estar와 함께 상태를 나타냅니다.","x":["animados: '활기찬'으로 문맥과 반대입니다 ✗","emocionados: '감동한, 들뜬'으로 맞지 않습니다 ✗","entusiasmados: '열광한'으로 맞지 않습니다 ✗","exhaustos: '기진맥진한'으로 쉬지 않고 일한 결과에 맞아 정답 ✓"]},{"id":"V539","q":"Las ____ son mis legumbres preferidas.","o":["peras","galletas","papas","lentejas"],"a":3,"k":"음식 어휘","t":"렌틸콩은 내가 가장 좋아하는 콩류이다.","e":"legumbre는 '콩류'입니다. 보기 중 콩류는 lenteja(렌틸콩)뿐입니다. 다른 콩류: garbanzo(병아리콩), judía/frijol(강낭콩, frijol은 중남미). lentejas는 스페인 가정식 대표 메뉴이기도 합니다.","x":["peras: '배'로 과일입니다 ✗","galletas: '과자, 쿠키'로 맞지 않습니다 ✗","papas: '감자'(중남미·카나리아 제도; 스페인 본토는 patatas)로 콩류가 아닙니다 ✗","lentejas: '렌틸콩'으로 콩류라서 정답 ✓"]},{"id":"V540","q":"Si quieres tener el pelo largo, ¿para qué te lo ____?","o":["alisas","lavas","rizas","cortas"],"a":3,"k":"머리 손질 동사","t":"머리를 길게 기르고 싶다면 왜 자르는 거야?","e":"머리를 기르고 싶은데 cortar(자르다)하는 것은 모순이라 '¿para qué?(뭐 하러?)'라고 묻습니다. 'te lo cortas'에서 te는 재귀(자신의), lo는 el pelo를 가리킵니다.","x":["alisas: alisar(머리를 펴다)는 길이를 줄이지 않아 모순이 아닙니다 ✗","lavas: lavar(감다)는 길이와 관련 없습니다 ✗","rizas: rizar(곱슬하게 하다)는 길이와 관련 없습니다 ✗","cortas: cortar(자르다)로 기르고 싶다는 바람과 모순되어 정답 ✓"]},{"id":"V541","q":"Este pan está muy ____ para el bebé, todavía no tiene dientes.","o":["blando","duro","tostado","caliente"],"a":1,"k":"음식 상태 형용사","t":"이 빵은 아기에게 너무 딱딱해, 아직 이가 없거든.","e":"이가 없는 아기에게 문제가 되는 빵은 duro(딱딱한) 빵입니다. 'muy + 형용사 + para ~'는 '~에게는 너무 …하다'라는 뜻입니다. duro의 반대말은 blando(부드러운)입니다.","x":["blando: '부드러운'으로 이가 없는 아기에게 오히려 좋습니다 ✗","duro: '딱딱한'으로 이가 없는 아기가 먹기 힘들어 정답 ✓","tostado: '구운'은 이가 없다는 이유와 직접 연결되지 않습니다 ✗","caliente: '뜨거운'은 이가 없다는 이유와 관련 없습니다 ✗"]},{"id":"V542","q":"Cuidado, no pases por ahí, el suelo está ____ y te puedes caer.","o":["sucio","mojado","seco","limpio"],"a":1,"k":"상태 형용사","t":"조심해, 거기로 지나가지 마. 바닥이 젖어 있어서 넘어질 수 있어.","e":"mojado/a는 '젖은'이라는 뜻으로 mojar(적시다)의 과거분사입니다. 바닥이 젖어 있으면 미끄러워 넘어질 수 있습니다. 반대말은 seco(마른)입니다.","x":["sucio: '더러운'은 넘어지는 이유로 약합니다 ✗","mojado: '젖은'으로 미끄러져 넘어질 수 있어 정답 ✓","seco: '마른'으로 넘어질 이유가 없습니다 ✗","limpio: '깨끗한'으로 넘어질 이유가 없습니다 ✗"]},{"id":"V543","q":"Me voy a apuntar a una escuela de ____ para recibir clases de danza moderna.","o":["baile","idiomas","cocina","pintura"],"a":0,"k":"학원 어휘","t":"현대 무용 수업을 받으려고 댄스 학원에 등록할 거야.","e":"danza(무용) 수업은 escuela de baile(댄스 학원)에서 받습니다. baile는 '춤', bailar는 '춤추다'입니다. 'apuntarse a ~'는 '~에 등록하다, 신청하다'(스페인에서 자주 씀)입니다.","x":["baile: '춤'으로 무용 수업을 받는 학원이 되어 정답 ✓","idiomas: '외국어'로 무용과 관련 없습니다 ✗","cocina: '요리'로 맞지 않습니다 ✗","pintura: '그림'으로 맞지 않습니다 ✗"]},{"id":"V544","q":"Actualmente, casi todos los teléfonos fijos son ____.","o":["inalámbricos","impactantes","imprescindibles","irreparables"],"a":0,"k":"inalámbrico","t":"요즘은 거의 모든 유선 전화기가 무선이다.","e":"inalámbrico는 '무선의'라는 뜻으로 in(없는) + alambre(전선)에서 나온 말입니다. 'teléfono fijo(집 전화)'가 선 없이 쓰는 무선 전화기라는 뜻입니다. 'red inalámbrica'는 '무선 네트워크(와이파이)'입니다.","x":["inalámbricos: '무선의'로 전화기의 특징을 설명해 정답 ✓","impactantes: '충격적인'으로 전화기 설명에 맞지 않습니다 ✗","imprescindibles: '필수적인'으로 actualmente(요즘)와 함께 쓰면 문맥상 어색합니다 ✗","irreparables: '수리할 수 없는'으로 맞지 않습니다 ✗"]},{"id":"V545","q":"El ____ de este evento es recaudar fondos para ayudar a los niños que están hospitalizados.","o":["test","estudio","intento","objetivo"],"a":3,"k":"objetivo 목적","t":"이 행사의 목적은 입원한 아이들을 돕기 위한 기금을 모으는 것이다.","e":"objetivo는 '목적, 목표'라는 뜻입니다. 'El objetivo de ~ es + 동사원형'은 '~의 목적은 …하는 것이다'라는 구조입니다. recaudar fondos는 '기금을 모으다'입니다.","x":["test: '테스트'로 행사의 목적을 설명하지 못합니다 ✗","estudio: '연구, 공부'로 맞지 않습니다 ✗","intento: '시도'로 맞지 않습니다 ✗","objetivo: '목적'으로 행사의 목적을 설명해 정답 ✓"]},{"id":"V546","q":"En esta ____ web hay muchos ejercicios de portugués.","o":["página","mesa","hoja","lámina"],"a":0,"k":"página web","t":"이 웹사이트에는 포르투갈어 연습 문제가 많다.","e":"'página web'은 '웹페이지, 웹사이트'입니다. página는 책의 '쪽, 페이지'라는 뜻도 있습니다. 'sitio web'도 같은 뜻으로 씁니다.","x":["página: página web(웹사이트)이 되어 정답 ✓","mesa: '탁자'로 맞지 않습니다 ✗","hoja: '종이 한 장, 잎'으로 hoja web라고 하지 않습니다 ✗","lámina: '얇은 판, 삽화'로 맞지 않습니다 ✗"]},{"id":"V547","q":"Elisa está muy ____ desde que hace dieta. Ha perdido ocho kilos.","o":["gorda","delgada","baja","alta"],"a":1,"k":"외모 형용사","t":"엘리사는 다이어트를 한 뒤로 아주 날씬해졌다. 8킬로그램이 빠졌다.","e":"다이어트로 8kg이 빠졌으니 delgada(날씬한)입니다. 반대말은 gordo/a(뚱뚱한)입니다. 'estar delgada'는 변화된 현재 상태를 나타내서 estar를 씁니다.","x":["gorda: '뚱뚱한'으로 살이 빠졌다는 내용과 반대입니다 ✗","delgada: '날씬한'으로 8kg이 빠진 결과에 맞아 정답 ✓","baja: '키가 작은'으로 다이어트와 관련 없습니다 ✗","alta: '키가 큰'으로 다이어트와 관련 없습니다 ✗"]},{"id":"V548","q":"¡Vaya ____ hay en esta habitación! Recogedlo todo ahora mismo.","o":["desorden","desproporción","desigualdad","desequilibrio"],"a":0,"k":"desorden","t":"이 방 정말 엉망이구나! 지금 당장 다 치워.","e":"desorden은 '무질서, 어지러움'으로 orden(질서, 정리)에 반대를 나타내는 des-가 붙은 말입니다. '¡Vaya + 명사!'는 '정말 ~구나!'라는 감탄 표현입니다. recoger는 '치우다, 정리하다'이고 recogedlo는 vosotros 명령형입니다.","x":["desorden: '어지러움, 엉망'으로 치우라는 명령과 맞아 정답 ✓","desproporción: '불균형(비율)'으로 방 상태에 쓰지 않습니다 ✗","desigualdad: '불평등'으로 맞지 않습니다 ✗","desequilibrio: '불균형'으로 방이 어질러진 상태에 쓰지 않습니다 ✗"]},{"id":"V549","q":"Las pinturas de esta artista son muy originales, su estilo es ____.","o":["creíble","imposible","irresistible","inconfundible"],"a":3,"k":"inconfundible","t":"이 화가의 그림들은 아주 독창적이어서, 그녀의 스타일은 착각할 수 없을 만큼 독특하다.","e":"inconfundible은 'in(아닌) + confundir(혼동하다) + -ible(~할 수 있는)'로 '혼동할 수 없는, 한눈에 알아볼 수 있는'이라는 뜻입니다. 독창적인(originales) 그림이라 누구 작품인지 바로 알 수 있다는 의미입니다.","x":["creíble: '믿을 만한'으로 스타일 설명에 어색합니다 ✗","imposible: '불가능한'으로 맞지 않습니다 ✗","irresistible: '거부할 수 없는'으로 독창성과 직접 연결되지 않습니다 ✗","inconfundible: '한눈에 알아볼 수 있는'으로 독창적인 스타일에 맞아 정답 ✓"]},{"id":"V550","q":"Según el ____ del tiempo, mañana va a llover y va a hacer frío.","o":["proyecto","plan","pronóstico","periódico"],"a":2,"k":"날씨 어휘","t":"일기예보에 따르면 내일 비가 오고 추울 것이다.","e":"'pronóstico del tiempo'는 '일기예보'입니다. pronóstico는 '예측, 예보'라는 뜻입니다. 'según ~'은 '~에 따르면'입니다. 'el tiempo'는 여기서 '시간'이 아니라 '날씨'입니다.","x":["proyecto: '프로젝트, 계획'으로 날씨와 쓰지 않습니다 ✗","plan: '계획'으로 날씨와 쓰지 않습니다 ✗","pronóstico: '예보'로 pronóstico del tiempo(일기예보)가 되어 정답 ✓","periódico: '신문'으로 'periódico del tiempo'라고 하지 않습니다 ✗"]},{"id":"V551","q":"____ son vehículos de dos ruedas.","o":["Los triciclos","Los aviones","Las bicis","Los trenes"],"a":2,"k":"교통수단 어휘","t":"자전거는 바퀴가 두 개인 탈것이다.","e":"bici는 bicicleta(자전거)의 줄임말입니다. bi(둘)라는 접두사처럼 바퀴(rueda)가 두 개입니다. triciclo는 tri(셋)로 세발자전거입니다. 줄임말이어도 여성명사라 las bicis입니다.","x":["Los triciclos: '세발자전거'로 바퀴가 세 개입니다 ✗","Los aviones: '비행기'로 두 바퀴 탈것이 아닙니다 ✗","Las bicis: '자전거'로 바퀴가 두 개라서 정답 ✓","Los trenes: '기차'로 맞지 않습니다 ✗"]},{"id":"V552","q":"Cuando tuve el ____ en mi ordenador, no podía acceder a mis archivos.","o":["ratón","virus","correo","teclado"],"a":1,"k":"컴퓨터 어휘","t":"내 컴퓨터에 바이러스가 걸렸을 때 파일에 접근할 수 없었다.","e":"virus는 '(컴퓨터) 바이러스'로 파일 접근을 막는 등 문제를 일으킵니다. 단수·복수 형태가 같습니다(el virus, los virus). 'tener un virus'는 '바이러스에 걸리다'입니다.","x":["ratón: '마우스'는 있다고 파일 접근이 막히지 않습니다 ✗","virus: '바이러스'로 파일에 접근할 수 없는 원인이 되어 정답 ✓","correo: '메일'은 파일 접근을 막는 원인이 아닙니다 ✗","teclado: '키보드'는 문맥에 맞지 않습니다 ✗"]},{"id":"V553","q":"El medio de transporte que más uso es el ____.","o":["semáforo","cinturón de seguridad","atasco","coche"],"a":3,"k":"교통 어휘","t":"내가 가장 많이 이용하는 교통수단은 자동차다.","e":"medio de transporte(교통수단)에 해당하는 것은 coche(자동차)뿐입니다. coche는 스페인, carro/auto는 중남미에서 많이 씁니다. 나머지 보기는 교통 관련 어휘이지만 탈것이 아닙니다.","x":["semáforo: '신호등'으로 교통수단이 아닙니다 ✗","cinturón de seguridad: '안전벨트'로 교통수단이 아닙니다 ✗","atasco: '교통 체증'으로 교통수단이 아닙니다 ✗","coche: '자동차'로 교통수단이라 정답 ✓"]},{"id":"V554","q":"Este vestido me queda ____, necesito una talla más.","o":["grande","suelto","genial","apretado"],"a":3,"k":"옷 사이즈 표현","t":"이 원피스는 나한테 꽉 껴, 한 치수 큰 게 필요해.","e":"apretado/a는 '꽉 끼는'이라는 뜻입니다. 한 사이즈 큰 것(una talla más)이 필요하다면 지금 옷이 작아서 끼는 것이죠. 'quedar + 형용사'는 '(옷이) ~하게 맞다'라는 표현입니다: Me queda grande.(나한테 커.)","x":["grande: '큰'이면 더 큰 사이즈가 필요 없습니다 ✗","suelto: '헐렁한'이면 더 큰 사이즈가 필요 없습니다 ✗","genial: '아주 좋은'이면 다른 사이즈가 필요 없습니다 ✗","apretado: '꽉 끼는'으로 큰 사이즈가 필요한 이유가 되어 정답 ✓"]},{"id":"V555","q":"El vecino está molesto con nosotros porque nuestro perro ____ mucho.","o":["relincha","pía","maúlla","ladra"],"a":3,"k":"동물 소리 동사","t":"우리 개가 많이 짖어서 이웃이 우리에게 화가 나 있다.","e":"ladrar는 '(개가) 짖다'입니다. 동물마다 소리 동사가 다릅니다: relinchar(말이 울다), piar(새가 짹짹거리다), maullar(고양이가 야옹하다).","x":["relincha: relinchar는 말이 우는 소리입니다 ✗","pía: piar는 새가 짹짹거리는 소리입니다 ✗","maúlla: maullar는 고양이가 우는 소리입니다 ✗","ladra: ladrar(짖다)로 개의 소리라서 정답 ✓"]},{"id":"V556","q":"Estuvo varias horas al sol sin ____, por eso tiene la cara roja.","o":["gorra","camisón","chaleco","cinturón"],"a":0,"k":"모자 어휘","t":"모자 없이 몇 시간 동안 햇볕 아래 있어서 얼굴이 빨갛다.","e":"gorra는 '챙이 있는 모자(캡)'로 햇볕으로부터 얼굴을 가려 줍니다. 모자를 쓰지 않아 얼굴이 탔다는 내용입니다. 참고: gorro는 '털모자, 챙 없는 모자', sombrero는 '챙이 넓은 모자'입니다.","x":["gorra: '캡 모자'로 얼굴을 햇볕에서 가려 주므로 정답 ✓","camisón: '잠옷(원피스형)'으로 맞지 않습니다 ✗","chaleco: '조끼'로 얼굴을 보호하지 않습니다 ✗","cinturón: '벨트'로 맞지 않습니다 ✗"]},{"id":"V557","q":"Es un ____ hablar con Sonia, tiene un carácter muy alegre.","o":["rollo","lío","logro","placer"],"a":3,"k":"ser un placer","t":"소니아와 이야기하는 것은 즐거운 일이다, 그녀는 성격이 아주 밝다.","e":"'Es un placer + 동사원형'은 '~하는 것은 즐거움이다'라는 표현입니다. placer는 '즐거움, 기쁨'으로 'Es un placer conocerte.(만나서 반가워.)'처럼 인사에도 씁니다.","x":["rollo: '지루한 것'(구어)으로 밝은 성격과 반대입니다 ✗","lío: '골칫거리, 혼란'으로 맞지 않습니다 ✗","logro: '성과, 업적'으로 대화와 어울리지 않습니다 ✗","placer: '즐거움'으로 밝은 사람과 이야기하는 문맥에 맞아 정답 ✓"]},{"id":"V558","q":"Tikal, en Guatemala, es una antigua ciudad maya con templos y pirámides ____.","o":["expectantes","alarmantes","agobiantes","impresionantes"],"a":3,"k":"impresionante","t":"과테말라의 티칼은 인상적인 신전과 피라미드가 있는 고대 마야 도시이다.","e":"impresionante는 '인상적인, 굉장한'이라는 뜻으로 경치나 건축물을 칭찬할 때 자주 씁니다. 티칼(Tikal)은 과테말라 정글 속의 대표적인 마야 유적입니다.","x":["expectantes: '기대하는'으로 사람의 상태에 쓰는 말입니다 ✗","alarmantes: '걱정스러운'으로 유적 묘사에 맞지 않습니다 ✗","agobiantes: '숨 막히는, 답답한'으로 부정적입니다 ✗","impresionantes: '인상적인'으로 유적을 묘사하기에 맞아 정답 ✓"]},{"id":"V559","q":"____ duró varias horas. La lluvia y el viento causaron muchos problemas.","o":["El terremoto","La tormenta","El arcoíris","La sequía"],"a":1,"k":"자연 현상 어휘","t":"폭풍우가 몇 시간 동안 계속되었다. 비와 바람이 많은 문제를 일으켰다.","e":"lluvia(비)와 viento(바람)가 함께 오는 현상은 tormenta(폭풍우)입니다. durar는 '지속되다'입니다. 관련 어휘: terremoto(지진), sequía(가뭄), arcoíris(무지개).","x":["El terremoto: '지진'은 비·바람과 관련이 없습니다 ✗","La tormenta: '폭풍우'로 비와 바람이 함께 오는 현상이라 정답 ✓","El arcoíris: '무지개'는 문제를 일으키지 않습니다 ✗","La sequía: '가뭄'은 비가 오지 않는 것이라 반대입니다 ✗"]},{"id":"V560","q":"____ muchas ganas de ver a mis amigos, hace dos años que no hablo con ellos en persona.","o":["Doy","Tengo","Pongo","Hago"],"a":1,"k":"tener ganas de","t":"친구들을 정말 보고 싶어, 2년째 직접 만나서 이야기하지 못했어.","e":"'tener ganas de + 동사원형'은 '~하고 싶다'라는 아주 자주 쓰는 표현입니다. 'muchas ganas'로 '정말 하고 싶다'를 강조합니다. 예: Tengo ganas de comer pizza.(피자 먹고 싶어.)","x":["Doy: dar ganas는 'me dan ganas de ~(~하고 싶어진다)' 형태로 쓰며 이 구조와 맞지 않습니다 ✗","Tengo: tener ganas de(~하고 싶다)라는 고정 표현이 되어 정답 ✓","Pongo: poner ganas는 '열의를 쏟다'라는 뜻으로 de + 동사와 쓰지 않습니다 ✗","Hago: hacer ganas라고 하지 않습니다 ✗"]},{"id":"V561","q":"Estuvo en la ____ porque cometió varios delitos en su juventud.","o":["cueva","galería","residencia","cárcel"],"a":3,"k":"cárcel 교도소","t":"그는 젊은 시절 여러 범죄를 저질러서 교도소에 있었다.","e":"cárcel은 '감옥, 교도소'입니다. delito(범죄)를 저지르면 가는 곳이죠. 'cometer un delito'는 '범죄를 저지르다'라는 표현입니다. 비슷한 말로 prisión이 있습니다.","x":["cueva: '동굴'로 범죄와 관련 없습니다 ✗","galería: '화랑, 회랑'으로 맞지 않습니다 ✗","residencia: '거주지, 기숙사'로 맞지 않습니다 ✗","cárcel: '교도소'로 범죄를 저지른 결과라서 정답 ✓"]},{"id":"V562","q":"Los peatones deben ____ la calzada por el paso de cebra.","o":["tocar","rozar","saltar","cruzar"],"a":3,"k":"cruzar 동사","t":"보행자는 횡단보도로 차도를 건너야 한다.","e":"cruzar는 '건너다, 횡단하다'입니다. 'cruzar la calle(길을 건너다)'처럼 씁니다. paso de cebra는 '얼룩말 무늬 길', 즉 '횡단보도'이고 calzada는 '차도', peatón은 '보행자'입니다.","x":["tocar: '만지다'로 길과 맞지 않습니다 ✗","rozar: '스치다'로 맞지 않습니다 ✗","saltar: '뛰어넘다'로 보행자 규칙과 맞지 않습니다 ✗","cruzar: '건너다'로 횡단보도로 차도를 건너는 문맥에 맞아 정답 ✓"]},{"id":"V563","q":"El símbolo que separa las dos partes de un correo electrónico se llama ____.","o":["arroba","chat","página web","red"],"a":0,"k":"인터넷 어휘","t":"이메일 주소의 두 부분을 나누는 기호는 아로바(@)라고 한다.","e":"스페인어로 @ 기호는 arroba라고 합니다. 이메일 주소를 말할 때 'juan arroba gmail punto com'처럼 읽습니다. punto는 '점(.)'입니다.","x":["arroba: '@ 기호'로 이메일 주소를 나누는 기호라서 정답 ✓","chat: '채팅'으로 기호가 아닙니다 ✗","página web: '웹페이지'로 기호가 아닙니다 ✗","red: '네트워크'로 기호가 아닙니다 ✗"]},{"id":"V564","q":"Antonio ____ muy bien al tenis.","o":["crea","toma","juega","hace"],"a":2,"k":"jugar a","t":"안토니오는 테니스를 아주 잘 친다.","e":"운동 경기를 '하다'는 'jugar a + 정관사 + 경기'로 씁니다. a + el = al이 되어 'jugar al tenis'가 됩니다. 중남미에서는 'jugar tenis'처럼 a 없이 쓰기도 합니다. jugar 현재형: juego, juegas, juega.","x":["crea: crear(창조하다)는 운동과 쓰지 않습니다 ✗","toma: tomar(잡다, 먹다)는 운동과 쓰지 않습니다 ✗","juega: jugar al tenis(테니스를 치다)가 되어 정답 ✓","hace: hacer는 'hacer deporte'처럼 쓰지만 'hacer al tenis'는 틀립니다 ✗"]},{"id":"V565","q":"¿Cuántos pasajeros pasan a diario por este ____?","o":["quiosco","aeropuerto","comercio","museo"],"a":1,"k":"aeropuerto","t":"이 공항에는 하루에 몇 명의 승객이 지나가나요?","e":"pasajero는 '승객'이므로 많은 승객이 지나가는 곳은 aeropuerto(공항)입니다. 'a diario'는 '매일'이라는 뜻입니다. 관련 어휘: estación(역), puerto(항구).","x":["quiosco: '가판대'로 승객이 지나가는 곳이 아닙니다 ✗","aeropuerto: '공항'으로 승객이 매일 오가는 곳이라 정답 ✓","comercio: '상점, 상업'으로 승객과 맞지 않습니다 ✗","museo: '박물관'으로 방문객은 있어도 승객은 없습니다 ✗"]},{"id":"V566","q":"Somos una familia ____, tenemos cinco hijos.","o":["especial","rica","rara","numerosa"],"a":3,"k":"familia numerosa","t":"우리는 대가족이다, 아이가 다섯이다.","e":"'familia numerosa'는 '다자녀 가족, 대가족'입니다. numeroso는 '수가 많은'이라는 뜻입니다. 스페인에서는 자녀가 셋 이상인 가족을 법적으로 familia numerosa라 부르며 혜택을 줍니다.","x":["especial: '특별한'으로 자녀 수와 직접 연결되지 않습니다 ✗","rica: '부유한'으로 자녀 수와 관련 없습니다 ✗","rara: '이상한'으로 맞지 않습니다 ✗","numerosa: '수가 많은'으로 familia numerosa(다자녀 가족)가 되어 정답 ✓"]},{"id":"V567","q":"No ____ a ese perro, parece peligroso.","o":["te acerques","te adaptes","te acostumbres","te resistas"],"a":0,"k":"acercarse 동사","t":"그 개에게 가까이 가지 마, 위험해 보여.","e":"acercarse a ~는 '~에 가까이 가다, 다가가다'입니다. 부정 명령(no + 접속법)이라 'no te acerques'가 됩니다. c가 e 앞에서 qu로 바뀌는 철자 변화에 주의하세요(acercar → acerque).","x":["te acerques: acercarse(다가가다)로 위험한 개에게 다가가지 말라는 뜻이 되어 정답 ✓","te adaptes: adaptarse(적응하다)는 개와 어울리지 않습니다 ✗","te acostumbres: acostumbrarse(익숙해지다)는 위험 경고와 맞지 않습니다 ✗","te resistas: resistirse(저항하다)는 맞지 않습니다 ✗"]},{"id":"V568","q":"Leo las noticias a diario porque me gusta estar ____.","o":["desocupada","agobiada","informada","estresada"],"a":2,"k":"estar informado","t":"나는 정보를 잘 알고 있는 게 좋아서 매일 뉴스를 읽는다.","e":"'estar informado/a'는 '소식을 잘 알고 있다, 정보에 밝다'라는 뜻입니다. 매일 뉴스를 읽는 이유로 자연스럽습니다. 화자가 여성이라 informada입니다.","x":["desocupada: '한가한'으로 뉴스 읽는 이유가 되지 않습니다 ✗","agobiada: '부담감에 짓눌린'으로 좋아할 상태가 아닙니다 ✗","informada: '정보를 잘 아는'으로 뉴스를 읽는 이유가 되어 정답 ✓","estresada: '스트레스 받은'으로 좋아할 상태가 아닙니다 ✗"]},{"id":"V569","q":"El ____ de mi equipo no permitió que entrase ningún gol en la portería.","o":["reportero","repostero","portero","póster"],"a":2,"k":"축구 어휘","t":"우리 팀 골키퍼는 골문에 한 골도 허용하지 않았다.","e":"portero는 '골키퍼'이며 portería(골문)를 지킵니다. 건물의 '경비원, 관리인'이라는 뜻도 있습니다. 중남미에서는 arquero라고도 합니다. 비슷하게 생긴 보기들에 속지 마세요.","x":["reportero: '기자, 리포터'로 골을 막지 않습니다 ✗","repostero: '제과사'로 맞지 않습니다 ✗","portero: '골키퍼'로 골문을 지키는 선수라서 정답 ✓","póster: '포스터'로 맞지 않습니다 ✗"]},{"id":"V570","q":"El ____ será rey un día.","o":["caballero","príncipe","emperador","héroe"],"a":1,"k":"왕실 어휘","t":"그 왕자는 언젠가 왕이 될 것이다.","e":"príncipe는 '왕자'로 나중에 rey(왕)가 될 사람입니다. 여성형은 princesa(공주)입니다. será는 ser의 미래형입니다.","x":["caballero: '기사, 신사'로 왕이 될 사람이 아닙니다 ✗","príncipe: '왕자'로 언젠가 왕이 될 사람이라 정답 ✓","emperador: '황제'로 이미 왕보다 높은 지위입니다 ✗","héroe: '영웅'으로 맞지 않습니다 ✗"]},{"id":"V571","q":"Nos gusta mucho el ____ moderno, por eso queremos visitar ese museo.","o":["cine","baile","arte","teatro"],"a":2,"k":"예술 어휘","t":"우리는 현대 미술을 아주 좋아해서 그 미술관에 가 보고 싶다.","e":"museo(미술관, 박물관)에서 보는 것은 arte(예술, 미술)입니다. 'arte moderno'는 '현대 미술'입니다. arte는 단수일 때 보통 남성(el arte moderno), 복수일 때 여성(las bellas artes)으로 씁니다.","x":["cine: '영화'는 영화관에서 봅니다 ✗","baile: '춤'은 미술관과 맞지 않습니다 ✗","arte: '미술'로 arte moderno(현대 미술)를 보러 미술관에 간다는 문맥에 맞아 정답 ✓","teatro: '연극'은 극장에서 봅니다 ✗"]},{"id":"V572","q":"Mi hermana y yo no nos vemos mucho, pero ____ a diario.","o":["nos reunimos","quedamos","nos llamamos","nos encontramos"],"a":2,"k":"상호 재귀 동사","t":"언니와 나는 자주 만나지는 못하지만, 매일 서로 전화한다.","e":"'nos llamamos'는 '서로에게 전화한다'라는 상호 재귀(서로 ~하다) 표현입니다. pero(하지만) 앞에서 자주 만나지 못한다고 했으니, 만나지 않고도 할 수 있는 연락 방법이 와야 합니다.","x":["nos reunimos: reunirse(모이다)는 '자주 못 만난다'와 모순됩니다 ✗","quedamos: quedar(약속해서 만나다)는 앞 내용과 모순됩니다 ✗","nos llamamos: '서로 전화하다'로 만나지 않고 연락한다는 대조가 되어 정답 ✓","nos encontramos: encontrarse(만나다)는 앞 내용과 모순됩니다 ✗"]},{"id":"V573","q":"Nunca pondría un cuadro así en las paredes de mi casa. ¡Qué ____!","o":["alegría","belleza","horror","bonito"],"a":2,"k":"감탄 표현 qué","t":"나는 우리 집 벽에 절대 그런 그림을 걸지 않을 거야. 정말 끔찍해!","e":"'¡Qué horror!'는 '정말 끔찍해!'라는 감탄 표현입니다. 그림을 절대 걸지 않겠다고 했으니 부정적인 감탄이 와야 합니다. '¡Qué + 명사/형용사!' 구조로 감정을 나타냅니다.","x":["alegría: '¡Qué alegría!(정말 기뻐!)'로 긍정적이라 문맥과 반대입니다 ✗","belleza: '¡Qué belleza!(정말 아름다워!)'로 문맥과 반대입니다 ✗","horror: '¡Qué horror!(정말 끔찍해!)'로 그림이 싫다는 내용과 맞아 정답 ✓","bonito: '¡Qué bonito!(정말 예뻐!)'로 문맥과 반대입니다 ✗"]},{"id":"V574","q":"Estoy muy ____ por vuestra ayuda. Sin vosotros no lo habría conseguido.","o":["insatisfecha","agradecida","amargada","decepcionada"],"a":1,"k":"agradecido 형용사","t":"너희들의 도움에 정말 감사해. 너희가 없었다면 해내지 못했을 거야.","e":"agradecido/a는 '감사하는, 고마워하는'이라는 뜻입니다. 'estar agradecido por ~'는 '~에 감사하다'라는 표현입니다. 도움 덕분에 해냈다는 뒤 문장과 자연스럽게 이어집니다.","x":["insatisfecha: '불만족한'으로 도움에 대한 반응과 맞지 않습니다 ✗","agradecida: '감사하는'으로 도움을 받은 상황에 맞아 정답 ✓","amargada: '씁쓸한, 원망하는'으로 맞지 않습니다 ✗","decepcionada: '실망한'으로 문맥과 반대입니다 ✗"]},{"id":"V575","q":"Cuando lleguen al aeropuerto de destino, ____ su equipaje en la cinta número 6.","o":["escojan","recojan","olviden","elijan"],"a":1,"k":"recoger 동사","t":"도착 공항에 도착하시면 6번 컨베이어 벨트에서 수하물을 찾으세요.","e":"recoger는 '줍다, 찾아가다, 수거하다'로, 공항에서 짐을 찾는 것은 'recoger el equipaje'라고 합니다. ustedes에 대한 명령형이라 recojan이며, g가 a 앞에서 j로 바뀝니다. cinta는 '컨베이어 벨트'입니다.","x":["escojan: escoger(고르다)는 수하물 찾기와 맞지 않습니다 ✗","recojan: recoger(찾아가다)로 recoger el equipaje(짐을 찾다)가 되어 정답 ✓","olviden: olvidar(잊다)는 안내 방송 내용으로 맞지 않습니다 ✗","elijan: elegir(선택하다)는 맞지 않습니다 ✗"]},{"id":"V576","q":"Lo primero que hago al levantarme por la mañana es ____.","o":["almorzar","desayunar","cenar","merendar"],"a":1,"k":"식사 어휘","t":"아침에 일어나서 제일 먼저 하는 일은 아침을 먹는 것이다.","e":"desayunar는 '아침 식사를 하다'입니다. 식사 동사: almorzar(점심 먹다, 지역에 따라 오전 간식), merendar(오후 간식 먹다), cenar(저녁 먹다). 일어나자마자 하는 것은 desayunar입니다.","x":["almorzar: '점심을 먹다'로 일어나자마자 하는 것이 아닙니다 ✗","desayunar: '아침을 먹다'로 일어나서 처음 하는 일이라 정답 ✓","cenar: '저녁을 먹다'로 맞지 않습니다 ✗","merendar: '오후 간식을 먹다'로 맞지 않습니다 ✗"]},{"id":"V577","q":"Todos los pasajeros están en ____ esperando para embarcar lo antes posible.","o":["la terminal","el comercio","el local","el bazar"],"a":0,"k":"공항 어휘","t":"모든 승객이 최대한 빨리 탑승하려고 터미널에서 기다리고 있다.","e":"terminal은 공항의 '터미널'로 승객들이 탑승(embarcar)을 기다리는 곳입니다. 공항 터미널은 여성명사(la terminal)로 쓰는 것이 일반적입니다. 'lo antes posible'은 '가능한 한 빨리'입니다.","x":["la terminal: '터미널'로 승객이 탑승을 기다리는 곳이라 정답 ✓","el comercio: '상점, 상업'으로 탑승 대기 장소가 아닙니다 ✗","el local: '(가게) 점포, 장소'로 맞지 않습니다 ✗","el bazar: '잡화점'으로 맞지 않습니다 ✗"]},{"id":"V578","q":"¿Cómo vais a celebrar vuestro ____ de boda?","o":["cumpleaños","recordatorio","aniversario","periodo"],"a":2,"k":"aniversario","t":"너희 결혼기념일은 어떻게 축하할 거야?","e":"aniversario는 '기념일'로 'aniversario de boda'는 '결혼기념일'입니다. cumpleaños(생일)는 태어난 날에만 씁니다. vais a celebrar는 'ir a + 동사원형(~할 것이다)'의 vosotros 형태입니다.","x":["cumpleaños: '생일'로 결혼과 함께 쓰지 않습니다 ✗","recordatorio: '알림, 리마인더'로 맞지 않습니다 ✗","aniversario: '기념일'로 aniversario de boda(결혼기념일)가 되어 정답 ✓","periodo: '기간'으로 맞지 않습니다 ✗"]},{"id":"V579","q":"No olvides el ____ cuando vayas a la playa.","o":["abrigo","chubasquero","protector solar","gorro de lana"],"a":2,"k":"해변 용품","t":"해변에 갈 때 선크림을 잊지 마.","e":"'protector solar'는 '자외선 차단제, 선크림'입니다. 해변(playa)에서는 햇볕으로부터 피부를 보호해야 하니까요. 'No olvides ~'는 '~을 잊지 마'라는 부정 명령입니다.","x":["abrigo: '외투'로 해변에 맞지 않습니다 ✗","chubasquero: '비옷'으로 해변에 꼭 필요한 것이 아닙니다 ✗","protector solar: '선크림'으로 해변에서 필요한 물건이라 정답 ✓","gorro de lana: '털모자'로 해변에 맞지 않습니다 ✗"]},{"id":"V580","q":"Desde pequeño me encantan los ordenadores, por eso voy a estudiar ____.","o":["Comercio","Mecánica","Informática","Química"],"a":2,"k":"전공 어휘","t":"어릴 때부터 컴퓨터를 아주 좋아해서 컴퓨터공학을 공부할 거야.","e":"ordenadores(컴퓨터)를 좋아하니 Informática(컴퓨터공학, 정보학)를 공부하는 것이 자연스럽습니다. 'Desde pequeño'는 '어릴 때부터'입니다. 학과 이름은 대문자로 쓰기도 합니다.","x":["Comercio: '상업'으로 컴퓨터와 직접 관련 없습니다 ✗","Mecánica: '기계공학'으로 맞지 않습니다 ✗","Informática: '컴퓨터공학'으로 컴퓨터를 좋아한다는 이유와 맞아 정답 ✓","Química: '화학'으로 맞지 않습니다 ✗"]},{"id":"V581","q":"Un ____ profesional debe entrenar con la bici cada día.","o":["ceramista","dentista","electricista","ciclista"],"a":3,"k":"-ista 직업명","t":"프로 사이클 선수는 매일 자전거로 훈련해야 한다.","e":"ciclista는 '사이클 선수, 자전거 타는 사람'입니다. -ista로 끝나는 직업명은 남녀 형태가 같습니다(el/la ciclista). entrenar는 '훈련하다'입니다.","x":["ceramista: '도예가'로 자전거와 관련 없습니다 ✗","dentista: '치과의사'로 맞지 않습니다 ✗","electricista: '전기 기사'로 맞지 않습니다 ✗","ciclista: '사이클 선수'로 자전거로 훈련하는 사람이라 정답 ✓"]},{"id":"V582","q":"Si no sabes lo que significa esta palabra, búscala en el ____.","o":["cuaderno","bloc","diccionario","periódico"],"a":2,"k":"diccionario","t":"이 단어의 뜻을 모르면 사전에서 찾아봐.","e":"단어의 뜻(significado)은 diccionario(사전)에서 찾습니다. búscala는 buscar(찾다)의 명령형에 la(esta palabra)가 붙은 형태입니다. 대명사가 붙으면 강세 위치 때문에 악센트가 생깁니다.","x":["cuaderno: '공책'으로 뜻을 찾는 곳이 아닙니다 ✗","bloc: '메모장'으로 맞지 않습니다 ✗","diccionario: '사전'으로 단어 뜻을 찾는 곳이라 정답 ✓","periódico: '신문'으로 맞지 않습니다 ✗"]},{"id":"V583","q":"¿Me dejas tu ____ para hacer una llamada? Olvidé el mío.","o":["celular","boli","bolso","cartera"],"a":0,"k":"휴대폰 어휘","t":"전화 좀 하게 네 휴대폰 빌려줄래? 내 거 깜빡했어.","e":"celular는 중남미에서 쓰는 '휴대폰'이고, 스페인에서는 móvil이라고 합니다. 'hacer una llamada'는 '전화를 걸다'입니다. 'el mío(내 것)'는 남성명사 celular를 가리킵니다.","x":["celular: '휴대폰'(중남미)으로 전화하는 데 필요해 정답 ✓","boli: '볼펜'으로 전화와 관련 없습니다 ✗","bolso: '핸드백'으로 전화할 수 없습니다 ✗","cartera: '지갑'으로 el mío와 성이 맞지 않고(cartera는 여성) 전화와 관련 없습니다 ✗"]},{"id":"V584","q":"Este refresco está bastante frío, no necesita ____.","o":["azúcar","gas","agua","hielo"],"a":3,"k":"음료 어휘","t":"이 탄산음료는 충분히 차가워서 얼음이 필요 없어.","e":"음료가 이미 frío(차가운)하므로 hielo(얼음)가 필요 없습니다. refresco는 '청량음료, 탄산음료'입니다. 바에서 '얼음 넣어 주세요'는 'Con hielo, por favor'라고 합니다.","x":["azúcar: '설탕'은 차가움과 관련 없습니다 ✗","gas: '탄산'은 차가움과 관련 없습니다 ✗","agua: '물'은 차가움과 직접 관련 없습니다 ✗","hielo: '얼음'으로 이미 차가우니 필요 없다는 흐름이 되어 정답 ✓"]},{"id":"V585","q":"En mi piso no hay ____, así que comemos en el salón o en la cocina.","o":["cantina","receptor","bufé","comedor"],"a":3,"k":"집 구조 어휘","t":"우리 집에는 식당(다이닝룸)이 없어서 거실이나 부엌에서 밥을 먹는다.","e":"comedor는 '식당, 다이닝룸(식사하는 방)'으로 comer(먹다)에서 나온 말입니다. 학교나 회사의 '구내식당'도 comedor라고 합니다. 집 구조: salón(거실), cocina(부엌), dormitorio(침실).","x":["cantina: '구내 매점, 술집'으로 집에 있는 공간이 아닙니다 ✗","receptor: '수신기'로 맞지 않습니다 ✗","bufé: '뷔페'로 집 공간이 아닙니다 ✗","comedor: '다이닝룸'으로 식사 공간이 없다는 내용에 맞아 정답 ✓"]},{"id":"V586","q":"Las guerras me producen un profundo ____ de tristeza.","o":["concepto","juicio","sentimiento","ideal"],"a":2,"k":"sentimiento","t":"전쟁은 나에게 깊은 슬픔의 감정을 불러일으킨다.","e":"sentimiento는 '감정, 느낌'입니다. 'sentimiento de tristeza'는 '슬픔의 감정'입니다. sentir(느끼다)에서 나온 명사입니다. producir는 여기서 '(감정을) 불러일으키다'라는 뜻입니다.","x":["concepto: '개념'으로 슬픔과 함께 쓰지 않습니다 ✗","juicio: '판단, 재판'으로 맞지 않습니다 ✗","sentimiento: '감정'으로 슬픔의 감정이 되어 정답 ✓","ideal: '이상'으로 맞지 않습니다 ✗"]},{"id":"V587","q":"Ojalá pudiera casarme con Antonio Banderas, pero es un sueño ____.","o":["inalcanzable","viable","realizable","factible"],"a":0,"k":"inalcanzable","t":"안토니오 반데라스와 결혼할 수 있으면 좋겠지만, 그건 이룰 수 없는 꿈이다.","e":"inalcanzable은 'in(아닌) + alcanzar(도달하다) + -able'로 '도달할 수 없는, 이룰 수 없는'이라는 뜻입니다. pero 앞의 'Ojalá pudiera ~(~할 수 있으면 좋을 텐데)'는 실현 가능성이 낮은 바람을 나타내므로 잘 어울립니다.","x":["inalcanzable: '이룰 수 없는'으로 비현실적인 바람에 맞아 정답 ✓","viable: '실현 가능한'으로 pero와 맞지 않습니다 ✗","realizable: '실현할 수 있는'으로 문맥과 반대입니다 ✗","factible: '실행 가능한'으로 문맥과 반대입니다 ✗"]},{"id":"V588","q":"Si no sabes tu contraseña, no puedes acceder a tu ____.","o":["cuento","cuenta","recuento","descuento"],"a":1,"k":"cuenta 계정","t":"비밀번호를 모르면 네 계정에 접속할 수 없다.","e":"cuenta는 '계좌, 계정, 계산서'라는 뜻이 있습니다. contraseña(비밀번호)로 접속하는 것은 cuenta(계정)입니다. 'acceder a ~'는 '~에 접속하다'입니다. cuento(이야기, 동화)와 헷갈리지 마세요.","x":["cuento: '이야기, 동화'로 비밀번호와 관련 없습니다 ✗","cuenta: '계정'으로 비밀번호로 접속하는 대상이라 정답 ✓","recuento: '재집계, 개수 세기'로 맞지 않습니다 ✗","descuento: '할인'으로 맞지 않습니다 ✗"]},{"id":"V589","q":"Maribel toma medicación para tratar su ____.","o":["imprecisión","ilusión","motivación","depresión"],"a":3,"k":"건강 어휘","t":"마리벨은 우울증을 치료하기 위해 약을 먹는다.","e":"depresión은 '우울증'으로 medicación(약물 치료)으로 치료할 수 있는 질환입니다. tratar는 여기서 '치료하다'라는 뜻입니다. 경제 분야에서는 '불황'이라는 뜻으로도 씁니다.","x":["imprecisión: '부정확함'으로 약으로 치료하는 대상이 아닙니다 ✗","ilusión: '환상, 설렘'으로 맞지 않습니다 ✗","motivación: '동기 부여'로 치료 대상이 아닙니다 ✗","depresión: '우울증'으로 약으로 치료하는 질환이라 정답 ✓"]},{"id":"V590","q":"Las personas con la piel muy clara deben usar crema protectora para no ____.","o":["marearse","estresarse","cansarse","quemarse"],"a":3,"k":"quemarse 동사","t":"피부가 아주 하얀 사람들은 화상을 입지 않도록 자외선 차단 크림을 발라야 한다.","e":"quemarse는 '데다, (햇볕에) 타다/화상을 입다'라는 뜻입니다. crema protectora(자외선 차단 크림)는 햇볕에 피부가 타는 것을 막아 줍니다. 'para no + 동사원형'은 '~하지 않도록'입니다.","x":["marearse: '어지러워지다, 멀미하다'로 크림과 관련 없습니다 ✗","estresarse: '스트레스 받다'로 맞지 않습니다 ✗","cansarse: '피곤해지다'로 맞지 않습니다 ✗","quemarse: '햇볕에 타다'로 자외선 차단 크림의 목적이라 정답 ✓"]},{"id":"V591","q":"Lleva este ____ al baño, que ya no hay.","o":["lavabo","papel higiénico","inodoro","papeleo"],"a":1,"k":"욕실 어휘","t":"이 휴지를 화장실에 갖다 놔, 이제 다 떨어졌어.","e":"'papel higiénico'는 '화장실 휴지'입니다. '이제 없다(ya no hay)'고 했으니 들고 갈 수 있는 소모품이어야 합니다. lavabo(세면대), inodoro(변기)는 옮길 수 있는 것이 아닙니다.","x":["lavabo: '세면대'로 가져다 놓을 물건이 아닙니다 ✗","papel higiénico: '화장실 휴지'로 떨어져서 가져다 놓는 물건이라 정답 ✓","inodoro: '변기'로 옮길 수 있는 물건이 아닙니다 ✗","papeleo: '서류 작업, 행정 절차'로 맞지 않습니다 ✗"]},{"id":"V592","q":"En general, ____ tiene dos sentidos de circulación.","o":["un callejón","una plaza","un túnel","una avenida"],"a":3,"k":"도로 어휘","t":"일반적으로 대로에는 양방향 차선이 있다.","e":"avenida는 '대로, 넓은 거리'로 보통 양방향(dos sentidos) 통행이 가능합니다. 'sentido de circulación'은 '통행 방향'입니다. callejón은 '골목'이라 좁습니다.","x":["un callejón: '골목'으로 좁아서 양방향 통행이 어렵습니다 ✗","una plaza: '광장'으로 통행 방향을 말하기 어색합니다 ✗","un túnel: '터널'은 일반적인 특징으로 맞지 않습니다 ✗","una avenida: '대로'로 보통 양방향 통행이라 정답 ✓"]},{"id":"V593","q":"Seis y cuatro son ____.","o":["once","diez","catorce","doce"],"a":1,"k":"숫자","t":"6 더하기 4는 10이다.","e":"seis(6) + cuatro(4) = diez(10)입니다. 스페인어로 덧셈을 말할 때 'Seis y cuatro son diez' 또는 'Seis más cuatro son diez'라고 합니다. 숫자 11~15는 once, doce, trece, catorce, quince입니다.","x":["once: '11'로 6+4의 답이 아닙니다 ✗","diez: '10'으로 6+4의 답이라 정답 ✓","catorce: '14'로 틀립니다 ✗","doce: '12'로 틀립니다 ✗"]},{"id":"V594","q":"Cada persona es única, no hay que ____ con nadie.","o":["compararse","relacionarse","comunicarse","conformarse"],"a":0,"k":"compararse 동사","t":"모든 사람은 각자 고유하니, 누구와도 자신을 비교할 필요가 없다.","e":"compararse con ~은 '~와 자신을 비교하다'입니다. '각 사람은 유일하다(única)'는 앞 문장과 자연스럽게 이어집니다. 'no hay que + 동사원형'은 '~할 필요가 없다, ~해서는 안 된다'입니다.","x":["compararse: '자신을 비교하다'로 사람은 각자 고유하다는 내용과 맞아 정답 ✓","relacionarse: '어울리다, 관계를 맺다'로 '누구와도 어울리지 마라'가 되어 어색합니다 ✗","comunicarse: '소통하다'로 문맥과 맞지 않습니다 ✗","conformarse: '만족하다, 감수하다'로 con nadie와 의미가 통하지 않습니다 ✗"]},{"id":"V595","q":"¡Qué ____! No se atreve a nadar en el lago.","o":["atrevido","valiente","egoísta","cobarde"],"a":3,"k":"성격 형용사","t":"정말 겁쟁이구나! 호수에서 수영할 엄두도 못 내다니.","e":"cobarde는 '겁 많은, 겁쟁이'입니다. 'atreverse a + 동사원형'은 '감히 ~하다, ~할 용기를 내다'로, 'no se atreve'는 '엄두를 못 낸다'는 뜻입니다. 반대말은 valiente(용감한)입니다.","x":["atrevido: '대담한'으로 문맥과 반대입니다 ✗","valiente: '용감한'으로 문맥과 반대입니다 ✗","egoísta: '이기적인'으로 수영 못 하는 것과 관련 없습니다 ✗","cobarde: '겁쟁이'로 수영할 용기가 없다는 내용과 맞아 정답 ✓"]},{"id":"V596","q":"Hoy la ____ de espera del centro de salud estaba llena.","o":["residencia","sala","habitación","vivienda"],"a":1,"k":"sala de espera","t":"오늘 보건소 대기실이 꽉 차 있었다.","e":"'sala de espera'는 '대기실'입니다. sala는 '(특정 용도의) 방, 홀'로 'sala de reuniones(회의실)'처럼 씁니다. 'centro de salud'는 '보건소, 동네 의원'입니다.","x":["residencia: '거주지, 요양원'으로 de espera와 쓰지 않습니다 ✗","sala: sala de espera(대기실)가 되어 정답 ✓","habitación: '(침실 같은) 방'으로 de espera와 쓰지 않습니다 ✗","vivienda: '주택'으로 맞지 않습니다 ✗"]},{"id":"V597","q":"Martín y su padre son ____, se parecen muchísimo.","o":["diferentes","desiguales","distintos","idénticos"],"a":3,"k":"idéntico","t":"마르틴과 그의 아버지는 똑같이 생겼다, 아주 많이 닮았다.","e":"idéntico/a는 '똑같은, 동일한'이라는 뜻입니다. 'parecerse'는 '서로 닮다'이고, muchísimo(아주 많이)로 강조합니다. 반대 의미의 보기(diferentes, distintos)는 문맥과 맞지 않습니다.","x":["diferentes: '다른'으로 닮았다는 내용과 반대입니다 ✗","desiguales: '고르지 않은, 불평등한'으로 맞지 않습니다 ✗","distintos: '다른'으로 문맥과 반대입니다 ✗","idénticos: '똑같은'으로 아주 닮았다는 내용과 맞아 정답 ✓"]},{"id":"V598","q":"¿Te gusta aprender español en grupo o de forma ____?","o":["individual","compartida","grupal","participativa"],"a":0,"k":"de forma individual","t":"너는 스페인어를 그룹으로 배우는 게 좋아, 아니면 개인으로 배우는 게 좋아?","e":"'de forma individual'은 '개인적으로, 혼자서'라는 뜻으로 'en grupo(그룹으로)'와 대비됩니다. 'de forma + 형용사'는 '~한 방식으로'라는 뜻의 부사 표현입니다.","x":["individual: '개인의'로 그룹과 대비되어 정답 ✓","compartida: '공유된'으로 그룹과 대비되지 않습니다 ✗","grupal: '그룹의'로 en grupo와 같은 뜻이라 선택지가 되지 않습니다 ✗","participativa: '참여형의'로 그룹과 대비되지 않습니다 ✗"]},{"id":"V599","q":"Ayer me hicieron la manicura en un salón de ____.","o":["eventos","belleza","actos","baile"],"a":1,"k":"salón de belleza","t":"어제 나는 미용실(뷰티숍)에서 매니큐어를 받았다.","e":"'salón de belleza'는 '미용실, 뷰티숍'입니다. belleza는 '아름다움'입니다. manicura(손톱 관리)를 받는 곳으로 자연스럽습니다. 'me hicieron'은 '(다른 사람이) 나에게 해 주었다'라는 뜻입니다.","x":["eventos: salón de eventos는 '연회장'으로 매니큐어와 관련 없습니다 ✗","belleza: salón de belleza(뷰티숍)로 매니큐어를 받는 곳이라 정답 ✓","actos: salón de actos는 '강당'으로 맞지 않습니다 ✗","baile: salón de baile는 '무도장'으로 맞지 않습니다 ✗"]},{"id":"V600","q":"Trabajo como ____ porque me encanta hacer reír a la gente, sobre todo a los niños.","o":["dramaturgo","compositor","oficinista","payaso"],"a":3,"k":"직업 어휘","t":"나는 사람들, 특히 아이들을 웃게 하는 것을 정말 좋아해서 광대로 일한다.","e":"payaso는 '광대, 어릿광대'로 사람들을 웃기는 직업입니다. 'hacer reír a ~'는 '~를 웃게 하다'라는 표현입니다. 'trabajar como + 직업'은 '~로 일하다'입니다.","x":["dramaturgo: '극작가'로 사람들을 웃기는 것이 주된 일이 아닙니다 ✗","compositor: '작곡가'로 맞지 않습니다 ✗","oficinista: '사무원'으로 맞지 않습니다 ✗","payaso: '광대'로 아이들을 웃게 하는 직업이라 정답 ✓"]},{"id":"V601","q":"Han tomado el sol durante sus vacaciones, por eso están tan ____.","o":["morenos","serios","sorprendidos","delgados"],"a":0,"k":"외모 형용사","t":"그들은 휴가 동안 햇볕을 쬐어서 저렇게 까무잡잡하게 탔다.","e":"tomar el sol은 '햇볕을 쬐다, 일광욕하다'라는 뜻입니다. 햇볕에 피부가 타면 moreno(피부가 까무잡잡한, 그을린)라고 합니다. 주어가 복수(ellos)이므로 morenos가 됩니다. 예: Volví de la playa muy morena.(해변에서 아주 까맣게 타서 돌아왔다.)","x":["morenos: 피부가 까무잡잡하게 그을린 → 햇볕을 쬔 결과와 맞으므로 정답 ✓","serios: 진지한, 심각한 → 햇볕과 관계없는 성격·표정 표현이라 ✗","sorprendidos: 놀란 → 휴가 중 햇볕을 쬔 결과로 보기 어려워 ✗","delgados: 마른, 날씬한 → 햇볕을 쬐어서 마르지는 않으므로 ✗"]},{"id":"V602","q":"Mi hermano ha crecido tanto que todos los pantalones le quedan ____.","o":["cortos","estrechos","largos","anchos"],"a":0,"k":"옷 크기 표현","t":"내 남동생은 키가 너무 커서 모든 바지가 짧다.","e":"quedar + 형용사는 옷이 '(몸에) ~하게 맞다'라는 뜻입니다. 키가 많이 자랐으니(ha crecido) 바지 길이가 모자라 cortos(짧은)가 맞습니다. pantalones가 남성 복수라서 cortos 형태입니다. 예: Esta camisa me queda grande.(이 셔츠는 나한테 크다.)","x":["cortos: 짧은 → 키가 자라면 바지가 짧아지므로 정답 ✓","estrechos: 좁은, 꽉 끼는 → 키(길이)가 아니라 폭에 관한 말이라 ✗","largos: 긴 → 키가 컸으면 바지는 오히려 짧아지므로 ✗","anchos: 헐렁한, 폭이 넓은 → 키가 큰 것과 반대 상황이라 ✗"]},{"id":"V603","q":"Maria Callas fue una de las mejores ____ del siglo XX.","o":["historiadoras","voces","marcas","escritoras"],"a":1,"k":"음악 어휘","t":"마리아 칼라스는 20세기 최고의 목소리(성악가) 중 한 명이었다.","e":"voz(목소리)는 복수형이 voces이며, 'una de las mejores voces'처럼 뛰어난 가수를 가리킬 때도 씁니다. 마리아 칼라스는 유명한 오페라 소프라노 가수이므로 voces가 정답입니다. z로 끝나는 명사는 복수형에서 z가 c로 바뀝니다(voz → voces, luz → luces).","x":["historiadoras: 역사가(여성) → 마리아 칼라스는 역사가가 아니라 가수라서 ✗","voces: 목소리, (뛰어난) 가수 → 오페라 가수를 가리키므로 정답 ✓","marcas: 상표, 브랜드 → 사람을 가리키는 말이 아니라 ✗","escritoras: 작가(여성) → 칼라스는 작가가 아니라서 ✗"]},{"id":"V604","q":"Esa joven es la cantante de moda, tiene millones de ____ en todo el mundo.","o":["seguidores","competidores","rivales","imitadores"],"a":0,"k":"SNS·대중문화 어휘","t":"저 젊은 여자는 인기 가수로, 전 세계에 수백만 명의 팔로워(팬)가 있다.","e":"seguidor는 동사 seguir(따르다)에서 나온 말로 '팬, 지지자, (SNS) 팔로워'를 뜻합니다. 인기 가수(la cantante de moda)에게 수백만 명이 있는 것은 seguidores가 자연스럽습니다. de moda는 '유행하는, 인기 있는'이라는 뜻입니다.","x":["seguidores: 팬, 팔로워 → 인기 가수에게 어울리므로 정답 ✓","competidores: 경쟁자 → 인기의 증거로 수백만 명의 경쟁자를 말하지 않아 ✗","rivales: 라이벌 → 문맥상 인기 정도를 나타내는 말이 아니라 ✗","imitadores: 모방하는 사람, 흉내 내는 사람 → 수백만 명이 따라 한다는 뜻이 아니라 ✗"]},{"id":"V605","q":"Rocío me ____ que todo estaba bajo control, así que me quedé tranquila.","o":["relató","aseguró","narró","enumeró"],"a":1,"k":"전달 동사","t":"로시오가 모든 게 통제되고 있다고 나에게 장담해서, 나는 안심했다.","e":"asegurar는 '확언하다, 장담하다, 보장하다'라는 뜻으로 상대를 안심시킬 때 자주 씁니다. 그래서 뒤에 'me quedé tranquila(나는 안심했다)'가 자연스럽게 이어집니다. bajo control은 '통제되는, 문제없는'이라는 표현입니다.","x":["relató: 이야기했다(사건을 자세히 서술) → 안심시키는 의미가 약해 ✗","aseguró: 장담했다, 확언했다 → 안심했다는 결과와 맞아 정답 ✓","narró: (이야기·소설 등을) 서술했다 → 한 마디 확인의 말에는 어색해 ✗","enumeró: 하나하나 열거했다 → 목록을 늘어놓는 뜻이라 ✗"]},{"id":"V606","q":"Paco y yo nos hemos ____. Vamos a casarnos en octubre.","o":["conocido","acordado","prometido","peleado"],"a":2,"k":"결혼·관계 어휘","t":"파코와 나는 약혼했어. 10월에 결혼할 거야.","e":"prometerse는 재귀 형태로 쓰면 '서로 결혼을 약속하다, 약혼하다'라는 뜻입니다. 10월에 결혼한다(casarnos)는 내용과 연결되므로 nos hemos prometido가 정답입니다. 약혼자는 prometido/prometida 또는 novio/novia라고도 합니다.","x":["conocido: (서로) 알게 되었다 → 막 알게 된 사이가 곧바로 결혼 날짜를 정했다고 보기는 어색해 ✗","acordado: 합의했다 → acordarse는 '기억하다'라는 뜻이 되어 문맥과 맞지 않아 ✗","prometido: 약혼했다 → 결혼 계획과 이어지므로 정답 ✓","peleado: 싸웠다 → 결혼한다는 내용과 반대라서 ✗"]},{"id":"V607","q":"Puedes fiarte de Andrés, siempre ____ lo que promete.","o":["aprueba","cumple","rememora","realiza"],"a":1,"k":"cumplir 동사","t":"안드레스는 믿어도 돼, 그는 약속한 것을 항상 지켜.","e":"cumplir는 '(약속·의무를) 지키다, 이행하다'라는 뜻으로, cumplir una promesa(약속을 지키다)가 대표 표현입니다. fiarse de는 '~을 믿다, 신뢰하다'라는 뜻이므로 믿을 수 있는 이유로 cumple가 알맞습니다. 참고로 cumplir años는 '생일을 맞다, ~살이 되다'라는 뜻도 있습니다.","x":["aprueba: 승인하다, 시험에 합격하다 → 약속과 함께 쓰지 않아 ✗","cumple: (약속을) 지키다 → 믿을 수 있는 이유와 맞아 정답 ✓","rememora: 회상하다 → 약속을 지킨다는 의미가 아니라 ✗","realiza: 실행하다, 실현하다 → 약속(lo que promete)과는 보통 cumplir를 써서 ✗"]},{"id":"V608","q":"Mis amigos no viven ____, por eso hablo con ellos por videollamada.","o":["cerca","allí","aislados","lejos"],"a":0,"k":"장소 부사","t":"내 친구들은 가까이에 살지 않아서, 나는 그들과 영상통화로 이야기한다.","e":"cerca는 '가까이', lejos는 '멀리'라는 뜻의 부사입니다. 영상통화(videollamada)로 이야기하는 이유는 친구들이 가까이 살지 않기 때문이므로 no viven cerca가 맞습니다. 'no viven lejos'라고 하면 가까이 산다는 뜻이 되어 영상통화를 하는 이유가 되지 않습니다.","x":["cerca: 가까이 → '가까이 살지 않는다'가 되어 정답 ✓","allí: 거기에 → 어디를 가리키는지 앞에 언급이 없어 어색해 ✗","aislados: 고립된 → '고립되어 살지 않는다'는 영상통화의 이유가 되지 않아 ✗","lejos: 멀리 → '멀리 살지 않는다'면 직접 만날 수 있으니 ✗"]},{"id":"V609","q":"Para saber cómo debes lavar este jersey, debes leer su ____.","o":["tarjeta","libreta","etiqueta","sello"],"a":2,"k":"옷·상품 어휘","t":"이 스웨터를 어떻게 세탁해야 하는지 알려면 라벨을 읽어야 한다.","e":"etiqueta는 옷에 붙어 있는 '라벨, 태그'로, 세탁 방법·소재·사이즈 등이 적혀 있습니다. 또 '예절, 격식'이라는 뜻도 있습니다(traje de etiqueta: 정장 예복). jersey는 스페인에서 '스웨터'를 뜻합니다.","x":["tarjeta: 카드(신용카드, 명함 등) → 옷의 세탁 정보가 적힌 곳이 아니라 ✗","libreta: 수첩, 공책 → 옷에 붙어 있지 않아 ✗","etiqueta: 라벨, 태그 → 세탁 방법이 적혀 있어 정답 ✓","sello: 도장, 우표 → 세탁 정보를 담고 있지 않아 ✗"]},{"id":"V610","q":"Estos papeles van al contenedor de ____ azul.","o":["alimentos","basura","reciclaje","pilas"],"a":2,"k":"환경·재활용 어휘","t":"이 종이들은 파란색 재활용 수거함에 넣는다.","e":"contenedor는 길가에 놓인 큰 '수거함, 쓰레기통'을 뜻합니다. 스페인에서는 종이·판지는 파란색 재활용 수거함(contenedor de reciclaje azul)에 넣습니다. reciclaje는 '재활용', reciclar는 '재활용하다'입니다.","x":["alimentos: 음식물 → 종이를 음식물 수거함에 넣지 않아 ✗","basura: 쓰레기 → 일반 쓰레기라는 말로는 종이 분리수거의 의미가 드러나지 않아 ✗","reciclaje: 재활용 → 종이를 넣는 파란 재활용 수거함이라 정답 ✓","pilas: 건전지 → 종이를 건전지 수거함에 넣지 않아 ✗"]},{"id":"V611","q":"Mario nació en Madrid, pero ____ a Bilbao con sus padres cuando tenía ocho años.","o":["regresó","se asistió","se trasladó","volvió"],"a":2,"k":"이사·이동 동사","t":"마리오는 마드리드에서 태어났지만, 여덟 살 때 부모님과 함께 빌바오로 이사했다.","e":"trasladarse는 '(거주지·근무지를) 옮기다, 이사하다'라는 뜻입니다. 마드리드에서 태어나 빌바오로 처음 옮겨 간 것이므로 se trasladó가 맞습니다. 비슷한 말로 mudarse(이사하다)도 있습니다.","x":["regresó: 돌아갔다 → 빌바오에 살던 적이 없으니 '돌아갔다'는 어색해 ✗","se asistió: asistir는 재귀형으로 쓰지 않으며 '참석하다'라는 뜻이라 ✗","se trasladó: 이사했다, 옮겨 갔다 → 정답 ✓","volvió: 돌아갔다 → regresó와 같은 이유로 ✗"]},{"id":"V612","q":"Si no quieres usar los medios de transporte cuando llegues a Madrid, alójate en un hotel ____.","o":["renovado","céntrico","rural","lujoso"],"a":1,"k":"숙소 어휘","t":"마드리드에 도착해서 교통수단을 이용하고 싶지 않다면, 도심에 있는 호텔에 묵어.","e":"céntrico는 '도심에 있는, 중심가에 위치한'이라는 뜻입니다. 교통수단 없이 걸어서 다니려면 시내 중심에 있는 호텔이 좋으므로 céntrico가 정답입니다. alojarse는 '묵다, 숙박하다'라는 뜻이고, alójate는 tú에게 하는 명령형입니다.","x":["renovado: 리모델링한 → 교통수단 이용 여부와 관계없어 ✗","céntrico: 도심의 → 걸어 다니기 좋아 정답 ✓","rural: 시골의 → 시골 호텔이면 오히려 교통수단이 더 필요해 ✗","lujoso: 호화로운 → 위치와 관련된 말이 아니라 ✗"]},{"id":"V613","q":"Está ____, así que podemos celebrar la fiesta al aire libre.","o":["nevando","lluvioso","lloviendo","despejado"],"a":3,"k":"날씨 표현","t":"하늘이 맑으니까, 야외에서 파티를 열 수 있어.","e":"despejado는 '구름 없이 맑은'이라는 뜻으로 'Está despejado(하늘이 맑다)'처럼 씁니다. 야외(al aire libre)에서 파티를 하려면 날씨가 맑아야 하므로 정답입니다. lluvioso는 'Es un día lluvioso(비 오는 날이다)'처럼 보통 ser와 함께 써서 'Está lluvioso'는 어색합니다.","x":["nevando: 눈이 오는 중 → 야외 파티를 하기 어려운 날씨라 ✗","lluvioso: 비가 많은 → 'Está lluvioso'는 어색하고 야외 파티 이유도 안 돼 ✗","lloviendo: 비가 오는 중 → 야외 파티를 할 이유가 되지 않아 ✗","despejado: (하늘이) 맑은 → 야외 파티 조건과 맞아 정답 ✓"]},{"id":"V614","q":"Los lápices están en el primer cajón de esa ____.","o":["tabla","estantería","silla","mesa"],"a":3,"k":"가구 어휘","t":"연필은 저 책상 첫 번째 서랍에 있어.","e":"cajón은 '서랍'이라는 뜻이고, 서랍이 달린 가구로는 mesa(테이블, 책상)가 가장 자연스럽습니다. 'el primer cajón'은 '첫 번째 서랍'입니다. primero는 남성 단수 명사 앞에서 primer로 줄어듭니다.","x":["tabla: 판자, 도마, 표 → 서랍이 없어 ✗","estantería: 책장, 선반 → 보통 칸(estante)으로 되어 있고 서랍이 기본이 아니라 ✗","silla: 의자 → 서랍이 없어 ✗","mesa: 테이블, 책상 → 서랍이 달려 있어 정답 ✓"]},{"id":"V615","q":"Pude solucionar ese problema con ____, no fue nada complicado.","o":["dificultad","lentitud","facilidad","paciencia"],"a":2,"k":"con + 명사 부사구","t":"나는 그 문제를 쉽게 해결할 수 있었어, 전혀 복잡하지 않았어.","e":"'con + 추상명사'는 부사처럼 쓰여 '~하게'라는 뜻이 됩니다. con facilidad는 '쉽게'(= fácilmente)라는 의미로, 뒤의 'no fue nada complicado(전혀 복잡하지 않았다)'와 맞습니다. 예: Habla español con fluidez.(그는 스페인어를 유창하게 말한다.)","x":["dificultad: 어려움(con dificultad = 어렵게) → 복잡하지 않았다는 말과 반대라 ✗","lentitud: 느림(con lentitud = 천천히) → 쉬웠다는 내용과 맞지 않아 ✗","facilidad: 쉬움(con facilidad = 쉽게) → 정답 ✓","paciencia: 인내(con paciencia = 참을성 있게) → 복잡하지 않았다는 말과 연결이 약해 ✗"]},{"id":"V616","q":"La hermana de mi marido es mi ____.","o":["prima","cuñada","sobrina","tía"],"a":1,"k":"가족 어휘","t":"내 남편의 여자 형제는 나의 시누이다.","e":"cuñado/cuñada는 배우자의 형제자매나 형제자매의 배우자를 가리킵니다(시누이, 처제, 형부, 매형 등). 남편의 여자 형제이므로 cuñada가 정답입니다. 참고로 시어머니·장모는 suegra, 시아버지·장인은 suegro입니다.","x":["prima: 사촌(여자) → 부모 형제의 딸이라 ✗","cuñada: 시누이·올케·처제 등 배우자 쪽 자매 → 정답 ✓","sobrina: 조카딸 → 형제자매의 딸이라 ✗","tía: 이모, 고모, 숙모 → 부모의 자매라 ✗"]},{"id":"V617","q":"Su gran capacidad de trabajo es ____.","o":["inaceptable","lamentable","inevitable","admirable"],"a":3,"k":"평가 형용사","t":"그의 뛰어난 업무 능력은 감탄할 만하다.","e":"admirable은 '감탄할 만한, 존경스러운'이라는 뜻으로, gran capacidad de trabajo(뛰어난 업무 능력)라는 긍정적인 내용과 어울립니다. admirar(감탄하다, 존경하다)에서 나온 말입니다. -able로 끝나는 형용사는 '~할 만한'이라는 의미가 많습니다.","x":["inaceptable: 받아들일 수 없는 → 뛰어난 능력에 부정적인 평가는 어색해 ✗","lamentable: 유감스러운, 한심한 → 칭찬할 내용과 반대라 ✗","inevitable: 피할 수 없는 → 능력을 평가하는 말이 아니라 ✗","admirable: 감탄할 만한 → 긍정적 내용과 맞아 정답 ✓"]},{"id":"V618","q":"Para ir a una ____ deberías ponerte algo más formal.","o":["clase","tienda","cervecería","boda"],"a":3,"k":"행사·장소 어휘","t":"결혼식에 가려면 좀 더 격식 있는 옷을 입어야 해.","e":"boda는 '결혼식'으로, 격식 있는 옷(algo más formal)을 입어야 하는 대표적인 행사입니다. deberías는 deber의 가능법(조건법)으로 '~하는 게 좋겠다'라는 부드러운 조언입니다. 결혼식 하객은 invitado, 신랑·신부는 novio/novia라고 합니다.","x":["clase: 수업 → 보통 격식 있는 옷이 필요하지 않아 ✗","tienda: 가게 → 격식 있는 옷이 필요한 곳이 아니라 ✗","cervecería: 맥줏집 → 편한 옷으로 가는 곳이라 ✗","boda: 결혼식 → 격식 있는 옷이 어울려 정답 ✓"]},{"id":"V619","q":"Ayer fui a la frutería y compré cerezas, mandarinas y ____.","o":["ciruelas","tortas","galletas","especias"],"a":0,"k":"과일 어휘","t":"어제 과일 가게에 가서 체리, 귤, 자두를 샀다.","e":"frutería는 '과일 가게'이므로 과일 이름이 와야 합니다. ciruela는 '자두'로, 체리(cereza)·귤(mandarina)과 함께 나열하기 알맞습니다. 가게 이름 -ería: panadería(빵집), carnicería(정육점), pescadería(생선 가게).","x":["ciruelas: 자두 → 과일이라 정답 ✓","tortas: 케이크, 납작한 빵 → 과일 가게에서 파는 것이 아니라 ✗","galletas: 비스킷, 쿠키 → 과일이 아니라 ✗","especias: 향신료 → 과일이 아니라 ✗"]},{"id":"V620","q":"Mi ____ ya tiene doce años, yo fui la madrina en su bautizo.","o":["hijastro","ahijado","padrino","hijo"],"a":1,"k":"가족·세례 어휘","t":"내 대자(代子)는 벌써 열두 살이야, 나는 그의 세례식 때 대모였어.","e":"가톨릭 세례식(bautizo)에서 아이를 영적으로 돌보기로 한 사람을 padrino(대부)/madrina(대모)라고 하고, 그 아이를 ahijado/ahijada(대자/대녀)라고 합니다. 내가 madrina였으므로 아이는 나의 ahijado입니다. 스페인어권에서는 지금도 중요한 관계입니다.","x":["hijastro: 의붓아들 → 대모 관계가 아니라 ✗","ahijado: 대자(대모·대부가 돌보는 아이) → 정답 ✓","padrino: 대부 → 열두 살 아이가 아니라 어른 쪽을 가리켜 ✗","hijo: 아들 → 친아들의 대모가 될 수는 없어 ✗"]},{"id":"V621","q":"El Louvre es uno de los museos más ____ del mundo.","o":["ignorados","conectados","esperados","visitados"],"a":3,"k":"과거분사 형용사","t":"루브르는 세계에서 가장 많이 방문되는 박물관 중 하나이다.","e":"visitado는 visitar(방문하다)의 과거분사로 '방문되는, 찾는 사람이 많은'이라는 뜻입니다. 'uno de los + 명사 + más + 형용사'는 '가장 ~한 것 중 하나'라는 최상급 표현입니다. 루브르는 관광객이 아주 많이 찾는 곳이므로 visitados가 정답입니다.","x":["ignorados: 무시된, 알려지지 않은 → 세계적으로 유명한 루브르와 맞지 않아 ✗","conectados: 연결된 → 박물관을 설명하기에 어색해 ✗","esperados: 기다려지는 → 이미 있는 박물관에 쓰기 어색해 ✗","visitados: 방문되는 → 정답 ✓"]},{"id":"V622","q":"No ____ a ningún partido político, tengo mis propias ideas.","o":["pertenezco","me enfrento","me niego","renuncio"],"a":0,"k":"pertenecer a","t":"나는 어떤 정당에도 속해 있지 않아, 나만의 생각이 있어.","e":"pertenecer a는 '~에 속하다, ~의 소유이다'라는 뜻입니다. 1인칭 현재형은 pertenezco로 불규칙(-cer → -zco)입니다(conocer → conozco와 같은 패턴). 'no ... ningún'은 '어떤 ~도 아니다'라는 이중부정입니다.","x":["pertenezco: 속하다 → 정당에 소속되지 않았다는 뜻이 되어 정답 ✓","me enfrento: 맞서다(enfrentarse a) → '어떤 정당에도 맞서지 않는다'는 뒤 문장과 연결이 어색해 ✗","me niego: 거부하다(negarse a + 동사원형) → 정당 이름과 바로 쓰지 않아 ✗","renuncio: 포기하다, 사임하다 → 속하지 않은 이유로 자연스럽지 않아 ✗"]},{"id":"V623","q":"¡Qué maleducado es el vecino del sexto! Nunca me ____ cuando me ve.","o":["interrumpe","saluda","invita","critica"],"a":1,"k":"인사·예절 동사","t":"6층 이웃은 정말 무례해! 나를 봐도 절대 인사를 안 해.","e":"saludar는 '인사하다'라는 뜻으로, 'me saluda'는 '나에게 인사한다'입니다. maleducado(무례한, 버릇없는)는 사람을 보고도 인사하지 않는 행동과 연결됩니다. 'el vecino del sexto'는 '6층(sexto piso)에 사는 이웃'입니다.","x":["interrumpe: 말을 끊다, 방해하다 → '절대 말을 끊지 않는다'면 무례하다는 말과 반대라 ✗","saluda: 인사하다 → 인사를 안 하는 것은 무례해 정답 ✓","invita: 초대하다 → 초대를 안 한다고 무례하다고 하긴 어색해 ✗","critica: 비판하다 → 비판하지 않는 것은 무례함이 아니라 ✗"]},{"id":"V624","q":"Una casa de ____ es más sólida que una casa de madera.","o":["piedra","plástico","metal","papel"],"a":0,"k":"재료 어휘","t":"돌로 지은 집은 나무로 지은 집보다 더 튼튼하다.","e":"'casa de + 재료'는 '~로 만든 집'이라는 뜻입니다. piedra(돌)로 지은 집은 나무(madera) 집보다 튼튼하다(más sólida)는 내용이 자연스럽습니다. 'más ... que'는 비교급 '~보다 더 ...한'입니다.","x":["piedra: 돌 → 튼튼한 건축 재료라 정답 ✓","plástico: 플라스틱 → 나무보다 튼튼한 집 재료라 보기 어려워 ✗","metal: 금속 → 집의 대표적 재료로 이 비교에 어색해 ✗","papel: 종이 → 집을 지을 수 없고 튼튼하지 않아 ✗"]},{"id":"V625","q":"Antes estaba nublado, pero ahora el cielo está ____ y hace sol.","o":["gris","oscuro","despejado","cubierto"],"a":2,"k":"날씨 표현","t":"아까는 흐렸지만, 지금은 하늘이 맑게 개고 햇볕이 난다.","e":"despejado는 '구름이 걷힌, 맑은'이라는 뜻입니다. 'Antes estaba nublado, pero ahora...'로 대조를 이루며 hace sol(해가 나다)과 어울리는 말이 필요합니다. 반대말 nublado/cubierto는 '흐린, 구름 낀'입니다.","x":["gris: 회색의 → 흐린 하늘을 나타내 해가 난다는 말과 맞지 않아 ✗","oscuro: 어두운 → 해가 난다는 내용과 반대라 ✗","despejado: 맑게 갠 → 정답 ✓","cubierto: 구름에 덮인 → 흐린 날씨라 ✗"]},{"id":"V626","q":"Esta niña es muy ____, lo entiende todo rápidamente.","o":["honesta","humilde","despierta","sincera"],"a":2,"k":"성격 형용사","t":"이 여자아이는 아주 영리해서, 모든 것을 빨리 이해한다.","e":"despierto는 원래 '깨어 있는'이라는 뜻이지만 사람의 성격을 말할 때는 '총명한, 영리한, 눈치 빠른'이라는 의미가 됩니다. 무엇이든 빨리 이해한다는 뒤 내용과 맞습니다. 'estar despierto'는 '깨어 있다', 'ser despierto'는 '영리하다'로 구분하세요.","x":["honesta: 정직한 → 이해가 빠른 것과 관계없어 ✗","humilde: 겸손한 → 이해력과 관계없어 ✗","despierta: 영리한, 총명한 → 빨리 이해한다는 내용과 맞아 정답 ✓","sincera: 솔직한 → 이해력과 관계없어 ✗"]},{"id":"V627","q":"Cuando estaba ____, tenía mucho tiempo libre, pero ahora lo único que hago es trabajar.","o":["soltero","ocupado","desempleado","casado"],"a":2,"k":"직업 상태 어휘","t":"실직 상태였을 때는 자유 시간이 많았는데, 지금은 일만 한다.","e":"desempleado는 '실업자의, 일자리가 없는'이라는 뜻으로 parado(스페인), sin trabajo와 비슷합니다. 문장은 과거(시간 많음)와 현재(일만 함)를 대조하므로, 과거에는 일이 없었다는 desempleado가 가장 알맞습니다. 'Cuando estaba ~'는 불완료과거로 과거의 상태를 나타냅니다.","x":["soltero: 미혼의 → 대조되는 내용이 '일'이므로 직업 상태가 더 알맞아 ✗","ocupado: 바쁜 → 바빴다면 시간이 많지 않았을 테니 ✗","desempleado: 실직한 → 일이 없어 시간이 많았다는 뜻이라 정답 ✓","casado: 결혼한 → 일과 직접적인 대조가 아니라 ✗"]},{"id":"V628","q":"____ yoga cada mañana.","o":["Juego","Practico","Creo","Tomo"],"a":1,"k":"운동 동사","t":"나는 매일 아침 요가를 한다.","e":"운동이나 활동을 꾸준히 한다고 할 때 practicar(실천하다, 연습하다)를 씁니다: practicar yoga, practicar deporte. 'hacer yoga'도 많이 씁니다. jugar는 공놀이나 게임 같은 경기에 씁니다(jugar al fútbol).","x":["Juego: (경기·놀이를) 하다 → 요가에는 jugar를 쓰지 않아 ✗","Practico: (운동을) 하다, 연습하다 → 정답 ✓","Creo: 믿다, 만들다 → 운동과 함께 쓰지 않아 ✗","Tomo: 먹다, 마시다, 타다 → 요가와 쓰지 않아 ✗"]},{"id":"V629","q":"España está en la parte más ____ de Europa.","o":["este","oeste","central","norte"],"a":1,"k":"방위 어휘","t":"스페인은 유럽의 가장 서쪽 부분에 있다.","e":"스페인은 이베리아 반도에 있어 유럽의 서쪽 끝에 위치합니다. 방위는 norte(북), sur(남), este(동), oeste(서)입니다. 형용사로는 occidental(서쪽의), oriental(동쪽의)도 자주 씁니다.","x":["este: 동쪽 → 스페인은 동쪽이 아니라 ✗","oeste: 서쪽 → 이베리아 반도의 위치와 맞아 정답 ✓","central: 중앙의 → 스페인은 유럽 중앙이 아니라 ✗","norte: 북쪽 → 스페인은 유럽 남서쪽이라 ✗"]},{"id":"V630","q":"Me han robado la cartera, voy a ir a la ____ de policía ahora mismo.","o":["casa","librería","comisaría","sala"],"a":2,"k":"공공기관 어휘","t":"지갑을 도둑맞았어, 지금 당장 경찰서에 갈 거야.","e":"comisaría (de policía)는 '경찰서'입니다. 도난 신고(denuncia)를 하러 가는 곳입니다. robar는 '훔치다'이고, 'Me han robado ~'는 '(누군가) 나에게서 ~을 훔쳐 갔다'라는 뜻입니다.","x":["casa: 집 → 'casa de policía'라는 표현은 쓰지 않아 ✗","librería: 서점 → 도난 신고하는 곳이 아니라 ✗","comisaría: 경찰서 → 정답 ✓","sala: 방, 홀 → 경찰서를 뜻하지 않아 ✗"]},{"id":"V631","q":"Lo primero que se ve al entrar a mi nueva vivienda es un gran ____.","o":["recibidor","aseo","baño","lavadero"],"a":0,"k":"집 구조 어휘","t":"내 새 집에 들어가면 가장 먼저 보이는 것은 큰 현관 홀이다.","e":"recibidor는 집 현관문을 열고 들어서면 바로 나오는 '현관 홀, 입구 공간'입니다. 동사 recibir(맞이하다)에서 나온 말입니다. 'Lo primero que se ve'는 '가장 먼저 보이는 것'이라는 뜻입니다.","x":["recibidor: 현관 홀 → 들어가자마자 보이는 공간이라 정답 ✓","aseo: 작은 화장실 → 보통 입구에 바로 보이는 공간이 아니라 ✗","baño: 욕실, 화장실 → 들어가자마자 보이는 공간으로 어색해 ✗","lavadero: 세탁실 → 입구 공간이 아니라 ✗"]},{"id":"V632","q":"A Ricardo le han ____ una beca para estudiar en Estados Unidos. Está muy ilusionado.","o":["dado","prestado","quitado","tomado"],"a":0,"k":"장학금 표현","t":"리카르도는 미국에서 공부할 장학금을 받았다. 그는 아주 들떠 있다.","e":"beca는 '장학금'입니다. 'le han dado una beca'는 '(누군가가) 그에게 장학금을 주었다'로, 결국 그가 장학금을 받았다는 뜻입니다. conceder una beca(장학금을 수여하다)도 자주 씁니다. ilusionado는 '기대에 부푼, 설레는'입니다.","x":["dado: 주었다 → 장학금을 받아 설렌다는 내용과 맞아 정답 ✓","prestado: 빌려주었다 → 장학금은 빌려주는 것이 아니라 ✗","quitado: 빼앗았다 → 그랬다면 설레지 않을 테니 ✗","tomado: 가져갔다, 받았다 → 'le han tomado'는 '그에게서 가져갔다'는 어색한 뜻이라 ✗"]},{"id":"V633","q":"Mi hermana no ve bien, tiene que ir a un ____ lo antes posible.","o":["dentista","cardiólogo","oftalmólogo","cirujano"],"a":2,"k":"의사·전문의 어휘","t":"내 여동생은 눈이 잘 안 보여서, 가능한 한 빨리 안과 의사에게 가야 한다.","e":"oftalmólogo는 '안과 의사'입니다. 눈이 잘 안 보인다(no ve bien)는 증상에 맞는 전문의입니다. lo antes posible는 '가능한 한 빨리'라는 표현입니다. 안경사는 óptico라고 합니다.","x":["dentista: 치과 의사 → 눈과 관계없어 ✗","cardiólogo: 심장 전문의 → 눈과 관계없어 ✗","oftalmólogo: 안과 의사 → 정답 ✓","cirujano: 외과 의사 → 시력 문제로 먼저 가는 곳이 아니라 ✗"]},{"id":"V634","q":"Si te duchas, ____ menos agua que si te bañas.","o":["gastas","salvas","guardas","ahorras"],"a":0,"k":"gastar 동사","t":"샤워를 하면 목욕을 할 때보다 물을 덜 쓴다.","e":"gastar는 '(돈·물·에너지 등을) 쓰다, 소비하다'라는 뜻입니다. 'gastas menos agua'는 '물을 덜 쓴다'입니다. ahorrar(절약하다)를 쓰려면 'ahorras más agua(물을 더 절약한다)'가 되어야 하므로, menos와 함께는 gastas가 맞습니다.","x":["gastas: 쓰다, 소비하다 → '물을 덜 쓴다'가 되어 정답 ✓","salvas: 구하다 → 물을 '구한다'는 어색해 ✗","guardas: 보관하다 → 샤워와 물 사용량에 맞지 않아 ✗","ahorras: 절약하다 → '덜 절약한다'가 되어 의미가 반대라 ✗"]},{"id":"V635","q":"Antes de freír los huevos, debes añadir aceite a la ____.","o":["cacerola","sartén","batidora","hornilla"],"a":1,"k":"주방용품 어휘","t":"달걀을 부치기 전에, 프라이팬에 기름을 둘러야 한다.","e":"sartén은 '프라이팬'으로, freír(튀기다, 부치다)할 때 씁니다. 여성 명사라서 la sartén입니다(지역에 따라 el sartén도 씀). cacerola는 국이나 스튜를 끓이는 냄비입니다.","x":["cacerola: 냄비 → 달걀 프라이에는 보통 쓰지 않아 ✗","sartén: 프라이팬 → 달걀을 부칠 때 쓰므로 정답 ✓","batidora: 믹서기, 거품기 → 기름을 넣고 부치는 도구가 아니라 ✗","hornilla: 가스레인지의 화구 → 기름을 직접 넣는 곳이 아니라 ✗"]},{"id":"V636","q":"Estaba ____ aquella noche, por eso no se acuerda de nada.","o":["despierto","atento","borracho","preparado"],"a":2,"k":"상태 형용사","t":"그날 밤 그는 취해 있어서, 아무것도 기억하지 못한다.","e":"borracho는 '술에 취한'이라는 뜻으로 'estar borracho'처럼 estar와 함께 씁니다. 술에 취해 아무것도 기억하지 못한다는 인과 관계가 자연스럽습니다. 'acordarse de'는 '~을 기억하다'입니다.","x":["despierto: 깨어 있는 → 깨어 있었다면 기억해야 하므로 ✗","atento: 주의 깊은 → 주의 깊었다면 기억할 테니 ✗","borracho: 술에 취한 → 기억하지 못하는 이유라 정답 ✓","preparado: 준비된 → 기억을 못 하는 이유가 아니라 ✗"]},{"id":"V637","q":"Aunque mis padres son rubios, mi hermano y yo somos ____.","o":["gorditos","pequeños","altos","morenos"],"a":3,"k":"외모(머리색) 어휘","t":"우리 부모님은 금발이지만, 내 남동생과 나는 머리가 갈색(검은 편)이다.","e":"moreno는 머리카락이 '짙은 색(갈색·검은색)인'이나 피부가 '까무잡잡한'을 뜻합니다. rubio(금발의)와 대조되므로 morenos가 정답입니다. Aunque(~이지만)가 대조를 만듭니다.","x":["gorditos: 통통한 → 금발과 대조되는 말이 아니라 ✗","pequeños: 작은 → 머리색과 대조가 아니라 ✗","altos: 키가 큰 → 머리색과 대조가 아니라 ✗","morenos: 머리가 짙은 색인 → 금발과 대조되어 정답 ✓"]},{"id":"V638","q":"Anabel y yo estuvimos ____ hasta la medianoche. Me encanta hablar con ella.","o":["conversando","esperando","peleando","colaborando"],"a":0,"k":"현재분사 진행","t":"아나벨과 나는 자정까지 이야기를 나눴다. 나는 그녀와 이야기하는 게 정말 좋다.","e":"conversar는 '대화하다, 이야기를 나누다'입니다. 'estar + 현재분사(-ando/-iendo)'는 진행 중인 동작을 나타내고, estuvimos conversando는 '(한동안) 이야기하고 있었다'입니다. 뒤의 'hablar con ella'와 의미가 이어집니다.","x":["conversando: 대화하는 중 → 이야기하는 걸 좋아한다는 말과 맞아 정답 ✓","esperando: 기다리는 중 → 이야기와 연결되지 않아 ✗","peleando: 싸우는 중 → 이야기하는 걸 좋아한다는 말과 맞지 않아 ✗","colaborando: 협력하는 중 → 대화와 직접 연결되지 않아 ✗"]},{"id":"V639","q":"Puedes echar los restos de comida en ese ____ de basura.","o":["cubo","vaso","plato","armario"],"a":0,"k":"생활용품 어휘","t":"남은 음식은 저 쓰레기통에 버리면 돼.","e":"cubo de basura는 스페인에서 '쓰레기통'을 뜻합니다(cubo = 양동이). 중남미에서는 bote de basura, tacho de basura 등 지역마다 다르게 말합니다. echar는 '던지다, 넣다, 버리다'라는 뜻으로 쓰였습니다.","x":["cubo: 통, 양동이(cubo de basura = 쓰레기통) → 정답 ✓","vaso: 컵 → 'vaso de basura'라는 말은 없어 ✗","plato: 접시 → 쓰레기를 넣는 곳이 아니라 ✗","armario: 옷장, 수납장 → 쓰레기통이 아니라 ✗"]},{"id":"V640","q":"Me aburren los ejercicios ____ porque no son dinámicos.","o":["variados","repetitivos","entretenidos","divertidos"],"a":1,"k":"성질 형용사","t":"반복적인 연습 문제는 역동적이지 않아서 지루하다.","e":"repetitivo는 '반복적인, 같은 것을 되풀이하는'이라는 뜻입니다. 'no son dinámicos(역동적이지 않다)'와 'me aburren(나를 지루하게 한다)'에 어울리는 것은 repetitivos입니다. aburrir는 gustar처럼 '대상'이 주어가 됩니다.","x":["variados: 다양한 → 다양하면 지루하지 않을 테니 ✗","repetitivos: 반복적인 → 지루한 이유라 정답 ✓","entretenidos: 재미있는 → 지루하다는 말과 반대라 ✗","divertidos: 즐거운 → 지루하다는 말과 반대라 ✗"]},{"id":"V641","q":"Este es el mejor cuchillo para ____ pan.","o":["tostar","cortar","salar","cocer"],"a":1,"k":"요리 동사","t":"이것이 빵을 자르기에 가장 좋은 칼이다.","e":"cuchillo(칼)로 하는 동작은 cortar(자르다)입니다. 'el mejor ~ para + 동사원형'은 '~하기에 가장 좋은 ~'입니다. 빵을 굽는(tostar) 것은 토스터(tostadora)로 합니다.","x":["tostar: 굽다(토스트하다) → 칼로 하는 일이 아니라 ✗","cortar: 자르다 → 칼의 용도라 정답 ✓","salar: 소금을 치다 → 칼로 하는 일이 아니라 ✗","cocer: 삶다, 익히다 → 칼로 하는 일이 아니라 ✗"]},{"id":"V642","q":"Mi casa no es grande ni pequeña, es ____.","o":["mediana","lujosa","barata","sencilla"],"a":0,"k":"크기 형용사","t":"우리 집은 크지도 작지도 않고, 중간 크기이다.","e":"mediano는 '중간 크기의, 보통의'라는 뜻입니다. 'ni grande ni pequeña(크지도 작지도 않은)'의 결론으로 알맞습니다. casa가 여성 명사라서 mediana가 됩니다. 옷 사이즈에서도 talla mediana(M 사이즈)라고 합니다.","x":["mediana: 중간 크기의 → 크지도 작지도 않다는 말과 맞아 정답 ✓","lujosa: 호화로운 → 크기에 대한 말이 아니라 ✗","barata: 값싼 → 크기에 대한 말이 아니라 ✗","sencilla: 소박한, 단순한 → 크기를 정확히 말하지 않아 ✗"]},{"id":"V643","q":"La cantidad de agua en los depósitos es ____, no podemos malgastarla.","o":["extraordinaria","abundante","superior","escasa"],"a":3,"k":"양 형용사","t":"저수조의 물의 양이 부족해서, 물을 낭비할 수 없다.","e":"escaso는 '부족한, 적은'이라는 뜻입니다. 'no podemos malgastarla(물을 낭비할 수 없다)'의 이유로는 물이 부족해야 하므로 escasa가 정답입니다. malgastar는 '낭비하다'입니다.","x":["extraordinaria: 엄청난, 특별한 → 물이 많다면 낭비 걱정의 이유가 안 돼 ✗","abundante: 풍부한 → 낭비할 수 없다는 말과 반대라 ✗","superior: 더 높은, 우월한 → 무엇보다 높은지 비교 대상이 없어 ✗","escasa: 부족한 → 낭비하면 안 되는 이유라 정답 ✓"]},{"id":"V644","q":"Los padres no suelen ser ____, piensan que sus hijos son los mejores.","o":["emotivos","subjetivos","objetivos","receptivos"],"a":2,"k":"성격 형용사","t":"부모들은 대개 객관적이지 않다, 자기 자식이 최고라고 생각한다.","e":"objetivo는 '객관적인', 반대말 subjetivo는 '주관적인'입니다. 자기 자식이 최고라고 생각하는 것은 객관적이지 않다는 뜻이므로 no ... objetivos가 맞습니다. soler + 동사원형은 '보통 ~하다'라는 표현입니다.","x":["emotivos: 감정적인 → '감정적이지 않다'는 자식 자랑과 맞지 않아 ✗","subjetivos: 주관적인 → '주관적이지 않다'면 뒤 내용과 모순이라 ✗","objetivos: 객관적인 → 객관적이지 않다는 뜻이 되어 정답 ✓","receptivos: 수용적인 → 뒤의 내용과 연결되지 않아 ✗"]},{"id":"V645","q":"Brasilia es la ____ de Brasil.","o":["ciudad","villa","región","capital"],"a":3,"k":"지리 어휘","t":"브라질리아는 브라질의 수도이다.","e":"capital은 '수도'라는 뜻의 여성 명사입니다(la capital). 브라질의 수도는 리우데자네이루나 상파울루가 아니라 브라질리아입니다. 참고로 el capital(남성)은 '자본'이라는 뜻입니다.","x":["ciudad: 도시 → 'la ciudad de Brasil'은 의미가 불분명해 ✗","villa: 마을, 별장 → 브라질리아를 설명하기에 맞지 않아 ✗","región: 지역 → 브라질리아는 도시라서 ✗","capital: 수도 → 정답 ✓"]},{"id":"V646","q":"En la autopista ____ a mayor velocidad que en las carreteras pequeñas.","o":["se conduce","se camina","se anda","se cabalga"],"a":0,"k":"무인칭 se","t":"고속도로에서는 작은 도로에서보다 더 빠른 속도로 운전한다.","e":"'se + 3인칭 동사'는 무인칭 표현으로 '(사람들은 일반적으로) ~한다'는 뜻입니다. autopista(고속도로)에서는 차를 운전하므로 se conduce가 맞습니다. 중남미에서는 conducir 대신 manejar를 많이 씁니다(se maneja).","x":["se conduce: 운전한다 → 고속도로와 속도에 맞아 정답 ✓","se camina: 걷는다 → 고속도로를 걷지 않아 ✗","se anda: 걷는다, 다닌다 → 고속 주행과 맞지 않아 ✗","se cabalga: 말을 탄다 → 고속도로에서 말을 타지 않아 ✗"]},{"id":"V647","q":"Estos zapatos son nuevos, todavía no los ____.","o":["he obtenido","he limpiado","he comprado","he estrenado"],"a":3,"k":"estrenar 동사","t":"이 신발은 새것이라, 아직 한 번도 신지 않았다.","e":"estrenar는 '(새 물건을) 처음 쓰다, 처음 입다'라는 뜻입니다. 새 신발이라 아직 처음으로 신어 보지 않았다는 의미이므로 no los he estrenado가 정답입니다. 영화가 '개봉하다'(estrenarse), 개봉작은 estreno입니다.","x":["he obtenido: 얻었다 → 새 신발을 '아직 얻지 않았다'는 모순이라 ✗","he limpiado: 닦았다 → 새 신발과 연결이 약해 ✗","he comprado: 샀다 → 이미 내 신발이니 '아직 안 샀다'는 모순이라 ✗","he estrenado: 처음 신었다 → 정답 ✓"]},{"id":"V648","q":"¿De qué color quiere que le ____ las uñas?","o":["recorte","lime","corte","pinte"],"a":3,"k":"미용 어휘","t":"손톱을 무슨 색으로 칠해 드릴까요?","e":"pintar las uñas는 '손톱에 매니큐어를 칠하다'입니다. 색(color)을 묻고 있으므로 pinte가 정답입니다. 'quiere que + 접속법(바람을 나타낼 때 쓰는 동사 형태)'이라서 pintar의 접속법 현재 pinte를 씁니다.","x":["recorte: 다듬어 자르다 → 색과 관계없어 ✗","lime: (줄로) 갈다 → 색과 관계없어 ✗","corte: 자르다 → 색과 관계없어 ✗","pinte: 칠하다 → 색을 묻는 질문과 맞아 정답 ✓"]},{"id":"V649","q":"Es una persona responsable que cumple con todas sus ____.","o":["obligaciones","pretensiones","elecciones","opciones"],"a":0,"k":"책임 어휘","t":"그는 자신의 모든 의무를 다하는 책임감 있는 사람이다.","e":"cumplir con sus obligaciones는 '자신의 의무를 다하다'라는 대표적인 표현입니다. responsable(책임감 있는)과 잘 어울립니다. obligación은 '의무', obligar는 '강요하다'입니다.","x":["obligaciones: 의무 → 책임감 있는 사람이 다하는 것이라 정답 ✓","pretensiones: 바람, 요구, 허세 → 'cumplir con'과 어울리지 않아 ✗","elecciones: 선택, 선거 → 의무를 다하는 의미가 아니라 ✗","opciones: 선택지 → 지키는 대상이 아니라 ✗"]},{"id":"V650","q":"Los viernes por la noche vamos a bailar a una conocida ____ de la ciudad.","o":["tasca","taberna","biblioteca","discoteca"],"a":3,"k":"여가 장소 어휘","t":"금요일 밤마다 우리는 시내의 유명한 클럽에 춤추러 간다.","e":"discoteca는 음악을 틀고 춤추는 '클럽, 디스코텍'입니다. ir a bailar(춤추러 가다)와 잘 어울립니다. 'ir a + 동사원형'은 여기서 '~하러 가다'라는 뜻입니다.","x":["tasca: 선술집(타파스와 술을 파는 작은 바) → 주로 춤추는 곳이 아니라 ✗","taberna: 주점 → 춤추러 가는 곳이 아니라 ✗","biblioteca: 도서관 → 춤추는 곳이 아니라 ✗","discoteca: 클럽 → 춤추러 가는 곳이라 정답 ✓"]},{"id":"V651","q":"¿Cuántas ____ hay en este rebaño?","o":["arañas","ovejas","palomas","gatas"],"a":1,"k":"동물 어휘","t":"이 양 떼에는 양이 몇 마리 있나요?","e":"rebaño는 양·염소 같은 가축의 '무리, 떼'입니다. 그래서 oveja(양)가 가장 자연스럽습니다. 목동은 pastor라고 합니다.","x":["arañas: 거미 → 떼를 지어 기르는 가축이 아니라 ✗","ovejas: 양 → rebaño를 이루는 대표 동물이라 정답 ✓","palomas: 비둘기 → 새 무리는 bandada라고 해서 ✗","gatas: (암)고양이 → rebaño로 기르지 않아 ✗"]},{"id":"V652","q":"El ____ es mi fruta favorita.","o":["queso","yogur","plátano","jamón"],"a":2,"k":"과일 어휘","t":"바나나는 내가 가장 좋아하는 과일이다.","e":"fruta favorita(가장 좋아하는 과일)이므로 과일 이름이 필요합니다. plátano는 스페인에서 '바나나'이고, 중남미에서는 banana, banano 등을 쓰기도 합니다. 남성 명사라 el plátano입니다.","x":["queso: 치즈 → 과일이 아니라 ✗","yogur: 요구르트 → 과일이 아니라 ✗","plátano: 바나나 → 과일이라 정답 ✓","jamón: 햄 → 과일이 아니라 ✗"]},{"id":"V653","q":"Siempre ____ atraído por la cultura mexicana.","o":["me senté","me volví","me noté","me sentí"],"a":3,"k":"sentirse 동사","t":"나는 항상 멕시코 문화에 끌렸다.","e":"sentirse + 형용사/과거분사는 '~하게 느끼다'라는 뜻입니다. sentirse atraído por는 '~에 끌림을 느끼다'로 자주 쓰는 표현입니다. sentir는 1인칭 단순과거가 sentí(규칙형 어미)입니다.","x":["me senté: 앉았다(sentarse) → sentirse와 헷갈리기 쉬운 오답 ✗","me volví: ~이 되었다 → siempre와 함께 '끌리게 되었다'는 어색해 ✗","me noté: (스스로) 느꼈다, 알아차렸다 → atraído와 함께 쓰지 않아 ✗","me sentí: 느꼈다 → sentirse atraído(끌리다)가 되어 정답 ✓"]},{"id":"V654","q":"Voy a darte mi número de teléfono ____, el que tienes es el anterior.","o":["real","legal","oficial","actual"],"a":3,"k":"시간 형용사","t":"내 현재 전화번호를 알려 줄게, 네가 가진 건 예전 번호야.","e":"actual은 영어 actual(실제의)과 달리 '현재의, 지금의'라는 뜻입니다. el anterior(이전 것)와 대조되므로 actual이 정답입니다. actualmente는 '현재'라는 부사입니다.","x":["real: 실제의, 진짜의 → 이전 번호와 대조되는 말이 아니라 ✗","legal: 합법적인 → 전화번호에 어울리지 않아 ✗","oficial: 공식적인 → 이전 번호와의 대조로 맞지 않아 ✗","actual: 현재의 → '예전 것'과 대조되어 정답 ✓"]},{"id":"V655","q":"Estamos preocupados porque nuestro hijo está ____.","o":["contento","enfermo","calmado","entretenido"],"a":1,"k":"건강 상태 어휘","t":"아들이 아파서 우리는 걱정하고 있다.","e":"enfermo는 '아픈, 병든'이라는 뜻으로 estar와 함께 상태를 나타냅니다. 부모가 걱정하는(preocupados) 이유가 되는 것은 아이가 아픈 것입니다. 병은 enfermedad, 간호사는 enfermero입니다.","x":["contento: 기쁜 → 걱정할 이유가 아니라 ✗","enfermo: 아픈 → 걱정하는 이유라 정답 ✓","calmado: 차분한 → 걱정할 이유가 아니라 ✗","entretenido: 즐겁게 시간을 보내는 → 걱정할 이유가 아니라 ✗"]},{"id":"V656","q":"La mía no es una profesión bien ____, por eso tengo siempre problemas de dinero.","o":["definida","pagada","delimitada","comprendida"],"a":1,"k":"보수·직업 어휘","t":"내 직업은 보수가 좋은 직업이 아니라서, 나는 늘 돈 문제가 있다.","e":"bien pagado는 '보수가 좋은, 급여를 잘 받는'이라는 뜻입니다. 돈 문제가 있다는 뒤 문장의 원인이 되므로 pagada가 정답입니다(profesión이 여성 명사). 반대는 mal pagado입니다.","x":["definida: 정의된 → 돈 문제와 직접 연결되지 않아 ✗","pagada: 보수가 지급되는 → 돈 문제의 이유라 정답 ✓","delimitada: 경계가 정해진 → 돈 문제와 관계없어 ✗","comprendida: 이해되는 → 돈 문제와 관계없어 ✗"]},{"id":"V657","q":"Si eres estudiante, la entrada a ese museo cuesta ____.","o":["la mitad","mucho más","el triple","el doble"],"a":0,"k":"분수·양 표현","t":"학생이면, 그 박물관 입장료는 절반이다.","e":"la mitad는 '절반'입니다. 학생 할인을 받으면 입장료가 반값이 된다는 뜻이 자연스럽습니다. el doble(두 배), el triple(세 배)도 함께 기억하세요.","x":["la mitad: 절반 → 학생 할인과 맞아 정답 ✓","mucho más: 훨씬 더 많이 → 학생이 더 많이 내는 것은 어색해 ✗","el triple: 세 배 → 학생이 세 배를 내는 것은 어색해 ✗","el doble: 두 배 → 학생이 두 배를 내는 것은 어색해 ✗"]},{"id":"V658","q":"¡Qué ____ tan pesada! ¿Cuántos libros llevas?","o":["agenda","cartera","libreta","mochila"],"a":3,"k":"가방 어휘","t":"배낭이 정말 무겁네! 책을 몇 권이나 넣었어?","e":"mochila는 등에 메는 '배낭, 책가방'입니다. 'Qué + 명사 + tan + 형용사'는 '정말 ~한 ~이구나!'라는 감탄문입니다. 책을 여러 권 넣어 무거운 것은 mochila가 가장 자연스럽습니다. 참고로 스페인에서 cartera는 '지갑'이나 '서류가방'을 뜻합니다.","x":["agenda: 다이어리, 일정 수첩 → 책을 넣는 물건이 아니라 ✗","cartera: 지갑, 서류가방 → 책 여러 권을 넣는 대표 물건으로 덜 자연스러워 ✗","libreta: 수첩 → 책을 넣는 물건이 아니라 ✗","mochila: 배낭 → 책을 넣어 무거운 가방이라 정답 ✓"]},{"id":"V659","q":"Mi hijo ya tiene 25 años, es lógico que quiera ____.","o":["olvidarse","independizarse","comportarse","agotarse"],"a":1,"k":"독립 동사","t":"내 아들은 벌써 25살이니, 독립하고 싶어 하는 건 당연하다.","e":"independizarse는 '독립하다(부모 곁을 떠나 혼자 살다)'라는 뜻의 재귀동사입니다. 'es lógico que + 접속법'은 '~하는 것은 당연하다'로, 그래서 quiera(querer의 접속법)가 쓰였습니다.","x":["olvidarse: 잊다 → 무엇을 잊는지 없어 어색해 ✗","independizarse: 독립하다 → 25살이 된 아들에게 자연스러워 정답 ✓","comportarse: 행동하다 → 보통 bien/mal 등과 함께 써서 ✗","agotarse: 지치다, 다 떨어지다 → 원하는 일로 어색해 ✗"]},{"id":"V660","q":"No ____ nada que tenga azúcar, soy diabético.","o":["consumo","vendo","fabrico","comparto"],"a":0,"k":"consumir 동사","t":"나는 설탕이 든 것은 아무것도 먹지 않는다, 당뇨병이 있어서.","e":"consumir는 '소비하다, (음식을) 섭취하다'라는 뜻입니다. 당뇨병(diabético) 환자가 설탕이 든 음식을 먹지 않는다는 내용이므로 consumo가 정답입니다. 'nada que tenga'는 '~을 가진 어떤 것도'로, 접속법 tenga가 쓰였습니다.","x":["consumo: 섭취하다 → 당뇨병과 맞아 정답 ✓","vendo: 팔다 → 당뇨병이 파는 것과 관계없어 ✗","fabrico: 제조하다 → 당뇨병과 관계없어 ✗","comparto: 나누다 → 당뇨병과 관계없어 ✗"]},{"id":"V661","q":"El dietista me dijo que tengo un ____ saludable para mi altura.","o":["órgano","peso","temperamento","carácter"],"a":1,"k":"건강·신체 어휘","t":"영양사가 내 키에 비해 체중이 건강한 수준이라고 말했다.","e":"peso는 '무게, 체중'입니다. 키(altura)와 함께 건강한 상태를 말할 때 '체중'이 가장 자연스럽습니다. 동사 pesar(무게가 ~이다)와 관련 있고, '살이 찌다'는 subir de peso / engordar입니다.","x":["órgano: 장기, 기관 → 키와 비교하는 대상이 아니라 ✗","peso: 체중 → 키에 맞는 건강한 체중이라 정답 ✓","temperamento: 기질 → 키와 관계없어 ✗","carácter: 성격 → 키와 관계없어 ✗"]},{"id":"V662","q":"Para no perderlos, meted estos folios en vuestras ____.","o":["tizas","carpetas","gomas","papeleras"],"a":1,"k":"문구류 어휘","t":"잃어버리지 않도록, 이 종이들을 너희 파일철에 넣어라.","e":"carpeta는 종이를 끼워 보관하는 '서류철, 파일'입니다. folio는 A4 크기의 종이입니다. meted는 meter(넣다)의 vosotros 긍정 명령형으로, 스페인에서 쓰는 형태입니다(중남미에서는 ustedes에게 metan).","x":["tizas: 분필 → 종이를 넣을 수 없어 ✗","carpetas: 서류철, 파일 → 종이를 보관해 정답 ✓","gomas: 지우개, 고무줄 → 종이를 넣을 수 없어 ✗","papeleras: 휴지통 → 잃어버리지 않으려는 목적과 반대라 ✗"]},{"id":"V663","q":"Los pisos están más baratos este año. ¡Es nuestra ____!","o":["oportunidad","comunidad","localidad","realidad"],"a":0,"k":"기회 어휘","t":"올해는 아파트가 더 싸다. 우리의 기회야!","e":"oportunidad는 '기회'입니다. 집값이 싸졌으니 살 '기회'라는 말이 자연스럽습니다. aprovechar la oportunidad(기회를 잡다)도 자주 쓰는 표현입니다. 스페인에서 piso는 '아파트(공동주택의 한 세대)'를 뜻합니다.","x":["oportunidad: 기회 → 집이 싸졌다는 상황과 맞아 정답 ✓","comunidad: 공동체, 주민회 → 문맥과 맞지 않아 ✗","localidad: 지역, 마을 → 문맥과 맞지 않아 ✗","realidad: 현실 → 감탄의 대상으로 어색해 ✗"]},{"id":"V664","q":"Mi abuelo no escucha nada, se quedó ____ hace tiempo.","o":["ciego","mudo","sordo","gordo"],"a":2,"k":"신체 장애 어휘","t":"우리 할아버지는 아무것도 듣지 못하신다, 오래전에 귀가 머셨다.","e":"sordo는 '귀가 먼, 청각 장애가 있는'입니다. 'no escucha nada(아무것도 못 듣는다)'와 연결됩니다. quedarse + 형용사는 '~한 상태가 되다'로, quedarse sordo(귀가 멀다), quedarse ciego(눈이 멀다)처럼 씁니다.","x":["ciego: 눈이 먼 → 듣는 것과 관계없어 ✗","mudo: 말을 못 하는 → 듣는 것과 관계없어 ✗","sordo: 귀가 먼 → 정답 ✓","gordo: 뚱뚱한 → 듣는 것과 관계없어 ✗"]},{"id":"V665","q":"Los ____ están en los últimos pisos de los edificios.","o":["sótanos","garajes","áticos","pasillos"],"a":2,"k":"건물 구조 어휘","t":"펜트하우스(꼭대기 층 집)는 건물의 맨 위층에 있다.","e":"ático는 건물의 '꼭대기 층(다락층, 펜트하우스)'입니다. 반대로 sótano는 '지하실'입니다. 'los últimos pisos'는 '맨 위의 층들'이라는 뜻입니다.","x":["sótanos: 지하실 → 건물 아래에 있어 ✗","garajes: 차고 → 보통 지하나 1층에 있어 ✗","áticos: 꼭대기 층 → 정답 ✓","pasillos: 복도 → 모든 층에 있어 ✗"]},{"id":"V666","q":"Manuel trabaja como ____ en el restaurante familiar.","o":["entrenador","farmacéutico","camarero","reportero"],"a":2,"k":"직업 어휘","t":"마누엘은 가족이 운영하는 식당에서 웨이터로 일한다.","e":"camarero는 스페인에서 '웨이터, 종업원'입니다. 식당(restaurante)에서 일하는 직업으로 알맞습니다. 중남미에서는 mesero(멕시코 등), mozo(아르헨티나 등)라고도 합니다. 'trabajar como + 직업'은 '~로 일하다'입니다.","x":["entrenador: 코치, 트레이너 → 식당 직업이 아니라 ✗","farmacéutico: 약사 → 식당 직업이 아니라 ✗","camarero: 웨이터 → 식당에서 일해 정답 ✓","reportero: 기자 → 식당 직업이 아니라 ✗"]},{"id":"V667","q":"Los tigres no son animales de compañía, sino animales ____.","o":["domados","indefensos","domésticos","salvajes"],"a":3,"k":"동물 형용사","t":"호랑이는 반려동물이 아니라 야생동물이다.","e":"animal salvaje는 '야생동물', animal de compañía는 '반려동물'입니다. 'no A, sino B'는 'A가 아니라 B'라는 표현이라 반려동물과 반대되는 salvajes가 정답입니다. 반려동물은 mascota라고도 합니다.","x":["domados: 길들여진 → 반려동물과 대조되지 않아 ✗","indefensos: 무방비의 → 호랑이를 설명하기에 맞지 않아 ✗","domésticos: 가축의, 집에서 기르는 → 반려동물과 같은 쪽이라 ✗","salvajes: 야생의 → 반려동물과 대조되어 정답 ✓"]},{"id":"V668","q":"Ser bilingüe es ____ a la hora de encontrar trabajo.","o":["un problema","un inconveniente","una ventaja","una desventaja"],"a":2,"k":"장단점 어휘","t":"2개 국어를 하는 것은 일자리를 구할 때 장점이다.","e":"ventaja는 '장점, 이점', 반대말 desventaja는 '단점'입니다. 두 언어를 하는 것은 취업할 때 유리하므로 una ventaja가 정답입니다. a la hora de + 동사원형은 '~할 때'라는 표현입니다.","x":["un problema: 문제 → 2개 국어 능력은 문제가 아니라 ✗","un inconveniente: 불편한 점, 단점 → 의미가 반대라 ✗","una ventaja: 장점 → 정답 ✓","una desventaja: 단점 → 의미가 반대라 ✗"]},{"id":"V669","q":"____ recuerdos a tus padres de mi parte.","o":["Dales","Diles","Hazles","Pásales"],"a":0,"k":"dar recuerdos","t":"내 대신 부모님께 안부 전해 줘.","e":"dar recuerdos a alguien은 '~에게 안부를 전하다'라는 관용 표현입니다. Dales는 dar의 tú 명령형 da에 간접목적격 대명사 les(그들에게)가 붙은 형태입니다. de mi parte는 '나를 대신해서'입니다.","x":["Dales: (그들에게) 주어라 → dar recuerdos(안부 전하다) 표현이라 정답 ✓","Diles: (그들에게) 말해라 → recuerdos와 함께 쓰지 않아 ✗","Hazles: (그들에게) 해 줘라 → recuerdos와 함께 쓰지 않아 ✗","Pásales: (그들에게) 건네라 → 안부 표현에서는 dar를 써서 ✗"]},{"id":"V670","q":"Algunos empleados tienen miedo de los ____ estrictos.","o":["profesores","maestros","ayudantes","jefes"],"a":3,"k":"직장 어휘","t":"어떤 직원들은 엄격한 상사를 무서워한다.","e":"jefe는 '상사, 우두머리'입니다. empleados(직원들)가 두려워하는 대상으로 회사의 상사가 자연스럽습니다. tener miedo de/a는 '~을 무서워하다'입니다.","x":["profesores: 선생님 → 직원과의 관계가 아니라 ✗","maestros: (초등) 교사 → 직원과의 관계가 아니라 ✗","ayudantes: 조수 → 직원이 두려워할 윗사람이 아니라 ✗","jefes: 상사 → 직원의 윗사람이라 정답 ✓"]},{"id":"V671","q":"____ se toma a media tarde.","o":["La merienda","La cena","El desayuno","El almuerzo"],"a":0,"k":"식사 어휘","t":"간식(메리엔다)은 오후 중간에 먹는다.","e":"merienda는 오후 5~6시쯤 먹는 '간식'입니다. a media tarde는 '오후 중간쯤'입니다. 스페인의 식사: desayuno(아침), almuerzo/comida(점심), merienda(간식), cena(저녁). 동사로는 merendar입니다.","x":["La merienda: 오후 간식 → 오후 중간에 먹어 정답 ✓","La cena: 저녁 식사 → 밤에 먹어 ✗","El desayuno: 아침 식사 → 아침에 먹어 ✗","El almuerzo: 점심(또는 오전 간식) → 오후 중간이 아니라 ✗"]},{"id":"V672","q":"Manuel es un ____ en historia del siglo XX. Sabe mucho sobre ese tema.","o":["participante","experto","principiante","ignorante"],"a":1,"k":"전문가 어휘","t":"마누엘은 20세기 역사 전문가다. 그 주제에 대해 아주 많이 안다.","e":"experto는 '전문가'로, 'experto en + 분야'는 '~의 전문가'입니다. 'Sabe mucho(많이 안다)'와 연결됩니다. 반대로 principiante는 '초보자'입니다.","x":["participante: 참가자 → 많이 안다는 내용과 연결되지 않아 ✗","experto: 전문가 → 정답 ✓","principiante: 초보자 → 많이 안다는 말과 반대라 ✗","ignorante: 무지한 사람 → 많이 안다는 말과 반대라 ✗"]},{"id":"V673","q":"Aquí en primavera el tiempo es más ____ que en verano, tanto que no sabes qué ropa ponerte.","o":["ilógico","variable","informal","razonable"],"a":1,"k":"날씨 형용사","t":"여기 봄 날씨는 여름보다 더 변덕스러워서, 무슨 옷을 입어야 할지 모를 정도다.","e":"variable은 '변하기 쉬운, 변덕스러운'이라는 뜻입니다. 날씨가 자주 바뀌어 어떤 옷을 입을지 모른다는 내용과 맞습니다. 'tanto que ~'는 '너무 그래서 ~할 정도이다'라는 표현입니다.","x":["ilógico: 비논리적인 → 날씨를 설명하는 말로 어색해 ✗","variable: 변덕스러운 → 옷 고르기 어렵다는 내용과 맞아 정답 ✓","informal: 격식 없는 → 날씨에 쓰지 않아 ✗","razonable: 합리적인 → 날씨에 쓰지 않아 ✗"]},{"id":"V674","q":"Esta ropa está ____, deberías comprar algunas prendas nuevas.","o":["tendida","arrugada","gastada","doblada"],"a":2,"k":"옷 상태 어휘","t":"이 옷은 낡았어, 새 옷을 몇 벌 사야겠다.","e":"gastado는 '닳은, 낡은'이라는 뜻으로 gastar(써서 없애다)의 과거분사입니다. 새 옷을 사야 하는 이유로 알맞습니다. prenda는 '옷 한 벌, 의류'입니다.","x":["tendida: 널린(빨래) → 새 옷을 사야 할 이유가 아니라 ✗","arrugada: 구겨진 → 다리면 되니 새 옷을 살 이유로 약해 ✗","gastada: 낡은 → 새 옷을 살 이유라 정답 ✓","doblada: 개어진 → 새 옷을 살 이유가 아니라 ✗"]},{"id":"V675","q":"Siempre he tenido ____, en particular perros y gatos.","o":["cabras","mascotas","burros","bueyes"],"a":1,"k":"반려동물 어휘","t":"나는 항상 반려동물을 키워 왔다, 특히 개와 고양이를.","e":"mascota는 '반려동물, 애완동물'입니다. 개와 고양이(perros y gatos)는 대표적인 반려동물입니다. 'en particular'는 '특히'라는 뜻입니다.","x":["cabras: 염소 → 개와 고양이를 포함하지 않아 ✗","mascotas: 반려동물 → 개와 고양이를 포함해 정답 ✓","burros: 당나귀 → 개와 고양이를 포함하지 않아 ✗","bueyes: 황소 → 개와 고양이를 포함하지 않아 ✗"]},{"id":"V676","q":"Todos los ____ deben respetar las señales de tráfico.","o":["compradores","conductores","empresarios","comerciantes"],"a":1,"k":"교통 어휘","t":"모든 운전자는 교통 표지판을 지켜야 한다.","e":"conductor는 '운전자'입니다(conducir: 운전하다). señales de tráfico(교통 표지판)를 지켜야 하는 사람으로 알맞습니다. 중남미에서는 chofer, manejador 등도 씁니다.","x":["compradores: 구매자 → 교통 표지판과 관계없어 ✗","conductores: 운전자 → 정답 ✓","empresarios: 기업가 → 교통 표지판과 관계없어 ✗","comerciantes: 상인 → 교통 표지판과 관계없어 ✗"]},{"id":"V677","q":"Apenas tiene dinero, su situación ____ es mala.","o":["médica","económica","física","histórica"],"a":1,"k":"경제 어휘","t":"그는 돈이 거의 없어서, 경제 사정이 좋지 않다.","e":"situación económica는 '경제 사정, 형편'입니다. apenas는 '거의 ~않다'라는 뜻이라 돈이 거의 없다는 말이 되고, 이것이 경제 사정과 연결됩니다.","x":["médica: 의료의 → 돈과 관계없어 ✗","económica: 경제적인 → 돈이 없다는 말과 맞아 정답 ✓","física: 신체적인 → 돈과 관계없어 ✗","histórica: 역사적인 → 돈과 관계없어 ✗"]},{"id":"V678","q":"Aunque me duele la cabeza, no quiero ninguna ____.","o":["galleta","torta","aspirina","banana"],"a":2,"k":"약 어휘","t":"머리가 아프지만, 아스피린은 전혀 먹고 싶지 않다.","e":"aspirina는 '아스피린(진통제)'입니다. 머리가 아플 때(me duele la cabeza) 먹는 약이 필요하므로 정답입니다. aunque(~이지만)는 대조를 나타냅니다. doler는 gustar처럼 아픈 부위가 주어입니다.","x":["galleta: 쿠키 → 두통과 관계없어 ✗","torta: 케이크 → 두통과 관계없어 ✗","aspirina: 아스피린 → 두통약이라 정답 ✓","banana: 바나나 → 두통과 관계없어 ✗"]},{"id":"V679","q":"Todos los artículos de esa tienda son muy ____, por eso compré tantas cosas allí.","o":["inútiles","feos","malos","baratos"],"a":3,"k":"가격 형용사","t":"그 가게의 모든 물건이 아주 싸서, 나는 거기서 많은 것을 샀다.","e":"barato는 '값싼', 반대말 caro는 '비싼'입니다. 많이 샀다(compré tantas cosas)는 이유가 되는 것은 물건이 싸서입니다. artículo는 여기서 '상품, 물건'입니다.","x":["inútiles: 쓸모없는 → 많이 산 이유가 되지 않아 ✗","feos: 못생긴 → 많이 산 이유가 되지 않아 ✗","malos: 나쁜 → 많이 산 이유가 되지 않아 ✗","baratos: 싼 → 많이 산 이유라 정답 ✓"]},{"id":"V680","q":"¿Qué ____ universitaria te gustaría hacer?","o":["carrera","secretaría","agencia","pensión"],"a":0,"k":"교육 어휘","t":"어떤 대학 전공을 하고 싶니?","e":"carrera universitaria는 '대학 전공(학위 과정)'입니다. hacer/estudiar una carrera는 '대학 과정을 밟다'는 뜻입니다. carrera는 '경주, 경력'이라는 뜻도 있습니다.","x":["carrera: 대학 전공 → 정답 ✓","secretaría: 비서직, 사무국 → 대학 전공을 뜻하지 않아 ✗","agencia: 대리점, 기관 → 대학과 관계없어 ✗","pensión: 연금, 하숙 → 대학 전공이 아니라 ✗"]},{"id":"V681","q":"Hace calor, ¿por qué te has puesto un ____?","o":["collar","sombrero","pantalón","jersey"],"a":3,"k":"옷 어휘","t":"날이 더운데, 왜 스웨터를 입었니?","e":"jersey는 스페인에서 '스웨터'입니다(중남미: suéter, chompa 등). 더운 날(Hace calor) 입기에 이상한 옷이라 질문의 대상이 됩니다. ponerse는 '(옷을) 입다'입니다.","x":["collar: 목걸이 → 더위와 관계없어 ✗","sombrero: 모자 → 더운 날에도 쓰므로 이상하지 않아 ✗","pantalón: 바지 → 더운 날에도 입으므로 ✗","jersey: 스웨터 → 더운 날 입기에 이상해 정답 ✓"]},{"id":"V682","q":"Un ____ suele ser más grande y más cómodo que una silla.","o":["taburete","sillón","cojín","paragüero"],"a":1,"k":"가구 어휘","t":"안락의자는 보통 의자보다 더 크고 편하다.","e":"sillón은 팔걸이가 있는 '안락의자'입니다. silla(의자)에 -ón(크다는 뜻의 접미사)이 붙은 말입니다. taburete는 등받이 없는 '스툴'입니다.","x":["taburete: 등받이 없는 의자 → 의자보다 편하지 않아 ✗","sillón: 안락의자 → 정답 ✓","cojín: 쿠션 → 의자보다 크다고 비교하는 가구가 아니라 ✗","paragüero: 우산꽂이 → 앉는 가구가 아니라 ✗"]},{"id":"V683","q":"Su ____ es muy evidente, no es una persona generosa.","o":["antipatía","euforia","tacañería","memoria"],"a":2,"k":"성격 명사","t":"그의 인색함은 아주 뚜렷하다, 그는 너그러운 사람이 아니다.","e":"tacañería는 '인색함, 구두쇠 기질'이고, 형용사는 tacaño(인색한)입니다. 'no es una persona generosa(너그러운 사람이 아니다)'와 연결됩니다. generoso(너그러운)는 tacaño의 반대말입니다.","x":["antipatía: 반감, 비호감 → 너그럽지 않다는 내용과 직접 맞지 않아 ✗","euforia: 큰 기쁨, 흥분 → 문맥과 관계없어 ✗","tacañería: 인색함 → 정답 ✓","memoria: 기억력 → 문맥과 관계없어 ✗"]},{"id":"V684","q":"Voy a la ____, necesito comprar lejía.","o":["tintorería","farmacia","droguería","lavandería"],"a":2,"k":"가게 어휘","t":"나는 잡화점에 가, 표백제를 사야 하거든.","e":"droguería는 스페인에서 세제·표백제·청소용품 등을 파는 '생활용품점'입니다. lejía는 '표백제(락스)'입니다. 콜롬비아 등 일부 중남미 지역에서는 droguería가 '약국'을 뜻하기도 합니다.","x":["tintorería: 세탁소(드라이클리닝) → 표백제를 파는 곳이 아니라 ✗","farmacia: 약국 → 표백제를 파는 곳이 아니라 ✗","droguería: 생활용품점 → 표백제를 팔아 정답 ✓","lavandería: 빨래방 → 표백제를 사는 곳이 아니라 ✗"]},{"id":"V685","q":"Me muero de ____, me voy a la cama ahora mismo.","o":["calor","frío","miedo","sueño"],"a":3,"k":"morirse de 표현","t":"졸려 죽겠어, 지금 당장 자러 갈래.","e":"morirse de + 명사는 '~해서 죽을 것 같다'라는 과장 표현입니다. morirse de sueño(졸려 죽겠다), morirse de hambre(배고파 죽겠다) 등으로 씁니다. 잠자리에 들겠다(me voy a la cama)는 말에 맞는 것은 sueño(졸림)입니다.","x":["calor: 더위 → 자러 가는 이유로 맞지 않아 ✗","frío: 추위 → 자러 가는 이유로 맞지 않아 ✗","miedo: 두려움 → 자러 가는 이유로 맞지 않아 ✗","sueño: 졸림 → 자러 가는 이유라 정답 ✓"]},{"id":"V686","q":"Tristemente, todavía hay mucha gente ____ en el mundo.","o":["pobre","lista","rica","normal"],"a":0,"k":"사회 어휘","t":"슬프게도, 세상에는 아직도 가난한 사람이 많다.","e":"pobre는 '가난한'입니다. Tristemente(슬프게도)와 어울리는 부정적인 사회 현실은 가난입니다. pobre가 명사 앞에 오면 '불쌍한'(un pobre hombre)이라는 뜻이 되니 주의하세요.","x":["pobre: 가난한 → 슬픈 현실이라 정답 ✓","lista: 똑똑한 → 슬퍼할 일이 아니라 ✗","rica: 부유한 → 슬퍼할 일이 아니라 ✗","normal: 평범한 → 슬퍼할 일이 아니라 ✗"]},{"id":"V687","q":"Me dedico a la prensa deportiva, escribo sobre ____.","o":["economía","historia","cine","atletismo"],"a":3,"k":"스포츠 어휘","t":"나는 스포츠 신문 일을 해서, 육상에 대해 쓴다.","e":"atletismo는 '육상'으로 스포츠 종목입니다. prensa deportiva(스포츠 언론)에서 다루는 주제이므로 정답입니다. dedicarse a는 '~에 종사하다'입니다. 육상 선수는 atleta입니다.","x":["economía: 경제 → 스포츠가 아니라 ✗","historia: 역사 → 스포츠가 아니라 ✗","cine: 영화 → 스포츠가 아니라 ✗","atletismo: 육상 → 스포츠 기사 주제라 정답 ✓"]},{"id":"V688","q":"Me temo que no hemos ____ a ningún acuerdo.","o":["venido","salido","andado","llegado"],"a":3,"k":"llegar a 표현","t":"유감스럽게도 우리는 아무 합의에도 이르지 못한 것 같다.","e":"llegar a un acuerdo는 '합의에 이르다'라는 관용 표현입니다. 현재완료 hemos llegado가 쓰였습니다. Me temo que ~는 '(유감이지만) ~인 것 같다'라는 표현입니다.","x":["venido: 왔다 → acuerdo와 함께 쓰지 않아 ✗","salido: 나갔다 → acuerdo와 함께 쓰지 않아 ✗","andado: 걸었다 → acuerdo와 함께 쓰지 않아 ✗","llegado: 이르렀다 → llegar a un acuerdo(합의에 이르다)라 정답 ✓"]},{"id":"V689","q":"Soy miope, por eso llevo ____.","o":["gafas","sombrero","bastón","corbata"],"a":0,"k":"시력 어휘","t":"나는 근시라서 안경을 쓴다.","e":"miope는 '근시인'입니다. 시력을 교정하려면 gafas(안경)를 씁니다. 중남미에서는 lentes, anteojos라고 많이 합니다. llevar는 '(몸에) 착용하다'라는 뜻으로도 씁니다.","x":["gafas: 안경 → 근시 교정용이라 정답 ✓","sombrero: 모자 → 시력과 관계없어 ✗","bastón: 지팡이 → 근시와 관계없어 ✗","corbata: 넥타이 → 시력과 관계없어 ✗"]},{"id":"V690","q":"Estoy harta de su ____, se cree superior a todos nosotros.","o":["discreción","amabilidad","arrogancia","serenidad"],"a":2,"k":"성격 명사","t":"그의 오만함에 질렸어, 그는 자기가 우리 모두보다 잘났다고 생각해.","e":"arrogancia는 '오만함, 거만함'입니다. 'se cree superior(자기가 더 낫다고 여긴다)'와 맞습니다. estar harto/a de는 '~에 질리다, 넌더리 나다'입니다.","x":["discreción: 신중함 → 좋은 성품이라 질릴 이유가 아니라 ✗","amabilidad: 친절함 → 질릴 이유가 아니라 ✗","arrogancia: 오만함 → 남보다 잘났다고 여기는 태도라 정답 ✓","serenidad: 침착함 → 질릴 이유가 아니라 ✗"]},{"id":"V691","q":"En mis ratos de ____ me dedico a mis aficiones.","o":["labores","ocio","ocupaciones","trabajo"],"a":1,"k":"여가 어휘","t":"여가 시간에는 내 취미 생활을 한다.","e":"ocio는 '여가, 쉬는 시간'입니다. ratos de ocio는 '한가한 시간'으로, 취미(aficiones)를 즐기는 때입니다. tiempo de ocio, tiempo libre도 같은 뜻입니다.","x":["labores: 일, 노동 → 취미와 반대 개념이라 ✗","ocio: 여가 → 취미를 하는 시간이라 정답 ✓","ocupaciones: 일, 업무 → 취미와 반대 개념이라 ✗","trabajo: 일 → 취미를 하는 시간이 아니라 ✗"]},{"id":"V692","q":"Mi madre le da ____ a mi hermanito porque todavía no puede beber solo.","o":["la manta","el pañal","la cuna","el biberón"],"a":3,"k":"아기용품 어휘","t":"엄마는 내 남동생이 아직 혼자 마시지 못해서 젖병을 물려준다.","e":"biberón은 '젖병'입니다. 아직 혼자 마실 수 없다(no puede beber solo)는 내용과 맞습니다. hermanito는 hermano에 축소사 -ito를 붙여 '어린 남동생'을 다정하게 말한 것입니다.","x":["la manta: 담요 → 마시는 것과 관계없어 ✗","el pañal: 기저귀 → 마시는 것과 관계없어 ✗","la cuna: 아기 침대 → 마시는 것과 관계없어 ✗","el biberón: 젖병 → 마실 때 쓰므로 정답 ✓"]},{"id":"V693","q":"Mañana vamos a aprender ____ coloquiales en la clase de español.","o":["expresiones","exposiciones","instrucciones","explicaciones"],"a":0,"k":"언어 어휘","t":"내일 스페인어 수업에서 구어 표현을 배울 것이다.","e":"expresión coloquial은 '구어 표현, 일상 회화 표현'입니다. coloquial은 '구어체의, 일상적인'이라는 뜻입니다. aprender expresiones(표현을 배우다)가 자연스러운 조합입니다.","x":["expresiones: 표현 → 구어 표현을 배우므로 정답 ✓","exposiciones: 전시회, 발표 → coloquiales와 어울리지 않아 ✗","instrucciones: 지시 사항, 설명서 → 문맥과 맞지 않아 ✗","explicaciones: 설명 → '구어 설명'을 배운다는 건 어색해 ✗"]},{"id":"V694","q":"Los ____ son mucho más grandes que los gallos.","o":["patos","caballos","pollos","ratones"],"a":1,"k":"동물 어휘","t":"말은 수탉보다 훨씬 더 크다.","e":"caballo는 '말'입니다. gallo(수탉)보다 훨씬 크다(mucho más grandes)는 비교가 성립하는 동물은 말입니다. 오리(pato), 병아리·닭(pollo), 쥐(ratón)는 수탉과 크기가 비슷하거나 작습니다.","x":["patos: 오리 → 수탉과 크기가 비슷해 ✗","caballos: 말 → 수탉보다 훨씬 커서 정답 ✓","pollos: 병아리, 닭 → 수탉보다 훨씬 크지 않아 ✗","ratones: 쥐 → 수탉보다 작아 ✗"]},{"id":"V695","q":"Me gustaría ir a un balneario para ____.","o":["relajarme","cansarme","ejercitarme","estresarme"],"a":0,"k":"재귀동사","t":"나는 휴식을 취하러 온천에 가고 싶다.","e":"balneario는 '온천, 스파 휴양지'입니다. 그곳에 가는 목적으로 relajarse(긴장을 풀다, 휴식하다)가 자연스럽습니다. 'para + 동사원형'은 목적을 나타내고, 재귀대명사 me가 동사원형 뒤에 붙었습니다.","x":["relajarme: 휴식하다 → 온천에 가는 목적이라 정답 ✓","cansarme: 지치다 → 온천에 가는 목적이 아니라 ✗","ejercitarme: 운동하다 → 온천의 주된 목적이 아니라 ✗","estresarme: 스트레스 받다 → 온천에 가는 목적과 반대라 ✗"]},{"id":"V696","q":"Eduardo es muy ____, es difícil hacer que cambie de idea.","o":["equilibrado","cabezota","exigente","pacífico"],"a":1,"k":"성격 형용사","t":"에두아르도는 정말 고집이 세서, 생각을 바꾸게 하기가 어렵다.","e":"cabezota는 '고집 센, 완고한'이라는 구어 표현으로 남녀 모두 같은 형태입니다(cabeza: 머리). 생각을 바꾸게 하기 어렵다는 내용과 맞습니다. 비슷한 말로 terco, tozudo가 있습니다.","x":["equilibrado: 균형 잡힌, 침착한 → 고집과 관계없어 ✗","cabezota: 고집 센 → 생각을 안 바꾸는 성격이라 정답 ✓","exigente: 요구가 많은, 까다로운 → 생각을 바꾸지 않는다는 뜻이 아니라 ✗","pacífico: 평화로운 → 고집과 관계없어 ✗"]},{"id":"V697","q":"El trigo es uno de los ____ más consumidos del mundo.","o":["mariscos","frutos","cereales","jugos"],"a":2,"k":"음식 어휘","t":"밀은 세계에서 가장 많이 소비되는 곡물 중 하나이다.","e":"cereal은 '곡물, 곡류'입니다. trigo(밀)는 쌀(arroz), 옥수수(maíz)와 함께 대표적인 곡물입니다. 'uno de los + 복수명사 + más + 형용사'는 '가장 ~한 것 중 하나'입니다.","x":["mariscos: 해산물 → 밀은 해산물이 아니라 ✗","frutos: 열매 → 밀을 분류하는 말로 맞지 않아 ✗","cereales: 곡물 → 밀이 곡물이라 정답 ✓","jugos: 주스 → 밀은 음료가 아니라 ✗"]},{"id":"V698","q":"El ____ más común en esta región es el pino.","o":["bicho","animal","insecto","árbol"],"a":3,"k":"자연 어휘","t":"이 지역에서 가장 흔한 나무는 소나무이다.","e":"pino는 '소나무'이므로 árbol(나무)이 정답입니다. común은 '흔한'입니다. 숲은 bosque, 나뭇잎은 hoja입니다.","x":["bicho: 벌레, 작은 동물 → 소나무는 벌레가 아니라 ✗","animal: 동물 → 소나무는 동물이 아니라 ✗","insecto: 곤충 → 소나무는 곤충이 아니라 ✗","árbol: 나무 → 소나무가 나무라 정답 ✓"]},{"id":"V699","q":"Hemos llegado tarde por mi culpa, os ____ perdón.","o":["doy","pido","hago","tengo"],"a":1,"k":"pedir perdón","t":"내 탓에 늦게 도착했어, 너희에게 사과할게.","e":"pedir perdón은 '용서를 구하다, 사과하다'라는 표현입니다. os는 vosotros(너희)에게 쓰는 간접목적격 대명사로 스페인에서 씁니다(중남미에서는 les). por mi culpa는 '내 잘못으로'입니다.","x":["doy: 주다 → 'dar perdón'은 쓰지 않아 ✗","pido: 요청하다 → pedir perdón(사과하다)이라 정답 ✓","hago: 하다 → 'hacer perdón'은 쓰지 않아 ✗","tengo: 가지다 → 'tener perdón'은 사과의 뜻이 아니라 ✗"]},{"id":"V700","q":"No podéis ____ todavía, el semáforo está en rojo para los peatones.","o":["cruzar","entrar","cambiar","esperar"],"a":0,"k":"교통 동사","t":"아직 건너면 안 돼, 보행자 신호가 빨간불이야.","e":"cruzar는 '(길을) 건너다'입니다. semáforo(신호등)가 보행자(peatones)에게 빨간불이므로 길을 건널 수 없다는 내용입니다. 'No podéis'는 vosotros(너희) 형태로 스페인식입니다.","x":["cruzar: 건너다 → 빨간불일 때 하면 안 되는 행동이라 정답 ✓","entrar: 들어가다 → 신호등과 연결되지 않아 ✗","cambiar: 바꾸다 → 신호등과 연결되지 않아 ✗","esperar: 기다리다 → 빨간불이면 오히려 기다려야 하니 ✗"]},{"id":"V701","q":"Álvaro me ____ genial, es un chico simpatiquísimo.","o":["marcha","sienta","cae","cuenta"],"a":2,"k":"caer bien 표현","t":"알바로는 정말 마음에 들어, 아주 상냥한 친구야.","e":"caer bien/genial a alguien은 '(사람이) ~에게 호감을 주다, 마음에 들다'라는 관용 표현입니다. gustar처럼 'me cae genial'은 '그가 나에게 아주 좋게 느껴진다'는 뜻입니다. 반대는 caer mal(비호감이다)입니다.","x":["marcha: 진행되다 → 사람에 대한 호감 표현이 아니라 ✗","sienta: (옷·음식이) 잘 맞다 → 사람에게는 보통 caer를 써서 ✗","cae: caer genial(아주 마음에 들다) → 정답 ✓","cuenta: 이야기하다, 세다 → 호감 표현이 아니라 ✗"]},{"id":"V702","q":"Aunque salía bastante ____ de la herida, no era grave.","o":["líquido","sangre","jugo","agua"],"a":1,"k":"신체 어휘","t":"상처에서 피가 꽤 나왔지만, 심각하지 않았다.","e":"sangre는 '피'입니다. herida(상처)에서 나오는 것으로 자연스럽습니다. sangre는 여성 명사(la sangre)입니다. '피가 나다'는 sangrar라고도 합니다.","x":["líquido: 액체 → 상처에서 나오는 것을 구체적으로 말하지 않아 ✗","sangre: 피 → 상처에서 나와 정답 ✓","jugo: 즙, 주스 → 상처에서 나오지 않아 ✗","agua: 물 → 상처에서 나오지 않아 ✗"]},{"id":"V703","q":"He trabajado 40 años en la enseñanza; ahora no trabajo, estoy ____.","o":["en forma","atareada","orgullosa","jubilada"],"a":3,"k":"은퇴 어휘","t":"나는 40년 동안 교직에서 일했다. 지금은 일하지 않고, 은퇴했다.","e":"jubilado/a는 '은퇴한, 퇴직한'이라는 뜻입니다. 40년 일하고 지금은 일하지 않는다는 내용과 맞습니다. jubilarse(은퇴하다), jubilación(은퇴, 연금)도 함께 기억하세요.","x":["en forma: 몸매가 좋은, 건강한 → 일하지 않는 이유가 아니라 ✗","atareada: 바쁜 → 일하지 않는다는 말과 반대라 ✗","orgullosa: 자랑스러운 → 일하지 않는 상태를 설명하지 않아 ✗","jubilada: 은퇴한 → 정답 ✓"]},{"id":"V704","q":"Mientras quitas el polvo de los muebles, yo ____ la aspiradora.","o":["abro","hago","rompo","paso"],"a":3,"k":"집안일 표현","t":"네가 가구 먼지를 터는 동안, 나는 청소기를 돌릴게.","e":"pasar la aspiradora는 '청소기를 돌리다'라는 관용 표현입니다. quitar el polvo는 '먼지를 털다'입니다. 집안일 표현을 함께 외우세요: fregar los platos(설거지하다), hacer la cama(침대를 정리하다).","x":["abro: 열다 → 청소기와 함께 쓰지 않아 ✗","hago: 하다 → 'hacer la aspiradora'는 쓰지 않아 ✗","rompo: 부수다 → 집안일 표현이 아니라 ✗","paso: pasar la aspiradora(청소기를 돌리다) → 정답 ✓"]},{"id":"V705","q":"¿Cuánto ____ el tren de Málaga a Madrid?","o":["sale","tarda","llega","viene"],"a":1,"k":"tardar 동사","t":"말라가에서 마드리드까지 기차로 얼마나 걸리나요?","e":"tardar는 '(시간이) 걸리다'라는 뜻입니다. ¿Cuánto tarda ~?는 '~은 얼마나 걸리나요?'라는 질문입니다. ¿Cuánto tarda el tren?처럼 이동 시간을 물을 때 자주 씁니다.","x":["sale: 출발하다, (비용이) 들다 → 시간이 걸린다는 뜻이 아니라 ✗","tarda: 걸리다 → 소요 시간을 묻는 표현이라 정답 ✓","llega: 도착하다 → ¿Cuánto llega?는 쓰지 않아 ✗","viene: 오다 → ¿Cuánto viene?는 쓰지 않아 ✗"]},{"id":"V706","q":"Mi marido es muy ____, en cambio yo no soy nada sentimental.","o":["romántico","equilibrado","tozudo","frío"],"a":0,"k":"성격 형용사","t":"내 남편은 아주 로맨틱한데, 반면에 나는 전혀 감성적이지 않다.","e":"romántico는 '로맨틱한, 낭만적인'입니다. en cambio(반면에)가 대조를 나타내므로, 'no soy nada sentimental(전혀 감성적이지 않다)'의 반대 성격이 필요합니다. 그래서 romántico가 정답입니다.","x":["romántico: 로맨틱한 → 감성적이지 않은 나와 대조되어 정답 ✓","equilibrado: 균형 잡힌 → 대조가 성립하지 않아 ✗","tozudo: 고집 센 → 감성과 대조되지 않아 ✗","frío: 차가운 → 나와 같은 쪽이라 대조가 되지 않아 ✗"]},{"id":"V707","q":"Actualmente, en mi ciudad apenas hay ____ telefónicas porque todos usan su celular.","o":["cámaras","cajas","cabinas","estaciones"],"a":2,"k":"통신 어휘","t":"요즘 우리 도시에는 모두가 휴대폰을 써서 공중전화 부스가 거의 없다.","e":"cabina telefónica는 '공중전화 부스'입니다. celular는 중남미에서 쓰는 '휴대폰'이고, 스페인에서는 móvil이라고 합니다. apenas hay는 '거의 없다'는 뜻입니다.","x":["cámaras: 카메라 → 휴대폰 때문에 사라진 것과 맞지 않아 ✗","cajas: 상자 → 'cajas telefónicas'는 쓰지 않아 ✗","cabinas: 부스 → 공중전화 부스라 정답 ✓","estaciones: 역, 정거장 → 'estaciones telefónicas'는 어색해 ✗"]},{"id":"V708","q":"Me ____, te dije que no contaras mi secreto pero me ignoraste.","o":["has salvado","has traicionado","has influido","has conquistado"],"a":1,"k":"traicionar 동사","t":"너는 나를 배신했어, 내 비밀을 말하지 말라고 했는데 넌 무시했지.","e":"traicionar는 '배신하다'입니다. 비밀을 지키지 않은 행동이 배신이므로 has traicionado가 정답입니다. 'te dije que no contaras'처럼 과거의 명령을 전할 때는 접속법 과거(contaras)를 씁니다.","x":["has salvado: 구했다 → 비밀을 누설한 것과 반대라 ✗","has traicionado: 배신했다 → 정답 ✓","has influido: 영향을 주었다 → 문맥과 맞지 않아 ✗","has conquistado: 정복했다, 마음을 얻었다 → 문맥과 반대라 ✗"]},{"id":"V709","q":"No te preocupes por el transporte para ir al hospital, te ____ yo.","o":["traigo","llego","voy","llevo"],"a":3,"k":"llevar vs traer","t":"병원에 갈 교통편은 걱정하지 마, 내가 데려다줄게.","e":"llevar는 '(다른 곳으로) 데려가다, 가져가다', traer는 '(이쪽으로) 데려오다, 가져오다'입니다. 말하는 사람이 상대를 병원(다른 장소)으로 데려가므로 te llevo가 정답입니다.","x":["traigo: 데려오다 → 이쪽으로 오는 방향이라 ✗","llego: 도착하다 → 목적어 te와 함께 쓰지 않아 ✗","voy: 가다 → 목적어 te와 함께 쓰지 않아 ✗","llevo: 데려가다 → 병원으로 데려가므로 정답 ✓"]},{"id":"V710","q":"Me gusta mucho el pelo rizado, pero lo tengo ____.","o":["rubio","castaño","liso","negro"],"a":2,"k":"머리 모양 어휘","t":"나는 곱슬머리를 정말 좋아하지만, 내 머리는 직모다.","e":"liso는 '곧은, 생머리인'이라는 뜻으로 rizado(곱슬곱슬한)의 반대말입니다. pero(하지만)가 대조를 나타내므로 liso가 정답입니다. 웨이브 머리는 ondulado입니다.","x":["rubio: 금발의 → 곱슬머리와 대조가 아니라 ✗","castaño: 갈색의 → 곱슬머리와 대조가 아니라 ✗","liso: 직모의 → 곱슬과 반대라 정답 ✓","negro: 검은 → 곱슬머리와 대조가 아니라 ✗"]},{"id":"V711","q":"Es un trayecto demasiado ____ como para hacerlo a pie. ¿Por qué no vas en taxi o en autobús?","o":["corto","directo","breve","largo"],"a":3,"k":"거리 형용사","t":"걸어가기에는 너무 먼 거리야. 택시나 버스를 타는 게 어때?","e":"largo는 '긴'이라는 뜻으로 trayecto(이동 거리, 구간)가 길다는 의미입니다. 'demasiado ... como para + 동사원형'은 '~하기에는 너무 ...한'입니다. 걸어가기 힘들어 택시를 권하므로 largo가 정답입니다.","x":["corto: 짧은 → 걸어가기 좋으므로 택시를 권할 이유가 없어 ✗","directo: 직행의 → 걸어가기 어려운 이유가 아니라 ✗","breve: 짧은 → corto와 같은 이유로 ✗","largo: 긴 → 걷기 힘들어 정답 ✓"]},{"id":"V712","q":"Está claro que sin ____ no se puede comprar nada.","o":["monedero","llavero","dinero","perchero"],"a":2,"k":"돈 어휘","t":"돈 없이는 아무것도 살 수 없다는 건 분명하다.","e":"dinero는 '돈'입니다. 물건을 사려면(comprar) 돈이 필요하다는 당연한 내용입니다. Está claro que ~는 '~은 분명하다'라는 표현입니다.","x":["monedero: 동전 지갑 → 지갑이 없어도 살 수는 있어 ✗","llavero: 열쇠고리 → 물건 사는 것과 관계없어 ✗","dinero: 돈 → 정답 ✓","perchero: 옷걸이 → 물건 사는 것과 관계없어 ✗"]},{"id":"V713","q":"Es una trabajadora ____, lleva horas trabajando y no se agota.","o":["detestable","inestable","incansable","comparable"],"a":2,"k":"-able 형용사","t":"그녀는 지칠 줄 모르는 일꾼이다, 몇 시간째 일하는데도 지치지 않는다.","e":"incansable은 '지칠 줄 모르는'으로, in-(부정) + cansar(지치게 하다) + -able로 이루어진 말입니다. 'no se agota(지치지 않는다)'와 같은 의미입니다. llevar + 시간 + 현재분사는 '~째 ...하고 있다'입니다.","x":["detestable: 혐오스러운 → 칭찬하는 문맥과 맞지 않아 ✗","inestable: 불안정한 → 문맥과 맞지 않아 ✗","incansable: 지칠 줄 모르는 → 정답 ✓","comparable: 비교할 만한 → 문맥과 맞지 않아 ✗"]},{"id":"V714","q":"No debemos ir a una entrevista de trabajo con ropa ____ porque causa mala impresión.","o":["clásica","descuidada","elegante","limpia"],"a":1,"k":"옷차림 형용사","t":"나쁜 인상을 주기 때문에 취업 면접에 단정하지 못한 옷을 입고 가면 안 된다.","e":"descuidado는 '단정하지 못한, 관리가 안 된'이라는 뜻입니다. causar mala impresión(나쁜 인상을 주다)의 이유가 되는 옷차림입니다. cuidar(돌보다)에 부정 접두사 des-가 붙은 말입니다.","x":["clásica: 클래식한 → 나쁜 인상을 주지 않아 ✗","descuidada: 단정치 못한 → 나쁜 인상을 주므로 정답 ✓","elegante: 우아한 → 좋은 인상을 줘서 ✗","limpia: 깨끗한 → 좋은 인상을 줘서 ✗"]},{"id":"V715","q":"En cuanto vi aquella casa en llamas, llamé a los ____.","o":["albañiles","bomberos","carpinteros","ejecutivos"],"a":1,"k":"직업 어휘","t":"불타는 그 집을 보자마자 나는 소방관을 불렀다.","e":"bombero는 '소방관'입니다. casa en llamas(불타는 집)에 부르는 사람입니다. en cuanto는 '~하자마자'라는 접속사입니다. 소방서는 estación de bomberos 또는 parque de bomberos(스페인)입니다.","x":["albañiles: 벽돌공, 건설 인부 → 불을 끄는 사람이 아니라 ✗","bomberos: 소방관 → 정답 ✓","carpinteros: 목수 → 불을 끄는 사람이 아니라 ✗","ejecutivos: 임원 → 불을 끄는 사람이 아니라 ✗"]},{"id":"V716","q":"No te creas esa historia, es una ____ urbana.","o":["idea","leyenda","verdad","explicación"],"a":1,"k":"leyenda urbana","t":"그 이야기 믿지 마, 그건 도시 전설이야.","e":"leyenda urbana는 '도시 전설(사실처럼 퍼진 근거 없는 이야기)'입니다. leyenda는 '전설'입니다. No te creas는 creerse의 부정 명령형으로 '믿지 마'라는 뜻입니다.","x":["idea: 생각 → 'idea urbana'는 쓰지 않아 ✗","leyenda: 전설 → leyenda urbana(도시 전설)라 정답 ✓","verdad: 진실 → 믿지 말라는 말과 모순이라 ✗","explicación: 설명 → 'explicación urbana'는 쓰지 않아 ✗"]},{"id":"V717","q":"Es triste que haya tantas especies de animales en ____ de extinción.","o":["inseguridad","peligro","caso","asunto"],"a":1,"k":"en peligro de","t":"멸종 위기에 처한 동물 종이 이렇게 많다니 슬프다.","e":"en peligro de extinción은 '멸종 위기에 처한'이라는 고정 표현입니다. peligro는 '위험'입니다. Es triste que + 접속법(haya)은 '~하다니 슬프다'로 감정 표현 뒤에 접속법을 씁니다.","x":["inseguridad: 불안정 → 'en inseguridad de'는 쓰지 않아 ✗","peligro: 위험 → en peligro de extinción(멸종 위기)이라 정답 ✓","caso: 경우 → 'en caso de'는 '~할 경우'라서 뜻이 달라 ✗","asunto: 일, 문제 → 이 표현에 쓰지 않아 ✗"]},{"id":"V718","q":"Puede que no llueva hoy, pero llévate el paraguas por si las ____.","o":["mariposas","moscas","abejas","hormigas"],"a":1,"k":"관용 표현","t":"오늘 비가 안 올 수도 있지만, 혹시 모르니 우산을 가져가.","e":"por si las moscas는 '만일을 위해, 혹시 모르니'라는 구어 관용 표현입니다(moscas: 파리). por si acaso와 같은 뜻입니다. Puede que + 접속법(llueva)은 '~일 수도 있다'입니다.","x":["mariposas: 나비 → 이 관용 표현에 쓰지 않아 ✗","moscas: 파리 → por si las moscas(혹시 모르니)라 정답 ✓","abejas: 벌 → 이 관용 표현에 쓰지 않아 ✗","hormigas: 개미 → 이 관용 표현에 쓰지 않아 ✗"]},{"id":"V719","q":"La profesora de italiano está escribiendo una lista de palabras en ____.","o":["la pared","el cuadro","la pizarra","el muro"],"a":2,"k":"교실 어휘","t":"이탈리아어 선생님이 칠판에 단어 목록을 쓰고 있다.","e":"pizarra는 '칠판'입니다(중남미 일부에서는 pizarrón). 교실에서 선생님이 글씨를 쓰는 곳입니다. 'estar + 현재분사(escribiendo)'는 지금 진행 중인 행동입니다.","x":["la pared: 벽 → 벽에 직접 쓰지는 않아 ✗","el cuadro: 그림, 액자 → 글을 쓰는 곳이 아니라 ✗","la pizarra: 칠판 → 정답 ✓","el muro: (바깥) 담, 벽 → 교실에서 쓰는 곳이 아니라 ✗"]},{"id":"V720","q":"De pequeño era muy flaco, pero ahora es un hombre ____.","o":["esbelto","delgado","corpulento","fino"],"a":2,"k":"체형 형용사","t":"어렸을 때는 아주 말랐지만, 지금은 덩치가 큰 남자다.","e":"corpulento는 '몸집이 큰, 건장한'입니다. flaco(마른)와 대조되어야 하므로 정답입니다. De pequeño는 '어렸을 때'라는 표현입니다.","x":["esbelto: 날씬한 → 마른 것과 대조되지 않아 ✗","delgado: 마른 → flaco와 같은 뜻이라 대조가 되지 않아 ✗","corpulento: 몸집이 큰 → 마른 것과 대조되어 정답 ✓","fino: 가는, 날씬한 → 대조가 되지 않아 ✗"]},{"id":"V721","q":"En Costa Rica vimos paisajes ____, por eso hicimos tantas fotos.","o":["sencillos","espectaculares","corrientes","normales"],"a":1,"k":"감탄 형용사","t":"코스타리카에서 우리는 장관인 풍경을 봐서, 사진을 그렇게 많이 찍었다.","e":"espectacular는 '장관인, 굉장한'이라는 뜻입니다. 사진을 많이 찍은 이유가 되려면 풍경이 아주 멋져야 하므로 espectaculares가 정답입니다. hacer fotos는 스페인에서 '사진을 찍다'이고, 중남미에서는 tomar fotos를 많이 씁니다.","x":["sencillos: 소박한 → 사진을 많이 찍은 이유로 약해 ✗","espectaculares: 장관인 → 사진을 많이 찍은 이유라 정답 ✓","corrientes: 평범한 → 사진을 많이 찍을 이유가 아니라 ✗","normales: 보통의 → 사진을 많이 찍을 이유가 아니라 ✗"]},{"id":"V722","q":"Todos hemos notado que están enamorados, es ____.","o":["obvio","ilógico","mentira","fundamental"],"a":0,"k":"판단 형용사","t":"그들이 사랑에 빠졌다는 걸 우리 모두 눈치챘어, 뻔하잖아.","e":"obvio는 '명백한, 뻔한'입니다. 모두가 알아챘다(Todos hemos notado)는 것은 누가 봐도 분명하다는 뜻이라 obvio가 정답입니다. 비슷한 말로 evidente, claro가 있습니다.","x":["obvio: 뻔한, 명백한 → 모두 알아챘다는 말과 맞아 정답 ✓","ilógico: 비논리적인 → 문맥과 맞지 않아 ✗","mentira: 거짓말 → 모두 알아챘다는 말과 모순이라 ✗","fundamental: 근본적인 → 문맥과 맞지 않아 ✗"]},{"id":"V723","q":"¡Qué ____ es ese hombre! No respeta a nadie.","o":["amable","listo","introvertido","grosero"],"a":3,"k":"성격 형용사","t":"저 남자 정말 무례하다! 아무도 존중하지 않아.","e":"grosero는 '무례한, 상스러운'입니다. 아무도 존중하지 않는다(No respeta a nadie)는 행동과 맞습니다. '¡Qué + 형용사 + es ~!'는 '~는 정말 ...하구나!'라는 감탄문입니다.","x":["amable: 친절한 → 존중하지 않는다는 말과 반대라 ✗","listo: 똑똑한 → 존중과 관계없어 ✗","introvertido: 내성적인 → 무례함과 다른 성격이라 ✗","grosero: 무례한 → 정답 ✓"]},{"id":"V724","q":"Isa tiene el móvil apagado, así que voy a enviarle un ____ para que me llame cuando lo encienda.","o":["mensaje","anuncio","informe","teléfono"],"a":0,"k":"통신 어휘","t":"이사가 휴대폰을 꺼 놔서, 켜면 나에게 전화하라고 메시지를 보낼 거야.","e":"mensaje는 '메시지'입니다. enviar un mensaje(메시지를 보내다)가 자연스러운 표현입니다. para que + 접속법(llame)은 '~하도록'이라는 목적을 나타냅니다.","x":["mensaje: 메시지 → 정답 ✓","anuncio: 광고, 공지 → 개인에게 보내는 것이 아니라 ✗","informe: 보고서 → 전화해 달라는 연락으로 맞지 않아 ✗","teléfono: 전화기 → 보내는 내용이 아니라 ✗"]},{"id":"V725","q":"¡Qué ____ es! No hace nada en todo el día.","o":["travieso","nervioso","prudente","vago"],"a":3,"k":"성격 형용사","t":"정말 게으르다! 하루 종일 아무것도 안 해.","e":"vago는 '게으른'입니다(perezoso와 비슷). 하루 종일 아무것도 하지 않는다(No hace nada en todo el día)는 내용과 맞습니다. vago는 '모호한'이라는 뜻도 있습니다.","x":["travieso: 장난꾸러기의 → 아무것도 안 하는 것과 관계없어 ✗","nervioso: 초조한 → 아무것도 안 하는 것과 관계없어 ✗","prudente: 신중한 → 아무것도 안 하는 것과 관계없어 ✗","vago: 게으른 → 정답 ✓"]},{"id":"V726","q":"Tuvo que venir el ____ porque nos quedamos sin luz.","o":["electricista","bombero","diseñador","cocinero"],"a":0,"k":"직업 어휘","t":"전기가 나가서 전기 기사가 와야 했다.","e":"electricista는 '전기 기사'로, -ista로 끝나 남녀 모두 같은 형태입니다(el/la electricista). quedarse sin luz는 '전기가 끊기다'입니다. 여기서 luz는 '전기'라는 뜻입니다.","x":["electricista: 전기 기사 → 정전을 고치는 사람이라 정답 ✓","bombero: 소방관 → 정전을 고치지 않아 ✗","diseñador: 디자이너 → 정전과 관계없어 ✗","cocinero: 요리사 → 정전과 관계없어 ✗"]},{"id":"V727","q":"Quiero probarme esta falda, ¿me dice dónde están los ____?","o":["ascensores","probadores","contenedores","extintores"],"a":1,"k":"쇼핑 어휘","t":"이 치마 입어 보고 싶은데, 탈의실이 어디 있는지 알려 주시겠어요?","e":"probador는 옷가게의 '탈의실, 피팅룸'입니다. probarse(입어 보다)에서 나온 말입니다. ¿me dice ~?는 usted에게 쓰는 정중한 요청입니다.","x":["ascensores: 엘리베이터 → 옷을 입어 보는 곳이 아니라 ✗","probadores: 탈의실 → 정답 ✓","contenedores: 수거함, 컨테이너 → 옷을 입어 보는 곳이 아니라 ✗","extintores: 소화기 → 옷을 입어 보는 곳이 아니라 ✗"]},{"id":"V728","q":"El pan ____ tiene un color más oscuro que el pan blanco.","o":["caliente","blando","integral","cortado"],"a":2,"k":"음식 어휘","t":"통밀빵은 흰 빵보다 색이 더 어둡다.","e":"pan integral은 '통밀빵'입니다. integral은 '정제하지 않은, 통곡물의'라는 뜻이고 arroz integral(현미)도 같은 표현입니다. 흰 빵(pan blanco)과 색으로 대조됩니다.","x":["caliente: 따뜻한 → 색과 관계없어 ✗","blando: 부드러운 → 색과 관계없어 ✗","integral: 통밀의 → 색이 더 어두워 정답 ✓","cortado: 잘린 → 색과 관계없어 ✗"]},{"id":"V729","q":"____ al marcar el número de teléfono y llamé a un desconocido.","o":["Me equivoqué","Acerté","Me aseguré","Me tranquilicé"],"a":0,"k":"equivocarse 동사","t":"전화번호를 잘못 눌러서 모르는 사람에게 전화했다.","e":"equivocarse는 '실수하다, 틀리다'라는 재귀동사입니다. 번호를 잘못 눌러 모르는 사람(un desconocido)에게 전화한 상황이므로 Me equivoqué가 정답입니다. 'al + 동사원형'은 '~할 때'라는 뜻입니다.","x":["Me equivoqué: 실수했다 → 정답 ✓","Acerté: 맞혔다 → 모르는 사람에게 전화한 결과와 반대라 ✗","Me aseguré: 확인했다 → 확인했다면 잘못 걸지 않았을 테니 ✗","Me tranquilicé: 진정했다 → 문맥과 맞지 않아 ✗"]},{"id":"V730","q":"Es normal que conozca bien las ____ de esta ciudad, es taxista.","o":["viviendas","factorías","atracciones","calles"],"a":3,"k":"도시 어휘","t":"그가 이 도시의 거리를 잘 아는 건 당연해, 택시 기사니까.","e":"calle는 '거리, 길'입니다. 택시 기사(taxista)가 잘 알아야 하는 것은 도시의 길입니다. Es normal que + 접속법(conozca)은 '~하는 것은 당연하다'입니다.","x":["viviendas: 주택 → 택시 기사가 잘 아는 대상으로 어색해 ✗","factorías: 공장 → 택시 기사와 관계없어 ✗","atracciones: 명소, 놀이기구 → 택시 기사의 일과 직접 연결되지 않아 ✗","calles: 거리 → 택시 기사가 잘 알아야 해 정답 ✓"]},{"id":"V731","q":"La ____ es la virtud de las personas que saben esperar.","o":["seriedad","cobardía","paciencia","bondad"],"a":2,"k":"덕목 어휘","t":"인내는 기다릴 줄 아는 사람의 미덕이다.","e":"paciencia는 '인내, 참을성'입니다. 기다릴 줄 안다(saben esperar)는 정의와 일치합니다. 형용사는 paciente(참을성 있는)이며, '환자'라는 뜻도 있습니다.","x":["seriedad: 진지함 → 기다리는 것과 직접 관계없어 ✗","cobardía: 비겁함 → 미덕이 아니라 ✗","paciencia: 인내 → 기다릴 줄 아는 미덕이라 정답 ✓","bondad: 선함 → 기다리는 것과 직접 관계없어 ✗"]},{"id":"V732","q":"Los ____ normalmente viven en las costas.","o":["cangrejos","osos","monos","camellos"],"a":0,"k":"동물 어휘","t":"게는 보통 해안에 산다.","e":"cangrejo는 '게'입니다. costa(해안)에 사는 동물로 알맞습니다. oso(곰)는 숲, mono(원숭이)는 정글, camello(낙타)는 사막에 삽니다.","x":["cangrejos: 게 → 해안에 살아 정답 ✓","osos: 곰 → 해안이 아니라 숲에 살아 ✗","monos: 원숭이 → 해안이 아니라 정글에 살아 ✗","camellos: 낙타 → 해안이 아니라 사막에 살아 ✗"]},{"id":"V733","q":"Se hizo una herida tan profunda que gritaba de ____.","o":["hervor","dolor","valor","calor"],"a":1,"k":"감각 어휘","t":"너무 깊은 상처를 입어서 아파서 소리를 질렀다.","e":"dolor는 '아픔, 고통'입니다. gritar de dolor는 '아파서 소리 지르다'입니다. 'de + 명사'가 원인을 나타냅니다(llorar de alegría: 기뻐서 울다). tan ... que는 '너무 ~해서 ...하다'입니다.","x":["hervor: 끓음 → 상처와 관계없어 ✗","dolor: 고통 → 상처 때문에 소리 지른 이유라 정답 ✓","valor: 용기, 가치 → 상처 때문에 소리 지를 이유가 아니라 ✗","calor: 더위 → 상처와 관계없어 ✗"]},{"id":"V734","q":"Soy ____, por eso me cuesta pedirle a Ana que salga conmigo.","o":["amable","generoso","hablador","tímido"],"a":3,"k":"성격 형용사","t":"나는 수줍음이 많아서, 아나에게 데이트 신청하기가 힘들다.","e":"tímido는 '수줍음 많은, 소심한'입니다. 데이트 신청이 어렵다(me cuesta pedirle)는 이유가 됩니다. costar는 '~하기 힘들다'라는 의미로 gustar처럼 씁니다. salir con alguien은 '~와 데이트하다'입니다.","x":["amable: 친절한 → 데이트 신청이 어려운 이유가 아니라 ✗","generoso: 너그러운 → 데이트 신청이 어려운 이유가 아니라 ✗","hablador: 수다스러운 → 오히려 말을 잘 걸 테니 ✗","tímido: 수줍은 → 정답 ✓"]},{"id":"V735","q":"Lo contrario de la guerra es la ____.","o":["enemistad","intranquilidad","paz","emoción"],"a":2,"k":"반의어","t":"전쟁의 반대는 평화이다.","e":"paz는 '평화'로 guerra(전쟁)의 반대말입니다. 여성 명사 la paz이고, 복수형은 paces입니다. 'Lo contrario de ~'는 '~의 반대'라는 표현입니다.","x":["enemistad: 적대감 → 전쟁의 반대가 아니라 ✗","intranquilidad: 불안 → 전쟁의 반대가 아니라 ✗","paz: 평화 → 정답 ✓","emoción: 감정, 감동 → 전쟁의 반대가 아니라 ✗"]},{"id":"V736","q":"A mi hija le encanta ____ de Caperucita Roja.","o":["el cuento","el chiste","la anécdota","la cuenta"],"a":0,"k":"이야기 어휘","t":"우리 딸은 빨간 모자 동화를 정말 좋아한다.","e":"cuento는 '동화, 짧은 이야기'입니다. Caperucita Roja(빨간 모자)는 유명한 동화입니다. cuento와 cuenta(계산서, 계좌)를 헷갈리지 마세요.","x":["el cuento: 동화 → 빨간 모자는 동화라 정답 ✓","el chiste: 농담, 우스갯소리 → 빨간 모자는 농담이 아니라 ✗","la anécdota: 일화 → 실제 겪은 짧은 이야기라 ✗","la cuenta: 계산서, 계좌 → 이야기가 아니라 ✗"]},{"id":"V737","q":"¿Cuántos dientes de ____ necesito para hacer esta receta?","o":["lechuga","tomate","ajo","palta"],"a":2,"k":"채소 어휘","t":"이 요리를 하려면 마늘 몇 쪽이 필요해?","e":"diente de ajo는 '마늘 한 쪽'이라는 고정 표현입니다(diente: 이빨). 마늘 한 통은 cabeza de ajo입니다. palta는 남미에서 쓰는 '아보카도'(스페인에서는 aguacate)입니다.","x":["lechuga: 상추 → diente와 쓰지 않아 ✗","tomate: 토마토 → diente와 쓰지 않아 ✗","ajo: 마늘 → diente de ajo(마늘 한 쪽)라 정답 ✓","palta: 아보카도 → diente와 쓰지 않아 ✗"]},{"id":"V738","q":"La sandía es una fruta muy ____ porque tiene bastante cantidad de agua.","o":["refrescante","amarga","picante","ácida"],"a":0,"k":"맛 형용사","t":"수박은 수분이 꽤 많아서 아주 시원한 과일이다.","e":"refrescante는 '상쾌한, 시원하게 해 주는'입니다. 수분이 많은(tiene bastante cantidad de agua) 것과 연결됩니다. refrescar(시원하게 하다)에서 나온 말이고 refresco는 '청량음료'입니다.","x":["refrescante: 시원한 → 수분이 많은 이유와 맞아 정답 ✓","amarga: 쓴 → 수분과 관계없어 ✗","picante: 매운 → 수분과 관계없어 ✗","ácida: 신 → 수분과 관계없어 ✗"]},{"id":"V739","q":"No me representa ningún partido político, por eso no voy a ____.","o":["elegir","jugar","tocar","votar"],"a":3,"k":"정치 어휘","t":"어떤 정당도 나를 대변하지 않아서, 나는 투표하지 않을 것이다.","e":"votar는 '투표하다'입니다. 정당(partido político)이 자신을 대변하지 않는다는 이유와 연결됩니다. 선거는 elecciones, 투표는 voto입니다.","x":["elegir: 선택하다 → 목적어 없이 쓰면 어색해 ✗","jugar: 놀다, 경기하다 → 정치와 관계없어 ✗","tocar: 만지다, 연주하다 → 정치와 관계없어 ✗","votar: 투표하다 → 정답 ✓"]},{"id":"V740","q":"¿Cuánto cuestan las ____ para ese concierto?","o":["postales","entradas","papeletas","tarjetas"],"a":1,"k":"공연 어휘","t":"그 콘서트 입장권은 얼마예요?","e":"entrada는 '입장권, 티켓'이며 '입구'라는 뜻도 있습니다. 콘서트(concierto)·영화·박물관 표에 씁니다. 중남미에서는 boleto, boleta도 씁니다.","x":["postales: 엽서 → 콘서트와 관계없어 ✗","entradas: 입장권 → 정답 ✓","papeletas: 투표용지, 쪽지 → 콘서트 표가 아니라 ✗","tarjetas: 카드 → 콘서트 표를 뜻하지 않아 ✗"]},{"id":"V741","q":"Te ____ por haber encontrado trabajo.","o":["comprendo","felicito","detesto","odio"],"a":1,"k":"felicitar 동사","t":"일자리를 구한 것을 축하해.","e":"felicitar는 '축하하다'입니다. felicitar a alguien por + 사유로 써서 무엇을 축하하는지 말합니다. 'por haber encontrado'처럼 전치사 뒤에 완료 동사원형(haber + 과거분사)이 왔습니다. ¡Felicidades!는 '축하해!'입니다.","x":["comprendo: 이해하다 → 취업한 것을 '이해한다'는 어색해 ✗","felicito: 축하하다 → 정답 ✓","detesto: 몹시 싫어하다 → 기쁜 소식에 맞지 않아 ✗","odio: 미워하다 → 기쁜 소식에 맞지 않아 ✗"]},{"id":"V742","q":"Le rompieron el ____ de la nariz en la pelea.","o":["dedo","hueso","cuello","diente"],"a":1,"k":"신체 어휘","t":"싸움에서 그의 코뼈가 부러졌다.","e":"hueso는 '뼈'입니다. el hueso de la nariz는 '코뼈'입니다. 스페인어는 신체 부위에 소유격 대신 정관사(el)와 간접목적격 대명사(le)를 함께 씁니다: Le rompieron el hueso.","x":["dedo: 손가락 → 코에 손가락은 없어 ✗","hueso: 뼈 → 코뼈라 정답 ✓","cuello: 목 → 코에 목은 없어 ✗","diente: 이 → 코에 이는 없어 ✗"]},{"id":"V743","q":"En el microondas los alimentos ____ antes que en el horno.","o":["se calientan","se pudren","se fríen","se deshacen"],"a":0,"k":"조리 동사","t":"전자레인지에서는 음식이 오븐보다 더 빨리 데워진다.","e":"calentarse는 '데워지다, 뜨거워지다'입니다. 전자레인지(microondas)의 주된 기능은 음식을 데우는 것입니다. 'antes que'는 여기서 '~보다 먼저(빨리)'라는 뜻입니다.","x":["se calientan: 데워지다 → 전자레인지 기능이라 정답 ✓","se pudren: 썩다 → 전자레인지와 관계없어 ✗","se fríen: 튀겨지다 → 전자레인지로 튀기지 않아 ✗","se deshacen: 녹다, 부서지다 → 전자레인지의 주된 기능이 아니라 ✗"]},{"id":"V744","q":"Esta salsa tiene demasiada pimienta, está muy ____.","o":["picante","dulce","sosa","amarga"],"a":0,"k":"맛 형용사","t":"이 소스는 후추가 너무 많아서 아주 맵다.","e":"picante는 '매운'입니다. pimienta(후추)가 너무 많아(demasiada) 맵다는 결과가 자연스럽습니다. soso는 '싱거운', dulce는 '단', amargo는 '쓴'입니다.","x":["picante: 매운 → 후추가 많으면 매워 정답 ✓","dulce: 단 → 후추와 관계없어 ✗","sosa: 싱거운 → 후추가 많은 것과 반대라 ✗","amarga: 쓴 → 후추가 많은 결과로 맞지 않아 ✗"]},{"id":"V745","q":"Hoy voy a ponerme estos pantalones vaqueros y esta ____ de manga corta.","o":["camiseta","corbata","falda","bufanda"],"a":0,"k":"옷 어휘","t":"오늘은 이 청바지와 이 반팔 티셔츠를 입을 거야.","e":"camiseta는 '티셔츠'입니다. de manga corta는 '반팔의'(manga: 소매)이고, 긴팔은 de manga larga입니다. pantalones vaqueros는 '청바지'입니다(중남미에서는 jeans를 많이 씀).","x":["camiseta: 티셔츠 → 반팔과 어울려 정답 ✓","corbata: 넥타이 → 소매가 없어 ✗","falda: 치마 → 바지와 함께 입지 않고 소매도 없어 ✗","bufanda: 목도리 → 소매가 없어 ✗"]},{"id":"V746","q":"Mientras Juan termina de cocinar, sus hijos ayudan a ____ la mesa.","o":["poner","tomar","hacer","dar"],"a":0,"k":"poner la mesa","t":"후안이 요리를 마저 하는 동안, 아이들은 상 차리는 것을 돕는다.","e":"poner la mesa는 '상을 차리다'라는 관용 표현입니다. 반대로 '상을 치우다'는 quitar/recoger la mesa입니다. ayudar a + 동사원형은 '~하는 것을 돕다'입니다.","x":["poner: 놓다 → poner la mesa(상을 차리다)라 정답 ✓","tomar: 잡다, 먹다 → 상 차리기 표현이 아니라 ✗","hacer: 만들다 → 'hacer la mesa'는 쓰지 않아 ✗","dar: 주다 → 'dar la mesa'는 쓰지 않아 ✗"]},{"id":"V747","q":"Soy estudiante y los fines de semana trabajo como ____ de comida a domicilio.","o":["cuidador","repartidor","camarero","instructor"],"a":1,"k":"직업 어휘","t":"나는 학생이고, 주말에는 음식 배달원으로 일한다.","e":"repartidor는 '배달원'입니다(repartir: 나누어 주다, 배달하다). comida a domicilio는 '배달 음식(집으로 가져다주는 음식)'입니다.","x":["cuidador: 돌보는 사람 → 음식 배달과 관계없어 ✗","repartidor: 배달원 → 정답 ✓","camarero: 웨이터 → 배달(a domicilio)과 맞지 않아 ✗","instructor: 강사 → 음식 배달과 관계없어 ✗"]},{"id":"V748","q":"¡Qué presumido eres! Siempre estás mirándote al ____.","o":["cuadro","cristal","espejo","reloj"],"a":2,"k":"생활용품 어휘","t":"너 정말 멋 부린다! 늘 거울을 보고 있잖아.","e":"espejo는 '거울'입니다. mirarse al espejo는 '거울을 보다(거울에 자신을 비추어 보다)'입니다. presumido는 '외모에 신경 쓰는, 멋 부리는'이라는 뜻입니다.","x":["cuadro: 그림 → 자신을 비추어 보지 않아 ✗","cristal: 유리 → 거울을 뜻하는 일반적인 말이 아니라 ✗","espejo: 거울 → 정답 ✓","reloj: 시계 → 자신을 비추어 보지 않아 ✗"]},{"id":"V749","q":"Vamos a ____ un texto para practicar la comprensión auditiva.","o":["leer","escribir","analizar","escuchar"],"a":3,"k":"학습 어휘","t":"듣기 연습을 위해 텍스트를 하나 들을 거예요.","e":"escuchar는 '듣다'입니다. comprensión auditiva는 '듣기 이해(청해)'이므로 텍스트를 들어야 합니다. 읽기 이해는 comprensión lectora입니다.","x":["leer: 읽다 → 듣기 연습과 맞지 않아 ✗","escribir: 쓰다 → 듣기 연습과 맞지 않아 ✗","analizar: 분석하다 → 듣기 연습의 직접적인 활동이 아니라 ✗","escuchar: 듣다 → 정답 ✓"]},{"id":"V750","q":"El español es una lengua que ____ del latín.","o":["regresa","se acuerda","procede","vuelve"],"a":2,"k":"proceder de","t":"스페인어는 라틴어에서 유래한 언어이다.","e":"proceder de는 '~에서 유래하다, ~에서 나오다'입니다. 스페인어는 라틴어에서 유래한 로망스어입니다. 비슷한 표현으로 venir de, derivar de가 있습니다.","x":["regresa: 돌아오다 → 유래를 뜻하지 않아 ✗","se acuerda: 기억하다 → 유래를 뜻하지 않아 ✗","procede: 유래하다 → 정답 ✓","vuelve: 돌아가다 → 유래를 뜻하지 않아 ✗"]}];